const imagePreloadCache = new Map();

function ensureIceMealAudio() {
  if (!(iceMealBgmAudio instanceof HTMLAudioElement)) {
    iceMealBgmAudio = new Audio(versionedAsset('./assets/audio/bgm-meal-ice.ogg'));
    iceMealBgmAudio.loop = true;
    iceMealBgmAudio.preload = 'auto';
    iceMealBgmAudio.setAttribute('playsinline', '');
  }
  if (!(iceMealAmbientAudio instanceof HTMLAudioElement)) {
    iceMealAmbientAudio = new Audio(versionedAsset('./assets/audio/amb-meal-ice.ogg'));
    iceMealAmbientAudio.loop = true;
    iceMealAmbientAudio.preload = 'auto';
    iceMealAmbientAudio.setAttribute('playsinline', '');
  }
}

function updateIceMealAudioVolumes() {
  ensureIceMealAudio();
  const settings = state?.settings || {};
  const bgmVolume = settings.bgmMuted ? 0 : Math.max(0, Math.min(1, Number(settings.bgmVolume) || 0)) * 0.72;
  const ambientVolume = settings.ambientMuted ? 0 : Math.max(0, Math.min(1, Number(settings.ambientVolume) || 0)) * 0.82;
  iceMealBgmAudio.volume = bgmVolume;
  iceMealAmbientAudio.volume = ambientVolume;
}

function startIceMealAudio() {
  ensureIceMealAudio();
  updateIceMealAudioVolumes();
  [iceMealBgmAudio, iceMealAmbientAudio].forEach((audio) => {
    if (!(audio instanceof HTMLAudioElement)) return;
    const promise = audio.play();
    if (promise && typeof promise.catch === 'function') promise.catch(() => {});
  });
}

function stopIceMealAudio({ rewind = true } = {}) {
  [iceMealBgmAudio, iceMealAmbientAudio].forEach((audio) => {
    if (!(audio instanceof HTMLAudioElement)) return;
    audio.pause();
    if (rewind) {
      try { audio.currentTime = 0; } catch (_) {}
    }
  });
}

function syncIceMealAudio() {
  const active = screen === 'meal' && screenData?.eating === true && screenData?.mealId === 'ice';
  if (!active) {
    stopIceMealAudio();
    return;
  }
  stopMealAudio();
  startIceMealAudio();
}

function whiteBunnyEventBgmVolume() {
  const settings = state?.settings || {};
  if (settings.bgmMuted || settings.externalAudioPriority || document.hidden) return 0;
  const configured = Math.max(0, Math.min(1, Number(settings.bgmVolume) || 0));
  return Math.max(0, Math.min(1, configured * WHITE_BUNNY_EVENT_BGM_GAIN));
}

function ensureWhiteBunnyEventBgm() {
  if (whiteBunnyEventBgmAudio instanceof HTMLAudioElement) return;
  whiteBunnyEventBgmAudio = new Audio(WHITE_BUNNY_EVENT_BGM_URL);
  whiteBunnyEventBgmAudio.loop = true;
  whiteBunnyEventBgmAudio.preload = 'auto';
  whiteBunnyEventBgmAudio.setAttribute('playsinline', '');
}

function stopWhiteBunnyEventBgm({ reset = true } = {}) {
  if (!(whiteBunnyEventBgmAudio instanceof HTMLAudioElement)) return;
  whiteBunnyEventBgmAudio.pause();
  if (reset) {
    try { whiteBunnyEventBgmAudio.currentTime = 0; } catch (_) {}
  }
}

function playWhiteBunnyEventBgm({ restart = false } = {}) {
  if (screen !== 'whiteBunnyIceEvent' || !whiteBunnyIceEventState().active) return;
  ensureWhiteBunnyEventBgm();
  const volume = whiteBunnyEventBgmVolume();
  whiteBunnyEventBgmAudio.volume = volume;
  if (volume <= 0) {
    stopWhiteBunnyEventBgm({ reset: false });
    return;
  }
  if (restart) {
    try { whiteBunnyEventBgmAudio.currentTime = 0; } catch (_) {}
  }
  if (whiteBunnyEventBgmAudio.paused) {
    const promise = whiteBunnyEventBgmAudio.play();
    if (promise && typeof promise.catch === 'function') promise.catch(() => {});
  }
}

function syncWhiteBunnyEventBgm() {
  if (screen !== 'whiteBunnyIceEvent' || !whiteBunnyIceEventState().active) {
    stopWhiteBunnyEventBgm();
    return;
  }
  stopMealAudio();
  stopIceMealAudio();
  playWhiteBunnyEventBgm();
}

function measuredPortraitLayout() {
  const viewport = window.visualViewport;
  const width = Math.max(1, Number(viewport?.width) || window.innerWidth || document.documentElement.clientWidth || 1);
  const height = Math.max(1, Number(viewport?.height) || window.innerHeight || document.documentElement.clientHeight || 1);
  return height >= width;
}

function isPortraitLayout() {
  if (shellViewportOrientation === 'portrait') return true;
  if (shellViewportOrientation === 'landscape') return false;
  return measuredPortraitLayout();
}

function clampViewportValue(value, min, max) {
  return Math.min(max, Math.max(min, Number(value) || min));
}

function applyDeviceViewportProfile({ orientation = '', width = 0, height = 0, deviceClass = '', uiScale = 0 } = {}) {
  const viewport = window.visualViewport;
  const measuredWidth = Math.max(1, Math.round(Number(width) || Number(viewport?.width) || window.innerWidth || document.documentElement.clientWidth || 1));
  const measuredHeight = Math.max(1, Math.round(Number(height) || Number(viewport?.height) || window.innerHeight || document.documentElement.clientHeight || 1));
  const resolvedOrientation = orientation === 'portrait' || orientation === 'landscape'
    ? orientation
    : measuredHeight >= measuredWidth ? 'portrait' : 'landscape';
  const shortSide = Math.min(measuredWidth, measuredHeight);
  const longSide = Math.max(measuredWidth, measuredHeight);
  const touchDevice = Number(navigator.maxTouchPoints || 0) > 0 || 'ontouchstart' in window;
  const resolvedDeviceClass = ['phone', 'tablet', 'desktop'].includes(deviceClass)
    ? deviceClass
    : touchDevice && shortSide <= 620 && longSide <= 1100
      ? 'phone'
      : touchDevice && shortSide <= 900
        ? 'tablet'
        : 'desktop';
  const scaleAxis = resolvedOrientation === 'landscape' ? measuredHeight : measuredWidth;
  const resolvedScale = resolvedDeviceClass === 'phone'
    ? clampViewportValue(uiScale || (scaleAxis / 390), .84, 1.08)
    : 1;

  shellViewportWidth = measuredWidth;
  shellViewportHeight = measuredHeight;
  const rootStyle = document.documentElement.style;
  rootStyle.setProperty('--jwj-layout-width', `${measuredWidth}px`);
  rootStyle.setProperty('--jwj-layout-height', `${measuredHeight}px`);
  rootStyle.setProperty('--jwj-ui-scale', resolvedScale.toFixed(4));
  document.documentElement.dataset.orientation = resolvedOrientation;
  document.documentElement.dataset.deviceClass = resolvedDeviceClass;
  document.documentElement.dataset.layoutProfile = `${resolvedDeviceClass}-${resolvedOrientation}`;
}

function syncDeviceViewportProfile() {
  applyDeviceViewportProfile({ orientation: shellViewportOrientation });
}

const KEYBOARD_AWARE_FIELD_SELECTOR = '[data-calendar-event-input]';
let focusedKeyboardField = null;
let keyboardVisibilityTimer = 0;

function keyboardViewportMetrics() {
  const viewport = window.visualViewport;
  const fullHeight = Math.max(1, Number(window.innerHeight) || document.documentElement.clientHeight || 1);
  const visibleHeight = Math.max(1, Number(viewport?.height) || fullHeight);
  const hiddenHeight = Math.max(0, fullHeight - visibleHeight - Math.max(0, Number(viewport?.offsetTop) || 0));
  return { viewport, fullHeight, visibleHeight, hiddenHeight };
}

function keepFocusedKeyboardFieldVisible({ smooth = false } = {}) {
  const field = focusedKeyboardField;
  if (!(field instanceof HTMLElement) || !field.isConnected) return;
  const { viewport, visibleHeight } = keyboardViewportMetrics();
  const visibleTop = Math.max(0, Number(viewport?.offsetTop) || 0) + 10;
  const visibleBottom = visibleTop + visibleHeight - 18;
  const target = field;
  const rect = target.getBoundingClientRect();
  if (rect.top < visibleTop || rect.bottom > visibleBottom) {
    target.scrollIntoView({ block: 'center', inline: 'nearest', behavior: smooth ? 'smooth' : 'auto' });
  }
}

function scheduleKeyboardFieldVisibility() {
  [40, 120, 240, 420, 700, 1000].forEach((delay, index) => {
    window.setTimeout(() => {
      updateKeyboardViewportLayout({ smooth: index > 1 });
      keepFocusedKeyboardFieldVisible({ smooth: index > 1 });
    }, delay);
  });
}

function updateKeyboardViewportLayout({ smooth = false } = {}) {
  const { visibleHeight, hiddenHeight, fullHeight } = keyboardViewportMetrics();
  document.documentElement.style.setProperty('--visual-viewport-height', `${Math.round(visibleHeight)}px`);
  const keyboardOpen = Boolean(focusedKeyboardField) && hiddenHeight > Math.max(90, fullHeight * 0.13);
  document.body.classList.toggle('keyboard-open', keyboardOpen);
  clearTimeout(keyboardVisibilityTimer);
  if (keyboardOpen) {
    keyboardVisibilityTimer = window.setTimeout(() => keepFocusedKeyboardFieldVisible({ smooth }), 80);
  }
}

