function uid() {
  if (globalThis.crypto?.randomUUID) return globalThis.crypto.randomUUID();
  return `id-${Date.now().toString(36)}-${Math.random().toString(36).slice(2, 10)}`;
}

function loadTitleSettings() {
  try {
    const settingsKey = `${SAVE_KEY}-settings`;
    const bgmMigrationKey = `${SAVE_KEY}-bgm-volume-v0.10.12`;
    const birthdayMigrationKey = `${SAVE_KEY}-birthday-default-v0.10.480`;
    const saved = JSON.parse(localStorage.getItem(settingsKey) || 'null');
    const settings = { ...initialState().settings, ...(saved || {}) };
    delete settings.textSize;
    settings.birthday = normalizeBirthday(settings.birthday);
    // タイトル側に残っている旧既定値1月1日も一度だけ4月1日へ更新する。
    // 移行後にユーザーが設定画面から1月1日へ変更した場合は、その設定を保持する。
    if (localStorage.getItem(birthdayMigrationKey) !== '1') {
      if (settings.birthday === '01-01') settings.birthday = DEFAULT_BIRTHDAY;
      localStorage.setItem(birthdayMigrationKey, '1');
      localStorage.setItem(settingsKey, JSON.stringify(settings));
    }
    // 自動操縦はゲームごとの進行設定のため、タイトル画面の共通設定から新規ゲームへ引き継がない。
    settings.autopilotEnabled = false;
    settings.bgmVolume = Number.isFinite(Number(settings.bgmVolume)) ? Math.max(0, Math.min(1, Number(settings.bgmVolume))) : 0.35;
    // 旧初期値75％だけを初回に35％へ移行し、その後の手動設定は尊重する。
    if (localStorage.getItem(bgmMigrationKey) !== '1') {
      if (Number(settings.bgmVolume) >= 0.70) settings.bgmVolume = 0.35;
      localStorage.setItem(bgmMigrationKey, '1');
      localStorage.setItem(settingsKey, JSON.stringify(settings));
    }
    settings.ambientVolume = Number.isFinite(Number(settings.ambientVolume)) ? Math.max(0, Math.min(1, Number(settings.ambientVolume))) : 0.60;
    if (Number(settings.sfxVolume) <= 0.65) settings.sfxVolume = 0.75;
    return settings;
  } catch (_) {
    return initialState().settings;
  }
}

function localSaveKey() {
  return currentUser?.uid ? `${SAVE_KEY}-${currentUser.uid}` : SAVE_KEY;
}

function freshStartFlagKey() {
  return currentUser?.uid ? `${SAVE_KEY}-fresh-start-${currentUser.uid}` : `${SAVE_KEY}-fresh-start`;
}

function freshStartRequested() {
  return localStorage.getItem(freshStartFlagKey()) === '1';
}

function hasSave() {
  return Boolean(cloudSave || localStorage.getItem(localSaveKey()));
}

function isUnneededHungerNotification(note) {
  const title = String(note?.title || '').trim();
  const body = String(note?.body || '').trim();
  return title.includes('空腹になりました') || body.includes('空腹になりました');
}

function visibleNotifications() {
  return (state?.notifications || []).filter((note) => !isUnneededHungerNotification(note));
}

function localSaveBackupKey() {
  return `${localSaveKey()}-backup`;
}

function localSavePreMigrationKey() {
  return `${localSaveKey()}-pre-migration`;
}

function localSaveCorruptKey() {
  return `${localSaveKey()}-corrupt`;
}

function localLastSaveAtKey() {
  return `${localSaveKey()}-last-saved-at`;
}

function saveStateFingerprint(value = state) {
  if (!value) return '';
  try {
    return JSON.stringify(value, (key, item) => (
      key === 'updatedAt' || key === 'saveRevision' ? undefined : item
    ));
  } catch (_) {
    return '';
  }
}

function ensureAutosaveStatusElement() {
  let element = document.querySelector('[data-autosave-status]');
  if (element) return element;
  element = document.createElement('div');
  element.className = 'autosave-status';
  element.dataset.autosaveStatus = 'idle';
  element.setAttribute('role', 'status');
  element.setAttribute('aria-live', 'polite');
  element.hidden = true;
  document.body.appendChild(element);
  return element;
}

function showAutosaveStatus(mode, text, { persistent = false } = {}) {
  const element = ensureAutosaveStatusElement();
  if (autosaveStatusHideTimer) {
    clearTimeout(autosaveStatusHideTimer);
    autosaveStatusHideTimer = null;
  }
  element.dataset.autosaveStatus = String(mode || 'idle');
  element.textContent = String(text || '');
  element.hidden = !text;
  if (!persistent && text) {
    autosaveStatusHideTimer = window.setTimeout(() => {
      element.hidden = true;
      element.dataset.autosaveStatus = 'idle';
      autosaveStatusHideTimer = null;
    }, AUTOSAVE_STATUS_HIDE_MS);
  }
}

function formatAutosaveTime(value) {
  const date = value ? new Date(value) : null;
  if (!date || Number.isNaN(date.getTime())) return '';
  return date.toLocaleTimeString('ja-JP', { hour: '2-digit', minute: '2-digit', second: '2-digit' });
}

function isSaveStateCandidate(value) {
  return Boolean(value && typeof value === 'object' && !Array.isArray(value)
    && value.game && typeof value.game === 'object'
    && value.inventory && typeof value.inventory === 'object');
}

function parseSaveText(raw) {
  if (!raw) return null;
  const parsed = JSON.parse(raw);
  if (!isSaveStateCandidate(parsed)) throw new Error('セーブデータの必須項目がありません。');
  return parsed;
}

function preserveCorruptLocalSave(raw, reason) {
  if (!raw) return;
  try {
    localStorage.setItem(localSaveCorruptKey(), JSON.stringify({
      savedAt: new Date().toISOString(),
      reason: String(reason?.message || reason || 'unknown'),
      raw,
    }));
  } catch (_) {}
}

function localSavedState() {
  const raw = localStorage.getItem(localSaveKey());
  if (!raw) return null;
  try {
    const parsed = parseSaveText(raw);
    // 読み込み・移行前の原本を保存。移行を繰り返しても数量は変化しない。
    localStorage.setItem(localSavePreMigrationKey(), raw);
    return parsed;
  } catch (error) {
    preserveCorruptLocalSave(raw, error);
    const backupRaw = localStorage.getItem(localSaveBackupKey());
    try {
      const backup = parseSaveText(backupRaw);
      saveRecoveryNotice = '破損した端末セーブを直前の正常なバックアップから復元しました。';
      saveRecoveryDetails = String(error?.message || error);
      localStorage.setItem(localSaveKey(), backupRaw);
      return backup;
    } catch (backupError) {
      saveRecoveryNotice = '端末セーブを読み込めず、正常なバックアップも見つかりませんでした。';
      saveRecoveryDetails = String(error?.message || error);
      return null;
    }
  }
}

function preferredSavedState() {
  const safeCloudSave = isSaveStateCandidate(cloudSave) ? cloudSave : null;
  return chooseNewestSavedState(localSavedState(), safeCloudSave);
}

function loadGame() {
  try {
    const preferred = preferredSavedState();
    if (!preferred.state) return null;
    const loaded = migrateState(preferred.state);
    if (!isSaveStateCandidate(loaded)) throw new Error('移行後のセーブデータが不正です。');
    loaded.saveSchemaVersion = SAVE_SCHEMA_VERSION;
    if (loaded?.notifications) loaded.notifications = loaded.notifications.filter((note) => !isUnneededHungerNotification(note));
    return loaded;
  } catch (error) {
    saveRecoveryNotice = saveRecoveryNotice || 'セーブデータの移行または整合性確認に失敗しました。';
    saveRecoveryDetails = String(error?.message || error);
    return null;
  }
}

function saveLocalBackup({ fingerprint = null, createCloudSnapshot = true, updateFingerprint = true } = {}) {
  if (!state || !currentUser || sessionTakenOver) return { saved: false, skipped: true };
  try {
    state.saveRevision = Math.max(0, Math.floor(Number(state.saveRevision) || 0)) + 1;
    state.updatedAt = new Date().toISOString();
    // 廃止済みの旧在庫を保存データへ戻さない。
    if (state.inventory && Object.prototype.hasOwnProperty.call(state.inventory, 'general')) delete state.inventory.general;
    if (state.inventory && Object.prototype.hasOwnProperty.call(state.inventory, 'gems')) delete state.inventory.gems;
    state.migrations = state.migrations && typeof state.migrations === 'object' && !Array.isArray(state.migrations) ? state.migrations : {};
    state.migrations.looseInventoryCanonicalV231 = true;
    state.saveSchemaVersion = SAVE_SCHEMA_VERSION;
    const key = localSaveKey();
    const nextRaw = JSON.stringify(state);
    const currentRaw = localStorage.getItem(key);
    if (currentRaw && currentRaw !== nextRaw) {
      try {
        parseSaveText(currentRaw);
        localStorage.setItem(localSaveBackupKey(), currentRaw);
      } catch (error) {
        preserveCorruptLocalSave(currentRaw, error);
      }
    }
    localStorage.setItem(key, nextRaw);
    localStorage.setItem(`${SAVE_KEY}-settings`, JSON.stringify(state.settings));
    lastSuccessfulSaveAt = state.updatedAt;
    localStorage.setItem(localLastSaveAtKey(), lastSuccessfulSaveAt);
    if (updateFingerprint) lastSavedFingerprint = fingerprint || saveStateFingerprint(state);
    // JSON.stringify済みの保存文字列から一度だけスナップショットを作る。
    // 同じstateをstructuredCloneで複数回コピーしない。
    const snapshot = createCloudSnapshot ? JSON.parse(nextRaw) : null;
    if (snapshot) cloudSave = snapshot;
    return { saved: true, savedAt: lastSuccessfulSaveAt, snapshot, raw: nextRaw };
  } catch (error) {
    console.error('端末保存に失敗しました', error);
    return { saved: false, error };
  }
}

function saveGame(message = false) {
  if (!state) return Promise.resolve();
  syncGameClearState();
  if (!currentUser || sessionTakenOver) return Promise.resolve();
  if (autosaveTimer) {
    clearTimeout(autosaveTimer);
    autosaveTimer = null;
  }
  autosavePending = false;
  const fingerprint = saveStateFingerprint(state);
  if (fingerprint && fingerprint === lastSavedFingerprint && fingerprint === lastCloudSavedFingerprint) {
    return saveQueue;
  }
  const localResult = saveLocalBackup({ fingerprint, createCloudSnapshot: true, updateFingerprint: true });
  if (!localResult.saved) {
    showAutosaveStatus('error', '端末に保存できませんでした', { persistent: true });
    return Promise.resolve();
  }
  // v0.10.611: 端末保存時に作成した切り離し済みスナップショットをクラウド保存にも再利用する。
  const snapshot = localResult.snapshot;
  const userId = currentUser.uid;
  const cloudFingerprint = fingerprint || saveStateFingerprint(snapshot);
  saveQueue = saveQueue
    .catch(() => {})
    .then(() => saveState(userId, snapshot))
    .then(() => {
      lastCloudSavedFingerprint = cloudFingerprint;
      if (cloudSaveFailureActive) {
        cloudSaveFailureActive = false;
        showAutosaveStatus('saved', 'クラウド保存を復旧しました');
      }
    })
    .catch((error) => {
      cloudSaveFailureActive = true;
      const message = firebaseErrorMessage(error, 'cloud-save');
      console.error('[Cloud Save]', { code: error?.code || '', message: error?.message || '', detail: error?.detail || null }, error);
      // 端末保存は成功しているので、中央の大きなエラーは出さず下部ステータスだけで通知する。
      showAutosaveStatus('error', `端末保存済み／${message}`, { persistent: true });
    });
  return saveQueue;
}

function scheduleAutosave(reason = 'state-change', delay = AUTOSAVE_DELAY_MS) {
  if (!state || !currentUser || sessionTakenOver) return;
  autosavePending = true;
  autosaveLastReason = String(reason || 'state-change');
  if (autosaveTimer) clearTimeout(autosaveTimer);
  autosaveTimer = window.setTimeout(() => {
    autosaveTimer = null;
    if (!autosavePending) return;
    void saveGame(false).catch(() => {});
  }, Math.max(0, Number(delay) || 0));
}

function flushAutosave(reason = 'lifecycle') {
  if (!state || !currentUser || sessionTakenOver) return Promise.resolve();
  autosaveLastReason = String(reason || 'lifecycle');
  if (autosaveTimer) {
    clearTimeout(autosaveTimer);
    autosaveTimer = null;
  }
  autosavePending = false;
  return saveGame(false).catch(() => {});
}

function flushAutosaveLocally(reason = 'lifecycle-local') {
  if (!state || !currentUser || sessionTakenOver) return;
  autosaveLastReason = String(reason || 'lifecycle-local');
  if (autosaveTimer) {
    clearTimeout(autosaveTimer);
    autosaveTimer = null;
  }
  autosavePending = false;
  syncGameClearState();
  const result = saveLocalBackup({ createCloudSnapshot: false, updateFingerprint: false });
  if (!result.saved && !result.skipped) showAutosaveStatus('error', '端末に保存できませんでした', { persistent: true });
}

function esc(value = '') {
  return String(value).replace(/[&<>'"]/g, (char) => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', "'": '&#39;', '"': '&quot;' }[char]));
}

function yen(value) {
  return `¥${Math.round(Number(value) || 0).toLocaleString('ja-JP')}`;
}

function roundedMetalWeight(value) {
  return Math.round(Math.max(0, Number(value) || 0) * 10) / 10;
}

function metalWeightLabel(value) {
  const amount = roundedMetalWeight(value);
  return Number.isInteger(amount) ? String(amount) : amount.toFixed(1);
}

function startMoneyFeedback(amount, duration = 1050) {
  const delta = Math.round(Number(amount) || 0);
  if (!delta || !state) return;
  clearTimeout(moneyFeedbackTimer);
  if (moneyAnimationFrame) cancelAnimationFrame(moneyAnimationFrame);

  const token = `${Date.now()}-${Math.random()}`;
  const toAmount = Math.round(Number(state.game.money) || 0);
  const fromAmount = toAmount - delta;
  const startedAt = performance.now();

  moneyFeedback = {
    amount: Math.abs(delta),
    delta,
    direction: delta > 0 ? 'gain' : 'loss',
    fromAmount,
    toAmount,
    displayAmount: fromAmount,
    token,
  };
  playSfx(delta > 0 ? 'sale' : 'coin');

  const animateAmount = (now) => {
    if (moneyFeedback?.token !== token) return;
    const elapsed = Math.max(0, now - startedAt);
    // 金額表示が大きくなった後から、現在額→変更後の金額へ切り替える。
    const changeStart = duration * 0.18;
    const changeEnd = duration * 0.72;
    const rawProgress = Math.max(0, Math.min(1, (elapsed - changeStart) / Math.max(1, changeEnd - changeStart)));
    const easedProgress = rawProgress < 0.5
      ? 4 * rawProgress * rawProgress * rawProgress
      : 1 - Math.pow(-2 * rawProgress + 2, 3) / 2;
    const displayAmount = Math.round(fromAmount + ((toAmount - fromAmount) * easedProgress));
    moneyFeedback.displayAmount = displayAmount;

    const valueEl = document.querySelector('.header-money-value');
    if (valueEl) valueEl.textContent = yen(displayAmount);

    if (elapsed < duration) {
      moneyAnimationFrame = requestAnimationFrame(animateAmount);
    } else {
      moneyFeedback.displayAmount = toAmount;
      const finalEl = document.querySelector('.header-money-value');
      if (finalEl) finalEl.textContent = yen(toAmount);
      moneyAnimationFrame = null;
    }
  };
  moneyAnimationFrame = requestAnimationFrame(animateAmount);

  moneyFeedbackTimer = setTimeout(() => {
    if (moneyFeedback?.token !== token) return;
    if (moneyAnimationFrame) cancelAnimationFrame(moneyAnimationFrame);
    moneyAnimationFrame = null;
    moneyFeedback = null;
    if (state) render();
  }, duration + 40);
}

function storeBranchLabel(number = 1) {
  const branchNumber = Math.max(1, Number(number) || 1);
  return `店舗${branchNumber}`;
}

function storeBranchDisplayName(branch = currentStoreBranch()) {
  const branchNumber = Math.max(1, Number(branch?.number || state?.store?.branchNumber) || 1);
  const baseName = String(branch?.name || state?.store?.name || '店舗').trim() || '店舗';
  return `${baseName}　${storeBranchLabel(branchNumber)}`;
}

function storeEmployeeDefaults(branchNumber = 1) {
  const number = Math.max(1, Math.min(MAX_STORE_BRANCHES, Math.floor(Number(branchNumber) || 1)));
  const candidate = STORE_EMPLOYEE_CANDIDATES[number] || STORE_EMPLOYEE_CANDIDATES[1];
  return { hired: false, name: candidate.name, workDays: 0, working: true, wageUnpaid: 0 };
}

function normalizedStoreEmployee(value, branchNumber = 1, legacyFallback = null) {
  const defaults = storeEmployeeDefaults(branchNumber);
  const source = value && typeof value === 'object' && !Array.isArray(value)
    ? value
    : (legacyFallback && typeof legacyFallback === 'object' && !Array.isArray(legacyFallback) ? legacyFallback : {});
  return {
    hired: Boolean(source.hired),
    name: defaults.name,
    workDays: Math.max(0, Math.floor(Number(source.workDays) || 0)),
    working: source.working !== false,
    wageUnpaid: Math.max(0, Math.floor(Number(source.wageUnpaid) || 0)),
  };
}

function storeBranchEmployee(branch = currentStoreBranch()) {
  if (!branch) return normalizedStoreEmployee(state?.employee, 1);
  const branchNumber = Math.max(1, Number(branch.number) || 1);
  const actualBranch = storeBranchByNumber(branchNumber) || branch;
  actualBranch.employee = normalizedStoreEmployee(actualBranch.employee, branchNumber, branchNumber === 1 ? state?.employee : null);
  if (branchNumber === 1) state.employee = actualBranch.employee;
  return actualBranch.employee;
}

function storeEmployeeAvailable(branch = currentStoreBranch()) {
  if (!branch) return false;
  return Number(branch.number) >= 2 || Boolean(state?.store?.expanded);
}

function storeStaffDefinition(employee) {
  return storeStaffGrowthForWorkDays(employee?.workDays);
}

function storeStaffNextDefinition(employee) {
  return storeStaffNextGrowthForWorkDays(employee?.workDays);
}

function storeStaffSalesDescription(employee) {
  const definition = storeStaffDefinition(employee);
  const visitorBonus = 2 + Math.max(0, Math.floor(Number(definition.visitorBonus) || 0));
  return `配置中はショーケース基礎販売力が無人時の約4倍・来店人数＋${visitorBonus}人・来店抽選＋${10 + Math.round((Number(definition.customerVisitBonus) || 0) * 100)}ポイント相当・接客購入率＋${10 + Math.round((Number(definition.purchaseBonus) || 0) * 100)}ポイント・ショーケース販売率はLv成長でさらに＋${Math.round((Number(definition.saleBonus) || 0) * 100)}ポイント`;
}

function activeStoreStaff(branchOrNumber) {
  const branch = typeof branchOrNumber === 'object'
    ? branchOrNumber
    : storeBranchByNumber(Math.max(1, Number(branchOrNumber) || 1));
  if (!branch || !storeBranchOperating(branch) || !storeEmployeeAvailable(branch)) return null;
  const employee = storeBranchEmployee(branch);
  if (!employee.hired || !employee.working || Math.max(0, Number(employee.wageUnpaid) || 0) > 0) return null;
  return employee;
}

function customerProposalMinutes() {
  return 60;
}

function storeStaffPurchaseBonus(branchNumber = state?.store?.branchNumber || 1) {
  const employee = activeStoreStaff(branchNumber);
  return employee ? Number(storeStaffDefinition(employee).purchaseBonus) || 0 : 0;
}

function storeStaffCustomerVisitBonus(employee) {
  if (!employee?.hired || !employee?.working) return 0;
  return Number(storeStaffDefinition(employee).customerVisitBonus) || 0;
}

function storeStaffVisitorBonus(employee) {
  if (!employee?.hired || !employee?.working) return 0;
  return Math.max(0, Math.floor(Number(storeStaffDefinition(employee).visitorBonus) || 0));
}

function storeStaffSaleBonus(employee) {
  if (!employee?.hired || !employee?.working) return 0;
  return Number(storeStaffDefinition(employee).saleBonus) || 0;
}


function workshopStaffState() {
  if (!state) return { hired: false, everHired: false, working: true, workDays: 0, workMinutesBank: 0, workedMinutesToday: 0, craftedToday: [] };
  const source = state.workshopStaff && typeof state.workshopStaff === 'object' && !Array.isArray(state.workshopStaff)
    ? state.workshopStaff
    : {};
  const workDays = Math.max(0, Math.floor(Number(source.workDays) || 0));
  const evolutionStage = workshopStaffGrowthForWorkDays(workDays).level >= 4 ? 2 : 1;
  state.workshopStaff = {
    hired: Boolean(source.hired),
    everHired: Boolean(source.everHired || source.hired),
    working: source.working !== false,
    workDays,
    workMinutesBank: Math.max(0, Number(source.workMinutesBank) || 0),
    workedMinutesToday: Math.max(0, Math.floor(Number(source.workedMinutesToday) || 0)),
    craftedToday: Array.isArray(source.craftedToday) ? source.craftedToday.slice(-20) : [],
    wageUnpaid: Math.max(0, Math.floor(Number(source.wageUnpaid) || 0)),
    evolutionStage,
  };
  return state.workshopStaff;
}

function workshopStaffDefinition(staff = workshopStaffState()) {
  return workshopStaffGrowthForWorkDays(staff?.workDays);
}

function workshopStaffNextDefinition(staff = workshopStaffState()) {
  return workshopStaffNextGrowthForWorkDays(staff?.workDays);
}

function workshopStaffHoliday(date = gameDate()) {
  if (!(date instanceof Date) || Number.isNaN(date.getTime())) return false;
  return date.getDay() === 0 || date.getDay() === 6 || Boolean(japaneseHolidayName(date));
}

function workshopStaffHolidayReason(date = gameDate()) {
  const holidayName = japaneseHolidayName(date);
  if (holidayName) return holidayName;
  if (date.getDay() === 0) return '日曜日';
  if (date.getDay() === 6) return '土曜日';
  return '';
}

function workshopStaffQualityRoll(definition = workshopStaffDefinition()) {
  const premiumChance = Math.max(0, Math.min(1, Number(definition?.premiumChance) || 0));
  const goodChance = Math.max(0, Math.min(1 - premiumChance, Number(definition?.goodChance) || 0));
  const roll = Math.random();
  if (roll < premiumChance) return 'premium';
  if (roll < premiumChance + goodChance) return 'good';
  return 'standard';
}

function workshopStaffQualityDescription(definition = workshopStaffDefinition()) {
  const good = Math.round((Number(definition?.goodChance) || 0) * 100);
  const premium = Math.round((Number(definition?.premiumChance) || 0) * 100);
  if (!good && !premium) return '品質：標準のみ';
  return `品質：良品${good}%${premium ? `・上質${premium}%` : ''}`;
}

function workshopStaffCraftCandidates(maxEffectiveMinutes) {
  const maxMinutes = Math.max(0, Number(maxEffectiveMinutes) || 0);
  if (maxMinutes < 120 || !workshopOperating() || !toolUsable('jewelryBench')) return [];
  const storedCount = state.inventory.jewelry.filter((item) => item.status !== 'sold').length;
  if (storedCount >= state.inventory.capacity) return [];

  const candidates = [];
  const plainCandidates = [];
  const looseCandidates = [];
  const itemIds = Object.keys(ITEMS);
  const designIds = Object.keys(DESIGNS);
  const finishIds = Object.keys(FINISHES);
  const metalIds = Object.keys(METALS);
  const availableLooseVariants = [];
  for (const gemId of Object.keys(GEMS)) {
    for (const shapeId of looseShapeIdsForGem(gemId)) {
      if (looseAvailableQuantity(gemId, shapeId) > 0) availableLooseVariants.push({ gemId, shapeId });
    }
  }

  for (const item of itemIds) {
    for (const design of designIds) {
      for (const finish of finishIds) {
        const hours = productionHours({ item, design, finish });
        if (hours * 60 > maxMinutes + 1e-9) continue;
        for (const metal of metalIds) {
          const plainDraft = { orderId: null, item, useLoose: false, gem: 'amethyst', looseShape: 'round', metal, design, finish };
          const plainRequirements = materialRequirementsFor(plainDraft);
          if (plainRequirements.enoughMetal) plainCandidates.push({ draft: plainDraft, hours, requirements: plainRequirements, usesLoose: false });
          for (const variant of availableLooseVariants) {
            const looseDraft = { orderId: null, item, useLoose: true, gem: variant.gemId, looseShape: variant.shapeId, metal, design, finish };
            const looseRequirements = materialRequirementsFor(looseDraft);
            if (looseRequirements.enoughMetal && looseRequirements.enoughLoose) {
              looseCandidates.push({ draft: looseDraft, hours, requirements: looseRequirements, usesLoose: true });
            }
          }
        }
      }
    }
  }

  if (looseCandidates.length && plainCandidates.length) {
    const preferLoose = Math.random() < 0.7;
    candidates.push(...(preferLoose ? looseCandidates : plainCandidates));
  } else candidates.push(...looseCandidates, ...plainCandidates);
  return candidates;
}

function workshopStaffCraftOne(maxEffectiveMinutes, definition = workshopStaffDefinition()) {
  const candidates = workshopStaffCraftCandidates(maxEffectiveMinutes);
  if (!candidates.length) return null;
  const selected = randomFrom(candidates);
  if (!selected) return null;
  const { draft, hours, requirements } = selected;
  if (draft.useLoose === true) adjustLooseInventory(draft.gem, draft.looseShape, -requirements.requiredLooseQuantity);
  state.inventory.metals[draft.metal] = roundedMetalWeight(requirements.ownedMetalWeight - requirements.requiredMetalWeight);
  const quality = workshopStaffQualityRoll(definition);
  const staffArtisanLevel = Math.max(1, Math.min(20, 2 + (Math.max(1, Number(definition?.level) || 1) * 3)));
  const craftsmanship = craftProductionProfile(draft, { artisanLevel: staffArtisanLevel });
  const jewelry = {
    id: uid(),
    ...draft,
    name: itemName(draft),
    quality,
    cost: productionCost(draft),
    recommendedPrice: craftsmanshipRecommendedPrice(draft, quality, craftsmanship),
    ...craftsmanshipSnapshot(craftsmanship),
    xp: 0,
    status: 'stored',
    createdDay: state.game.day,
    madeBy: 'workshopStaff',
  };
  state.inventory.jewelry.push(jewelry);
  state.daily.crafted.push(jewelry.id);
  state.daily.workshopStaffCrafted = Array.isArray(state.daily.workshopStaffCrafted) ? state.daily.workshopStaffCrafted : [];
  const summary = { id: jewelry.id, name: jewelry.name, quality, hours };
  state.daily.workshopStaffCrafted.push(summary);
  const staff = workshopStaffState();
  staff.craftedToday.push(summary);
  staff.craftedToday = staff.craftedToday.slice(-20);
  const brokenToolName = checkWorkshopToolFailure();
  if (brokenToolName) addNotification(`${brokenToolName}が故障しました`, '職人スタッフの制作後に故障しました。修理が完了するまで自動制作は止まります。', 'warning');
  return { jewelry, hours, brokenToolName };
}

function processWorkshopStaffElapsedTime(beforeMinutes, afterMinutes) {
  if (!state || workshopStaffHoliday(gameDate())) return 0;
  const staff = workshopStaffState();
  if (!staff.hired || !staff.working || !workshopOperating() || Math.max(0, Number(staff.wageUnpaid) || 0) > 0) return 0;
  const start = Math.max(WORKSHOP_STAFF_SHIFT_START_MINUTES, Number(beforeMinutes) || 0);
  const end = Math.min(WORKSHOP_STAFF_SHIFT_END_MINUTES, Number(afterMinutes) || 0);
  const elapsed = Math.max(0, end - start);
  if (!elapsed) return 0;
  staff.workedMinutesToday += elapsed;
  if (!toolUsable('jewelryBench')) return 0;
  const definition = workshopStaffDefinition(staff);
  staff.workMinutesBank += elapsed * Math.max(0.1, Number(definition.speedMultiplier) || 1);
  let crafted = 0;
  let safety = 0;
  while (staff.workMinutesBank >= 120 && safety < 12) {
    safety += 1;
    const result = workshopStaffCraftOne(staff.workMinutesBank, definition);
    if (!result) break;
    staff.workMinutesBank = Math.max(0, staff.workMinutesBank - (result.hours * 60));
    crafted += 1;
    if (result.brokenToolName || !toolUsable('jewelryBench')) break;
  }
  staff.workMinutesBank = Math.round(staff.workMinutesBank * 10) / 10;
  return crafted;
}

function settleWorkshopStaffDay() {
  const staff = workshopStaffState();
  const workedMinutes = Math.max(0, Math.floor(Number(staff.workedMinutesToday) || 0));
  const craftedRows = Array.isArray(state.daily?.workshopStaffCrafted) ? state.daily.workshopStaffCrafted : [];
  if (!staff.hired || workedMinutes <= 0 || workshopStaffHoliday(gameDate())) {
    return { worked: false, crafted: craftedRows.length, items: structuredClone(craftedRows) };
  }
  const beforeDefinition = workshopStaffDefinition(staff);
  if (craftedRows.length <= 0) {
    return {
      worked: true,
      productive: false,
      level: beforeDefinition.level,
      levelLabel: beforeDefinition.label,
      workDays: staff.workDays,
      wage: 0,
      paidWage: 0,
      unpaidWage: 0,
      workedMinutes,
      crafted: 0,
      items: [],
      leveledUp: false,
    };
  }
  const wage = Math.max(0, Math.floor(Number(beforeDefinition.dailyWage) || 10000));
  const wageResult = payFixedCost(`職人スタッフの日当（Lv.${beforeDefinition.level}）`, wage, (unpaid) => {
    staff.wageUnpaid = Math.max(0, Number(staff.wageUnpaid) || 0) + unpaid;
  });
  if (wageResult.unpaid > 0) {
    addNotification('職人スタッフの給与が未払いです', `${yen(wageResult.unpaid)}が未払いです。完済するまで職人スタッフは出勤しません。`, 'warning');
  }
  staff.workDays += 1;
  const afterDefinition = workshopStaffDefinition(staff);
  const leveledUp = Number(afterDefinition.level) > Number(beforeDefinition.level);
  staff.evolutionStage = Number(afterDefinition.level) >= 4 ? 2 : 1;
  const names = craftedRows.slice(0, 3).map((entry) => entry.name).join('、');
  addNotification('職人スタッフがジュエリーを制作しました', `${craftedRows.length}点を完成品在庫へ追加しました。${names}${craftedRows.length > 3 ? 'ほか' : ''}`);
  if (leveledUp) {
    addNotification('職人スタッフが成長しました', `職人スタッフがLv.${afterDefinition.level}（${afterDefinition.label}）になりました。次回の日当は${yen(afterDefinition.dailyWage)}です。`, 'success');
  }
  return {
    worked: true,
    productive: true,
    level: afterDefinition.level,
    levelLabel: afterDefinition.label,
    workDays: staff.workDays,
    wage,
    paidWage: wageResult.paid,
    unpaidWage: wageResult.unpaid,
    workedMinutes,
    crafted: craftedRows.length,
    items: structuredClone(craftedRows),
    leveledUp,
  };
}

function resetWorkshopStaffDaily() {
  const staff = workshopStaffState();
  staff.workMinutesBank = 0;
  staff.workedMinutesToday = 0;
  staff.craftedToday = [];
}

function storeLeaseCost(branchNumber = 1) {
  return Math.max(0, Number(STORE_LEASE_COSTS[branchNumber]) || Number(STORE_LEASE_COST) || 0);
}

function storeMonthlyRent(branchNumber = 1) {
  return Math.max(0, Number(STORE_MONTHLY_RENTS[branchNumber]) || 0);
}

function contractedStoreBranches() {
  const branches = Array.isArray(state?.store?.branches) ? state.store.branches : [];
  const normalized = branches
    .filter((branch) => branch && Number(branch.number) >= 1 && Number(branch.number) <= MAX_STORE_BRANCHES)
    .map((branch) => ({
      ...branch,
      id: branch.id || `branch-${Math.max(1, Number(branch.number) || 1)}`,
      number: Math.max(1, Number(branch.number) || 1),
      label: storeBranchLabel(branch.number),
      name: String(branch.name || state.store.name || '').trim().slice(0, 30),
      rentedDay: Math.max(1, Number(branch.rentedDay) || state.store.rentedDay || state.game.day),
      suspended: Boolean(branch.suspended),
      unpaidRent: Math.max(0, Number(branch.unpaidRent) || 0),
      points: Math.max(0, Math.floor(Number(branch.points) || 0)),
      level: Math.max(1, Math.min(20, Math.floor(Number(branch.level) || 1))),
      peakLevel: Math.max(1, Math.min(20, Math.floor(Number(branch.peakLevel) || Number(branch.level) || 1))),
      paidThroughLevel: Math.max(1, Math.min(20, Math.floor(Number(branch.paidThroughLevel) || Number(branch.level) || 1))),
      operatingDays: Math.max(0, Math.floor(Number(branch.operatingDays) || 0)),
      totalRevenue: Math.max(0, Math.floor(Number(branch.totalRevenue) || 0)),
      serviceSuccesses: Math.max(0, Math.floor(Number(branch.serviceSuccesses) || 0)),
      openMinutesToday: Math.max(0, Math.floor(Number(branch.openMinutesToday) || 0)),
      visitorsToday: Math.max(0, Math.floor(Number(branch.visitorsToday) || 0)),
      rating: Math.max(0, Math.min(100, Number.isFinite(Number(branch.rating)) ? Math.round(Number(branch.rating)) : 50)),
      salesCount: Math.max(0, Math.floor(Number(branch.salesCount) || 0)),
      orderDeliveries: Math.max(0, Math.floor(Number(branch.orderDeliveries) || 0)),
      displaySuppliesInstalled: Math.max(0, Math.floor(Number(branch.displaySuppliesInstalled) || 0)),
      casesInstalled: Math.min(50, Math.max(0, Math.floor(Number(branch.casesInstalled) || 0))),
      showcases: Array.isArray(branch.showcases) ? branch.showcases : [],
      showcaseCount: Array.isArray(branch.showcases) ? branch.showcases.length : 0,
      employee: normalizedStoreEmployee(branch.employee, branch.number, Number(branch.number) === 1 ? state?.employee : null),
    }))
    .sort((left, right) => left.number - right.number);
  if (state?.store?.rented && !normalized.some((branch) => branch.number === 1)) {
    normalized.unshift({
      id: 'branch-1', number: 1, label: storeBranchLabel(1), name: String(state.store.name || '').trim().slice(0, 30),
      rentedDay: Math.max(1, Number(state.store.rentedDay) || 1), suspended: false, unpaidRent: 0,
      points: Math.max(0, Math.floor(Number(state.store.points) || 0)), level: Math.max(1, Math.min(20, Math.floor(Number(state.store.level) || 1))), peakLevel: Math.max(1, Math.min(20, Math.floor(Number(state.store.peakLevel) || Number(state.store.level) || 1))), paidThroughLevel: Math.max(1, Math.min(20, Math.floor(Number(state.store.paidThroughLevel) || Number(state.store.level) || 1))), operatingDays: Math.max(0, Math.floor(Number(state.store.operatingDays) || 0)), totalRevenue: Math.max(0, Math.floor(Number(state.store.totalRevenue) || 0)), serviceSuccesses: Math.max(0, Math.floor(Number(state.store.serviceSuccesses) || 0)), openMinutesToday: 0, visitorsToday: 0,
      rating: Math.max(0, Math.min(100, Number.isFinite(Number(state.store.rating)) ? Math.round(Number(state.store.rating)) : 50)), salesCount: 0, orderDeliveries: 0,
      displaySuppliesInstalled: Math.max(0, Math.floor(Number(state.store.displaySuppliesInstalled) || 0)),
      casesInstalled: Math.min(50, Math.max(0, Math.floor(Number(state.store.casesInstalled) || 0))),
      showcases: Array.isArray(state.store.showcases) ? state.store.showcases : [],
      showcaseCount: Array.isArray(state.store.showcases) ? state.store.showcases.length : 0,
      employee: normalizedStoreEmployee(state?.employee, 1),
    });
  }
  if (state?.store) state.store.branches = normalized;
  return normalized;
}

function nextStoreBranchNumber() {
  const branches = contractedStoreBranches();
  if (!branches.length) return 1;
  return Math.max(...branches.map((branch) => Number(branch.number) || 0)) + 1;
}

function currentStoreBranch() {
  const number = Math.max(1, Number(state?.store?.branchNumber) || 1);
  return (state?.store?.branches || []).find((branch) => Number(branch?.number) === number) || null;
}

function storeBranchOperating(branch = currentStoreBranch()) {
  return Boolean(branch && !branch.suspended && Math.max(0, Number(branch.unpaidRent) || 0) === 0);
}

function storeBranchHasWaitingCustomer(branchOrNumber = currentStoreBranch()) {
  const branchNumber = typeof branchOrNumber === 'object'
    ? Math.max(1, Math.floor(Number(branchOrNumber?.number) || 1))
    : Math.max(1, Math.floor(Number(branchOrNumber) || 1));
  return Object.values(state?.customers || {}).some((customer) => (
    Boolean(customer?.visiting)
    && Math.max(1, Math.floor(Number(customer.visitingBranchNumber) || 1)) === branchNumber
  ));
}

function storeBusinessOpen(minutes = state?.game?.minutes ?? DAY_START_MINUTES) {
  const value = Number(minutes);
  return Number.isFinite(value) && value >= STORE_OPEN_MINUTES && value < STORE_CLOSE_MINUTES;
}

function storeDeliveryOpen(minutes = state?.game?.minutes ?? DAY_START_MINUTES) {
  const value = Number(minutes);
  return Number.isFinite(value) && value >= STORE_OPEN_MINUTES && value <= STORE_CLOSE_MINUTES;
}

function canSpendStoreMinutes(minutes) {
  const elapsed = Math.max(0, Math.round(Number(minutes) || 0));
  return storeBusinessOpen() && state.game.minutes + elapsed <= STORE_CLOSE_MINUTES;
}

function closeVisitingCustomersAtStoreClosing() {
  let closedCount = 0;
  Object.values(state?.customers || {}).forEach((customer) => {
    if (customer?.visiting) closedCount += 1;
    customer.visiting = false;
    customer.visitingBranchNumber = null;
    customer.activeRequest = null;
    customer.wishesHeard = false;
    customer.proposedItemIds = [];
  });
  if (closedCount > 0) {
    addNotification('店舗の営業を終了しました', '19:00になったため、本日の接客と注文受付を終了しました。');
  }
}

function anyStoreBranchOperating() {
  return contractedStoreBranches().some((branch) => storeBranchOperating(branch));
}

function artisanTitle(level = state?.artisan?.level || 1) {
  const value = Math.max(1, Math.min(20, Math.floor(Number(level) || 1)));
  return ARTISAN_LEVEL_TITLES[value] || ARTISAN_LEVEL_TITLES[1];
}

function gameClearProgress() {
  const branches = contractedStoreBranches();
  const highestStoreLevel = branches.length ? Math.max(...branches.map((branch) => storeLevel(branch))) : 0;
  const operatingStoreCount = branches.filter((branch) => storeBranchOperating(branch)).length;
  const conditions = [
    { id: 'artisan', label: '職人レベル', current: Math.max(1, Number(state?.artisan?.level) || 1), target: 20 },
    { id: 'workshop', label: '工房レベル', current: workshopLevel(), target: 20 },
    { id: 'store', label: '最高店舗レベル', current: highestStoreLevel, target: 20 },
    { id: 'branches', label: '営業店舗数', current: operatingStoreCount, target: 3 },
  ].map((condition) => ({ ...condition, achieved: condition.current >= condition.target }));
  return {
    artisanLevel: conditions[0].current,
    workshopLevel: conditions[1].current,
    highestStoreLevel: conditions[2].current,
    operatingStoreCount: conditions[3].current,
    contractedStoreCount: branches.length,
    conditions,
    complete: conditions.every((condition) => condition.achieved),
  };
}

function syncGameClearState() {
  if (!state) return false;
  state.progressFlags = state.progressFlags && typeof state.progressFlags === 'object' ? state.progressFlags : {};
  const progress = gameClearProgress();
  if (!state.progressFlags.gameClearAchieved && progress.complete) {
    state.progressFlags.gameClearAchieved = true;
    state.progressFlags.gameClearShown = false;
    state.progressFlags.gameClearDay = state.game.day;
    addNotification('ゲームクリア', '職人Lv.20、工房Lv.20、店舗Lv.20、3店舗営業を達成しました。クリア後も引き続きプレイできます。');
    return true;
  }
  return false;
}

function gameClearConditionRows(progress = gameClearProgress()) {
  return progress.conditions.map((condition) => `<div class="game-clear-condition ${condition.achieved ? 'achieved' : ''}"><span>${condition.achieved ? '✓' : '○'}</span><strong>${esc(condition.label)}</strong><em>${condition.current}／${condition.target}</em></div>`).join('');
}

function maybeShowGameClearModal() {
  if (!state || !currentUser || sessionTakenOver) return;
  const newlyAchieved = syncGameClearState();
  if (newlyAchieved) saveGame();
  if (!state.progressFlags?.gameClearAchieved || state.progressFlags?.gameClearShown) return;
  if (!modalEl.classList.contains('hidden')) return;
  const progress = gameClearProgress();
  state.progressFlags.gameClearShown = true;
  saveGame();
  playSfx('levelup');
  showModal({
    title: 'JEWELRY×JEWELRY クリア',
    body: `<section class="game-clear-modal"><p class="game-clear-message">すべてのクリア条件を達成しました。</p><div class="game-clear-condition-list">${gameClearConditionRows(progress)}</div><p>これまでの店舗・在庫・所持金・ゲームデータはそのまま維持されます。</p><strong>このまま自由にプレイを続けられます。</strong></section>`,
    confirm: 'ゲームを続ける',
    action: 'modal-close',
    hideCancel: true,
    className: 'game-clear-dialog',
  });
}

function workshopOperating() {
  return !Boolean(state?.business?.workshopSuspended) && Math.max(0, Number(state?.business?.workshopUnpaid) || 0) === 0;
}

function artisanBaseLevelForXp(xp = state?.artisan?.xp || 0) {
  const value = Math.max(0, Math.floor(Number(xp) || 0));
  return ARTISAN_LEVEL_XP.reduce((level, threshold, index) => value >= threshold ? index + 1 : level, 1);
}

function artisanLevelForXp(xp = state?.artisan?.xp || 0) {
  const base = artisanBaseLevelForXp(xp);
  const penalty = Math.max(0, Math.floor(Number(state?.artisan?.levelPenalty) || 0));
  return Math.max(1, Math.min(20, base - penalty));
}

function addArtisanXp(amount) {
  const gain = Math.max(0, Math.floor(Number(amount) || 0));
  if (!gain) return;
  const previousLevel = Math.max(1, Number(state.artisan.level) || 1);
  state.artisan.xp = Math.max(0, Math.floor(Number(state.artisan.xp) || 0)) + gain;
  state.artisan.level = artisanLevelForXp(state.artisan.xp);
  state.artisan.peakLevel = Math.max(Number(state.artisan.peakLevel) || 1, state.artisan.level);
  if (state.artisan.level > previousLevel) addNotification('職人レベルが上がりました', `職人レベル${state.artisan.level}（${artisanTitle(state.artisan.level)}）になりました。`);
}

// 将来の重大イベントから呼び出すレベル低下基盤。累計経験値は消さない。
function applyArtisanLevelPenalty(levels = 1, reason = '技術状態が低下しました') {
  const amount = Math.max(1, Math.min(2, Math.floor(Number(levels) || 1)));
  const before = Math.max(1, Number(state.artisan.level) || 1);
  state.artisan.levelPenalty = Math.max(0, Math.floor(Number(state.artisan.levelPenalty) || 0)) + amount;
  state.artisan.level = artisanLevelForXp(state.artisan.xp);
  if (state.artisan.level < before) addNotification('職人レベルが低下しました', `${reason} Lv.${before} → Lv.${state.artisan.level}`, 'warning');
  return state.artisan.level;
}

// 将来の回復イベントから呼び出す。累計経験値と過去最高レベルを保持したまま低下分だけ戻す。
function recoverArtisanLevelPenalty(levels = 1, reason = '技術状態が回復しました') {
  const amount = Math.max(1, Math.min(2, Math.floor(Number(levels) || 1)));
  const before = Math.max(1, Number(state.artisan.level) || 1);
  state.artisan.levelPenalty = Math.max(0, Math.floor(Number(state.artisan.levelPenalty) || 0) - amount);
  state.artisan.level = artisanLevelForXp(state.artisan.xp);
  state.artisan.peakLevel = Math.max(Number(state.artisan.peakLevel) || 1, state.artisan.level);
  if (state.artisan.level > before) addNotification('職人レベルが回復しました', `${reason} Lv.${before} → Lv.${state.artisan.level}`, 'success');
  return state.artisan.level;
}

function storeDisplayName() {
  const name = String(state?.store?.name || '').trim();
  return name || '店舗';
}

function normalizeSellingPrice(value, fallback = 1000) {
  const numeric = Number(value);
  const resolved = Number.isFinite(numeric) && numeric >= 1000 ? numeric : Number(fallback);
  return Math.max(1000, Math.round(Number.isFinite(resolved) ? resolved : 1000));
}

function showcaseLocationForJewelry(itemId, branch = null) {
  const branches = branch
    ? [branch]
    : (Array.isArray(state?.store?.branches) ? state.store.branches : []);
  for (const candidateBranch of branches) {
    const showcases = branchShowcases(candidateBranch);
    for (let showcaseIndex = 0; showcaseIndex < showcases.length; showcaseIndex += 1) {
      const showcase = showcases[showcaseIndex];
      const slotIndex = (showcase?.slots || []).findIndex((entry) => entry?.jewelryId === itemId);
      if (slotIndex >= 0) {
        return { branch: candidateBranch, showcaseIndex, slotIndex, slot: showcase.slots[slotIndex] };
      }
    }
  }
  if (!branch && (!state?.store?.branches || state.store.branches.length === 0)) {
    const showcases = branchShowcases(null);
    for (let showcaseIndex = 0; showcaseIndex < showcases.length; showcaseIndex += 1) {
      const slotIndex = (showcases[showcaseIndex]?.slots || []).findIndex((entry) => entry?.jewelryId === itemId);
      if (slotIndex >= 0) return { branch: null, showcaseIndex, slotIndex, slot: showcases[showcaseIndex].slots[slotIndex] };
    }
  }
  return null;
}

function showcaseSlotForJewelry(itemId, branch = null) {
  return showcaseLocationForJewelry(itemId, branch)?.slot || null;
}

function jewelryDisplayBranch(itemId) {
  return showcaseLocationForJewelry(itemId)?.branch || null;
}

function showcaseSellingPrice(slot, item) {
  return normalizeSellingPrice(slot?.sellingPrice, item?.recommendedPrice || 1000);
}

function sellingPriceForJewelry(item) {
  if (!item) return 1000;
  return showcaseSellingPrice(showcaseSlotForJewelry(item.id), item);
}

function sellingPriceStatus(item, sellingPrice = sellingPriceForJewelry(item)) {
  const recommended = normalizeSellingPrice(item?.recommendedPrice, 1000);
  const price = normalizeSellingPrice(sellingPrice, recommended);
  if (price < recommended) return { id: 'cheap', name: '安い', saleBonus: 0.2 };
  if (price > recommended) return { id: 'expensive', name: '高い', saleBonus: -0.2 };
  return { id: 'appropriate', name: '適正', saleBonus: 0 };
}

function storeMaximumShowcases(branch = currentStoreBranch()) {
  if (Number(branch?.number) >= 2) return 3;
  return state?.store?.expanded ? 3 : 1;
}

function installedShowcaseCount(branch = currentStoreBranch()) {
  return branchShowcases(branch).length;
}

function storeShowcaseCapacity(branch = currentStoreBranch()) {
  return installedShowcaseCount(branch) * 5;
}

function storeShowcaseUsedSlots(branch = currentStoreBranch()) {
  return branchShowcases(branch).reduce((sum, showcase) => sum + (showcase?.slots || []).filter(Boolean).length, 0);
}

function storeMaximumCases() {
  return 50;
}

function storeMaximumDisplaySupplies(branch = currentStoreBranch()) {
  return installedShowcaseCount(branch);
}

function storeDisplaySuppliesInstalled(branch = currentStoreBranch()) {
  if (branch && Number.isFinite(Number(branch.displaySuppliesInstalled))) {
    return Math.max(0, Math.floor(Number(branch.displaySuppliesInstalled) || 0));
  }
  return Math.max(0, Math.floor(Number(state?.store?.displaySuppliesInstalled) || 0));
}

function storeCaseRemaining(branch = currentStoreBranch()) {
  const value = branch && Number.isFinite(Number(branch.casesInstalled)) ? branch.casesInstalled : state?.store?.casesInstalled;
  return Math.min(storeMaximumCases(), Math.max(0, Math.floor(Number(value) || 0)));
}

function branchShowcases(branch = currentStoreBranch()) {
  if (branch) {
    if (!Array.isArray(branch.showcases)) branch.showcases = [];
    return branch.showcases;
  }
  if (!Array.isArray(state?.store?.showcases)) state.store.showcases = [];
  return state.store.showcases;
}

function mirrorCurrentStoreDisplay(branch = currentStoreBranch()) {
  if (!branch) return;
  state.store.displaySuppliesInstalled = storeDisplaySuppliesInstalled(branch);
  state.store.casesInstalled = storeCaseRemaining(branch);
  state.store.showcases = branchShowcases(branch);
  state.store.showcaseCount = state.store.showcases.length;
}

function storeBranchByNumber(number = state?.store?.branchNumber || 1) {
  const branchNumber = Math.max(1, Number(number) || 1);
  return (state?.store?.branches || []).find((branch) => Number(branch?.number) === branchNumber) || null;
}

function storeLevelForPoints(points = 0) {
  // 旧保存データ互換用。現在の店舗レベルはbranch.levelで管理する。
  const value = Math.max(0, Math.floor(Number(points) || 0));
  return STORE_LEVEL_POINTS.reduce((level, threshold, index) => value >= threshold ? index + 1 : level, 1);
}

function storeDisplayLevelBonus() { return 0; }

function storeLevel(branch = currentStoreBranch()) {
  const value = branch ? branch.level : state?.store?.level;
  return Math.max(1, Math.min(20, Math.floor(Number(value) || 1)));
}

function storeRating(branch = currentStoreBranch()) {
  const value = branch ? branch.rating : state?.store?.rating;
  const numeric = Number(value);
  return Math.max(0, Math.min(100, Number.isFinite(numeric) ? Math.round(numeric) : 50));
}

function storeLevelRequirement(level) {
  return STORE_LEVEL_REQUIREMENTS.find((entry) => Number(entry.level) === Number(level)) || null;
}

function storeUpgradeStatus(branch = currentStoreBranch()) {
  const current = storeLevel(branch);
  const requirement = current >= 20 ? null : storeLevelRequirement(current + 1);
  if (!branch || !requirement) return { current, requirement, complete: current >= 20, conditions: [] };
  const conditions = [
    { id: 'days', label: '累計営業日数', current: Math.max(0, Number(branch.operatingDays) || 0), target: requirement.operatingDays },
    { id: 'sales', label: '累計販売数', current: Math.max(0, Number(branch.salesCount) || 0), target: requirement.sales },
    { id: 'revenue', label: '累計売上', current: Math.max(0, Number(branch.totalRevenue) || 0), target: requirement.revenue, money: true },
    { id: 'service', label: '接客成功数', current: Math.max(0, Number(branch.serviceSuccesses) || 0), target: requirement.serviceSuccesses },
  ].map((condition) => ({ ...condition, met: condition.current >= condition.target }));
  const alreadyPaid = Math.max(1, Number(branch.paidThroughLevel) || 1) >= requirement.level;
  const cost = alreadyPaid ? 0 : requirement.cost;
  return { current, requirement, conditions, cost, alreadyPaid, complete: conditions.every((condition) => condition.met) && state.game.money >= cost && storeBranchOperating(branch) };
}

function syncStoreLevel(branch = currentStoreBranch()) {
  if (branch) {
    branch.level = storeLevel(branch);
    branch.peakLevel = Math.max(branch.level, Math.floor(Number(branch.peakLevel) || branch.level));
    branch.rating = storeRating(branch);
    state.store.level = branch.level;
    state.store.rating = branch.rating;
    return branch.level;
  }
  state.store.level = storeLevel(null);
  state.store.rating = storeRating(null);
  return state.store.level;
}

function addStoreProgress({ branchNumber = state?.store?.branchNumber || 1, rating = 0, sale = false, orderDelivery = false, revenue = 0, serviceSuccess = false } = {}) {
  const branch = storeBranchByNumber(branchNumber);
  if (!branch) return null;
  let ratingDelta = Math.round(Number(rating) || 0);
  if (sale) {
    branch.salesCount = Math.max(0, Math.floor(Number(branch.salesCount) || 0)) + 1;
    branch.totalRevenue = Math.max(0, Math.floor(Number(branch.totalRevenue) || 0)) + Math.max(0, Math.floor(Number(revenue) || 0));
    if (serviceSuccess) branch.serviceSuccesses = Math.max(0, Math.floor(Number(branch.serviceSuccesses) || 0)) + 1;
    if (branch.salesCount % 5 === 0) ratingDelta += 1;
  }
  if (orderDelivery) branch.orderDeliveries = Math.max(0, Math.floor(Number(branch.orderDeliveries) || 0)) + 1;
  branch.rating = Math.max(0, Math.min(100, storeRating(branch) + ratingDelta));
  syncStoreLevel(branch);
  return branch;
}

function upgradeStoreLevel(branch = currentStoreBranch()) {
  const status = storeUpgradeStatus(branch);
  if (!branch || !status.requirement) return showToast('店舗は最大レベルです。');
  if (!status.complete) return showToast('店舗改装の条件を満たしていません。', 'error');
  if (status.cost > 0) {
    state.game.money -= status.cost;
    startMoneyFeedback(-status.cost);
    addFinance(`${storeBranchLabel(branch.number)}を店舗レベル${status.requirement.level}へ改装`, 0, status.cost);
    branch.paidThroughLevel = Math.max(Number(branch.paidThroughLevel) || 1, status.requirement.level);
  }
  branch.level = status.requirement.level;
  branch.peakLevel = Math.max(Number(branch.peakLevel) || 1, branch.level);
  syncStoreLevel(branch);
  addNotification('店舗レベルが上がりました', `${storeBranchLabel(branch.number)}が店舗レベル${branch.level}になりました。`);
  saveGame();
  showToast(`店舗レベル${branch.level}になりました。`, 'info', false);
  render();
}

function applyStoreLevelPenalty(branch, levels = 1, reason = '店舗の信用が低下しました') {
  if (!branch) return 1;
  const amount = Math.max(1, Math.min(2, Math.floor(Number(levels) || 1)));
  const before = storeLevel(branch);
  branch.level = Math.max(1, before - amount);
  branch.peakLevel = Math.max(Number(branch.peakLevel) || before, before);
  syncStoreLevel(branch);
  if (branch.level < before) addNotification('店舗レベルが低下しました', `${storeBranchLabel(branch.number)}：${reason} Lv.${before} → Lv.${branch.level}`, 'warning');
  return branch.level;
}

function salesStoreBranch() {
  const selected = currentStoreBranch();
  if (storeBranchOperating(selected)) return selected;
  return (state?.store?.branches || []).find((branch) => storeBranchOperating(branch)) || null;
}

function consumeStoreCase(branch = salesStoreBranch() || currentStoreBranch()) {
  const remaining = storeCaseRemaining(branch);
  if (remaining <= 0) return false;
  const nextRemaining = remaining - 1;
  if (branch) branch.casesInstalled = nextRemaining;
  state.store.casesInstalled = nextRemaining;
  syncStoreLevel(branch);
  if (nextRemaining === 0) {
    addNotification(
      'ケースが0個になりました',
      `${storeBranchLabel(branch?.number || state.store.branchNumber)}のケースがなくなりました。ディスプレイ屋で購入し、店頭設備から補充してください。`,
      'warning',
    );
  }
  return true;
}

function findEmptyShowcasePosition(branch = currentStoreBranch()) {
  const showcases = branchShowcases(branch);
  for (let showcaseIndex = 0; showcaseIndex < showcases.length; showcaseIndex += 1) {
    const showcase = showcases[showcaseIndex];
    const slotIndex = (showcase?.slots || []).findIndex((slot) => !slot);
    if (slotIndex >= 0) return { showcaseIndex, slotIndex };
  }
  return null;
}

function facilityUnlocked(id) {
  return Boolean(state?.facilities?.[id]);
}

const OKACHIMACHI_CLOSE_MINUTES = 18 * 60;
const OKACHIMACHI_FACILITY_SCREENS = Object.freeze({
  supplier: 'materialShop', supplierMetals: 'materialShop', supplierMetalHistory: 'materialShop', pureMetalProfessionalGuide: 'materialShop', supplierRough: 'looseShop',
  looseShop: 'looseShop',
  glab: 'glab', glabSns: 'glab', glabTool: 'glab', glabToolGuide: 'glab',
  jewelryShop: 'jewelryShop', settingShop: 'settingShop', castingShop: 'castingShop',
  displayShop: 'displayShop', realEstate: 'realEstate', recruitment: 'recruitment',
});

function facilityIdForScreen(screenName) {
  return OKACHIMACHI_FACILITY_SCREENS[screenName] || '';
}

function glabAnnualHoliday(date = gameDate()) {
  const month = date.getMonth() + 1;
  const day = date.getDate();
  return (month === 12 && day === 31) || (month === 1 && (day === 1 || day === 2));
}

function okachimachiFacilityAvailability(id, date = gameDate(), minutes = state?.game?.minutes ?? 9 * 60) {
  if (!facilityUnlocked(id)) {
    return { open: false, status: '未解放', reason: 'この施設はまだ利用できません。' };
  }

  if (id === 'glab') {
    if (glabAnnualHoliday(date)) {
      return { open: false, status: '休業', reason: 'g-Lab.は12月31日、1月1日、1月2日は休業です。' };
    }
  } else {
    const holidayName = japaneseHolidayName(date);
    if (date.getDay() === 0 || date.getDay() === 6 || holidayName) {
      return { open: false, status: '休業', reason: holidayName ? `本日は${holidayName}のため休業です。` : '本日は土日のため休業です。' };
    }
  }

  if (minutes >= OKACHIMACHI_CLOSE_MINUTES) {
    return { open: false, status: '営業時間外', reason: '御徒町の施設を利用できるのは18:00までです。' };
  }

  return { open: true, status: '営業中', reason: '' };
}

function facilityButton({ id, label, screen, primary = false }) {
  const buttonClass = primary ? 'primary-button' : 'secondary-button';
  const facilityAttribute = `data-facility="${esc(id)}"`;
  if (!facilityUnlocked(id)) {
    return `<button type="button" class="${buttonClass} full-button facility-locked" ${facilityAttribute} disabled aria-disabled="true"><span>${esc(label)}</span><small>未解放</small></button>`;
  }
  const availability = okachimachiFacilityAvailability(id);
  if (!availability.open) {
    return `<button type="button" class="${buttonClass} full-button facility-closed" ${facilityAttribute} disabled aria-disabled="true" title="${esc(availability.reason)}"><span>${esc(label)}</span><small>${esc(availability.status)}</small></button>`;
  }
  return `<button class="${buttonClass} full-button" ${facilityAttribute} data-action="nav" data-screen="${screen}">${esc(label)}</button>`;
}

function storeNameEntry(buttonAction, buttonLabel) {
  return `
    <label class="name-entry-field">
      <span>店舗名</span>
      <input id="store-name-input" type="text" maxlength="30" autocomplete="organization" enterkeyhint="done" placeholder="店舗名を入力">
    </label>
    <p class="small-note">契約した店舗は「店舗1」「店舗2」「店舗3」として選択できます。</p>
    <button class="primary-button full-button" data-action="${buttonAction}">${buttonLabel}</button>`;
}

function clamp(value, min, max) {
  return Math.max(min, Math.min(max, Number(value) || 0));
}

function roughDisplayName(id) {
  const gem = GEMS[id];
  return gem?.roughName || (gem ? `${gem.name}原石` : '原石');
}

function roughVisual(id, className = 'gem-thumb', alt = '') {
  const gem = GEMS[id];
  if (!gem) return '';
  return `<img class="${className}" src="./assets/images/gems/${gem.id}.png" alt="${esc(alt || roughDisplayName(id))}">`;
}

function looseVisual(id, className = 'loose-inline', alt = '', shapeId = 'default') {
  const gem = GEMS[id];
  if (!gem) return '';
  const resolvedShape = shapeId === 'default' ? defaultLooseShapeForGem(id) : normalizeLooseShape(id, shapeId);
  const imagePath = looseImagePath(id, resolvedShape);
  const label = alt || looseDisplayLabel(id, resolvedShape, { suffix: true });
  if (imagePath) return `<img class="${className} loose-image" src="${imagePath}" alt="${esc(label)}">`;
  return `<span class="${className}" style="--gem:${gem.hue}" role="img" aria-label="${esc(label)}">◆</span>`;
}

function metalVisual(id, className = 'metal-inline-visual', alt = '') {
  const metal = METALS[id];
  if (!metal) return '';
  const imageMap = {
    gold: './assets/images/metals/k18yg.png',
    platinum: './assets/images/metals/pt900.png',
    silver: './assets/images/metals/sv925.png',
  };
  const imagePath = imageMap[id] || '';
  const label = alt || `${metal.shortName || metal.alloy || metal.name}地金`;
  if (imagePath) return `<img class="${className} metal-visual-${esc(id)}" src="${imagePath}" alt="${esc(label)}" draggable="false">`;
  return '';
}

function jewelryItemVisual(itemId, className = 'jewelry-item-shape', useLoose = true) {
  if (!ITEMS[itemId]) return '';
  const itemClass = itemId === 'ring' && useLoose === false ? 'item-ring-plain' : `item-${itemId}`;
  return `<span class="${className} ${itemClass}" aria-hidden="true"></span>`;
}

function jewelryLooseSetVisual(itemId, gemId, shapeId = 'default', mode = 'large') {
  const gem = GEMS[gemId];
  if (!gem) return '';
  const isSmall = mode === 'small';
  const isCompletion = mode === 'completion';
  const isShowcaseSmall = mode === 'showcaseSmall';
  const looseClass = (isSmall || isShowcaseSmall) ? 'small-jewelry-loose' : 'jewelry-loose-preview';
  const wrapperClass = (isSmall || isShowcaseSmall) ? 'jewelry-loose-set small' : 'jewelry-loose-set';
  const completionGemPx = itemId === 'pendant' ? 62 : itemId === 'ring' ? 72 : itemId === 'earrings' ? 58 : 76;
  const showcaseSmallGemPx = itemId === 'pendant' ? 16 : itemId === 'ring' ? 18 : itemId === 'earrings' ? 15 : 19;
  const resolvedGemPx = isCompletion ? completionGemPx : isShowcaseSmall ? showcaseSmallGemPx : 0;
  const styleLooseMarkup = (markup, sizePercent = '100%') => {
    if (typeof markup !== 'string' || !markup) return markup;
    if (markup.startsWith('<img ')) {
      const completionStyle = (isCompletion || isShowcaseSmall)
        ? `display:block;width:100%;height:auto;max-width:${resolvedGemPx}px;max-height:${resolvedGemPx}px;object-fit:contain;position:relative;z-index:5;pointer-events:none;`
        : `display:block;width:${sizePercent};height:auto;max-width:none;object-fit:contain;position:relative;z-index:5;pointer-events:none;`;
      return markup.replace('<img ', `<img style="${completionStyle}" `);
    }
    const renderSize = (isCompletion || isShowcaseSmall) ? '100%' : sizePercent;
    return `<span style="display:inline-flex;align-items:center;justify-content:center;width:${renderSize};height:${renderSize};position:relative;z-index:5;pointer-events:none;">${markup}</span>`;
  };
  const looseSize = isSmall ? '112%' : (isCompletion || isShowcaseSmall) ? '100%' : '120%';
  const single = styleLooseMarkup(looseVisual(gemId, looseClass, '', shapeId), looseSize);
  if (itemId === 'earrings') {
    const pair = styleLooseMarkup(looseVisual(gemId, looseClass, '', shapeId), looseSize);
    const slotWidth = isSmall ? '21%' : (isCompletion || isShowcaseSmall) ? `${resolvedGemPx}px` : '23%';
    // v0.10.646: completion earrings are positioned against the actual earring-art stage,
    // so each loose sits on the center of the round top plate instead of the full preview width.
    // v0.10.672: showcaseSmall ring/pendant now use centered small-artwork stages so their stone placement matches Workshop completion proportions.
    // v0.10.671: store showcase earrings use the same round-top-plate centers as Workshop completion.
    // The mask is scaled with contain inside the earring artwork, so these stage-relative centers remain valid at showcase size.
    const slotTop = isSmall ? '33%' : (isCompletion || isShowcaseSmall) ? '20.5%' : '31%';
    const leftX = isSmall ? '28.5%' : (isCompletion || isShowcaseSmall) ? '24.8%' : '29%';
    const rightX = isSmall ? '71.5%' : (isCompletion || isShowcaseSmall) ? '74.7%' : '71%';
    const maxWidthPx = isShowcaseSmall ? showcaseSmallGemPx : completionGemPx;
    return `<span class="${wrapperClass} item-earrings" aria-hidden="true" style="position:absolute;inset:0;display:block;pointer-events:none;z-index:3;overflow:visible;">
      <span class="center-gem earring-left" style="position:absolute;left:${leftX};top:${slotTop};width:${slotWidth};max-width:${maxWidthPx}px;display:flex;align-items:center;justify-content:center;transform:translate(-50%,-50%);z-index:5;pointer-events:none;">${single}</span>
      <span class="center-gem earring-right" style="position:absolute;left:${rightX};top:${slotTop};width:${slotWidth};max-width:${maxWidthPx}px;display:flex;align-items:center;justify-content:center;transform:translate(-50%,-50%);z-index:5;pointer-events:none;">${pair}</span>
    </span>`;
  }
  if (isShowcaseSmall && (itemId === 'ring' || itemId === 'pendant')) {
    const stageWidth = itemId === 'pendant' ? 40 : 54;
    const stageHeight = itemId === 'pendant' ? 58 : 54;
    const centerTop = itemId === 'pendant' ? '66%' : '57%';
    return `<span class="${wrapperClass} item-${itemId}" aria-hidden="true" style="position:absolute;left:50%;top:50%;width:${stageWidth}px;height:${stageHeight}px;display:block;pointer-events:none;z-index:3;overflow:visible;transform:translate(-50%,-50%);"><span class="center-gem" style="position:absolute;left:50%;top:${centerTop};width:${resolvedGemPx}px;max-width:${resolvedGemPx}px;min-width:0;display:grid;place-items:center;transform:translate(-50%,-50%);z-index:5;pointer-events:none;">${single}</span></span>`;
  }
  const centerStyle = (isCompletion || isShowcaseSmall)
    ? ` style="width:${resolvedGemPx}px;max-width:${resolvedGemPx}px;min-width:0;"`
    : '';
  return `<span class="${wrapperClass} item-${itemId}" aria-hidden="true"><span class="center-gem"${centerStyle}>${single}</span></span>`;
}

function equipmentVisual(itemOrId, className = 'equipment-item-image', alt = '') {
  const item = typeof itemOrId === 'string' ? EQUIPMENT_ITEMS[itemOrId] : itemOrId;
  if (!item) return '';
  const label = alt || item.name;
  if (item.image) return `<img class="${className}" src="${item.image}" alt="${esc(label)}" draggable="false">`;
  return `<span class="${className}" role="img" aria-label="${esc(label)}">${esc(item.symbol || '◇')}</span>`;
}

function showToast(message, type = 'info', withSound = true) {
  toastEl.textContent = message;
  toastEl.dataset.type = type;
  toastEl.classList.add('show');
  clearTimeout(showToast.timer);
  showToast.timer = setTimeout(() => toastEl.classList.remove('show'), 2100);
  if (withSound) playSfx(type === 'error' ? 'error' : type === 'sale' ? 'sale' : 'select');
  scheduleWinterColdTextEffect();
}

function showModal({ title = '', body = '', confirm = '決定', cancel = 'キャンセル', cancelAction = 'modal-close', confirmDisabled = false, danger = false, hideCancel = false, hideActions = false, action = '', className = '' }) {
  modalEl.innerHTML = `
    <div class="modal-backdrop">
      <section class="modal-card ${esc(className)}" role="dialog" aria-modal="true">
        ${title ? `<h2>${esc(title)}</h2>` : ''}
        <div class="modal-body">${body}</div>
        ${hideActions ? '' : `<div class="modal-actions">
          ${hideCancel ? '' : `<button class="secondary-button" data-action="${esc(cancelAction)}">${esc(cancel)}</button>`}
          <button class="${danger ? 'danger-button' : 'primary-button'}" data-action="${esc(action)}" ${action === 'do-sleep' ? 'data-illness-readable="true"' : ''} ${confirmDisabled ? 'disabled' : ''}>${esc(confirm)}</button>
        </div>`}
      </section>
    </div>`;
  modalEl.classList.remove('hidden');
  scheduleWinterColdTextEffect();
}

function closeModal() {
  modalEl.classList.add('hidden');
  modalEl.innerHTML = '';
  queueMicrotask(() => {
    maybeShowGameClearModal();
    maybeStartForcedBirthdayRest();
  });
}

function addNotification(title, body, type = 'info') {
  const notification = { id: uid(), title, body, type, day: state.game.day, unread: true };
  if (isUnneededHungerNotification(notification)) return;
  state.notifications.unshift(notification);
  state.notifications = state.notifications.filter((note) => !isUnneededHungerNotification(note)).slice(0, 80);
}

function addFinance(label, income = 0, expense = 0) {
  state.finance.push({ id: uid(), day: state.game.day, label, income, expense });
  state.finance = state.finance.slice(-2000);
  state.daily.income += income;
  state.daily.expense += expense;
}

function robberyEventState() {
  if (!state.events || typeof state.events !== 'object') state.events = {};
  if (!state.events.robbery || typeof state.events.robbery !== 'object') {
    state.events.robbery = { lastTriggeredDay: 0, pendingReport: null, history: [] };
  }
  if (!Array.isArray(state.events.robbery.history)) state.events.robbery.history = [];
  return state.events.robbery;
}

function pendingRobberyReport() {
  const report = robberyEventState().pendingReport;
  return report && Number(report.reportDay) <= Number(state.game.day) ? report : null;
}

function robberyItemsInBranch(branch) {
  if (!branch) return [];
  const found = [];
  const seen = new Set();
  for (const showcase of branchShowcases(branch)) {
    for (const slot of showcase?.slots || []) {
      if (!slot?.jewelryId || seen.has(slot.jewelryId)) continue;
      const item = state.inventory.jewelry.find((entry) => entry.id === slot.jewelryId && entry.status !== 'sold');
      if (!item) continue;
      seen.add(item.id);
      found.push({ item, sellingPrice: showcaseSellingPrice(slot, item) });
    }
  }
  return found;
}

function hasBokuto() {
  return Math.max(0, Math.floor(Number(state.inventory.items?.bokuto) || 0)) > 0;
}

function maybeTriggerRobberyEvent(randomValue = Math.random()) {
  if (illnessEventSuppressionActive()) return false;
  const robbery = robberyEventState();
  if (robbery.pendingReport) return null;
  const candidates = contractedStoreBranches()
    .map((branch) => ({ branch, products: robberyItemsInBranch(branch) }))
    .filter((entry) => entry.products.length > 0);
  const robberyChance = hasBokuto() ? ROBBERY_DAILY_CHANCE * WOOD_SWORD_ROBBERY_MULTIPLIER : ROBBERY_DAILY_CHANCE;
  if (!candidates.length || Number(randomValue) >= robberyChance) return null;

  const target = randomFrom(candidates, candidates[0]);
  if (!target?.branch || !target.products.length) return null;
  const branchNumber = Math.max(1, Number(target.branch.number) || 1);
  const branchLabel = storeBranchLabel(branchNumber);
  const lossAmount = target.products.reduce((sum, entry) => sum + Math.max(0, Number(entry.sellingPrice) || 0), 0);
  const incidentDay = Math.max(1, Number(state.game.day) - 1);
  const report = {
    id: `robbery-${state.game.day}-${uid()}`,
    incidentDay,
    reportDay: state.game.day,
    branchId: target.branch.id || `branch-${branchNumber}`,
    branchNumber,
    branchLabel,
    itemCount: target.products.length,
    lossAmount: Math.round(lossAmount),
    itemNames: target.products.map(({ item }) => item.name),
    stage: 'waitingMorning',
  };

  for (const { item, sellingPrice } of target.products) {
    item.stolenDay = state.game.day;
    item.stolenBranchNumber = branchNumber;
    item.stolenLossValue = Math.max(0, Math.round(Number(sellingPrice) || 0));
    removeJewelry(item.id);
  }
  mirrorCurrentStoreDisplay(currentStoreBranch());

  robbery.lastTriggeredDay = state.game.day;
  robbery.pendingReport = report;
  robbery.history.push(structuredClone(report));
  robbery.history = robbery.history.slice(-ROBBERY_HISTORY_LIMIT);
  addNotification(
    '強盗事件が発生しました',
    `${branchLabel}に強盗が入り、完成品${report.itemCount}点が盗まれました。損失額は${yen(report.lossAmount)}です。`,
    'warning',
  );
  return report;
}

function acknowledgeRobberyReport() {
  const robbery = robberyEventState();
  const report = robbery.pendingReport;
  if (report) {
    const historyEntry = robbery.history.find((entry) => entry.id === report.id);
    if (historyEntry) historyEntry.acknowledgedDay = state.game.day;
  }
  robbery.pendingReport = null;
  stopPoliceSiren();
  saveGame();
  goMain();
}

function workshopToolRecord(toolId) {
  return state?.tools?.items?.[toolId] || null;
}

function toolOwned(toolId) {
  return Boolean(workshopToolRecord(toolId));
}


function toolUsable(toolId) {
  return workshopToolRecord(toolId)?.status === 'available';
}

const CRAFTSMANSHIP_PROFILE_VERSION = 1;

function craftRelevantToolWeights(draft = {}) {
  const weights = new Map();
  const add = (toolId, weight) => {
    if (!WORKSHOP_TOOLS[toolId]) return;
    const amount = Math.max(0, Number(weight) || 0);
    if (!amount) return;
    weights.set(toolId, (weights.get(toolId) || 0) + amount);
  };

  // 基本成形。彫金机は制作必須なので、価格評価の分母には含めない。
  add('file', 3.0);
  add('pliers', 1.5);
  add('benchPeg', 1.5);
  add('piercingSaw', 1.5);
  add('nipper', 0.5);
  add('hammer', 0.75);
  add('woodBlock', 0.5);
  add('rotaryTool', 2.5);
  add('dividers', 1.5);
  add('electronicScale', 1.0);
  add('torch', 2.0);
  add('rollingMill', 1.5);
  add('loupe', 0.75);

  if (draft.item === 'ring') {
    add('rollingMill', 1.0);
    add('hammer', 0.75);
    add('dividers', 0.5);
  } else if (draft.item === 'earrings') {
    add('pliers', 0.75);
    add('nipper', 0.5);
    add('electronicScale', 0.5);
  }

  if (draft.useLoose !== false) {
    add('graver', 3.0);
    add('magnifier', 4.0);
    add('loupe', 1.5);
    add('engravingBlock', 2.5);
    add('rotaryTool', 1.0);
  }

  const finishId = String(draft.finish || 'mirror');
  if (finishId.includes('mirror')) {
    add('buffer', 4.0);
    add('ultrasonicCleaner', 2.0);
    add('rotaryTool', 1.5);
    add('loupe', 0.5);
  } else if (finishId.includes('matte')) {
    add('rotaryTool', 2.0);
    add('ultrasonicCleaner', 1.0);
    add('loupe', 0.5);
  }

  if (finishId.includes('Decorated') || finishId === 'decorated') {
    add('graver', 2.5);
    add('engravingBlock', 2.0);
    add('milgrainTool', 2.0);
    add('stamps', 1.5);
    add('magnifier', 1.5);
  }

  if (draft.design === 'modern') {
    add('computer', 1.0);
    add('cadSoftware', 2.0);
    add('printer3d', 2.0);
  } else if (draft.design === 'classic') {
    add('cadSoftware', 0.75);
  }

  return weights;
}

function processingKnowledgeKnownMatching(pattern) {
  const records = Array.isArray(state?.workshop?.processingKnowledge) ? state.workshop.processingKnowledge : [];
  return records.some((record) => {
    const id = String(record?.id || record || '');
    const document = PROCESSING_KNOWLEDGE[id];
    if (!document) return false;
    const haystack = [id, document.shortTitle, document.title, document.category].filter(Boolean).join(' ');
    return pattern.test(haystack);
  });
}

function craftKnowledgeSupport(draft = {}) {
  const labels = [];
  let scoreBonus = 0;
  const hasSizing = processingKnowledgeKnownMatching(/サイズ直し/i);
  const hasSoldering = processingKnowledgeKnownMatching(/ロー付け|ろう付け|solder/i);
  const hasFinishing = processingKnowledgeKnownMatching(/仕上げ|finishing/i);
  const hasSetting = processingKnowledgeKnownMatching(/石留め|stone\s*setting/i);

  if (draft.item === 'ring' && hasSizing) {
    labels.push('サイズ直し');
    scoreBonus += 1.0;
  }
  if (hasSoldering) {
    labels.push('ロー付け');
    scoreBonus += toolUsable('torch') ? 3.0 : 1.0;
  }
  if (hasFinishing) {
    labels.push('仕上げ');
    scoreBonus += (toolUsable('buffer') || toolUsable('rotaryTool')) ? 3.0 : 1.0;
  }
  if (draft.useLoose !== false && hasSetting) {
    labels.push('石留め');
    scoreBonus += (toolUsable('graver') || toolUsable('magnifier')) ? 4.0 : 1.5;
  }
  return { labels: [...new Set(labels)], scoreBonus: Math.min(10, scoreBonus), hasSizing, hasSoldering, hasFinishing, hasSetting };
}

function craftProductionTags(draft = {}, knowledge = craftKnowledgeSupport(draft)) {
  const tags = [];
  const allUsable = (...toolIds) => toolIds.every((toolId) => toolUsable(toolId));
  if (allUsable('file', 'rotaryTool', 'dividers')) tags.push('精密成形');
  if (knowledge.hasSoldering && allUsable('torch', 'file')) tags.push('安定ロー付け');
  if (draft.useLoose !== false && knowledge.hasSetting && allUsable('graver', 'magnifier', 'engravingBlock')) tags.push('精密石留め');
  if (knowledge.hasFinishing && allUsable('rotaryTool', 'buffer', 'ultrasonicCleaner')) tags.push('プロ仕上げ');
  if (allUsable('magnifier', 'loupe')) tags.push('高精度検品');
  const finishId = String(draft.finish || '');
  if ((finishId.includes('Decorated') || finishId === 'decorated') && allUsable('graver', 'engravingBlock', 'milgrainTool')) tags.push('意匠加工');
  if (draft.design === 'modern' && allUsable('computer', 'cadSoftware', 'printer3d')) tags.push('CAD設計');
  return tags;
}

function craftProductionProfile(draft = {}, options = {}) {
  const toolWeights = craftRelevantToolWeights(draft);
  const totalWeight = [...toolWeights.values()].reduce((total, weight) => total + weight, 0);
  let usableWeight = 0;
  let usableCount = 0;
  let ownedCount = 0;
  const missing = [];
  for (const [toolId, weight] of toolWeights.entries()) {
    if (toolOwned(toolId)) ownedCount += 1;
    if (toolUsable(toolId)) {
      usableWeight += weight;
      usableCount += 1;
    } else {
      missing.push({ toolId, weight, name: WORKSHOP_TOOLS[toolId]?.name || toolId, owned: toolOwned(toolId) });
    }
  }
  missing.sort((a, b) => b.weight - a.weight || a.name.localeCompare(b.name, 'ja'));
  const toolRatio = totalWeight > 0 ? Math.max(0, Math.min(1, usableWeight / totalWeight)) : 1;
  const knowledge = craftKnowledgeSupport(draft);
  const tags = craftProductionTags(draft, knowledge);
  const artisanLevel = Math.max(1, Math.min(20, Math.floor(Number(options.artisanLevel ?? state?.artisan?.level) || 1)));

  // 工具の有無を価格へ強く反映。設備不足0.78倍～十分な設備1.25倍。
  const equipmentMultiplier = 0.78 + (toolRatio * 0.47);
  // 職人レベルは0.90～1.10倍。設備だけで熟練差を完全には埋められない。
  const artisanMultiplier = 0.90 + ((artisanLevel - 1) / 19) * 0.20;
  // 加工知識は該当工程で最大+10%。工具と組み合わさると評価が高くなる。
  const knowledgeMultiplier = 1 + (knowledge.scoreBonus * 0.01);
  // 工具セットが成立した場合は相乗効果。最大+7.5%。
  const setMultiplier = 1 + Math.min(0.075, tags.length * 0.015);
  const priceMultiplier = Math.max(0.72, Math.min(1.55, equipmentMultiplier * artisanMultiplier * knowledgeMultiplier * setMultiplier));

  const craftsmanshipScore = Math.max(20, Math.min(100, Math.round(
    28
    + ((artisanLevel - 1) / 19) * 28
    + toolRatio * 36
    + Math.min(8, knowledge.scoreBonus)
    + Math.min(5, tags.length)
  )));
  const tier = craftsmanshipScore >= 95 ? '最高級'
    : craftsmanshipScore >= 85 ? '高精度'
      : craftsmanshipScore >= 72 ? '良好'
        : craftsmanshipScore >= 55 ? '標準'
          : '設備不足';

  return {
    version: CRAFTSMANSHIP_PROFILE_VERSION,
    artisanLevel,
    craftsmanshipScore,
    tier,
    toolRatio,
    usableToolCount: usableCount,
    ownedToolCount: ownedCount,
    relevantToolCount: toolWeights.size,
    usableWeight,
    totalWeight,
    equipmentMultiplier,
    artisanMultiplier,
    knowledgeMultiplier,
    setMultiplier,
    priceMultiplier,
    knowledgeLabels: knowledge.labels,
    tags,
    missingTools: missing.slice(0, 5),
  };
}

function craftsmanshipRecommendedPrice(draft = {}, quality = 'standard', profile = craftProductionProfile(draft)) {
  const basePrice = recommendedPrice({ ...draft, quality });
  const cost = Math.max(0, Number(productionCost(draft)) || 0);
  const adjusted = roundThousand(basePrice * Math.max(0.1, Number(profile?.priceMultiplier) || 1));
  return Math.max(roundThousand(cost * 1.2), adjusted);
}

function craftsmanshipSnapshot(profile = {}) {
  return {
    craftsmanshipProfileVersion: Number(profile.version) || CRAFTSMANSHIP_PROFILE_VERSION,
    craftsmanshipScore: Math.max(0, Math.round(Number(profile.craftsmanshipScore) || 0)),
    craftsmanshipTier: String(profile.tier || ''),
    craftsmanshipPriceMultiplier: Math.round((Number(profile.priceMultiplier) || 1) * 1000) / 1000,
    craftsmanshipToolRatio: Math.round((Number(profile.toolRatio) || 0) * 1000) / 1000,
    craftsmanshipUsableTools: Math.max(0, Math.floor(Number(profile.usableToolCount) || 0)),
    craftsmanshipRelevantTools: Math.max(0, Math.floor(Number(profile.relevantToolCount) || 0)),
    craftsmanshipTags: Array.isArray(profile.tags) ? profile.tags.slice(0, 12) : [],
    craftsmanshipKnowledge: Array.isArray(profile.knowledgeLabels) ? profile.knowledgeLabels.slice(0, 12) : [],
  };
}

function workshopToolUnlockConditionsMet(tool) {
  const unlock = tool?.unlock;
  if (!unlock?.enabled) return false;

  const requiredTools = Array.isArray(unlock.requiresOwned) ? unlock.requiresOwned : [];
  if (requiredTools.some((toolId) => !toolOwned(toolId))) return false;

  const minimumArtisanLevel = Math.max(0, Number(unlock.minArtisanLevel) || 0);
  if (minimumArtisanLevel && Number(state?.artisan?.level || 0) < minimumArtisanLevel) return false;

  const minimumWorkshopLevel = Math.max(0, Number(unlock.minWorkshopLevel) || 0);
  if (minimumWorkshopLevel && workshopLevel() < minimumWorkshopLevel) return false;

  const minimumMiningFinds = Math.max(0, Number(unlock.minMiningFinds) || 0);
  if (minimumMiningFinds && Number(state?.miningProgress?.successfulFinds || 0) < minimumMiningFinds) return false;

  const minimumCrafted = Math.max(0, Number(unlock.minCrafted) || 0);
  const craftedCount = Number(state?.daily?.crafted?.length || 0)
    + Number(state?.inventory?.jewelry?.length || 0)
    + Number(state?.store?.salesCount || 0);
  if (minimumCrafted && craftedCount < minimumCrafted) return false;

  const minimumStores = Math.max(0, Number(unlock.minStores) || 0);
  const storeCount = Array.isArray(state?.store?.branches) ? state.store.branches.length : Number(Boolean(state?.store?.rented));
  if (minimumStores && storeCount < minimumStores) return false;

  const requiredFlag = String(unlock.requiredFlag || '');
  if (requiredFlag && !state?.progressFlags?.[requiredFlag]) return false;

  return true;
}

function workshopToolUnlocked(toolOrId) {
  const tool = typeof toolOrId === 'string' ? WORKSHOP_TOOLS[toolOrId] : toolOrId;
  return Boolean(tool && (tool.initiallyAvailable || workshopToolUnlockConditionsMet(tool)));
}

function workshopToolCatalogVisible(tool) {
  return Boolean(tool && Number(tool.price) > 0 && (tool.initiallyAvailable || tool.unlock?.enabled));
}

function workshopToolUnlockLevel(tool) {
  if (!tool || tool.initiallyAvailable) return 1;
  return Math.max(1, Number(tool.unlock?.minWorkshopLevel) || 1);
}

function workshopToolRepairPrice(toolId) {
  const price = Number(WORKSHOP_TOOLS[toolId]?.price || 0);
  return Math.max(1000, Math.round((price * 0.60) / 1000) * 1000);
}

function workshopToolFailureDueDay(toolId, fromDay = state.game.day) {
  const definition = WORKSHOP_TOOLS[toolId];
  if (!definition?.breakable) return null;
  const prices = Object.values(WORKSHOP_TOOLS).filter((tool) => tool.breakable && tool.price > 0).map((tool) => tool.price);
  const minimumPrice = Math.min(...prices);
  const maximumPrice = Math.max(...prices);
  const ratio = maximumPrice > minimumPrice ? Math.max(0, Math.min(1, (definition.price - minimumPrice) / (maximumPrice - minimumPrice))) : 0.5;
  const minimumDays = Math.round(90 + ratio * 45);
  const maximumDays = Math.round(120 + ratio * 60);
  return Math.max(1, Number(fromDay) || state.game.day) + minimumDays + Math.floor(Math.random() * (maximumDays - minimumDays + 1));
}

function createWorkshopToolRecord(toolId, acquiredDay = state.game.day) {
  return {
    id: toolId,
    status: 'available',
    acquiredDay: Math.max(1, Number(acquiredDay) || state.game.day),
    failureDueDay: workshopToolFailureDueDay(toolId, acquiredDay),
    repairCompleteDay: null,
  };
}

function syncLegacyToolFlags() {
  if (!state?.tools) return;
  state.tools.jewelryBench = toolOwned('jewelryBench');
  state.tools.jewelryBenchDay = workshopToolRecord('jewelryBench')?.acquiredDay || null;
  state.tools.polishingMachine = toolOwned('polishingMachine');
  state.tools.polishingMachineDay = workshopToolRecord('polishingMachine')?.acquiredDay || null;
}

function workshopQualityPoints() {
  return Object.entries(state?.tools?.items || {}).reduce((total, [toolId, record]) => {
    if (!record || record.status !== 'available') return total;
    return total + Math.max(0, Number(WORKSHOP_TOOLS[toolId]?.qualityPoints) || 0);
  }, 0);
}

function workshopLevel() {
  return Math.max(1, Math.min(20, Math.floor(Number(state?.workshop?.level) || 1)));
}

function workshopLevelRequirement(level = workshopLevel() + 1) {
  return WORKSHOP_LEVEL_REQUIREMENTS.find((entry) => Number(entry.level) === Number(level)) || null;
}

function cumulativeWorkshopRequiredTools(level = workshopLevel() + 1) {
  const required = new Set();
  WORKSHOP_LEVEL_REQUIREMENTS.filter((entry) => entry.level <= Math.min(8, level)).forEach((entry) => (entry.requiredTools || []).forEach((id) => required.add(id)));
  return [...required];
}

function workshopUpgradeStatus() {
  const current = workshopLevel();
  const requirement = current >= 20 ? null : workshopLevelRequirement(current + 1);
  if (!requirement) return { current, requirement: null, complete: true, conditions: [], cost: 0 };
  const missingTools = cumulativeWorkshopRequiredTools(requirement.level).filter((id) => !toolUsable(id));
  const activeHours = Math.max(0, Number(state?.workshop?.activeHours) || 0);
  const quality = workshopQualityPoints();
  const alreadyPaid = Math.max(1, Number(state?.workshop?.paidThroughLevel) || 1) >= requirement.level;
  const cost = alreadyPaid ? 0 : requirement.cost;
  const conditions = [
    { id: 'hours', label: '累計工房稼働実績', current: activeHours, target: requirement.hours, suffix: '時間', met: activeHours >= requirement.hours },
    { id: 'quality', label: '工房評価', current: quality, target: requirement.quality, suffix: '', met: quality >= requirement.quality },
    { id: 'tools', label: '必須工具・設備', current: missingTools.length ? `不足 ${missingTools.length}点` : '使用可能', target: 'すべて', suffix: '', met: missingTools.length === 0, missingTools },
  ];
  return { current, requirement, conditions, cost, alreadyPaid, missingTools, complete: conditions.every((condition) => condition.met) && state.game.money >= cost && workshopOperating() };
}

function workshopExpansionCost() {
  return workshopUpgradeStatus().cost;
}

function addWorkshopActiveHours(hours) {
  const gain = Math.max(0, Number(hours) || 0);
  if (!gain) return;
  state.workshop.activeHours = Math.round((Math.max(0, Number(state.workshop.activeHours) || 0) + gain) * 10) / 10;
}

function applyWorkshopLevelPenalty(levels = 1, reason = '工房の機能が低下しました') {
  const amount = Math.max(1, Math.min(2, Math.floor(Number(levels) || 1)));
  const before = workshopLevel();
  state.workshop.level = Math.max(1, before - amount);
  state.workshop.peakLevel = Math.max(Number(state.workshop.peakLevel) || before, before);
  if (state.workshop.level < before) addNotification('工房レベルが低下しました', `${reason} Lv.${before} → Lv.${state.workshop.level}`, 'warning');
  return state.workshop.level;
}

function workshopToolStatusText(toolId, record = workshopToolRecord(toolId)) {
  if (!record) return '未所持';
  if (record.status === 'unusable') return '使用不能';
  if (record.status === 'repairing') return `修理中・あと${Math.max(0, Number(record.repairCompleteDay || 0) - state.game.day)}日`;
  return '使用可能';
}

function workshopToolImageSrc(tool) {
  return `${tool?.image || './assets/images/tools/placeholder.svg'}?v=${VERSION}`;
}

function showWorkshopToolDetail(toolId) {
  const tool = WORKSHOP_TOOLS[toolId];
  if (!tool) return;
  const record = workshopToolRecord(toolId);
  showModal({
    title: tool.name,
    body: `<div class="tool-detail-modal">
      <img src="${workshopToolImageSrc(tool)}" alt="${esc(tool.name)}の工具・設備画像">
      <p>${esc(tool.detail || tool.description)}</p>
      <div class="tool-detail-meta"><span>${esc(tool.type)}</span><span>工房評価 ＋${tool.qualityPoints}</span>${record ? `<span>${esc(workshopToolStatusText(toolId, record))}</span>` : ''}</div>
    </div>`,
    confirm: '閉じる', action: 'modal-close', hideCancel: true,
  });
}

function checkWorkshopToolFailure() {
  const dueTools = Object.entries(state?.tools?.items || {}).filter(([toolId, record]) => {
    const definition = WORKSHOP_TOOLS[toolId];
    return Boolean(record && record.status === 'available' && definition?.breakable && Number(record.failureDueDay || Infinity) <= state.game.day);
  });
  if (!dueTools.length) return '';
  const [toolId, record] = dueTools[Math.floor(Math.random() * dueTools.length)];
  const definition = WORKSHOP_TOOLS[toolId];
  if (definition.repairable) {
    record.status = 'unusable';
    record.failureDueDay = null;
    record.repairCompleteDay = null;
  } else {
    state.tools.items[toolId] = null;
  }
  syncLegacyToolFlags();
  return definition.name;
}

function processCompletedWorkshopRepairs() {
  const messages = [];
  for (const [toolId, record] of Object.entries(state?.tools?.items || {})) {
    if (!record || record.status !== 'repairing' || Number(record.repairCompleteDay || Infinity) > state.game.day) continue;
    const tool = WORKSHOP_TOOLS[toolId];
    record.status = 'available';
    record.repairCompleteDay = null;
    record.failureDueDay = workshopToolFailureDueDay(toolId, state.game.day);
    const message = `${tool.name}が修理を終えました`;
    messages.push(message);
    addNotification(`${tool.name}の修理が完了しました`, `${tool.name}が使用できるようになりました。`);
  }
  if (messages.length) {
    state.tools.morningMessages = [...(state.tools.morningMessages || []), ...messages].slice(-10);
  }
  syncLegacyToolFlags();
  return messages;
}

function canSpendMinutes(minutes) {
  return state.game.minutes + Math.max(0, Math.round(Number(minutes) || 0)) <= DAY_END_MINUTES;
}

function canSpendHours(hours) {
  return canSpendMinutes(Number(hours) * 60);
}

function canSpendMealTime() {
  return canSpendMinutes(MEAL_DURATION_MINUTES);
}

function spendMealTime() {
  // v0.10.612: 食事は1時間経過するが、その1時間では空腹度を消費しない。
  spendMinutes(MEAL_DURATION_MINUTES, { consumeHunger: false });
}

function mealTimeUnavailableMessage() {
  return '今日は食事をする時間がありません。';
}

function hasCraftedJewelry() {
  return Boolean(state && (state.artisan.xp > 0 || state.inventory.jewelry.length > 0 || state.store.salesCount > 0));
}

function specialOrderCustomerVisiting() {
  return Boolean(state?.customers?.brownBunny?.visiting);
}

function canServeCustomers() {
  return Boolean(state?.store?.rented && storeBusinessOpen() && storeBranchOperating(currentStoreBranch()) && (hasCraftedJewelry() || specialOrderCustomerVisiting()));
}

function canAcceptOrders() {
  return Boolean(state?.store?.rented && storeBusinessOpen() && storeBranchOperating(currentStoreBranch()) && workshopOperating() && toolUsable('jewelryBench'));
}

function hungerLevel() {
  return Math.max(0, Math.min(7, Math.round(Number(state?.wellbeing?.hunger) || 0)));
}

function hungerLocked() {
  return Boolean(state && hungerLevel() <= 0);
}

function alienHungerEmergency() {
  return Boolean(isAlienAbducted() && hungerLocked() && Number(state?.game?.minutes) < SLEEP_UNLOCK_MINUTES);
}

function hasSelectableRegularMeal() {
  if (!state) return false;
  return Object.values(MEALS).some((meal) => {
    if (Number(state.game.money) < Number(meal.price)) return false;
    return !(Number(state.wellbeing.mealsEaten) > 0 && state.wellbeing.lastMeal === meal.id);
  });
}

function canSleepNow() {
  if (!state) return false;
  if (winterColdTextActive()) return true;
  // v0.10.552: 誕生日当日は時刻に関係なく「寝る」から誕生日イベントへ入れる。
  if (birthdaySleepAvailableToday()) return true;
  // 宇宙滞在中は食事へ移動できない。19時以降、または空腹度0なら必ず就寝できる。
  // この判定を地球上の食事可否から完全に分離し、宇宙での進行不能を防ぐ。
  if (isAlienAbducted()) return Number(state.game.minutes) >= SLEEP_UNLOCK_MINUTES || hungerLocked();
  if (Number(state.game.minutes) >= SLEEP_UNLOCK_MINUTES) return true;
  return hungerLocked() && !hasSelectableRegularMeal();
}

function sleepRestrictionMessage() {
  if (isAlienAbducted()) return '宇宙では19時になるまで寝られません。空腹度が0の場合は、すぐに休めます。';
  return '19時になるまで寝られません。空腹で選べる食事がない場合は、19時前でも寝られます。';
}

function hungerPips(level = hungerLevel()) {
  const safe = Math.max(0, Math.min(7, Number(level) || 0));
  return `<span class="hunger-pips" aria-label="空腹度 ${safe}／7">${Array.from({ length: 7 }, (_, index) => `<i class="${index < safe ? 'filled' : ''}"></i>`).join('')}</span>`;
}

function spendMinutes(minutes, { consumeHunger = true } = {}) {
  const elapsedMinutes = Math.max(0, Math.round(Number(minutes) || 0));
  const hungerCost = consumeHunger ? Math.floor(elapsedMinutes / 60) : 0;
  const before = hungerLevel();
  const beforeMinutes = state.game.minutes;
  state.game.minutes = Math.min(DAY_END_MINUTES, state.game.minutes + elapsedMinutes);
  const storeOpenStart = Math.max(beforeMinutes, STORE_OPEN_MINUTES);
  const storeOpenEnd = Math.min(state.game.minutes, STORE_CLOSE_MINUTES);
  const storeElapsed = Math.max(0, storeOpenEnd - storeOpenStart);
  if (storeElapsed > 0) contractedStoreBranches().filter((branch) => storeBranchOperating(branch)).forEach((branch) => { branch.openMinutesToday = Math.max(0, Number(branch.openMinutesToday) || 0) + storeElapsed; });
  processWorkshopStaffElapsedTime(beforeMinutes, state.game.minutes);
  if (beforeMinutes < STORE_CLOSE_MINUTES && state.game.minutes >= STORE_CLOSE_MINUTES) closeVisitingCustomersAtStoreClosing();
  state.wellbeing.hunger = Math.max(0, before - hungerCost);
  // v0.10.552: 現行ゲームでは空腹度が行動可能量を兼ねる。
  // 誕生日当日に空腹度が1以下へ到達したら、現在の行動結果を反映した後で強制休息へ移る。
  if (consumeHunger && birthdaySleepAvailableToday() && state.wellbeing.hunger <= 1) {
    const birthdayEvent = birthdaySleepEventState();
    birthdayEvent.restPending = true;
    birthdayEvent.triggerReason = 'energy';
  }
}

function spendHours(hours) {
  spendMinutes(Math.max(0, Math.round(Number(hours) || 0)) * 60);
}

function weatherIcon(label) {
  const common = 'class="weather-icon-svg" viewBox="0 0 24 24" aria-hidden="true" focusable="false"';
  const weather = String(label || '');
  if (weather === '雪') {
    return `<svg ${common}><path d="M11 2h2v5.05l3.57-3.57 1.42 1.42L14.4 8.5H19.5v2h-5.1l3.59 3.59-1.42 1.42L13 11.95V17h-2v-5.05l-3.57 3.56-1.42-1.42L9.6 10.5H4.5v-2h5.1L6.01 4.9l1.42-1.42L11 7.05V2Zm0 17h2v3h-2v-3Z" fill="currentColor"/></svg>`;
  }
  if (weather === '雨') {
    return `<svg ${common}><path d="M7.6 17.2h9.05a4.35 4.35 0 0 0 .44-8.68A6.2 6.2 0 0 0 5.36 7.1 5.1 5.1 0 0 0 7.6 17.2Z" fill="currentColor"/><path d="m8.2 18.2-1.1 3h2l1.1-3h-2Zm4 0-1.1 3h2l1.1-3h-2Zm4 0-1.1 3h2l1.1-3h-2Z" fill="currentColor"/></svg>`;
  }
  if (weather === '曇り') {
    return `<svg ${common}><path d="M7.4 18.2h9.2a4.4 4.4 0 0 0 .45-8.78A6.35 6.35 0 0 0 5 8a5.15 5.15 0 0 0 2.4 10.2Z" fill="currentColor"/></svg>`;
  }
  return `<svg ${common}><path d="M11 1h2v3h-2V1Zm0 19h2v3h-2v-3ZM1 11h3v2H1v-2Zm19 0h3v2h-3v-2ZM4.22 5.64 5.64 4.22l2.12 2.12-1.42 1.42-2.12-2.12Zm12.02 12.02 1.42-1.42 2.12 2.12-1.42 1.42-2.12-2.12Zm0-11.32 2.12-2.12 1.42 1.42-2.12 2.12-1.42-1.42ZM4.22 18.36l2.12-2.12 1.42 1.42-2.12 2.12-1.42-1.42ZM12 5.2A6.8 6.8 0 1 1 12 18.8 6.8 6.8 0 0 1 12 5.2Z" fill="currentColor"/></svg>`;
}

function parseGameStartDate() {
  const value = String(state?.game?.startDate || '').trim();
  const match = value.match(/^(\d{4})-(\d{2})-(\d{2})$/);
  if (match) {
    const parsed = new Date(Number(match[1]), Number(match[2]) - 1, Number(match[3]), 12, 0, 0, 0);
    if (!Number.isNaN(parsed.getTime())) return parsed;
  }
  const created = new Date(state?.createdAt || Date.now());
  const fallback = Number.isNaN(created.getTime()) ? new Date() : created;
  return new Date(fallback.getFullYear(), fallback.getMonth(), fallback.getDate(), 12, 0, 0, 0);
}

function gameDateForDay(dayNumber = state?.game?.day || 1) {
  const date = parseGameStartDate();
  date.setDate(date.getDate() + Math.max(0, Number(dayNumber || 1) - 1));
  return date;
}

function gameDate() {
  return gameDateForDay(state?.game?.day || 1);
}

function dateKey(date) {
  return `${date.getFullYear()}-${String(date.getMonth() + 1).padStart(2, '0')}-${String(date.getDate()).padStart(2, '0')}`;
}

function gameDateLabel(dayNumber = state?.game?.day || 1) {
  const date = gameDateForDay(dayNumber);
  const weekdays = ['日', '月', '火', '水', '木', '金', '土'];
  return `${date.getFullYear()}年${date.getMonth() + 1}月${date.getDate()}日（${weekdays[date.getDay()]}）`;
}

function calendarUserEvents() {
  const rows = state?.game?.calendarEvents;
  return rows && typeof rows === 'object' && !Array.isArray(rows) ? rows : {};
}

function calendarUserEventForDate(key) {
  return String(calendarUserEvents()[key] || '').trim();
}

function configuredBirthday() {
  return normalizeBirthday(state?.settings?.birthday);
}

function birthdayMatchesDate(date) {
  return isBirthdayOnDate(configuredBirthday(), date);
}

function birthdayJapaneseLabel(value = configuredBirthday()) {
  const birthday = normalizeBirthday(value);
  if (!birthday) return '';
  return `${Number(birthday.slice(0, 2))}月${Number(birthday.slice(3, 5))}日`;
}

function birthdayParts(value = configuredBirthday()) {
  const birthday = normalizeBirthday(value);
  return birthday
    ? { month: Number(birthday.slice(0, 2)), day: Number(birthday.slice(3, 5)) }
    : { month: 4, day: 1 };
}

function birthdayMaximumDay(month) {
  const normalizedMonth = Math.max(1, Math.min(12, Math.floor(Number(month) || 1)));
  return new Date(2000, normalizedMonth, 0, 12, 0, 0, 0).getDate();
}

function birthdayMonthOptions(selected) {
  return Array.from({ length: 12 }, (_, index) => index + 1)
    .map((month) => `<option value="${month}" ${month === selected ? 'selected' : ''}>${month}月</option>`)
    .join('');
}

function birthdayDayOptions(month, selected) {
  return Array.from({ length: birthdayMaximumDay(month) }, (_, index) => index + 1)
    .map((day) => `<option value="${day}" ${day === selected ? 'selected' : ''}>${day}日</option>`)
    .join('');
}

function birthdaySetupMonthOptions(selected = 0) {
  return `<option value="" ${selected ? '' : 'selected'}>月を選択</option>${Array.from({ length: 12 }, (_, index) => index + 1)
    .map((month) => `<option value="${month}" ${month === selected ? 'selected' : ''}>${month}月</option>`)
    .join('')}`;
}

function birthdaySetupDayOptions(month, selected = 0) {
  const normalizedMonth = Math.floor(Number(month) || 0);
  if (normalizedMonth < 1 || normalizedMonth > 12) return '<option value="" selected>先に月を選択</option>';
  return `<option value="" ${selected ? '' : 'selected'}>日を選択</option>${Array.from({ length: birthdayMaximumDay(normalizedMonth) }, (_, index) => index + 1)
    .map((day) => `<option value="${day}" ${day === selected ? 'selected' : ''}>${day}日</option>`)
    .join('')}`;
}

function syncSetupBirthdayDaySelect() {
  const monthSelect = root.querySelector('[data-setup-birthday-month]');
  const daySelect = root.querySelector('[data-setup-birthday-day]');
  if (!monthSelect || !daySelect) return;
  const month = Math.floor(Number(monthSelect.value) || 0);
  const previousDay = Math.floor(Number(daySelect.value) || 0);
  if (month < 1 || month > 12) {
    daySelect.innerHTML = birthdaySetupDayOptions(0, 0);
    daySelect.disabled = true;
    return;
  }
  const selectedDay = previousDay > 0 ? Math.min(previousDay, birthdayMaximumDay(month)) : 0;
  daySelect.innerHTML = birthdaySetupDayOptions(month, selectedDay);
  daySelect.disabled = false;
  daySelect.value = selectedDay ? String(selectedDay) : '';
}

function syncBirthdayDaySelect() {
  const monthSelect = root.querySelector('[data-birthday-month]');
  const daySelect = root.querySelector('[data-birthday-day]');
  if (!monthSelect || !daySelect) return;
  const month = Number(monthSelect.value) || 1;
  const previousDay = Number(daySelect.value) || 1;
  const maximum = birthdayMaximumDay(month);
  const selectedDay = Math.min(previousDay, maximum);
  daySelect.innerHTML = birthdayDayOptions(month, selectedDay);
  daySelect.value = String(selectedDay);
}

function calendarDateFromKey(key) {
  const match = String(key || '').match(/^(\d{4})-(\d{2})-(\d{2})$/);
  if (!match) return null;
  const date = new Date(Number(match[1]), Number(match[2]) - 1, Number(match[3]), 12, 0, 0, 0);
  return Number.isNaN(date.getTime()) ? null : date;
}

function calendarDateLabelFromKey(key) {
  const match = String(key || '').match(/^(\d{4})-(\d{2})-(\d{2})$/);
  if (!match) return '';
  const date = new Date(Number(match[1]), Number(match[2]) - 1, Number(match[3]), 12, 0, 0, 0);
  if (Number.isNaN(date.getTime())) return '';
  const weekdays = ['日', '月', '火', '水', '木', '金', '土'];
  const holidayName = japaneseHolidayName(date);
  return `${date.getFullYear()}年${date.getMonth() + 1}月${date.getDate()}日（${weekdays[date.getDay()]}）${holidayName ? `・${holidayName}` : ''}`;
}

function scheduledBusinessPaymentsForDate(date) {
  if (!(date instanceof Date) || Number.isNaN(date.getTime())) return [];
  const events = [];

  if (date.getDate() === 15) {
    events.push('自宅家賃支払日');
  }

  if (date.getDate() !== 1) return events;

  const targetDate = new Date(date.getFullYear(), date.getMonth() - 1, 1, 12, 0, 0, 0);
  const start = parseGameStartDate();
  if (monthIndex(targetDate) - monthIndex(start) >= 2) {
    events.push('工房維持費支払日');
  }

  const hasStoreRent = [...(state?.store?.branches || [])]
    .some((branch) => {
      const contractDate = gameDateForDay(branch.rentedDay || 1);
      return monthIndex(targetDate) - monthIndex(contractDate) >= 1;
    });
  if (hasStoreRent) events.push('店舗家賃支払日');

  return events;
}

function calendarSystemEventsForDate(date) {
  if (!(date instanceof Date) || Number.isNaN(date.getTime())) return [];
  const key = dateKey(date);
  const events = [];
  const holidayName = japaneseHolidayName(date);
  if (holidayName) events.push(`祝日：${holidayName}`);
  if (birthdayMatchesDate(date)) events.push('誕生日');

  state.orders
    .filter((order) => !orderClosed(order) && dateKey(gameDateForDay(order.deadlineDay)) === key)
    .forEach((order) => events.push(`${order.customerName}さんの注文納期`));

  if (key === dateKey(gameDate())) {
    Object.keys(CUSTOMERS)
      .filter((id) => state.customers[id]?.visiting)
      .forEach((id) => events.push(`${CUSTOMERS[id].name}さんが来店中`));
  }

  Object.entries(state.tools?.items || {})
    .filter(([, record]) => record?.status === 'repairing' && Number(record.repairCompleteDay) >= state.game.day)
    .filter(([, record]) => dateKey(gameDateForDay(record.repairCompleteDay)) === key)
    .forEach(([toolId]) => events.push(`${WORKSHOP_TOOLS[toolId]?.name || '工具'}の修理完了`));

  events.push(...scheduledBusinessPaymentsForDate(date));
  return [...new Set(events)];
}

function openCalendarEventEditor(key) {
  const date = calendarDateFromKey(key);
  const label = calendarDateLabelFromKey(key);
  if (!label || !date) return;
  const current = calendarUserEventForDate(key);
  const systemEvents = calendarSystemEventsForDate(date);
  const systemEventNote = systemEvents.length
    ? `<section class="calendar-system-events"><strong>この日の予定</strong>${systemEvents.map((event) => `<p>${esc(event)}</p>`).join('')}</section>`
    : '';
  showModal({
    title: `${label}の予定`,
    body: `${systemEventNote}<label class="calendar-event-editor"><span>予定を入力</span><textarea data-calendar-event-input data-date="${esc(key)}" maxlength="120" rows="4" placeholder="予定を入力してください">${esc(current)}</textarea><small>120文字まで入力できます。</small></label>${current ? `<button type="button" class="text-button calendar-event-delete-button" data-action="calendar-event-delete" data-date="${esc(key)}">この予定を削除</button>` : ''}`,
    confirm: '保存する',
    cancel: 'キャンセル',
    action: 'calendar-event-save',
  });
  queueMicrotask(() => modalEl.querySelector('[data-calendar-event-input]')?.focus());
}

function currentCalendarEvents() {
  if (!state) return [];
  const events = calendarSystemEventsForDate(gameDate());
  const userEvent = calendarUserEventForDate(dateKey(gameDate()));
  if (userEvent) events.push(userEvent);
  return [...new Set(events)];
}


function winterColdBlackoutDate(date) {
  const targetDate = date || gameDate();
  const month = targetDate.getMonth();
  const day = targetDate.getDate();
  return (month === 11 && day >= 23) || (month === 0 && day <= 3);
}

function winterColdSeasonKey(date = gameDate()) {
  const month = date.getMonth();
  const year = date.getFullYear();
  if (month === 10 || month === 11) return `${year}-${year + 1}`;
  if (month === 0 || month === 1) return `${year - 1}-${year}`;
  return '';
}

function winterColdSeasonEnd(date = gameDate()) {
  const season = winterColdSeasonKey(date);
  if (!season) return null;
  const startYear = Number(season.slice(0, 4));
  return new Date(startYear + 1, 2, 0, 12, 0, 0, 0);
}

function winterColdRemainingDays(date = gameDate()) {
  const end = winterColdSeasonEnd(date);
  if (!end) return 0;
  const startUtc = Date.UTC(date.getFullYear(), date.getMonth(), date.getDate());
  const endUtc = Date.UTC(end.getFullYear(), end.getMonth(), end.getDate());
  return Math.max(1, Math.floor((endUtc - startUtc) / 86400000) + 1);
}

function winterColdEventState() {
  state.events = state.events && typeof state.events === 'object' && !Array.isArray(state.events) ? state.events : {};
  const saved = state.events.winterColdEvent && typeof state.events.winterColdEvent === 'object' && !Array.isArray(state.events.winterColdEvent)
    ? state.events.winterColdEvent
    : {};
  const validStages = new Set(['idle', 'intro', 'sick', 'completed']);
  const normalizedDaysCompleted = Math.max(0, Math.min(WINTER_COLD_EVENT_DAYS, Math.floor(Number(saved.daysCompleted) || 0)));
  // 旧保存で active=false / stage=sick が残っていても、療養日数が未完了なら体調不良を継続して復旧する。
  const legacySickState = saved.stage === 'sick' && normalizedDaysCompleted < WINTER_COLD_EVENT_DAYS;
  state.events.winterColdEvent = {
    active: Boolean(saved.active) || legacySickState,
    stage: validStages.has(saved.stage) ? saved.stage : 'idle',
    seasonKey: /^\d{4}-\d{4}$/.test(String(saved.seasonKey || '')) ? String(saved.seasonKey) : '',
    lastCompletedSeason: /^\d{4}-\d{4}$/.test(String(saved.lastCompletedSeason || '')) ? String(saved.lastCompletedSeason) : '',
    lastCheckedDate: /^\d{4}-\d{2}-\d{2}$/.test(String(saved.lastCheckedDate || '')) ? String(saved.lastCheckedDate) : '',
    startDay: Math.max(0, Math.floor(Number(saved.startDay) || 0)),
    daysCompleted: normalizedDaysCompleted,
    totalTriggered: Math.max(0, Math.floor(Number(saved.totalTriggered) || 0)),
    recoveryNoticePending: Boolean(saved.recoveryNoticePending),
  };
  if (!state.events.winterColdEvent.active && !['idle', 'completed'].includes(state.events.winterColdEvent.stage)) {
    state.events.winterColdEvent.stage = 'completed';
  }
  return state.events.winterColdEvent;
}

function winterColdTextActive() {
  if (!state) return false;
  const eventState = winterColdEventState();
  return eventState.active && eventState.stage === 'sick';
}

function cancelWinterColdDuringBlackout({ save = false } = {}) {
  if (!state || !winterColdBlackoutDate()) return false;
  const eventState = winterColdEventState();
  const shouldCancel = Boolean(eventState.active) || eventState.stage === 'intro' || eventState.stage === 'sick';
  if (!shouldCancel) return false;

  eventState.active = false;
  eventState.stage = 'idle';
  eventState.seasonKey = '';
  eventState.lastCheckedDate = dateKey(gameDate());
  eventState.startDay = 0;
  eventState.daysCompleted = 0;
  eventState.recoveryNoticePending = false;
  winterColdMorningBriefPending = false;

  if (screen === 'winterColdEvent' || state.game?.screen === 'winterColdEvent') {
    screen = 'main';
    screenData = {};
    navigation = [];
    state.game.screen = 'main';
  }
  sleepCurtainEl?.classList.remove('active', 'next-day-blackout');
  scheduleWinterColdTextEffect();
  if (save) void saveGame();
  return true;
}

function illnessEventSuppressionActive() {
  return winterColdTextActive();
}

function repairIllnessBirthdayDeadlock({ save = false } = {}) {
  if (!state) return false;
  state.events = state.events && typeof state.events === 'object' && !Array.isArray(state.events) ? state.events : {};
  const rawCold = state.events.winterColdEvent && typeof state.events.winterColdEvent === 'object' && !Array.isArray(state.events.winterColdEvent)
    ? state.events.winterColdEvent
    : {};
  const rawBirthday = state.events.birthdaySleepEvent && typeof state.events.birthdaySleepEvent === 'object' && !Array.isArray(state.events.birthdaySleepEvent)
    ? state.events.birthdaySleepEvent
    : {};
  const coldDays = Math.max(0, Math.min(WINTER_COLD_EVENT_DAYS, Math.floor(Number(rawCold.daysCompleted) || 0)));
  const illnessConflictState = rawCold.stage === 'sick';
  const illnessStillActive = illnessConflictState && (rawCold.active !== false || coldDays < WINTER_COLD_EVENT_DAYS);
  const birthdayInProgress = Boolean(rawBirthday.active)
    || ['phone', 'greeting', 'congratulations', 'thanks'].includes(String(rawBirthday.stage || ''))
    || screen === 'birthdaySleepEvent'
    || state.game?.screen === 'birthdaySleepEvent';
  if (!illnessConflictState || !birthdayInProgress) return false;

  state.events.winterColdEvent = illnessStillActive
    ? {
      ...rawCold,
      active: true,
      stage: 'sick',
      daysCompleted: coldDays,
    }
    : {
      ...rawCold,
      active: false,
      stage: 'completed',
      daysCompleted: coldDays,
      lastCompletedSeason: String(rawCold.lastCompletedSeason || rawCold.seasonKey || ''),
      recoveryNoticePending: true,
    };
  state.events.birthdaySleepEvent = {
    ...rawBirthday,
    active: Boolean(rawBirthday.active),
    stage: String(rawBirthday.stage || 'idle'),
    eventYear: Math.max(0, Math.floor(Number(rawBirthday.eventYear) || 0)),
    lastCompletedYear: Math.max(0, Math.floor(Number(rawBirthday.lastCompletedYear) || 0)),
  };
  resetStaleBirthdayEventForIllness(state.events.birthdaySleepEvent);
  state.migrations = state.migrations && typeof state.migrations === 'object' && !Array.isArray(state.migrations) ? state.migrations : {};
  state.migrations.illnessBirthdayDeadlockV460 = true;
  screen = 'main';
  screenData = {};
  navigation = [];
  state.game.screen = 'main';
  sleepCurtainEl?.classList.remove('active', 'next-day-blackout');
  modalEl?.classList.add('hidden');
  if (modalEl) modalEl.innerHTML = '';
  clearMorningBrief();
  if (save) void saveGame();
  return true;
}

function resetStaleBirthdayEventForIllness(eventState) {
  eventState = eventState || birthdaySleepEventState();
  const today = gameDate();
  const currentYear = today.getFullYear();
  const birthdayToday = birthdayMatchesDate(today);
  const eventYear = Math.max(0, Math.floor(Number(eventState.eventYear) || 0));
  eventState.active = false;
  eventState.restPending = false;
  eventState.triggerReason = '';
  if (birthdayToday) {
    eventState.stage = 'completed';
    eventState.eventYear = currentYear;
    eventState.lastCompletedYear = Math.max(Math.floor(Number(eventState.lastCompletedYear) || 0), currentYear);
  } else {
    // 旧1月1日など、現在の設定日と一致しない誕生日イベントは将来の誕生日を塞がない。
    eventState.stage = 'idle';
    eventState.eventYear = 0;
    if (eventYear === currentYear || configuredBirthday() === DEFAULT_BIRTHDAY) eventState.lastCompletedYear = 0;
  }
  return true;
}

function reconcileMorningPaymentsIdempotently() {
  try { processMonthlyFixedCosts(); } catch (error) { console.error('月初固定費の復旧エラー', error); }
  try { processHomeRent(); } catch (error) { console.error('自宅家賃の復旧エラー', error); }
}

function repairIllnessPaymentBirthdayOverlapV481({ save = false } = {}) {
  if (!state || !illnessEventSuppressionActive() || sleepTransitioning) return false;
  const transition = dayTransitionState();
  const birthday = birthdaySleepEventState();
  const today = gameDate();
  const birthdayInProgress = Boolean(birthday.active)
    || ['phone', 'greeting', 'congratulations', 'thanks'].includes(String(birthday.stage || ''))
    || screen === 'birthdaySleepEvent'
    || state.game?.screen === 'birthdaySleepEvent';
  const staleJanuaryCompletion = configuredBirthday() === DEFAULT_BIRTHDAY
    && today.getMonth() === 0
    && today.getDate() === 1
    && Math.floor(Number(birthday.lastCompletedYear) || 0) === today.getFullYear();
  state.migrations = state.migrations && typeof state.migrations === 'object' && !Array.isArray(state.migrations) ? state.migrations : {};
  const paymentReconcilePending = Boolean(state.migrations.illnessPaymentBirthdayOverlapV481PaymentPending);
  const currentDay = Math.max(1, Math.floor(Number(state.game.day) || 1));
  const targetDay = Math.max(0, Math.floor(Number(transition.toDay) || 0));
  const advancedToMorning = transition.phase === 'morningPending'
    || (transition.phase === 'settling' && targetDay > 0 && currentDay >= targetDay);
  const interruptedBeforeAdvance = transition.phase === 'settling' && !advancedToMorning;
  const suppressedScreen = ILLNESS_SUPPRESSED_EVENT_SCREENS.has(String(screen || state.game?.screen || ''));
  if (!birthdayInProgress && !staleJanuaryCompletion && !paymentReconcilePending && transition.phase === 'idle' && !suppressedScreen) return false;

  clearTransientEventRuntime({ releaseDayLocks: true });
  suppressAllTransientEventsForIllness();
  if (birthdayInProgress || staleJanuaryCompletion) resetStaleBirthdayEventForIllness(birthday);

  if (advancedToMorning || paymentReconcilePending) {
    state.game.minutes = DAY_START_MINUTES;
    state.wellbeing.hunger = Math.max(1, Math.floor(Number(state.wellbeing.maxHunger) || 7));
    reconcileMorningPaymentsIdempotently();
  }
  if (transition.phase !== 'idle') completeMorningTransition();
  if (interruptedBeforeAdvance) {
    // 日付が進む前の中断は当日の状態へ戻し、次の「休む」で改めて日次処理を行う。
    transition.phase = 'idle';
  }

  screen = 'main';
  screenData = {};
  navigation = [];
  state.game.screen = 'main';
  state.migrations.illnessPaymentBirthdayOverlapV481 = true;
  state.migrations.illnessPaymentBirthdayOverlapV481PaymentPending = false;
  if (save) void saveGame();
  return true;
}

function repairChildhoodFriendEventDeadlock({ save = false, force = false } = {}) {
  if (!state) return false;
  state.events = state.events && typeof state.events === 'object' && !Array.isArray(state.events) ? state.events : {};
  state.migrations = state.migrations && typeof state.migrations === 'object' && !Array.isArray(state.migrations) ? state.migrations : {};
  const raw = state.events.childhoodFriendEvent && typeof state.events.childhoodFriendEvent === 'object' && !Array.isArray(state.events.childhoodFriendEvent)
    ? state.events.childhoodFriendEvent
    : {};
  const activeStages = new Set(['intro1', 'intro2', 'intro3', 'eating', 'postMeal']);
  const stage = String(raw.stage || 'idle');
  const savedOnEventScreen = screen === 'childhoodFriendEvent' || state.game?.screen === 'childhoodFriendEvent';
  const eventInProgress = Boolean(raw.active) || activeStages.has(stage);
  const invalidActiveState = Boolean(raw.active) && !activeStages.has(stage);
  const orphanedScreen = savedOnEventScreen && !eventInProgress;
  const illnessConflict = illnessEventSuppressionActive() && eventInProgress;
  if (!force && !invalidActiveState && !orphanedScreen && !illnessConflict) return false;

  clearChildhoodFriendMealWatchdog();
  mealTransitioning = false;
  const meal = MEALS.ramen;
  const before = Math.max(0, Math.min(7, Math.floor(Number(raw.hungerBefore) || hungerLevel())));
  if (raw.mealPaid && !raw.mealCompleted) {
    state.wellbeing = state.wellbeing && typeof state.wellbeing === 'object' ? state.wellbeing : {};
    const maxHunger = Math.max(1, Math.floor(Number(state.wellbeing.maxHunger) || 7));
    state.wellbeing.hunger = Math.min(maxHunger, hungerLevel() + Number(meal?.recovery || 3));
    raw.hungerBefore = before;
    raw.hungerAfter = state.wellbeing.hunger;
    raw.mealCompleted = true;
  }
  raw.active = false;
  raw.stage = 'completed';
  raw.nextTriggerDay = Math.max(
    Math.floor(Number(raw.nextTriggerDay) || 0),
    Math.floor(Number(state.game?.day) || 1) + randomEventDayOffset(CHILDHOOD_FRIEND_REPEAT_TRIGGER_MIN, CHILDHOOD_FRIEND_REPEAT_TRIGGER_MAX),
  );
  state.events.childhoodFriendEvent = raw;
  state.migrations.childhoodFriendDeadlockV461 = true;
  screen = 'main';
  screenData = {};
  navigation = [];
  state.game.screen = 'main';
  modalEl?.classList.add('hidden');
  if (modalEl) modalEl.innerHTML = '';
  if (save) void saveGame();
  return true;
}

function suppressBirthdaySleepEventForIllness({ save = false } = {}) {
  if (!state || !winterColdTextActive()) return false;
  const eventState = birthdaySleepEventState();
  const today = gameDate();
  const currentYear = today.getFullYear();
  const birthdayToday = birthdayMatchesDate(today);
  const birthdayPendingToday = birthdayToday && eventState.lastCompletedYear !== currentYear;
  if (!eventState.active && !birthdayPendingToday) return false;

  resetStaleBirthdayEventForIllness(eventState);
  if (screen === 'birthdaySleepEvent') {
    screen = 'main';
    screenData = {};
    navigation = [];
    state.game.screen = 'main';
  }
  if (save) void saveGame();
  return true;
}

function resumeWinterColdEvent() {
  if (!state) return false;
  const eventState = winterColdEventState();
  if (!eventState.active || eventState.stage !== 'intro') return false;
  setScreen('winterColdEvent', {}, false);
  return true;
}

function maybeStartWinterColdEvent(randomValue) {
  if (randomValue === undefined) randomValue = Math.random();
  if (!state || isAlienAbducted()) return false;
  const today = gameDate();
  if (winterColdBlackoutDate(today)) {
    cancelWinterColdDuringBlackout();
    return false;
  }
  if (illnessEventSuppressionActive()) return false;
  const eventState = winterColdEventState();
  if (eventState.active) return resumeWinterColdEvent();
  if (Number(state.game.minutes) !== DAY_START_MINUTES) return false;
  const seasonKey = winterColdSeasonKey(today);
  if (!seasonKey || eventState.lastCompletedSeason === seasonKey) return false;
  const todayKey = dateKey(today);
  if (eventState.lastCheckedDate === todayKey) return false;
  eventState.lastCheckedDate = todayKey;
  const triggerChance = 1 / winterColdRemainingDays(today);
  if (Math.max(0, Math.min(0.999999999, Number(randomValue) || 0)) >= triggerChance) {
    saveGame();
    return false;
  }
  eventState.active = true;
  eventState.stage = 'intro';
  eventState.seasonKey = seasonKey;
  eventState.startDay = Math.max(1, Math.floor(Number(state.game.day) || 1));
  eventState.daysCompleted = 0;
  eventState.recoveryNoticePending = false;
  eventState.totalTriggered += 1;
  saveGame();
  setScreen('winterColdEvent', {}, false);
  playSfx('alarm', { gain: 0.42, rate: 0.72 });
  setTimeout(() => playSfx('impact', { gain: 0.24, rate: 0.62 }), 110);
  vibrate([18, 46, 28]);
  return true;
}

function advanceWinterColdEvent() {
  const eventState = winterColdEventState();
  if (!eventState.active || eventState.stage !== 'intro') {
    goMain();
    return;
  }
  eventState.stage = 'sick';
  suppressBirthdaySleepEventForIllness();
  suppressAllTransientEventsForIllness();
  winterColdMorningBriefPending = false;
  clearMorningBrief();
  clearCustomerVisitsForIllness();
  // 朝の体調不良開始イベントを閉じた時点で、翌朝処理を必ず完了させる。
  completeMorningTransition();
  saveGame();
  playSfx('impact', { gain: 0.22, rate: 0.58 });
  setScreen('main', {}, false);
}

function progressWinterColdSleep({ showResult = true } = {}) {
  if (!state) return false;
  const eventState = winterColdEventState();
  if (!eventState.active || eventState.stage !== 'sick') return false;
  eventState.daysCompleted = Math.min(WINTER_COLD_EVENT_DAYS, eventState.daysCompleted + 1);
  if (!showResult && eventState.daysCompleted >= WINTER_COLD_EVENT_DAYS) {
    eventState.active = false;
    eventState.stage = 'completed';
    eventState.lastCompletedSeason = eventState.seasonKey;
    eventState.recoveryNoticePending = true;
  }
  return true;
}

function finishWinterColdRecoveryAfterNight() {
  if (!state) return false;
  const eventState = winterColdEventState();
  if (!eventState.active || eventState.stage !== 'sick' || eventState.daysCompleted < WINTER_COLD_EVENT_DAYS) return false;
  eventState.active = false;
  eventState.stage = 'completed';
  eventState.lastCompletedSeason = eventState.seasonKey;
  eventState.recoveryNoticePending = true;
  return true;
}

function winterColdGarbleText(value) {
  const symbols = ['譁', '縺', '繧', '莠', '蜿', '荳', '螟', '驥', '莉', '咲', '髫', '�'];
  let index = 0;
  return Array.from(String(value || '')).map((character) => {
    if (/\s/u.test(character)) return character;
    const code = character.codePointAt(0) || 0;
    const symbol = symbols[(code + index) % symbols.length];
    index += 1;
    return symbol;
  }).join('');
}

function winterColdReadableElement(element) {
  const readableControl = element?.closest?.('[data-action="sleep"],[data-action="do-sleep"],[data-action="main"],[data-action="back"],[data-action="next-day"]');
  return Boolean(readableControl || element?.closest?.('[data-illness-readable="true"],script,style,noscript'));
}

function applyWinterColdTextEffect() {
  const active = winterColdTextActive();
  document.body.toggleAttribute('data-winter-cold-active', active);
  const walker = document.createTreeWalker(document.body, NodeFilter.SHOW_TEXT);
  const nodes = [];
  while (walker.nextNode()) nodes.push(walker.currentNode);
  nodes.forEach((node) => {
    const parent = node.parentElement;
    const readable = winterColdReadableElement(parent);
    const previousOriginal = winterColdOriginalText.get(node);
    if (!active || readable) {
      if (previousOriginal !== undefined) {
        node.nodeValue = previousOriginal;
        winterColdOriginalText.delete(node);
      }
      return;
    }
    const expected = previousOriginal === undefined ? '' : winterColdGarbleText(previousOriginal);
    const original = previousOriginal !== undefined && node.nodeValue === expected
      ? previousOriginal
      : String(node.nodeValue || '');
    winterColdOriginalText.set(node, original);
    const garbled = winterColdGarbleText(original);
    if (node.nodeValue !== garbled) node.nodeValue = garbled;
  });

  const elements = [document.body, ...document.body.querySelectorAll('[placeholder],[title],[aria-label],[alt],input[type="button"][value],input[type="submit"][value],input[type="reset"][value]')];
  const attributes = ['placeholder', 'title', 'aria-label', 'alt', 'value'];
  elements.forEach((element) => {
    if (!(element instanceof Element)) return;
    const readable = winterColdReadableElement(element);
    let originalMap = winterColdOriginalAttributes.get(element);
    attributes.forEach((attribute) => {
      if (!element.hasAttribute(attribute)) return;
      const previousOriginal = originalMap?.get(attribute);
      if (!active || readable) {
        if (previousOriginal !== undefined) {
          element.setAttribute(attribute, previousOriginal);
          originalMap.delete(attribute);
        }
        return;
      }
      if (!originalMap) {
        originalMap = new Map();
        winterColdOriginalAttributes.set(element, originalMap);
      }
      const expected = previousOriginal === undefined ? '' : winterColdGarbleText(previousOriginal);
      const current = element.getAttribute(attribute) || '';
      const original = previousOriginal !== undefined && current === expected ? previousOriginal : current;
      originalMap.set(attribute, original);
      const garbled = winterColdGarbleText(original);
      if (current !== garbled) element.setAttribute(attribute, garbled);
    });
    if (originalMap && originalMap.size === 0) winterColdOriginalAttributes.delete(element);
  });
}

function scheduleWinterColdTextEffect() {
  if (winterColdGarbleScheduled) return;
  winterColdGarbleScheduled = true;
  queueMicrotask(() => {
    winterColdGarbleScheduled = false;
    applyWinterColdTextEffect();
  });
}

function clearMorningBrief() {
  if (!morningBriefEl) return;
  morningBriefEl.classList.remove('active', 'persistent');
  morningBriefEl.innerHTML = '';
  morningBriefShowing = false;
}

function dayTransitionState() {
  if (!state?.game) return { phase: 'idle', fromDay: 0, toDay: 0, startedDateKey: '', morningDateKey: '', overlapRecoveryCount: 0 };
  const saved = state.game.dayTransition && typeof state.game.dayTransition === 'object' && !Array.isArray(state.game.dayTransition)
    ? state.game.dayTransition
    : {};
  const validPhases = new Set(['idle', 'settling', 'morningPending']);
  state.game.dayTransition = {
    phase: validPhases.has(String(saved.phase || '')) ? String(saved.phase) : 'idle',
    fromDay: Math.max(0, Math.floor(Number(saved.fromDay) || 0)),
    toDay: Math.max(0, Math.floor(Number(saved.toDay) || 0)),
    startedDateKey: /^\d{4}-\d{2}-\d{2}$/.test(String(saved.startedDateKey || '')) ? String(saved.startedDateKey) : '',
    morningDateKey: /^\d{4}-\d{2}-\d{2}$/.test(String(saved.morningDateKey || '')) ? String(saved.morningDateKey) : '',
    overlapRecoveryCount: Math.max(0, Math.floor(Number(saved.overlapRecoveryCount) || 0)),
  };
  return state.game.dayTransition;
}

function markNightTransitionCheckpoint() {
  const transition = dayTransitionState();
  transition.phase = 'settling';
  transition.fromDay = Math.max(1, Math.floor(Number(state.game.day) || 1));
  transition.toDay = transition.fromDay + 1;
  transition.startedDateKey = dateKey(gameDate());
  transition.morningDateKey = '';
  return transition;
}

function markMorningTransitionPending() {
  const transition = dayTransitionState();
  transition.phase = 'morningPending';
  transition.toDay = Math.max(1, Math.floor(Number(state.game.day) || 1));
  transition.morningDateKey = dateKey(gameDate());
  return transition;
}

function completeMorningTransition({ save = false } = {}) {
  if (!state?.game) return false;
  const transition = dayTransitionState();
  if (transition.phase === 'idle') return false;
  transition.phase = 'idle';
  transition.fromDay = 0;
  transition.toDay = 0;
  transition.startedDateKey = '';
  transition.morningDateKey = '';
  if (save) void saveGame();
  return true;
}

function morningOverlapStatus(date = gameDate()) {
  const birthday = birthdaySleepEventState();
  return {
    holiday: Boolean(japaneseHolidayName(date)),
    payment: scheduledBusinessPaymentsForDate(date).length > 0,
    hungerZero: hungerLocked(),
    birthdayActive: Boolean(birthday.active) || ['phone', 'greeting', 'congratulations', 'thanks'].includes(String(birthday.stage || '')),
  };
}

function repairMorningOverlapDeadlockV475({ save = false } = {}) {
  if (!state?.game) return false;
  const transition = dayTransitionState();
  const currentDay = Math.max(1, Math.floor(Number(state.game.day) || 1));
  const atMorningStart = Number(state.game.minutes) <= DAY_START_MINUTES;
  const advancedDuringSettling = transition.phase === 'settling' && transition.toDay > 0 && currentDay >= transition.toDay;
  const interruptedBeforeAdvance = transition.phase === 'settling' && !advancedDuringSettling;
  const normalMorningScreens = new Set(['main', 'dayResult', 'robberyReport', 'alienReturnEvent', 'alienAbductionEvent', 'winterColdEvent', 'mermaidEvent', 'westernUnionEvent']);
  const abnormalMorningScreen = transition.phase === 'morningPending'
    && !normalMorningScreens.has(String(screen || state.game.screen || ''));
  const overlap = morningOverlapStatus();
  const staleBirthdayAtMorning = transition.phase === 'morningPending' && atMorningStart && overlap.birthdayActive;
  const overlapCount = Object.values(overlap).filter(Boolean).length;
  const legacyOverlap = transition.phase === 'idle'
    && atMorningStart
    && overlap.birthdayActive
    && overlap.hungerZero
    && (overlap.holiday || overlap.payment);
  if (!interruptedBeforeAdvance && !advancedDuringSettling && !abnormalMorningScreen && !staleBirthdayAtMorning && !legacyOverlap) return false;

  sleepTransitioning = false;
  sleepCurtainEl?.classList.remove('active', 'next-day-blackout');
  modalEl?.classList.add('hidden');
  if (modalEl) modalEl.innerHTML = '';
  clearMorningBrief();

  if (interruptedBeforeAdvance) {
    // 日付が進む前に中断された場合は、金銭・在庫・日次結果を二重処理せず、その日のメイン画面へ戻す。
    completeMorningTransition();
  } else {
    // 翌朝まで進んでいる場合は、朝の初期値と固定費を冪等に整え、夜の誕生日状態を残さない。
    state.game.minutes = DAY_START_MINUTES;
    if (hungerLocked()) state.wellbeing.hunger = Math.max(1, Number(state.wellbeing.maxHunger) || 7);
    try { processMonthlyFixedCosts(); } catch (error) { console.error('月初固定費の復旧エラー', error); }
    try { processHomeRent(); } catch (error) { console.error('自宅家賃の復旧エラー', error); }
    const birthday = birthdaySleepEventState();
    if (birthday.active || !['idle', 'completed'].includes(birthday.stage)) {
      const completionYear = Math.max(0, Math.floor(Number(birthday.eventYear) || gameDate().getFullYear()));
      birthday.active = false;
      birthday.stage = 'completed';
      birthday.eventYear = completionYear;
      birthday.lastCompletedYear = Math.max(Number(birthday.lastCompletedYear) || 0, completionYear);
    }
    transition.phase = 'idle';
    transition.fromDay = 0;
    transition.toDay = 0;
    transition.startedDateKey = '';
    transition.morningDateKey = '';
    transition.overlapRecoveryCount += 1;
  }

  screen = 'main';
  screenData = {};
  navigation = [];
  state.game.screen = 'main';
  if (save) void saveGame();
  if (overlapCount >= 2) queueMicrotask(() => showToast('重なった朝の処理を整理し、メイン画面へ復帰しました。', 'warning'));
  return true;
}

function continueMorningAfterSpecialEvents() {
  if (illnessEventSuppressionActive()) {
    clearMorningBrief();
    completeMorningTransition({ save: true });
    goMain();
    return;
  }
  if (isAlienAbducted()) {
    completeMorningTransition({ save: true });
    goMain();
    return;
  }
  const report = pendingRobberyReport();
  if (report) {
    report.stage = 'showing';
    saveGame();
    setScreen('robberyReport', {}, false);
    return;
  }
  completeMorningTransition({ save: true });
  goMain();
}

function specialMorningEventTriggeredToday() {
  const day = Math.max(1, Math.floor(Number(state?.game?.day) || 1));
  const todayKey = dateKey(gameDate());
  const mermaid = state?.events?.mermaidEvent;
  const western = state?.events?.westernUnionEvent;
  return Number(mermaid?.lastTriggeredDay) === day
    || String(western?.eventDate || '') === todayKey;
}

function finishMorningBriefAndContinue() {
  clearMorningBrief();
  if (illnessEventSuppressionActive()) {
    completeMorningTransition({ save: true });
    goMain();
    return;
  }
  if (isAlienAbducted()) {
    completeMorningTransition({ save: true });
    goMain();
    return;
  }
  if (maybeStartAlienAbductionEvent()) return;
  if (!specialMorningEventTriggeredToday()) {
    if (maybeStartMermaidEvent()) return;
    if (maybeStartWesternUnionEvent()) return;
  }
  continueMorningAfterSpecialEvents();
}

async function maybeResumeMorningSequence() {
  if (!state || screen !== 'main' || morningBriefShowing || winterColdMorningBriefPending || sleepTransitioning) return;
  if (cancelWinterColdDuringBlackout({ save: true })) {
    completeMorningTransition({ save: true });
  }
  if (illnessEventSuppressionActive()) {
    clearMorningBrief();
    clearCustomerVisitsForIllness();
    repairIllnessPaymentBirthdayOverlapV481({ save: true });
    completeMorningTransition({ save: true });
    if (screen !== 'main') goMain();
    return;
  }
  if (resumeBluesJukeEvent()) return;
  if (resumeWinterColdEvent()) return;
  if (dayTransitionState().phase === 'morningPending' && maybeStartBluesJukeEvent()) return;
  if (maybeStartWinterColdEvent()) return;
  if (resumeAlienReturnEvent()) return;
  if (resumeAlienAbductionEvent()) return;
  if (resumeMermaidEvent()) return;
  if (resumeWesternUnionEvent()) return;
  if (!specialMorningEventTriggeredToday()) {
    if (maybeStartMermaidEvent()) return;
    if (maybeStartWesternUnionEvent()) return;
  }
  const report = pendingRobberyReport();
  if (!report) {
    if (dayTransitionState().phase === 'morningPending') await showMorningBrief();
    return;
  }
  if (report.stage === 'showing') {
    setScreen('robberyReport', {}, false);
    return;
  }
  await showMorningBrief();
}

async function showMorningBrief() {
  if (!morningBriefEl || !state || morningBriefShowing) return;
  cancelWinterColdDuringBlackout({ save: true });
  if (illnessEventSuppressionActive()) {
    clearMorningBrief();
    repairIllnessPaymentBirthdayOverlapV481({ save: true });
    completeMorningTransition({ save: true });
    if (screen !== 'main') goMain();
    return;
  }
  morningBriefShowing = true;
  const repairMessages = Array.isArray(state.tools?.morningMessages) ? [...state.tools.morningMessages] : [];
  const date = gameDate();
  const todayGem = dailyGemForDate(date);
  const coldRecoveryPending = Boolean(winterColdEventState().recoveryNoticePending);
  const events = [...repairMessages, `今日の宝石：${todayGem.name}`, ...currentCalendarEvents()];
  const hasEvents = events.length > 0;
  const playerName = state.playerName || 'プレイヤー';
  const morningWeekdays = ['日', '月', '火', '水', '木', '金', '土'];
  const morningDateLabel = `${date.getFullYear()}年${date.getMonth() + 1}月${date.getDate()}日（${morningWeekdays[date.getDay()]}）`;
  morningBriefEl.innerHTML = `
    <section class="morning-brief-card" role="status" aria-live="polite">
      <div class="morning-date-summary">
        <strong>${esc(morningDateLabel)}</strong>
        <span>${state.game.day}日目</span>
        <span>${weatherIcon(state.game.weather)} ${esc(state.game.weather)}</span>
      </div>
      <p class="morning-greeting">おはようございます、${esc(playerName)}</p>
      ${coldRecoveryPending ? '<p class="morning-cold-recovery" data-illness-readable="true">体調が戻った</p>' : ''}
      <div class="morning-events ${hasEvents ? 'has-events' : 'is-empty'}">
        <small>本日の予定・お知らせ</small>
        ${hasEvents
          ? events.map((event) => `<p>${esc(event)}</p>`).join('')
          : ''}
      </div>
      <button type="button" class="primary-button morning-main-button" data-action="morning-main" data-illness-readable="true">メイン画面へ</button>
    </section>`;
  morningBriefEl.classList.remove('persistent');
  morningBriefEl.classList.add('active');

  if (repairMessages.length) state.tools.morningMessages = [];
  if (coldRecoveryPending) winterColdEventState().recoveryNoticePending = false;
  if (repairMessages.length || coldRecoveryPending) saveGame();

  const displayDuration = events.length > 1
    ? Math.min(6500, 3500 + (events.length - 1) * 650)
    : 3000;
  await wait(displayDuration);
  if (!morningBriefShowing) return;
  morningBriefEl.classList.remove('active');
  await wait(300);
  if (!morningBriefShowing) return;
  finishMorningBriefAndContinue();
}

async function beginNextDay() {
  // 日次結果画面で朝表示フラグが異常に残っていても、翌日へ進めるように復旧する。
  cancelWinterColdDuringBlackout();
  repairIllnessBirthdayDeadlock();
  repairIllnessPaymentBirthdayOverlapV481();
  repairLegacyTransientEventDeadlocksV462();
  repairMorningOverlapDeadlockV475();
  if (morningBriefShowing) clearMorningBrief();
  if (illnessEventSuppressionActive()) {
    suppressBirthdaySleepEventForIllness();
    suppressAllTransientEventsForIllness();
  }
  if (nextDayTransitionPromise) return nextDayTransitionPromise;

  nextDayTransitionPromise = (async () => {
    const waitStartedAt = Date.now();
    while (sleepTransitioning && Date.now() - waitStartedAt < 5000) await wait(50);
    if (sleepTransitioning) {
      console.warn('就寝処理のロックを解除して翌日処理を継続します。');
      sleepTransitioning = false;
    }

    sleepTransitioning = true;
    try {
      sleepCurtainEl?.classList.add('next-day-blackout', 'active');
      playSfx('sleep', { gain: .9 });
      await wait(2000);
      const recoveredFromCold = finishWinterColdRecoveryAfterNight();
      const cancelledForBlackout = cancelWinterColdDuringBlackout();
      if (recoveredFromCold || cancelledForBlackout) await saveGame();
      const stillSick = illnessEventSuppressionActive();
      const returningFromSpace = alienAbductionEventState().active && alienAbductionEventState().stage === 'returnPending';
      let coldStarted = false;
      let bluesJukeStarted = false;
      if (returningFromSpace) {
        grantAlienBodyChip();
        setScreen('alienReturnEvent', {}, false);
      } else if (stillSick) {
        clearMorningBrief();
        repairIllnessPaymentBirthdayOverlapV481({ save: true });
        completeMorningTransition({ save: true });
        goMain();
      } else {
        bluesJukeStarted = maybeStartBluesJukeEvent();
        if (!bluesJukeStarted) {
          coldStarted = maybeStartWinterColdEvent();
          if (!coldStarted) goMain();
        }
      }
      await wait(40);
      sleepCurtainEl?.classList.remove('active', 'next-day-blackout');
      if (!bluesJukeStarted) playSfx(returningFromSpace ? 'success' : coldStarted ? 'impact' : stillSick ? 'sleep' : 'alarm', { gain: .92 });
      if (!returningFromSpace && !coldStarted && !stillSick && !bluesJukeStarted) await showMorningBrief();
    } catch (error) {
      console.error('翌日表示復帰エラー', error);
      clearMorningBrief();
      screen = 'main';
      screenData = {};
      navigation = [];
      if (state?.game) state.game.screen = 'main';
      try { await saveGame(); } catch (saveError) { console.error('翌日復帰後の保存エラー', saveError); }
      render();
      try { showToast('翌日へ進みました。競合したイベント表示は安全にスキップしました。', 'warning'); } catch (_) {}
    } finally {
      sleepCurtainEl?.classList.remove('active', 'next-day-blackout');
      sleepTransitioning = false;
    }
  })();

  try {
    return await nextDayTransitionPromise;
  } finally {
    nextDayTransitionPromise = null;
  }
}

function gameDayOfYear(date) {
  const start = new Date(date.getFullYear(), 0, 1, 12, 0, 0, 0);
  return Math.floor((date.getTime() - start.getTime()) / 86400000) + 1;
}

function daysInGameYear(year) {
  return new Date(year, 1, 29, 12, 0, 0, 0).getMonth() === 1 ? 366 : 365;
}

function westernUnionEventState() {
  state.events = state.events && typeof state.events === 'object' && !Array.isArray(state.events) ? state.events : {};
  const saved = state.events.westernUnionEvent && typeof state.events.westernUnionEvent === 'object' && !Array.isArray(state.events.westernUnionEvent)
    ? state.events.westernUnionEvent
    : {};
  const dialogueStages = new Set(['choice', 'declined', 'gift', 'explain1', 'explain2', 'explain3']);
  state.events.westernUnionEvent = {
    scheduleYear: Math.max(0, Math.floor(Number(saved.scheduleYear) || 0)),
    eligibleDayOfYear: Math.max(0, Math.min(366, Math.floor(Number(saved.eligibleDayOfYear) || 0))),
    lastCheckedDate: /^\d{4}-\d{2}-\d{2}$/.test(String(saved.lastCheckedDate || '')) ? String(saved.lastCheckedDate) : '',
    lastTriggeredYear: Math.max(0, Math.floor(Number(saved.lastTriggeredYear) || 0)),
    totalTriggered: Math.max(0, Math.floor(Number(saved.totalTriggered) || 0)),
    active: Boolean(saved.active),
    stage: WESTERN_UNION_EVENT_STAGES.has(saved.stage) ? saved.stage : 'idle',
    rewardGranted: Boolean(saved.rewardGranted),
    eventDate: /^\d{4}-\d{2}-\d{2}$/.test(String(saved.eventDate || '')) ? String(saved.eventDate) : '',
    introVideoCompleted: Boolean(saved.introVideoCompleted),
    stageAfterVideo: dialogueStages.has(saved.stageAfterVideo) ? saved.stageAfterVideo : '',
  };
  const eventState = state.events.westernUnionEvent;
  if (!eventState.active) {
    eventState.stageAfterVideo = '';
    if (eventState.stage === 'completed') eventState.introVideoCompleted = true;
    return eventState;
  }
  // v0.10.584より前からイベント途中のセーブでも、動画を飛ばさず
  // 視聴後に元の進行段階へ戻す。
  if (!eventState.introVideoCompleted) {
    if (eventState.stage !== 'video') {
      eventState.stageAfterVideo = dialogueStages.has(eventState.stage) ? eventState.stage : (eventState.stageAfterVideo || 'choice');
    }
    if (!eventState.stageAfterVideo) eventState.stageAfterVideo = 'choice';
    eventState.stage = 'video';
  }
  return eventState;
}

function ensureWesternUnionAnnualSchedule(eventState, date = gameDate()) {
  const year = date.getFullYear();
  if (eventState.scheduleYear === year && eventState.eligibleDayOfYear >= 1) return false;
  eventState.scheduleYear = year;
  eventState.eligibleDayOfYear = 1 + Math.floor(Math.random() * daysInGameYear(year));
  eventState.lastCheckedDate = '';
  if (!eventState.active) {
    eventState.stage = eventState.lastTriggeredYear === year ? 'completed' : 'idle';
    eventState.rewardGranted = false;
    eventState.eventDate = '';
    eventState.introVideoCompleted = eventState.stage === 'completed';
    eventState.stageAfterVideo = '';
  }
  return true;
}

function resumeWesternUnionEvent() {
  const eventState = westernUnionEventState();
  if (!eventState.active) return false;
  setScreen('westernUnionEvent', {}, false);
  return true;
}

function westernUnionIntroVideoUrl() {
  return `${WESTERN_UNION_INTRO_VIDEO}?v=${VERSION}`;
}

function startWesternUnionIntroPlayback() {
  const eventState = westernUnionEventState();
  if (!eventState.active || eventState.stage !== 'video') return;
  const video = root.querySelector('video[data-western-union-intro-video]');
  if (!(video instanceof HTMLVideoElement)) return;
  const stage = video.closest('.western-union-video-stage');
  stage?.classList.remove('needs-start', 'has-error');
  video.muted = false;
  video.volume = 1;
  // BGM・環境音はそのまま継続し、suspendAudio()は呼ばない。
  const playPromise = video.play();
  if (playPromise && typeof playPromise.catch === 'function') {
    playPromise
      .then(() => {
        stage?.classList.add('is-playing');
        stage?.classList.remove('needs-start', 'has-error');
      })
      .catch(() => stage?.classList.add('needs-start'));
  }
}

function retryWesternUnionIntroPlayback() {
  const stage = root.querySelector('.western-union-video-stage');
  const video = root.querySelector('video[data-western-union-intro-video]');
  stage?.classList.remove('needs-start', 'has-error');
  if (video instanceof HTMLVideoElement && video.error) video.load();
  startWesternUnionIntroPlayback();
}

function completeWesternUnionIntroVideo() {
  const eventState = westernUnionEventState();
  if (!eventState.active || eventState.stage !== 'video') return;
  const dialogueStages = new Set(['choice', 'declined', 'gift', 'explain1', 'explain2', 'explain3']);
  eventState.introVideoCompleted = true;
  eventState.stage = dialogueStages.has(eventState.stageAfterVideo) ? eventState.stageAfterVideo : 'choice';
  eventState.stageAfterVideo = '';
  saveGame();
  render();
  requestAnimationFrame(() => playSfx('western-union-arrival', { gain: .96 }));
}

function maybeStartWesternUnionEvent() {
  if (illnessEventSuppressionActive()) return false;
  if (!state || state.game.weather !== '雨' || Number(state.game.minutes) !== DAY_START_MINUTES) return false;
  const date = gameDate();
  const year = date.getFullYear();
  const todayKey = dateKey(date);
  const eventState = westernUnionEventState();
  let changed = ensureWesternUnionAnnualSchedule(eventState, date);
  if (eventState.active) {
    if (changed) saveGame();
    return resumeWesternUnionEvent();
  }
  if (eventState.lastCheckedDate === todayKey) {
    if (changed) saveGame();
    return false;
  }
  eventState.lastCheckedDate = todayKey;
  changed = true;
  const eligible = eventState.lastTriggeredYear !== year
    && gameDayOfYear(date) >= eventState.eligibleDayOfYear;
  if (!eligible) {
    saveGame();
    return false;
  }
  eventState.lastTriggeredYear = year;
  eventState.totalTriggered += 1;
  eventState.active = true;
  eventState.stage = 'video';
  eventState.stageAfterVideo = 'choice';
  eventState.introVideoCompleted = false;
  eventState.rewardGranted = false;
  eventState.eventDate = todayKey;
  saveGame();
  setScreen('westernUnionEvent', {}, false);
  vibrate([18, 34, 18]);
  return true;
}

function westernUnionPlayerName() {
  return String(state?.playerName || '君').trim() || '君';
}

function westernUnionEventDateText(eventState = westernUnionEventState()) {
  const match = String(eventState.eventDate || '').match(/^(\d{4})-(\d{2})-(\d{2})$/);
  if (!match) {
    const date = gameDate();
    return `${date.getFullYear()}年${date.getMonth() + 1}月${date.getDate()}日`;
  }
  return `${Number(match[1])}年${Number(match[2])}月${Number(match[3])}日`;
}

function grantWesternUnionAntiqueDiamond(eventState = westernUnionEventState()) {
  if (eventState.rewardGranted) return;
  adjustLooseInventory(WESTERN_UNION_EVENT_GEM_ID, WESTERN_UNION_EVENT_SHAPE_ID, 1);
  eventState.rewardGranted = true;
  addNotification('アンティークダイヤを手に入れました', '雨の日に現れた人物から、特別なアンティークダイヤを受け取りました。', 'special');
  saveGame();
  window.setTimeout(() => playSfx('loose-sparkle', { gain: 1.1 }), 230);
  vibrate([35, 35, 70]);
}

function chooseWesternUnionEvent(answer) {
  const eventState = westernUnionEventState();
  if (!eventState.active || eventState.stage !== 'choice') return;
  if (answer === 'yes') {
    eventState.stage = 'gift';
    playSfx('western-union-handover', { gain: .92 });
    grantWesternUnionAntiqueDiamond(eventState);
  } else if (answer === 'no') {
    eventState.stage = 'declined';
    saveGame();
  } else {
    return;
  }
  render();
}

function finishWesternUnionEvent() {
  const eventState = westernUnionEventState();
  eventState.active = false;
  eventState.stage = 'completed';
  eventState.introVideoCompleted = true;
  eventState.stageAfterVideo = '';
  saveGame();
  continueMorningAfterSpecialEvents();
}

function advanceWesternUnionEvent() {
  const eventState = westernUnionEventState();
  if (!eventState.active) return finishWesternUnionEvent();
  const nextStage = {
    gift: 'explain1',
    explain1: 'explain2',
    explain2: 'explain3',
  }[eventState.stage];
  if (nextStage) {
    eventState.stage = nextStage;
    saveGame();
    render();
    return;
  }
  if (eventState.stage === 'declined' || eventState.stage === 'explain3') finishWesternUnionEvent();
}

function randomEventTriggerDay(minimumDays, maximumDays, fromDay = state?.game?.day || 1) {
  const minimum = Math.max(1, Math.floor(Number(minimumDays) || 1));
  const maximum = Math.max(minimum, Math.floor(Number(maximumDays) || minimum));
  const offset = minimum + Math.floor(Math.random() * (maximum - minimum + 1));
  return Math.max(1, Math.floor(Number(fromDay) || 1)) + offset;
}

function simpleEventState(key, validStages, defaults = {}) {
  state.events = state.events && typeof state.events === 'object' && !Array.isArray(state.events) ? state.events : {};
  const saved = state.events[key] && typeof state.events[key] === 'object' && !Array.isArray(state.events[key]) ? state.events[key] : {};
  state.events[key] = {
    nextTriggerDay: Math.max(0, Math.floor(Number(saved.nextTriggerDay) || 0)),
    lastTriggeredDay: Math.max(0, Math.floor(Number(saved.lastTriggeredDay) || 0)),
    totalTriggered: Math.max(0, Math.floor(Number(saved.totalTriggered) || 0)),
    active: Boolean(saved.active),
    stage: validStages.includes(saved.stage) ? saved.stage : 'idle',
    ...defaults,
    ...Object.fromEntries(Object.keys(defaults).map((keyName) => [keyName, Boolean(saved[keyName])])),
  };
  if (!state.events[key].active && !['idle', 'completed'].includes(state.events[key].stage)) state.events[key].stage = 'completed';
  return state.events[key];
}

