    const choicesMarkup=['A','B','C','D'].map(k=>`<button type="button" class="jxj-quiz-answer-v2" data-action="storyteller-quiz-answer" data-key="${k}"><span>${k}</span><strong>${esc(q.choices[k])}</strong></button>`).join('');
