function renderTropicalFishShop(){
  if (!tropicalFishShopEventAccessAllowed()) {
    queueMicrotask(() => {
      if (screen === 'tropicalFishShop') setScreen('okachimachi', {}, false);
    });
    return `<main class="main-screen"></main>`;
  }
  const category=['fish','plant','display'].includes(screenData?.tropicalCategory)?screenData.tropicalCategory:'fish';
  const aquarium=aquariumState(); refreshAquariumLoad(aquarium);
  const label={fish:'魚',plant:'水草',display:'ディスプレイ'}[category];
  const rows=tropicalShopProducts(category).map(product=>{
    const max=tropicalShopMaxQuantity(product); let status='';
    if(category==='fish'){const def=aquariumFishDefinition(product.id),row=aquarium.fish[product.id];status=`水槽 ${row.inTank}/${def.speciesMax}匹・負荷 ${def.loadPoint}`;}
    else if(category==='plant'){status=`水草合計 ${aquariumPlantTotal(aquarium)}/${AQUARIUM_CONFIG.capacity.plantTotalMax}株`;}
    else status=`${product.family==='driftwood'?'流木':'石'}合計 ${tropicalShopFamilyCount(product.family)}/${product.family==='driftwood'?3:5}個`;
    return `<article class="tropical-product-card ${max<1?'limit':''}"><img src="./assets/images/tropical-shop/${product.image}?v=${VERSION}" alt="${esc(product.name)}"><div><strong>${esc(product.name)}</strong><b>${yen(product.price)}</b><small>${esc(status)}</small></div><button data-action="tropical-shop-open-qty" data-category="${category}" data-id="${product.id}" ${max<1?'disabled':''}>${max<1?'購入上限':category==='fish'?'匹数を選択して購入':category==='plant'?'株数を選択して購入':'個数を選択して購入'}</button></article>`;
  }).join('');
  const modal=screenData?.tropicalModal; let modalHtml='';
  if(modal){const product=tropicalShopFindProduct(modal.category,modal.id); if(product){const max=tropicalShopMaxQuantity(product);const qty=Math.max(1,Math.min(max,Math.floor(Number(modal.qty)||1)));modal.qty=qty;modalHtml=`<div class="tropical-modal-backdrop"><section class="tropical-modal"><button class="tropical-modal-close" data-action="tropical-shop-close-qty">×</button><div class="tropical-modal-imgbox"><img src="./assets/images/tropical-shop/${product.image}?v=${VERSION}" alt="${esc(product.name)}"></div><h2>${esc(product.name)}</h2><strong class="tropical-modal-total">${yen(product.price)} × ${qty} = ${yen(product.price*qty)}</strong><div class="tropical-qty-control"><button data-action="tropical-shop-qty" data-delta="-1" ${qty<=1?'disabled':''}>▼</button><output>${qty}</output><button data-action="tropical-shop-qty" data-delta="1" ${qty>=max?'disabled':''}>▲</button></div><small>購入可能：最大 ${max}${modal.category==='fish'?'匹':modal.category==='plant'?'株':'個'}</small><button class="primary-button full-button" data-action="tropical-shop-purchase">購入する</button></section></div>`;}}
  return shell('熱帯魚屋', `<section class="tropical-shop-status"><b>${yen(state.game.money)}</b><span>魚の飼育負荷 ${aquarium.fishLoad.current}/${aquarium.fishLoad.max}</span><span>水草 ${aquariumPlantTotal(aquarium)}/15株</span></section><nav class="tropical-shop-tabs">${[['fish','魚'],['plant','水草'],['display','ディスプレイ']].map(([id,n])=>`<button data-action="tropical-shop-tab" data-category="${id}" class="${category===id?'active':''}">${n}</button>`).join('')}</nav><section class="tropical-product-grid" aria-label="${label}">${rows}</section>${modalHtml}`, {
    help: '熱帯魚・水草・ディスプレイを選び、数量を決めて購入できます。購入品は水槽へ自動で入ります。',
    contentClass: 'tropical-fish-shop-content',
  });
}

async function enterOkachimachiFromOutside() {
  if (illnessEventSuppressionActive()) {
    setScreen('okachimachi', {});
    return;
  }
  if (resumeOkachimachiInvasiveTurtlesEvent()) return;
  if (resumePandaMusicEvent()) return;
  if (resumeWristFoundEvent()) return;
  if (resumeOkachimachiTollEvent()) return;
  if (resumeApprenticeCinemaEvent()) return;
  if (resumeCinemaVisitEvent()) return;
  if (resumeClockTowerDonationEvent()) return;
  if (resumePearlHumanEvent()) return;
  if (resumeOyatsuDaisukiEvent()) return;
  if (resumeSpeedStarEvent()) return;
  if (resumeStorytellerEvent()) return;
  const eventState = okachimachiQuizEventState();
  const todayKey = dateKey(gameDate());
  if (eventState.lastCountedDate !== todayKey) {
    eventState.totalVisits += 1;
    eventState.visitsSinceLast += 1;
    eventState.lastCountedDate = todayKey;
  }
  const shouldTrigger = eventState.visitsSinceLast >= eventState.nextTriggerAt && canSpendHours(1);
  saveGame();
  if (maybeStartOkachimachiInvasiveTurtlesEvent()) return;
  if (maybeStartWristFoundEvent()) return;
  if (maybeStartPandaMusicEvent()) return;
  if (maybeStartOkachimachiTollEvent()) return;
  if (await maybeStartApprenticeCinemaEvent()) return;
  if (await maybeStartCinemaVisitEvent()) return;
  if (maybeStartClockTowerDonationEvent()) return;
  if (maybeStartOyatsuDaisukiEvent()) return;
  if (maybeStartSpeedStarEvent()) return;
  if (await maybeStartStorytellerEvent()) return;
  if (!shouldTrigger) {
    setScreen('okachimachi', {});
    return;
  }

  try {
    const questions = await loadOkachimachiQuizQuestions();
    const selected = chooseOkachimachiQuizQuestion(questions, eventState.lastQuestionIndex);
    eventState.visitsSinceLast = 0;
    eventState.nextTriggerAt = nextOkachimachiQuizTriggerAt();
    eventState.totalTriggered += 1;
    eventState.lastQuestionIndex = selected.index;
    spendHours(1);
    okachimachiQuizSession = {
      stage: 'video',
      questionIndex: selected.index,
      question: selected.question,
      selectedIndex: null,
      rewardGemId: '',
    };
    persistQuizSession('okachimachi');
    saveGame();
    setScreen('okachimachiQuiz', {});
    vibrate([20, 28, 46]);
  } catch (error) {
    console.error(error);
    showToast('クイズデータを読み込めなかったため、通常の御徒町へ移動しました。', 'error');
    setScreen('okachimachi', {});
  }
}

function okachimachiQuizPlayerName() {
  return String(state?.playerName || 'あなた').trim() || 'あなた';
}

function okachimachiQuizIntroVideoUrl() {
  return `${OKACHIMACHI_QUIZ_INTRO_VIDEO}?v=${VERSION}`;
}

function startOkachimachiQuizIntroPlayback() {
  const session = okachimachiQuizSession;
  if (!session || session.stage !== 'video') return;
  const video = root.querySelector('video[data-okachimachi-quiz-intro-video]');
  if (!(video instanceof HTMLVideoElement)) return;
  const stage = video.closest('.okachimachi-quiz-video-stage');
  stage?.classList.remove('needs-start', 'has-error');
  video.muted = false;
  video.volume = 1;
  // v0.10.582: クイズ王の導入動画中も御徒町BGMは停止しない。
  void resumeAudio();
  const playPromise = video.play();
  if (playPromise && typeof playPromise.catch === 'function') {
    playPromise
      .then(() => {
        stage?.classList.add('is-playing');
        stage?.classList.remove('needs-start', 'has-error');
      })
      .catch(() => stage?.classList.add('needs-start'));
  }
}

function retryOkachimachiQuizIntroPlayback() {
  const stage = root.querySelector('.okachimachi-quiz-video-stage');
  const video = root.querySelector('video[data-okachimachi-quiz-intro-video]');
  stage?.classList.remove('needs-start', 'has-error');
  if (video instanceof HTMLVideoElement && video.error) video.load();
  startOkachimachiQuizIntroPlayback();
}

function completeOkachimachiQuizIntroVideo() {
  const session = okachimachiQuizSession;
  if (!session || session.stage !== 'video') return;
  session.stage = 'intro1';
  persistQuizSession('okachimachi', { save: true });
  render();
  scheduleOkachimachiQuizBottomLayoutSync();
  playSfx('quiz-intro', { gain: .96 });
  vibrate([20, 28, 46]);
}

function okachimachiQuizCharacterImage(stage = okachimachiQuizSession?.stage) {
  if (stage === 'correct') return './assets/images/quiz/quiz-king-player-correct.png';
  if (stage === 'incorrect' || stage === 'incorrectAnswer') return './assets/images/quiz/quiz-king-player-incorrect.png';
  return './assets/images/quiz/quiz-king-normal.png';
}

function answerOkachimachiQuiz(index) {
  const session = okachimachiQuizSession;
  if (!session || session.stage !== 'question') return;
  const selectedIndex = Number(index);
  if (!Number.isInteger(selectedIndex) || selectedIndex < 0 || selectedIndex > 3) return;
  session.selectedIndex = selectedIndex;
  const correct = selectedIndex === session.question.answerIndex;
  session.stage = correct ? 'correct' : 'incorrect';
  persistQuizSession('okachimachi', { save: true });
  render();
  playSfx(correct ? 'quiz-correct' : 'quiz-incorrect', { gain: 1 });
  vibrate(correct ? [35, 45, 80] : 110);
}

function grantOkachimachiQuizReward({ renderAfter = true, saveAfter = true } = {}) {
  const session = okachimachiQuizSession;
  if (!session || session.stage !== 'correct') return false;
  const gemIds = Object.values(GEMS)
    .filter((gem) => !gem.eventOnly && (gem.id !== 'diamond' || toolOwned('diamondPolishingLap')))
    .map((gem) => gem.id);
  if (!gemIds.length) return false;
  const gemId = gemIds[Math.floor(Math.random() * gemIds.length)];
  state.inventory.rough[gemId] = Math.max(0, Math.floor(Number(state.inventory.rough[gemId]) || 0)) + 1;
  session.rewardGemId = gemId;
  session.stage = 'reward';
  persistQuizSession('okachimachi');
  if (saveAfter) saveGame();
  if (renderAfter) render();
  playSfx('loose-sparkle', { gain: 1.06 });
  vibrate([28, 35, 58]);
  return true;
}

function finishOkachimachiQuiz() {
  clearPersistedQuizSession('okachimachi', { save: true });
  setScreen('okachimachi', {}, false);
}


function advanceOkachimachiQuizDialogue() {
  const session = okachimachiQuizSession;
  if (!session) return finishOkachimachiQuiz();
  if (session.stage === 'intro1') {
    session.stage = 'intro2';
    persistQuizSession('okachimachi', { save: true });
    render();
    playSfx('select', { gain: .82 });
    return;
  }
  if (session.stage === 'intro2') {
    session.stage = 'question';
    persistQuizSession('okachimachi', { save: true });
    render();
    playSfx('quiz-question', { gain: .96 });
    vibrate(38);
    return;
  }
  if (session.stage === 'correct') {
    grantOkachimachiQuizReward();
    return;
  }
  if (session.stage === 'incorrect') {
    session.stage = 'incorrectAnswer';
    persistQuizSession('okachimachi', { save: true });
    render();
    playSfx('select', { gain: .82 });
    return;
  }
  if (session.stage === 'incorrectAnswer' || session.stage === 'reward') {
    playSfx('select', { gain: .82 });
    finishOkachimachiQuiz();
  }
}

