const ORDER_DIFFICULTIES = Object.freeze({
  basic: { id: 'basic', label: '基本', days: 7, artisanLevel: 1 },
  general: { id: 'general', label: '一般', days: 10, artisanLevel: 4 },
  complex: { id: 'complex', label: '複雑', days: 14, artisanLevel: 8 },
  high: { id: 'high', label: '高難度', days: 21, artisanLevel: 12 },
  special: { id: 'special', label: '特別', days: 21, artisanLevel: 16 },
});
const ORDER_LABOR_FEES = Object.freeze({ basic: 5000, general: 10000, complex: 20000, high: 35000, special: 50000 });
const CLOSED_ORDER_STATUSES = Object.freeze(['完了', '取消', '期限切れ']);

const STORE_CUSTOMER_PROFILES = Object.freeze({
  1: Object.freeze({ id: 'general', name: '幅広い一般客', description: '商品・予算・希望が幅広い標準的な客層です。' }),
  2: Object.freeze({ id: 'quality', name: '品質を重視する客層', description: '良品・上質の商品が少し売れやすく、一般以上の注文が少し増えます。' }),
  3: Object.freeze({ id: 'premium', name: '予算が高い客層', description: '高額商品・上質品が少し売れやすく、高難度・特別注文が発生しやすくなります。' }),
});

const STORE_EXPANSION_REQUIREMENTS = Object.freeze({
  salesCount: 20,
  totalRevenue: 500000,
  orderDeliveries: 3,
  storePoints: 30,
  storeRating: 55,
  money: 300000,
  cost: 300000,
});
const HIGH_VALUE_GEMS = Object.freeze(['diamond', 'ruby', 'emerald', 'sapphire', 'paraibatourmaline', 'tanzanite', 'imperialtopaz']);
const HIGH_VALUE_METALS = Object.freeze(['gold', 'platinum']);

function randomFrom(values, fallback = null) {
  const rows = Array.isArray(values) ? values.filter(Boolean) : [];
  return rows.length ? rows[Math.floor(Math.random() * rows.length)] : fallback;
}

function storeCustomerProfile(branchNumber = state?.store?.branchNumber || 1) {
  const number = Math.max(1, Math.min(3, Math.floor(Number(branchNumber) || 1)));
  return STORE_CUSTOMER_PROFILES[number] || STORE_CUSTOMER_PROFILES[1];
}

function customerVisitDifficulty(branchNumber, baseDifficulty = 'basic') {
  const branch = Math.max(1, Math.min(3, Math.floor(Number(branchNumber) || 1)));
  const artisan = Math.max(1, Math.min(20, Math.floor(Number(state?.artisan?.level) || 1)));
  const fallback = ORDER_DIFFICULTIES[baseDifficulty] ? baseDifficulty : 'basic';
  if (branch === 1 || artisan < 4) return fallback;
  const roll = Math.random();
  if (branch === 2) {
    if (artisan >= 8 && roll < 0.10) return 'complex';
    if (artisan >= 4 && roll < 0.55) return 'general';
    return fallback;
  }
  if (artisan >= 16) {
    if (roll < 0.20) return 'special';
    if (roll < 0.45) return 'high';
    if (roll < 0.75) return 'complex';
    if (roll < 0.95) return 'general';
    return 'basic';
  }
  if (artisan >= 12) {
    if (roll < 0.25) return 'high';
    if (roll < 0.60) return 'complex';
    if (roll < 0.90) return 'general';
    return 'basic';
  }
  if (artisan >= 8) {
    if (roll < 0.30) return 'complex';
    if (roll < 0.75) return 'general';
    return 'basic';
  }
  return roll < 0.55 ? 'general' : 'basic';
}

function orderMinimumProfitablePrice(request = {}) {
  const looseShape = normalizeLooseShape(request.gem, request.looseShape);
  const draft = { ...request, looseShape, finish: 'mirror', quality: 'standard' };
  const materialCost = Math.max(0, Math.round(productionCost(draft)));
  const difficultyId = orderDifficultyId(request);
  const laborFee = ORDER_LABOR_FEES[difficultyId] || ORDER_LABOR_FEES.basic;
  const profitAllowance = Math.max(5000, Math.round(materialCost * 0.35));
  return roundThousand(materialCost + laborFee + profitAllowance);
}

function normalizeOrderRequestBudget(request = {}) {
  const normalized = { ...request };
  normalized.looseShape = normalizeLooseShape(normalized.gem, normalized.looseShape);
  const minimumBudget = orderMinimumProfitablePrice(normalized);
  normalized.budget = roundThousand(Math.max(minimumBudget, Number(normalized.budget) || 0));
  return normalized;
}

function customerRequestSignature(request = {}) {
  return [
    request.item || '',
    request.gem || '',
    normalizeLooseShape(request.gem, request.looseShape),
    request.metal || '',
    request.design || '',
  ].join('|');
}

function randomCustomerPreference(request = {}) {
  const preferences = [
    { type: 'gem', value: request.gem, label: GEMS[request.gem]?.name || '石指定' },
    { type: 'metal', value: request.metal, label: METALS[request.metal]?.name || '地金指定' },
    { type: 'design', value: request.design, label: DESIGNS[request.design]?.name || 'デザイン指定' },
  ];
  return structuredClone(randomFrom(preferences, preferences[0]));
}

function buildRandomCustomerVisitRequest(customerId, branchNumber) {
  const customer = CUSTOMERS[customerId];
  const baseRequest = structuredClone(customer?.request || {});
  const branch = Math.max(1, Math.min(3, Math.floor(Number(branchNumber) || 1)));
  const allGemIds = Object.values(GEMS).filter((gem) => !gem.eventOnly).map((gem) => gem.id);
  const commonGemIds = allGemIds.filter((gemId) => !HIGH_VALUE_GEMS.includes(gemId));
  const gemPool = branch === 3 ? HIGH_VALUE_GEMS.filter((gemId) => GEMS[gemId]) : (commonGemIds.length ? commonGemIds : allGemIds);
  const metalPool = branch === 3 ? HIGH_VALUE_METALS.filter((metalId) => METALS[metalId]) : Object.keys(METALS);
  const request = {
    ...baseRequest,
    item: randomFrom(Object.keys(ITEMS), baseRequest.item || 'ring'),
    gem: randomFrom(gemPool, baseRequest.gem || 'amethyst'),
    metal: randomFrom(metalPool, baseRequest.metal || 'silver'),
    design: randomFrom(Object.keys(DESIGNS), baseRequest.design || 'simple'),
  };
  request.looseShape = randomFrom(looseShapeIdsForGem(request.gem), defaultLooseShapeForGem(request.gem));
  request.difficulty = customerVisitDifficulty(branch, baseRequest.difficulty || 'basic');
  request.requiredArtisanLevel = ORDER_DIFFICULTIES[request.difficulty]?.artisanLevel || 1;
  request.deadlineDays = ORDER_DIFFICULTIES[request.difficulty]?.days || 7;
  request.requiredTools = Array.isArray(baseRequest.requiredTools) && baseRequest.requiredTools.length
    ? [...new Set(baseRequest.requiredTools.map(String))]
    : ['jewelryBench'];
  request.preference = randomCustomerPreference(request);
  const quality = branch === 3 ? 'premium' : branch === 2 ? 'good' : 'standard';
  const recommended = recommendedPrice({ ...request, quality, useLoose: true });
  const budgetRate = branch === 3
    ? 1.15 + Math.random() * 0.35
    : branch === 2
      ? 1.05 + Math.random() * 0.25
      : 0.95 + Math.random() * 0.25;
  request.budget = roundThousand(recommended * budgetRate);
  request.storeProfile = branch === 3 ? 'premium' : branch === 2 ? 'quality' : 'general';
  return normalizeOrderRequestBudget(request);
}

function customerVisitRequest(customerId, branchNumber) {
  const customerState = state?.customers?.[customerId];
  const previousSignature = String(customerState?.lastRequestSignature || customerRequestSignature(customerState?.activeRequest || {}));
  let candidate = null;
  for (let attempt = 0; attempt < 16; attempt += 1) {
    candidate = buildRandomCustomerVisitRequest(customerId, branchNumber);
    if (!previousSignature || customerRequestSignature(candidate) !== previousSignature) return candidate;
  }
  // 極端に同じ抽選が続いた場合も、デザインを必ず次へ送って前回と同じ要望にならないようにする。
  const designIds = Object.keys(DESIGNS);
  const currentIndex = Math.max(0, designIds.indexOf(candidate?.design));
  candidate.design = designIds[(currentIndex + 1) % designIds.length] || 'simple';
  candidate.preference = { type: 'design', value: candidate.design, label: DESIGNS[candidate.design]?.name || 'デザイン指定' };
  return normalizeOrderRequestBudget(candidate);
}

function activeCustomerRequest(customerId) {
  const active = state?.customers?.[customerId]?.activeRequest;
  const source = active && typeof active === 'object' ? active : CUSTOMERS[customerId]?.request || {};
  return normalizeOrderRequestBudget(source);
}

function customerRequestDescription(request = {}) {
  const rows = [
    looseDisplayLabel(request.gem, normalizeLooseShape(request.gem, request.looseShape)),
    METALS[request.metal]?.name,
    DESIGNS[request.design]?.name,
    ITEMS[request.item]?.name,
  ].filter(Boolean);
  return rows.join('・') || '指定なし';
}

function customerTemplateText(template, request = {}) {
  const itemLabel = ITEMS[request.item]?.name || 'ジュエリー';
  return String(template || '').replace(/\{item\}/g, itemLabel);
}

function customerProfileData(customerId, request = {}, order = null) {
  const customer = CUSTOMERS[customerId] || {};
  const customerState = state?.customers?.[customerId];
  const hasStoredDetails = Boolean(order?.customerProfileDetails && typeof order.customerProfileDetails === 'object');
  const storedDetails = hasStoredDetails ? order.customerProfileDetails : {};
  const baseDetails = customer.details && typeof customer.details === 'object' ? customer.details : {};
  const summary = hasStoredDetails && order?.customerProfile
    ? String(order.customerProfile)
    : customer.profileTemplate
      ? customerTemplateText(customer.profileTemplate, request)
      : String(order?.customerProfile || customer.profile || customer.opening || 'プロフィール情報はありません。');
  return {
    relation: String(customerState?.relation || '初来店'),
    opening: customerTemplateText(customer.openingTemplate || customer.opening || 'ジュエリーを探しています。', request),
    summary,
    traits: String(order?.customerTraits || customer.traits || '特徴情報はありません。'),
    ageGroup: String(storedDetails.ageGroup || baseDetails.ageGroup || '不明'),
    occupation: String(storedDetails.occupation || baseDetails.occupation || '不明'),
    purpose: String(storedDetails.purpose || customerTemplateText(baseDetails.purposeTemplate || '希望に合う{item}を選ぶため', request)),
    wearer: String(storedDetails.wearer || baseDetails.wearer || '本人'),
    wearingScene: String(storedDetails.wearingScene || baseDetails.wearingScene || '日常'),
    preference: String(storedDetails.preference || baseDetails.preference || '長く使いやすいもの'),
    budgetStyle: String(storedDetails.budgetStyle || baseDetails.budgetStyle || '価格と品質のバランスを重視'),
  };
}

function customerProfileDetailsSnapshot(profile = {}) {
  return {
    ageGroup: String(profile.ageGroup || ''),
    occupation: String(profile.occupation || ''),
    purpose: String(profile.purpose || ''),
    wearer: String(profile.wearer || ''),
    wearingScene: String(profile.wearingScene || ''),
    preference: String(profile.preference || ''),
    budgetStyle: String(profile.budgetStyle || ''),
  };
}

function customerProfileCardMarkup(profile = {}) {
  return `<article class="customer-profile-card">
    <header><small>お客様プロフィール</small><span>${esc(profile.relation)}</span></header>
    <p class="customer-profile-summary">${esc(profile.summary)}</p>
    <dl class="customer-profile-grid">
      <div><dt>年代</dt><dd>${esc(profile.ageGroup)}</dd></div>
      <div><dt>職業</dt><dd>${esc(profile.occupation)}</dd></div>
      <div class="wide"><dt>来店目的</dt><dd>${esc(profile.purpose)}</dd></div>
      <div><dt>使用者</dt><dd>${esc(profile.wearer)}</dd></div>
      <div><dt>着用場面</dt><dd>${esc(profile.wearingScene)}</dd></div>
      <div class="wide"><dt>好み</dt><dd>${esc(profile.preference)}</dd></div>
      <div class="wide"><dt>予算の考え方</dt><dd>${esc(profile.budgetStyle)}</dd></div>
    </dl>
    <p class="customer-profile-traits"><b>接客傾向</b><span>${esc(profile.traits)}</span></p>
  </article>`;
}

function storeProductSaleBonus(item, branchNumber = state?.store?.branchNumber || 1) {
  const branch = Math.max(1, Math.min(3, Math.floor(Number(branchNumber) || 1)));
  if (!item || branch === 1) return 0;
  if (branch === 2) {
    if (item.quality === 'premium') return 0.16;
    if (item.quality === 'good') return 0.10;
    return -0.03;
  }
  let bonus = item.quality === 'premium' ? 0.12 : item.quality === 'good' ? 0.04 : 0;
  if ((item.useLoose !== false && HIGH_VALUE_GEMS.includes(item.gem)) || HIGH_VALUE_METALS.includes(item.metal)) bonus += 0.08;
  return bonus;
}

function orderClosed(order) {
  return CLOSED_ORDER_STATUSES.includes(order?.status);
}

function orderDifficultyId(orderLike = {}) {
  if (ORDER_DIFFICULTIES[orderLike.difficulty]) return orderLike.difficulty;
  return orderLike.design === 'simple' ? 'basic' : 'general';
}

function orderDifficulty(orderLike = {}) {
  return ORDER_DIFFICULTIES[orderDifficultyId(orderLike)];
}

function orderRequiredTools(orderLike = {}) {
  const tools = Array.isArray(orderLike.requiredTools) ? orderLike.requiredTools.filter((toolId) => WORKSHOP_TOOLS[toolId]) : [];
  return tools.length ? [...new Set(tools)] : ['jewelryBench'];
}

function orderLimit() {
  const level = Math.max(1, Math.min(20, Math.floor(Number(state?.artisan?.level) || 1)));
  if (level <= 3) return 1;
  if (level <= 7) return 2;
  if (level <= 11) return 3;
  if (level <= 15) return 4;
  if (level <= 19) return 5;
  return 6;
}

function activeOrderCount() {
  if (!Array.isArray(state?.orders)) return 0;
  return state.orders.filter((order) => !orderClosed(order)).length;
}

function orderMaterialsObtainable(request = {}) {
  const shape = normalizeLooseShape(request.gem, request.looseShape);
  return Boolean(ITEMS[request.item] && GEMS[request.gem] && METALS[request.metal] && DESIGNS[request.design] && looseShapeIdsForGem(request.gem).includes(shape));
}

function orderFeasibility(request = {}) {
  const difficulty = orderDifficulty(request);
  const requiredArtisanLevel = Math.max(1, Math.min(20, Number(request.requiredArtisanLevel) || difficulty.artisanLevel));
  const requiredTools = orderRequiredTools(request);
  const artisanReady = Math.max(1, Number(state?.artisan?.level) || 1) >= requiredArtisanLevel;
  const equipmentReady = requiredTools.every((toolId) => toolUsable(toolId));
  const materialsObtainable = orderMaterialsObtainable(request);
  const reasons = [];
  if (!artisanReady) reasons.push(`職人Lv.${requiredArtisanLevel}が必要`);
  if (!equipmentReady) reasons.push(`必要設備：${requiredTools.map((toolId) => WORKSHOP_TOOLS[toolId]?.name || toolId).join('、')}`);
  if (!materialsObtainable) reasons.push('材料をゲーム内で入手できない');
  return { possible: artisanReady && equipmentReady && materialsObtainable, difficulty, requiredArtisanLevel, requiredTools, artisanReady, equipmentReady, materialsObtainable, reasons };
}

function orderEstimatedFigures(request = {}) {
  const normalizedRequest = normalizeOrderRequestBudget(request);
  const looseShape = normalizeLooseShape(normalizedRequest.gem, normalizedRequest.looseShape);
  const draft = { ...normalizedRequest, looseShape, finish: 'mirror', quality: 'standard' };
  const estimatedCost = Math.max(0, Math.round(productionCost(draft)));
  const minimumPrice = orderMinimumProfitablePrice(draft);
  const difficultyId = orderDifficultyId(draft);
  const targetPrice = Math.max(minimumPrice, roundThousand(recommendedPrice({ ...draft, quality: 'good' }) + (ORDER_LABOR_FEES[difficultyId] || 0)));
  const budget = roundThousand(Math.max(minimumPrice, Number(normalizedRequest.budget) || targetPrice));
  const price = Math.max(minimumPrice, Math.min(budget, targetPrice));
  return { estimatedCost, price, estimatedProfit: price - estimatedCost, budget, minimumPrice };
}

function orderDisplayStatus(order) {
  if (order?.status === '期限切れ') return '期限切れ';
  if (order?.status === '完成') return '納品可能';
  if (order?.status === '受注') {
    const requirements = orderRequirements(order);
    const feasibility = orderFeasibility(order);
    return requirements.enoughMetal && requirements.enoughLoose && feasibility.artisanReady && feasibility.equipmentReady ? '製作可能' : '未製作';
  }
  return order?.status || '未製作';
}

function orderHistoryStatus(order) {
  if (order?.status === '完了') return { label: '納品済', className: 'delivered' };
  if (order?.status === '期限切れ') return { label: '期限切れ', className: 'expired' };
  if (order?.status === '取消') return { label: '取消', className: 'cancelled' };
  return { label: order?.status || '不明', className: 'other' };
}

function orderClosedSortValue(order, index = 0) {
  const day = Number(order?.closedDay ?? order?.deliveredDay ?? order?.expiredDay ?? order?.cancelledDay ?? order?.deadlineDay ?? order?.acceptedDay ?? 0) || 0;
  return day * 100000 + Math.max(0, Number(index) || 0);
}

function aquariumState() {
  state.aquarium = normalizeAquariumState(state.aquarium || createInitialAquariumState());
  return state.aquarium;
}

function aquariumUnlocked() {
  return Boolean(state && aquariumState().unlocked);
}

function aquariumFishDefinition(id) { return AQUARIUM_CONFIG.fish.find((row) => row.id === id) || null; }
function aquariumPlantDefinition(id) { return AQUARIUM_CONFIG.plants.find((row) => row.id === id) || null; }
function aquariumDisplayDefinition(id) { return AQUARIUM_CONFIG.displayItems.find((row) => row.id === id) || null; }
function aquariumFishLoad(aquarium = aquariumState()) {
  return AQUARIUM_CONFIG.fish.reduce((sum, def) => sum + Math.max(0, Number(aquarium.fish?.[def.id]?.inTank) || 0) * def.loadPoint, 0);
}
function refreshAquariumLoad(aquarium = aquariumState()) {
  aquarium.fishLoad = { current: aquariumFishLoad(aquarium), max: AQUARIUM_CONFIG.capacity.fishLoadMax };
  return aquarium.fishLoad.current;
}
function aquariumPlantTotal(aquarium = aquariumState()) {
  return AQUARIUM_CONFIG.plants.reduce((sum, def) => sum + Math.max(0, Number(aquarium.plants?.[def.id]?.inTank) || 0), 0);
}
function aquariumLimitResult(ok, reason = '', message = '') { return { ok, reason, ...(message ? { message } : {}) }; }
function canAcquireAquariumFish(id, quantity = 1) {
  const def = aquariumFishDefinition(id), row = aquariumState().fish?.[id], qty = Math.max(1, Math.floor(Number(quantity) || 1));
  if (!def || !row) return aquariumLimitResult(false, 'unknown');
  if (row.owned + qty > def.speciesMax) return aquariumLimitResult(false, 'species', AQUARIUM_CONFIG.rules.messages.fishSpeciesLimit);
  return aquariumLimitResult(true);
}
function canAddAquariumFishToTank(id, quantity = 1) {
  const aquarium = aquariumState(), def = aquariumFishDefinition(id), row = aquarium.fish?.[id], qty = Math.max(1, Math.floor(Number(quantity) || 1));
  if (!def || !row) return aquariumLimitResult(false, 'unknown');
  if (row.inTank + qty > def.speciesMax) return aquariumLimitResult(false, 'species', AQUARIUM_CONFIG.rules.messages.fishSpeciesLimit);
  if (aquariumFishLoad(aquarium) + qty * def.loadPoint > AQUARIUM_CONFIG.capacity.fishLoadMax) return aquariumLimitResult(false, 'load', AQUARIUM_CONFIG.rules.messages.fishLoadLimit);
  if (row.inTank + qty > row.owned) return aquariumLimitResult(false, 'owned');
  return aquariumLimitResult(true);
}
function canAcquireAquariumPlant(id, quantity = 1) {
  const def = aquariumPlantDefinition(id), row = aquariumState().plants?.[id], qty = Math.max(1, Math.floor(Number(quantity) || 1));
  if (!def || !row) return aquariumLimitResult(false, 'unknown');
  if (row.owned + qty > def.speciesMax) return aquariumLimitResult(false, 'species', AQUARIUM_CONFIG.rules.messages.plantSpeciesLimit);
  return aquariumLimitResult(true);
}
function canAddAquariumPlantToTank(id, quantity = 1) {
  const aquarium = aquariumState(), def = aquariumPlantDefinition(id), row = aquarium.plants?.[id], qty = Math.max(1, Math.floor(Number(quantity) || 1));
  if (!def || !row) return aquariumLimitResult(false, 'unknown');
  if (row.inTank + qty > def.speciesMax) return aquariumLimitResult(false, 'species', AQUARIUM_CONFIG.rules.messages.plantSpeciesLimit);
  if (aquariumPlantTotal(aquarium) + qty > AQUARIUM_CONFIG.capacity.plantTotalMax) return aquariumLimitResult(false, 'total', AQUARIUM_CONFIG.rules.messages.plantTotalLimit);
  if (row.inTank + qty > row.owned) return aquariumLimitResult(false, 'owned');
  return aquariumLimitResult(true);
}
function canAcquireAquariumDisplay(id, quantity = 1) {
  const def = aquariumDisplayDefinition(id), row = aquariumState().displayItems?.[id], qty = Math.max(1, Math.floor(Number(quantity) || 1));
  if (!def || !row) return aquariumLimitResult(false, 'unknown');
  if (row.owned + qty > def.ownedMax) return aquariumLimitResult(false, 'limit', AQUARIUM_CONFIG.rules.messages.displayLimit);
  return aquariumLimitResult(true);
}
function unlockAquariumFeature({ source = 'event', notify = true } = {}) {
  const aquarium = aquariumState(); const newlyUnlocked = !aquarium.unlocked; aquarium.unlocked = true;
  if (!aquarium.unlockedDay) aquarium.unlockedDay = Math.max(1, Math.floor(Number(state?.game?.day) || 1));
  if (!aquarium.unlockSource) aquarium.unlockSource = String(source || 'event').slice(0, 80);
  if (newlyUnlocked && notify) addNotification('水槽機能を解放しました', 'スマートフォンに「水槽」が追加されました。', 'special');
  return newlyUnlocked;
}
function setAquariumItemQuantity(id, quantity, metadata = {}) {
  const aquarium = aquariumState(), safeId = String(id || '').trim().slice(0, 100), qty = Math.max(0, Math.floor(Number(quantity) || 0)); if (!safeId) return false;
  const category = metadata.category || (aquarium.fish[safeId] ? 'fish' : aquarium.plants[safeId] ? 'plant' : aquarium.displayItems[safeId] ? 'display' : '');
  const collection = category === 'fish' ? aquarium.fish : category === 'plant' ? aquarium.plants : category === 'display' ? aquarium.displayItems : null;
  if (!collection?.[safeId]) return false;
  const key = category === 'display' ? 'owned' : 'owned', previous = collection[safeId][key]; collection[safeId][key] = qty;
  if (category === 'fish') collection[safeId].inTank = Math.min(collection[safeId].inTank, qty);
  if (category === 'plant') collection[safeId].inTank = Math.min(collection[safeId].inTank, qty);
  if (category === 'display') collection[safeId].installed = Math.min(collection[safeId].installed, qty);
  const changed = previous !== qty; if (changed) { aquarium.lastSyncRevision += 1; refreshAquariumLoad(aquarium); }
  return changed;
}
function addAquariumItem(id, quantity = 1, metadata = {}) {
  const aquarium = aquariumState(), safeId = String(id || '').trim().slice(0, 100), qty = Math.max(0, Math.floor(Number(quantity) || 0)); if (!safeId || !qty) return false;
  const category = metadata.category || (aquarium.fish[safeId] ? 'fish' : aquarium.plants[safeId] ? 'plant' : aquarium.displayItems[safeId] ? 'display' : '');
  const check = category === 'fish' ? canAcquireAquariumFish(safeId, qty) : category === 'plant' ? canAcquireAquariumPlant(safeId, qty) : category === 'display' ? canAcquireAquariumDisplay(safeId, qty) : aquariumLimitResult(false, 'unknown');
  if (!check.ok) { if (check.message) showToast(check.message); return false; }
  const row = category === 'fish' ? aquarium.fish[safeId] : category === 'plant' ? aquarium.plants[safeId] : aquarium.displayItems[safeId]; row.owned += qty; aquarium.lastSyncRevision += 1; return true;
}
function setAquariumDisplayInstalled(id, target) {
  const aquarium = aquariumState(), def = aquariumDisplayDefinition(id), row = aquarium.displayItems?.[id]; if (!def || !row || def.required) return aquariumLimitResult(false, 'required');
  const next = Math.max(0, Math.floor(Number(target) || 0));
  if (next > def.installedMax || next > row.owned) return aquariumLimitResult(false, 'limit', next > row.owned ? '所持数が不足しています' : AQUARIUM_CONFIG.rules.messages.displayLimit);
  if (row.installed === next) return aquariumLimitResult(true);
  row.installed = next; aquarium.lastSyncRevision += 1; return aquariumLimitResult(true);
}
function aquariumSnapshot() { const aquarium = aquariumState(); refreshAquariumLoad(aquarium); return structuredClone(aquarium); }

const AQUARIUM_ENGINE_FISH_ALIASES = Object.freeze({
  rummy_nose_tetra: ['rummy_nose_tetra', 'rummynose_tetra'],
});
const AQUARIUM_ENGINE_PLANT_ALIASES = Object.freeze({
  amazon_sword: ['amazon_sword', 'amazon_sword_plant'],
});
const AQUARIUM_ENGINE_LAYOUT_ALIASES = Object.freeze({
  driftwood: ['driftwood', 'driftwood_large_a', 'driftwood_medium_a', 'driftwood_small_a'],
  layout_stone: ['layout_stone', 'stone_dark_medium', 'stone_smooth_medium', 'stone_gray_medium'],
});

function aquariumEngineCompatibleId(registry, id, aliases = {}) {
  const candidates = aliases[id] || [id];
  return candidates.find((candidate) => registry && Object.prototype.hasOwnProperty.call(registry, candidate)) || '';
}

function aquariumRuntimeFingerprint(snapshot = aquariumSnapshot()) {
  return JSON.stringify({
    revision: Math.max(0, Math.floor(Number(snapshot?.lastSyncRevision) || 0)),
    fish: AQUARIUM_CONFIG.fish.map((definition) => [definition.id, Math.max(0, Math.floor(Number(snapshot?.fish?.[definition.id]?.inTank) || 0))]),
    plants: AQUARIUM_CONFIG.plants.map((definition) => [definition.id, Math.max(0, Math.floor(Number(snapshot?.plants?.[definition.id]?.inTank) || 0))]),
    layout: AQUARIUM_CONFIG.displayItems.filter((definition) => !definition.required).map((definition) => [definition.id, Math.max(0, Math.floor(Number(snapshot?.displayItems?.[definition.id]?.installed) || 0))]),
  });
}

function normalizeAquariumObservationName(value) {
  return String(value || '').replace(/[\s・･（）()\[\]【】「」『』]/g, '').toLowerCase();
}

function aquariumCurrentObservationNames(snapshot = aquariumSnapshot(), engine = null) {
  const names = new Set();
  const fishRegistry = engine?.config?.speciesProfiles || {};
  const decorationRegistry = engine?.config?.decorationProfiles || {};
  for (const definition of AQUARIUM_CONFIG.fish) {
    if (Math.max(0, Math.floor(Number(snapshot.fish?.[definition.id]?.inTank) || 0)) <= 0) continue;
    names.add(normalizeAquariumObservationName(definition.name));
    const engineId = aquariumEngineCompatibleId(fishRegistry, definition.id, AQUARIUM_ENGINE_FISH_ALIASES);
    if (engineId) names.add(normalizeAquariumObservationName(fishRegistry[engineId]?.displayName));
  }
  for (const definition of AQUARIUM_CONFIG.plants) {
    if (Math.max(0, Math.floor(Number(snapshot.plants?.[definition.id]?.inTank) || 0)) <= 0) continue;
    names.add(normalizeAquariumObservationName(definition.name));
    const engineId = aquariumEngineCompatibleId(decorationRegistry, definition.id, AQUARIUM_ENGINE_PLANT_ALIASES);
    if (engineId) names.add(normalizeAquariumObservationName(decorationRegistry[engineId]?.displayName));
  }
  // v0.10.726: 観察画面は固定5項目を常時表示し、任意レイアウト品は実際に設置中のみ表示する。
  for (const definition of AQUARIUM_CONFIG.displayItems) {
    const installed = Math.max(0, Math.floor(Number(snapshot.displayItems?.[definition.id]?.installed) || 0));
    if (!definition.required && installed <= 0) continue;
    names.add(normalizeAquariumObservationName(definition.name));
    const engineId = aquariumEngineCompatibleId(decorationRegistry, definition.id, AQUARIUM_ENGINE_LAYOUT_ALIASES);
    if (engineId) names.add(normalizeAquariumObservationName(decorationRegistry[engineId]?.displayName));
  }
  names.delete('');
  return names;
}

function aquariumPlacedDiscoveryNames(snapshot = aquariumSnapshot(), engine = null) {
  const names = new Set();
  const fishRegistry = engine?.config?.speciesProfiles || {};
  const decorationRegistry = engine?.config?.decorationProfiles || {};
  for (const definition of AQUARIUM_CONFIG.fish) {
    // v0.10.619: 所持しただけでは図鑑・一覧・詳細を解放しない。
    // 実際に水槽へ入っている魚だけを既知扱いにする。
    if (Math.max(0, Math.floor(Number(snapshot.fish?.[definition.id]?.inTank) || 0)) <= 0) continue;
    names.add(normalizeAquariumObservationName(definition.name));
    const engineId = aquariumEngineCompatibleId(fishRegistry, definition.id, AQUARIUM_ENGINE_FISH_ALIASES);
    if (engineId) names.add(normalizeAquariumObservationName(fishRegistry[engineId]?.displayName));
  }
  for (const definition of AQUARIUM_CONFIG.plants) {
    // 水草も実際に水槽へ入っている種類だけ表示・詳細閲覧を許可する。
    if (Math.max(0, Math.floor(Number(snapshot.plants?.[definition.id]?.inTank) || 0)) <= 0) continue;
    names.add(normalizeAquariumObservationName(definition.name));
    const engineId = aquariumEngineCompatibleId(decorationRegistry, definition.id, AQUARIUM_ENGINE_PLANT_ALIASES);
    if (engineId) names.add(normalizeAquariumObservationName(decorationRegistry[engineId]?.displayName));
  }
  for (const definition of AQUARIUM_CONFIG.displayItems) {
    // 任意用品は設置されているものだけ既知扱いにする。必須用品は既存仕様を維持。
    if (!definition.required && Math.max(0, Math.floor(Number(snapshot.displayItems?.[definition.id]?.installed) || 0)) <= 0) continue;
    if (definition.required || Math.max(0, Math.floor(Number(snapshot.displayItems?.[definition.id]?.installed) || 0)) > 0) {
      names.add(normalizeAquariumObservationName(definition.name));
      const engineId = aquariumEngineCompatibleId(decorationRegistry, definition.id, AQUARIUM_ENGINE_LAYOUT_ALIASES);
      if (engineId) names.add(normalizeAquariumObservationName(decorationRegistry[engineId]?.displayName));
    }
  }
  return names;
}

function aquariumKnownDiscoveryNames(engine = null) {
  const names = new Set();
  const fishRegistry = engine?.config?.speciesProfiles || {};
  const decorationRegistry = engine?.config?.decorationProfiles || {};
  for (const definition of AQUARIUM_CONFIG.fish) {
    names.add(normalizeAquariumObservationName(definition.name));
    const engineId = aquariumEngineCompatibleId(fishRegistry, definition.id, AQUARIUM_ENGINE_FISH_ALIASES);
    if (engineId) names.add(normalizeAquariumObservationName(fishRegistry[engineId]?.displayName));
  }
  for (const definition of AQUARIUM_CONFIG.plants) {
    names.add(normalizeAquariumObservationName(definition.name));
    const engineId = aquariumEngineCompatibleId(decorationRegistry, definition.id, AQUARIUM_ENGINE_PLANT_ALIASES);
    if (engineId) names.add(normalizeAquariumObservationName(decorationRegistry[engineId]?.displayName));
  }
  for (const definition of AQUARIUM_CONFIG.displayItems) {
    names.add(normalizeAquariumObservationName(definition.name));
    const engineId = aquariumEngineCompatibleId(decorationRegistry, definition.id, AQUARIUM_ENGINE_LAYOUT_ALIASES);
    if (engineId) names.add(normalizeAquariumObservationName(decorationRegistry[engineId]?.displayName));
  }
  names.delete('');
  return names;
}

// v0.10.619: 魚・水草は「所持」だけでは一覧・詳細を解放せず、実際に水槽へ入った種類だけ表示する。
function filterAquariumUndiscoveredDocument(frame) {
  try {
    const documentRef = frame?.contentDocument;
    if (!documentRef) return false;
    const engine = frame.contentWindow?.aquariumEngine || null;
    const snapshot = aquariumSnapshot();
    const placedNames = aquariumPlacedDiscoveryNames(snapshot, engine);
    const hiddenNames = [...aquariumKnownDiscoveryNames(engine)].filter((name) => !placedNames.has(name));

    // 名前がDOMに出ていないカードや詳細ボタンも、IDから未解放種を判定して消す。
    // これにより画像だけのカード・selectのvalue・data属性経由の詳細導線も先に見えない。
    const fishRegistry = engine?.config?.speciesProfiles || {};
    const decorationRegistry = engine?.config?.decorationProfiles || {};
    const allowedIds = new Set();
    const knownIds = new Set();
    const addIds = (set, values) => values.filter(Boolean).forEach((value) => set.add(String(value).trim().toLowerCase()));
    for (const definition of AQUARIUM_CONFIG.fish) {
      const engineId = aquariumEngineCompatibleId(fishRegistry, definition.id, AQUARIUM_ENGINE_FISH_ALIASES);
      addIds(knownIds, [definition.id, engineId]);
      if (Math.max(0, Math.floor(Number(snapshot.fish?.[definition.id]?.inTank) || 0)) > 0) addIds(allowedIds, [definition.id, engineId]);
    }
    for (const definition of AQUARIUM_CONFIG.plants) {
      const engineId = aquariumEngineCompatibleId(decorationRegistry, definition.id, AQUARIUM_ENGINE_PLANT_ALIASES);
      addIds(knownIds, [definition.id, engineId]);
      if (Math.max(0, Math.floor(Number(snapshot.plants?.[definition.id]?.inTank) || 0)) > 0) addIds(allowedIds, [definition.id, engineId]);
    }
    for (const definition of AQUARIUM_CONFIG.displayItems) {
      const engineId = aquariumEngineCompatibleId(decorationRegistry, definition.id, AQUARIUM_ENGINE_LAYOUT_ALIASES);
      addIds(knownIds, [definition.id, engineId]);
      if (definition.required || Math.max(0, Math.floor(Number(snapshot.displayItems?.[definition.id]?.installed) || 0)) > 0) addIds(allowedIds, [definition.id, engineId]);
    }
    const hiddenIds = new Set([...knownIds].filter((id) => !allowedIds.has(id)));
    const containsHiddenName = (text) => {
      const normalized = normalizeAquariumObservationName(text);
      return normalized && hiddenNames.some((name) => name && normalized.includes(name));
    };
    const containsHiddenId = (node) => {
      if (!(node instanceof Element)) return false;
      const values = [
        node.getAttribute('value'), node.getAttribute('data-item-id'), node.getAttribute('data-species'),
        node.getAttribute('data-species-id'), node.getAttribute('data-id'), node.getAttribute('data-detail-id'),
        node.getAttribute('data-fish-id'), node.getAttribute('data-plant-id'),
      ].filter(Boolean).map((value) => String(value).trim().toLowerCase());
      return values.some((value) => hiddenIds.has(value));
    };

    documentRef.querySelectorAll('option').forEach((option) => {
      if (containsHiddenName(option.textContent) || containsHiddenId(option)) option.remove();
    });

    documentRef.querySelectorAll('[data-item-id],[data-species],[data-species-id],[data-id],[data-detail-id],[data-fish-id],[data-plant-id]').forEach((node) => {
      if (!containsHiddenId(node)) return;
      const row = node.closest('.item-card,.inventory-item,.collection-item,.catalog-item,.option-card,.shop-item,.list-item,tr,li');
      (row || node).remove();
    });

    const leafSelectors = '.item-name,.species-name,.plant-name,.decoration-name,.inventory-name,.collection-name,.catalog-name,[data-item-name],[data-species-name]';
    documentRef.querySelectorAll(leafSelectors).forEach((nameNode) => {
      if (!containsHiddenName(nameNode.textContent || nameNode.getAttribute('data-item-name') || nameNode.getAttribute('data-species-name'))) return;
      const row = nameNode.closest('.item-card,.inventory-item,.collection-item,.catalog-item,.option-card,.shop-item,.list-item,tr,li');
      (row || nameNode).remove();
    });

    const candidateSelectors = '.item-card,.inventory-item,.collection-item,.catalog-item,.option-card,.shop-item,.list-item,tr,li,[data-item-id],[data-species]';
    documentRef.querySelectorAll(candidateSelectors).forEach((node) => {
      if (containsHiddenName(node.textContent)) node.remove();
    });

    // カード構造に含まれない説明文・ボタン・ラベルに将来品名が出た場合も伏せる。
    documentRef.querySelectorAll('button,label,span,strong,p,small,td,th').forEach((node) => {
      if (!containsHiddenName(node.textContent)) return;
      const row = node.closest('.item-card,.inventory-item,.collection-item,.catalog-item,.option-card,.shop-item,.list-item,tr,li');
      (row || node).remove();
    });
    return true;
  } catch (_) {
    return false;
  }
}

function filterAquariumObservationDocument(frame) {
  try {
    const documentRef = frame?.contentDocument;
    if (!documentRef) return false;
    const engine = frame.contentWindow?.aquariumEngine || null;
    const allowedNames = aquariumCurrentObservationNames(aquariumSnapshot(), engine);
    documentRef.querySelectorAll('.empty').forEach((empty) => {
      if (String(empty.textContent || '').includes('観察')) empty.textContent = '現在の水槽設備と、水槽内にいる魚・水草・設置品を確認できます。';
    });
    documentRef.querySelectorAll('.section').forEach((section) => {
      section.querySelectorAll('.item-card').forEach((card) => {
        const name = normalizeAquariumObservationName(card.querySelector('.item-name')?.textContent);
        if (!name || !allowedNames.has(name)) card.remove();
      });
      if (!section.querySelector('.item-card')) section.remove();
    });
    return true;
  } catch (_) {
    return false;
  }
}

function installAquariumObservationGuard(frame) {
  try {
    const documentRef = frame?.contentDocument;
    if (!documentRef?.documentElement) return false;
    if (frame.__jxjObservationObserver) return true;
    const Observer = frame.contentWindow?.MutationObserver || MutationObserver;
    const observer = new Observer(() => {
      filterAquariumObservationDocument(frame);
      filterAquariumUndiscoveredDocument(frame);
    });
    observer.observe(documentRef.documentElement, { childList: true, subtree: true });
    frame.__jxjObservationObserver = observer;
    filterAquariumObservationDocument(frame);
    filterAquariumUndiscoveredDocument(frame);
    return true;
  } catch (_) {
    return false;
  }
}

function installAquariumPortraitCentering(frame) {
  try {
    const documentRef = frame?.contentDocument;
    if (!documentRef?.head) return false;
    const styleId = 'jxj-main-game-portrait-centering';
    let style = documentRef.getElementById(styleId);
    if (!style) {
      style = documentRef.createElement('style');
      style.id = styleId;
      style.textContent = `@media (orientation: portrait) {
        .tank-view {
          justify-content: center !important;
          padding-top: 0 !important;
        }
      }`;
      documentRef.head.appendChild(style);
    }
    return true;
  } catch (_) {
    return false;
  }
}

function syncAquariumRuntime(frame = document.querySelector('.aquarium-game-frame'), options = {}) {
  const force = Boolean(options.force);
  if (!frame?.contentWindow) return false;
  try {
    const aquariumWindow = frame.contentWindow;
    const engine = aquariumWindow.aquariumEngine;
    if (!engine || typeof engine.getObservationEntries !== 'function') return false;

    if (!engine.__jxjObservationFilterInstalled) {
      const originalGetObservationEntries = engine.getObservationEntries.bind(engine);
      engine.getObservationEntries = () => {
        const allowed = engine.__jxjAllowedObservationKeys;
        return originalGetObservationEntries().filter((entry) => {
          const category = entry?.category === 'plant' ? 'plants' : entry?.category;
          if (!entry || !['fish', 'plants'].includes(category)) return false;
          return !(allowed instanceof Set) || allowed.has(`${category}:${entry.id}`);
        });
      };
      engine.__jxjObservationFilterInstalled = true;
    }

    const snapshot = aquariumSnapshot();
    const fingerprint = aquariumRuntimeFingerprint(snapshot);
    if (force || engine.__jxjMainGameFingerprint !== fingerprint) {
      const fishRegistry = engine.config?.speciesProfiles || {};
      const decorationRegistry = engine.config?.decorationProfiles || {};
      const allowedObservationKeys = new Set();
      const wasRunning = Boolean(engine.running);
      engine.stop?.();
      engine.clear?.({ keepAcquisitionHistory: false, keepLossLedger: false });

      for (const definition of AQUARIUM_CONFIG.fish) {
        const count = Math.max(0, Math.floor(Number(snapshot.fish?.[definition.id]?.inTank) || 0));
        if (count <= 0) continue;
        const engineId = aquariumEngineCompatibleId(fishRegistry, definition.id, AQUARIUM_ENGINE_FISH_ALIASES);
        if (!engineId) continue;
        allowedObservationKeys.add(`fish:${engineId}`);
        for (let index = 0; index < count; index += 1) engine.addFish?.({ species: engineId });
      }

      for (const definition of AQUARIUM_CONFIG.plants) {
        const count = Math.max(0, Math.floor(Number(snapshot.plants?.[definition.id]?.inTank) || 0));
        if (count <= 0) continue;
        const engineId = aquariumEngineCompatibleId(decorationRegistry, definition.id, AQUARIUM_ENGINE_PLANT_ALIASES);
        if (!engineId) continue;
        allowedObservationKeys.add(`plants:${engineId}`);
        for (let index = 0; index < count; index += 1) engine.addDecoration?.({ itemId: engineId, category: 'plants' });
      }

      for (const definition of AQUARIUM_CONFIG.displayItems.filter((entry) => !entry.required)) {
        const count = Math.max(0, Math.floor(Number(snapshot.displayItems?.[definition.id]?.installed) || 0));
        if (count <= 0) continue;
        const engineId = aquariumEngineCompatibleId(decorationRegistry, definition.id, AQUARIUM_ENGINE_LAYOUT_ALIASES);
        if (!engineId) continue;
        for (let index = 0; index < count; index += 1) engine.addDecoration?.({ itemId: engineId, category: 'layout' });
      }

      engine.__jxjAllowedObservationKeys = allowedObservationKeys;
      engine.__jxjMainGameFingerprint = fingerprint;
      if (wasRunning || engine.options?.autoStart !== false) engine.start?.();
    }

    installAquariumObservationGuard(frame);
    filterAquariumObservationDocument(frame);
    filterAquariumUndiscoveredDocument(frame);
    return true;
  } catch (error) {
    console.warn('水槽ミニゲームの現在配置同期に失敗しました。', error);
    return false;
  }
}

function postAquariumSnapshot(frame = document.querySelector('.aquarium-game-frame')) {
  if (!frame?.contentWindow) return false;
  const targetOrigin = window.location.origin && window.location.origin !== 'null' ? window.location.origin : '*';
  frame.contentWindow.postMessage({ source: 'jxj-main-game', type: 'aquarium-state', state: aquariumSnapshot() }, targetOrigin);
  return true;
}

function bindAquariumFrameSync() {
  const frame = document.querySelector('.aquarium-game-frame');
  if (!(frame instanceof HTMLIFrameElement)) return;
  const forceFreshSyncs = () => {
    for (const delay of [120, 450, 1000, 1800]) {
      window.setTimeout(() => {
        if (!frame.isConnected) return;
        postAquariumSnapshot(frame);
        syncAquariumRuntime(frame, { force: true });
      }, delay);
    }
  };
  const sync = () => {
    postAquariumSnapshot(frame);
    installAquariumPortraitCentering(frame);
    syncAquariumRuntime(frame);
    forceFreshSyncs();
  };
  if (frame.dataset.jxjSyncBound !== '1') {
    frame.dataset.jxjSyncBound = '1';
    frame.addEventListener('load', () => {
      sync();
      [80, 260, 700, 1400].forEach((delay) => window.setTimeout(sync, delay));
    });
  }
  sync();
  [80, 260, 700, 1400].forEach((delay) => window.setTimeout(sync, delay));
}


function validPhoneTab(value) {
  const tabs = ['profile', 'calendar', 'notifications', 'finance', 'items', 'gift'];
  if (aquariumUnlocked()) tabs.push('aquarium');
  tabs.push('ai', 'settings');
  return tabs.includes(value) ? value : 'notifications';
}

function validFinancePeriod(value) {
  return ['today', 'month', 'year', 'cumulative'].includes(value) ? value : 'today';
}

function financePeriodRows(period = state?.game?.financePeriod) {
  const resolved = validFinancePeriod(period);
  const current = gameDate();
  return (state?.finance || []).filter((row) => {
    if (resolved === 'cumulative') return true;
    const rowDate = gameDateForDay(row.day);
    if (resolved === 'today') return Number(row.day) === Number(state.game.day);
    if (resolved === 'month') {
      return rowDate.getFullYear() === current.getFullYear() && rowDate.getMonth() === current.getMonth();
    }
    return rowDate.getFullYear() === current.getFullYear();
  });
}

function financePeriodHeading(period = state?.game?.financePeriod) {
  const resolved = validFinancePeriod(period);
  const current = gameDate();
  if (resolved === 'today') return `今日の収支（${current.getMonth() + 1}月${current.getDate()}日）`;
  if (resolved === 'month') return `${current.getFullYear()}年${current.getMonth() + 1}月の収支`;
  if (resolved === 'year') return `${current.getFullYear()}年の収支`;
  return 'これまでの累計収支';
}

function financeRowDateLabel(dayNumber) {
  const date = gameDateForDay(dayNumber);
  return `${date.getMonth() + 1}月${date.getDate()}日`;
}

function notificationDateLabel(dayNumber) {
  const date = gameDateForDay(dayNumber);
  return `${date.getFullYear()}年${date.getMonth() + 1}月${date.getDate()}日`;
}

function materialRequirementsFor({ item, gem, looseShape, metal, orderId = null, useLoose = true }) {
  const order = orderId ? state.orders.find((entry) => entry.id === orderId) : null;
  const itemData = ITEMS[item] || ITEMS.ring;
  const usesLoose = order ? true : useLoose !== false;
  const resolvedLooseShape = normalizeLooseShape(gem, order?.looseShape || looseShape);
  const requiredMetalWeight = roundedMetalWeight(Math.max(0.1, Number(order?.requiredMetalWeight) || Number(itemData.metalWeight) || 1));
  const requiredLooseQuantity = usesLoose ? Math.max(1, Math.round(Number(order?.requiredLooseQuantity) || Number(itemData.looseQuantity) || 1)) : 0;
  const ownedMetalWeight = metalOwnedWeight(metal);
  const reservedMetalWeight = metalReservedWeight(metal);
  const availableMetalWeight = metalAvailableWeight(metal, order?.id || '');
  const ownedLooseQuantity = usesLoose ? looseOwned(gem, resolvedLooseShape) : 0;
  const reservedLooseQuantity = usesLoose ? looseReservedQuantity(gem, resolvedLooseShape) : 0;
  const reservedLooseOtherOrders = usesLoose ? (order ? looseReservedQuantity(gem, resolvedLooseShape, order.id) : reservedLooseQuantity) : 0;
  const availableLooseQuantity = usesLoose ? Math.max(0, ownedLooseQuantity - reservedLooseOtherOrders) : 0;
  const missingMetalWeight = roundedMetalWeight(Math.max(0, requiredMetalWeight - availableMetalWeight));
  const missingLooseQuantity = usesLoose ? Math.max(0, requiredLooseQuantity - availableLooseQuantity) : 0;
  return {
    usesLoose,
    looseShape: resolvedLooseShape,
    requiredMetalWeight, requiredLooseQuantity, ownedMetalWeight, reservedMetalWeight, availableMetalWeight,
    ownedLooseQuantity, reservedLooseQuantity, reservedLooseOtherOrders, availableLooseQuantity,
    missingMetalWeight, missingLooseQuantity,
    enoughMetal: availableMetalWeight + 1e-9 >= requiredMetalWeight,
    enoughLoose: !usesLoose || availableLooseQuantity >= requiredLooseQuantity,
  };
}

function orderRequirements(order) {
  return materialRequirementsFor({ ...order, orderId: order.id });
}

