function renderSupplier() {
  // v0.10.154以前の保存画面との互換用。現在は地金屋から地金画面へ直接入ります。
  return renderSupplierMetals();
}

function renderSupplierMetals() {
  const requestedView = screenData.view || screenData.tab || 'market';
  const normalizedView = requestedView === 'metalBuy' || requestedView === 'metals' || requestedView === 'buy' ? 'buy'
    : requestedView === 'metalSell' || requestedView === 'sell' ? 'sell'
      : 'market';
  const view = ['market', 'buy', 'sell'].includes(normalizedView) ? normalizedView : 'market';
  const mode = view === 'sell' ? 'sell' : 'buy';
  const orderedMetals = METAL_WORKSHOP_ORDER.map((id) => METALS[id]).filter(Boolean);
  const products = view === 'sell'
    ? orderedMetals.filter((product) => metalOwnedWeight(product.id) > 0)
    : orderedMetals;
  const tradeReady = metalMarketTradeReady();
  const productRows = view === 'market' || !tradeReady ? '' : products.map((product) => {
    const owned = metalOwnedWeight(product.id);
    const reserved = metalReservedWeight(product.id);
    const available = metalAvailableWeight(product.id);
    const storageLimit = metalStorageLimit(product.id);
    const maximum = metalTradeMaximum(mode, product.id);
    const quantity = metalTradeQuantity(mode, product.id);
    const perGram = metalTradePricePerGram(mode, product.id);
    const disabled = !tradeReady || quantity < 1 || !canSpendHours(1);
    return `<article class="product-row metal-product-row metal-trade-card" data-metal-trade-card="${mode}:${product.id}">
      <div class="product-main metal-trade-heading">
        <div class="metal-title-status-row">
          <strong class="metal-product-name"><span class="metal-name-wrap">${metalVisual(product.id, 'metal-inline-visual')}<span>${esc(product.name)}</span></span></strong>
          <div class="metal-owned-limit">
            <small>現在所持：${metalWeightLabel(owned)}g</small>
            <small>保管上限：${metalWeightLabel(storageLimit)}g</small>
          </div>
        </div>
        <div class="metal-limit-price-row">
          <small class="metal-maximum">${mode === 'buy' ? '現在購入できる最大量' : '現在売却できる最大量'}：${maximum}g</small>
          <small class="metal-unit-price">${mode === 'buy' ? '購入' : '売却'}価格　${yen(perGram)}／g</small>
        </div>
        ${reserved > 0 ? `<div class="metal-reservation-summary"><small>注文に使用予定：${metalWeightLabel(reserved)}g</small><small>使用できる重量：${metalWeightLabel(available)}g</small></div>` : ''}
      </div>
      ${mode === 'buy' ? `<div class="metal-purchase-control-row">
        <span class="metal-quantity-label">購入重量</span>
        <span class="metal-vertical-stepper" aria-label="重量を増減">
          <button type="button" class="metal-stepper-button metal-stepper-up" data-action="metal-qty-step" data-mode="${mode}" data-id="${product.id}" data-delta="1" aria-label="${esc(product.name)}を1g増やす。長押しで連続増加" ${quantity >= maximum ? 'disabled' : ''}>▲</button>
          <span class="metal-input-wrap"><output class="quantity-readout" data-metal-trade-value aria-live="polite" aria-label="${esc(product.name)}の購入重量">${quantity}</output><b>g</b></span>
          <button type="button" class="metal-stepper-button metal-stepper-down" data-action="metal-qty-step" data-mode="${mode}" data-id="${product.id}" data-delta="-1" aria-label="${esc(product.name)}を1g減らす。長押しで連続減少" ${quantity <= 0 ? 'disabled' : ''}>▼</button>
        </span>
        <button class="primary-button metal-inline-purchase" data-action="buy-metal" data-id="${product.id}" ${disabled ? 'disabled' : ''}>購入</button>
      </div>` : `<div class="metal-quantity-area">
        <div class="metal-quantity-input"><span>売却重量</span><span class="metal-vertical-stepper" aria-label="重量を増減">
          <button type="button" class="metal-stepper-button metal-stepper-up" data-action="metal-qty-step" data-mode="${mode}" data-id="${product.id}" data-delta="1" aria-label="${esc(product.name)}を1g増やす。長押しで連続増加" ${quantity >= maximum ? 'disabled' : ''}>▲</button>
          <span class="metal-input-wrap"><output class="quantity-readout" data-metal-trade-value aria-live="polite" aria-label="${esc(product.name)}の売却重量">${quantity}</output><b>g</b></span>
          <button type="button" class="metal-stepper-button metal-stepper-down" data-action="metal-qty-step" data-mode="${mode}" data-id="${product.id}" data-delta="-1" aria-label="${esc(product.name)}を1g減らす。長押しで連続減少" ${quantity <= 0 ? 'disabled' : ''}>▼</button>
        </span></div>
        <button type="button" class="secondary-button full-button metal-max-button" data-action="metal-qty-max" data-mode="${mode}" data-id="${product.id}" ${maximum < 1 ? 'disabled' : ''}>全部売る</button>
      </div>`}
      <div class="metal-trade-preview" data-metal-trade-preview>${metalTradePreviewMarkup(mode, product.id, quantity)}</div>
      ${mode === 'sell' ? `<button class="primary-button full-button metal-trade-submit" data-action="sell-metal" data-id="${product.id}" ${disabled ? 'disabled' : ''}>売却する</button>` : ''}
      ${mode === 'sell' && reserved > 0 ? '<p class="small-note metal-fraction-note">注文に使用予定の地金は売却できません。</p>' : mode === 'sell' && owned > 0 && maximum < 1 ? '<p class="small-note metal-fraction-note">1g未満の端数は所持品に残ります。</p>' : ''}
    </article>`;
  }).join('');

  const marketContent = `
    ${metalSpotMarketMarkup()}
    <button type="button" class="secondary-button full-button metal-market-detail-button" data-action="metal-history-open">地金相場推移</button>
    <div class="button-stack metal-market-trade-buttons">
      <button type="button" class="primary-button large-button full-button" data-action="metal-trade-open" data-mode="buy" ${tradeReady ? '' : 'disabled'}>地金を買う</button>
      <button type="button" class="secondary-button large-button full-button" data-action="metal-trade-open" data-mode="sell" ${tradeReady ? '' : 'disabled'}>地金を売る</button>
    </div>`;
  const tradeContent = `
    <button type="button" class="secondary-button full-button metal-market-return-button" data-action="metal-market-home">地金相場へ戻る</button>
    <div class="product-list metal-trade-list">
      ${!tradeReady
        ? '<div class="empty-state sell-empty-state"><strong>地金相場を確認できないため売買を停止しています。</strong><small>地金相場へ戻り「相場を再取得」を押してください。</small></div>'
        : (productRows || (view === 'sell' ? '<div class="empty-state sell-empty-state"><strong>売却できる地金はありません。</strong></div>' : ''))}
    </div>`;

  return shell('地金', `
    <div class="split-layout">
      <section class="scene-space"></section>
      <section class="action-panel glass-panel">
        ${view === 'market' ? marketContent : tradeContent}
      </section>
    </div>`, { help: '地金画面では純プラチナ・純金・純銀の現実相場を確認できます。地金相場推移では月間・年間の履歴を最大5年間表示します。購入・売却重量は▲▼で1gずつ選び、長押しで連続増減します。数字の直接入力はできません。' });
}

function roughSaleContentMarkup() {
  const products = Object.values(GEMS).filter((product) => Number(state.inventory.rough[product.id]) > 0);
  const productRows = products.map((product) => {
    const owned = state.inventory.rough[product.id];
    const price = roughSalePrice(product.id);
    const disabled = !canSpendHours(1);
    return `<article class="product-row">
      <div class="product-main">
        ${roughVisual(product.id, 'gem-inline')}
        <div><strong>${esc(roughDisplayName(product.id))}</strong><small>所持：${owned}個</small></div>
      </div>
      <strong>${yen(price)}</strong>
      <div class="sell-action-row">
        <button class="primary-button" data-action="sell-rough" data-id="${product.id}" ${disabled ? 'disabled' : ''}>1個売る</button>
        <button class="secondary-button" data-action="sell-all-rough" data-id="${product.id}" ${disabled ? 'disabled' : ''}>全部売る</button>
      </div>
    </article>`;
  }).join('');
  return `<section class="loose-shop-rough-sale">
    <div class="product-list">
      ${productRows || '<div class="empty-state sell-empty-state"><strong>売却できる原石はありません。</strong><p>所持数が1個以上ある原石だけ表示されます。</p></div>'}
    </div>
  </section>`;
}

function renderSupplierRough() {
  // v0.10.154以前の保存画面との互換用。原石売却はルース屋へ統合済みです。
  return renderLooseShop('rough');
}

function renderLooseShop(forcedTab = '') {
  const requestedTab = forcedTab || screenData.tab || 'buy';
  const tab = ['buy', 'sell', 'rough'].includes(requestedTab) ? requestedTab : 'buy';
  const isSelling = tab === 'sell';
  const isRoughSelling = tab === 'rough';
  const selectedGem = isRoughSelling ? null : (GEMS[screenData.gemId] || null);

  let shopContent = '';
  if (isRoughSelling) {
    shopContent = roughSaleContentMarkup();
  } else if (!selectedGem) {
    const gems = Object.values(GEMS).filter((gem) => {
      if (isSelling) return !gem.noLooseShopTrade && looseTotalForGem(gem.id) > 0;
      return !gem.eventOnly;
    });
    const gemChoices = gems.map((gem) => {
      const owned = looseTotalForGem(gem.id);
      const available = looseAvailableTotalForGem(gem.id);
      const status = isSelling
        ? `<small>所持：${owned}個・売却可能：${available}個</small>`
        : '';
      return `<button type="button" class="loose-shop-gem-choice" data-action="select-loose-shop-gem" data-id="${esc(gem.id)}">
        ${looseVisual(gem.id, 'loose-shop-gem-image', '', defaultLooseShapeForGem(gem.id))}
        <span><strong>${esc(gem.name)}</strong>${status}</span>
        <i aria-hidden="true">›</i>
      </button>`;
    }).join('');
    shopContent = `<section class="loose-shop-gem-selection">
      <header class="loose-shop-step-heading"><h2>石種を選択</h2></header>
      <div class="loose-shop-gem-grid">
        ${gemChoices || '<div class="empty-state sell-empty-state"><strong>売却できるルースはありません。</strong><p>所持しているルースがある場合、石種がここに表示されます。</p></div>'}
      </div>
    </section>`;
  } else {
    const rows = looseVariantRows({ ownedOnly: isSelling }).filter((entry) => entry.gem.id === selectedGem.id);
    const productRows = rows.map(({ shapeId, shape, owned, reserved, available }) => {
      const purchasePrice = loosePurchasePrice(selectedGem.id, shapeId);
      const salePrice = looseSalePrice(selectedGem.id, shapeId);
      const detailButton = `<button class="secondary-button" data-action="open-loose-detail" data-id="${selectedGem.id}" data-shape="${shapeId}">詳細</button>`;
      const tradeLocked = Boolean(selectedGem.noLooseShopTrade);
      if (isSelling) {
        const disabled = tradeLocked || available < 1 || !canSpendHours(1);
        return `<article class="product-row loose-shop-product-row">
          <div class="product-main">
            ${looseVisual(selectedGem.id, 'loose-inline', '', shapeId)}
            <div><strong>${esc(selectedGem.id === 'pearl' ? selectedGem.name : shape.name)}</strong><small>所持：${owned}個</small><small>注文予定：${reserved}個・売却可能：${available}個</small></div>
          </div>
          <strong>${yen(salePrice)}／個</strong>
          <div class="loose-shop-actions">${detailButton}<button class="primary-button" data-action="sell-loose" data-id="${selectedGem.id}" data-shape="${shapeId}" ${disabled ? 'disabled' : ''}>1個売る</button><button class="secondary-button" data-action="sell-all-loose" data-id="${selectedGem.id}" data-shape="${shapeId}" ${disabled ? 'disabled' : ''}>全部売る</button></div>
        </article>`;
      }
      const maximum = loosePurchaseMaximum(selectedGem.id, shapeId);
      const quantity = loosePurchaseQuantity(selectedGem.id, shapeId);
      const disabled = quantity < 1 || !canSpendHours(1);
      return `<article class="product-row loose-shop-product-row">
        <div class="product-main">
          ${looseVisual(selectedGem.id, 'loose-inline', '', shapeId)}
          <div><strong>${esc(selectedGem.id === 'pearl' ? selectedGem.name : shape.name)}</strong><small>所持：${owned}個</small>${reserved > 0 ? `<small>注文予定：${reserved}個・使用可能：${available}個</small>` : ''}</div>
        </div>
        <strong>${yen(purchasePrice)}／個</strong>
        <div class="loose-shop-actions loose-shop-buy-actions" data-loose-purchase-card="${selectedGem.id}:${shapeId}">
          ${detailButton}
          <div class="loose-purchase-quantity">
            <span class="loose-quantity-label">数</span>
            <span class="metal-vertical-stepper loose-vertical-stepper" aria-label="購入数を増減">
              <button type="button" class="metal-stepper-button metal-stepper-up" data-action="loose-qty-step" data-id="${selectedGem.id}" data-shape="${shapeId}" data-delta="1" aria-label="${esc(shape.name)}を1個増やす。長押しで連続増加" ${quantity >= maximum ? 'disabled' : ''}>▲</button>
              <span class="metal-input-wrap loose-input-wrap"><output class="quantity-readout" data-loose-purchase-value aria-live="polite" aria-label="${esc(shape.name)}の購入数">${quantity}</output><b>個</b></span>
              <button type="button" class="metal-stepper-button metal-stepper-down" data-action="loose-qty-step" data-id="${selectedGem.id}" data-shape="${shapeId}" data-delta="-1" aria-label="${esc(shape.name)}を1個減らす。長押しで連続減少" ${quantity <= 0 ? 'disabled' : ''}>▼</button>
            </span>
            <strong class="loose-purchase-total" data-loose-purchase-total>${loosePurchaseTotalMarkup(selectedGem.id, shapeId, quantity)}</strong>
          </div>
          <button class="primary-button loose-inline-purchase" data-action="purchase" data-kind="loose" data-id="${selectedGem.id}" data-shape="${shapeId}" ${disabled ? 'disabled' : ''}>購入する</button>
        </div>
      </article>`;
    }).join('');
    shopContent = `<section class="loose-shop-cut-selection">
      <button type="button" class="secondary-button loose-shop-gem-back" data-action="loose-shop-gem-back">← 石種一覧へ戻る</button>
      <div class="product-list loose-shop-cut-list">
        ${productRows || '<div class="empty-state sell-empty-state"><strong>この石種で売却できるルースはありません。</strong><p>別の石種を選択してください。</p></div>'}
      </div>
      <button type="button" class="secondary-button loose-shop-gem-back loose-shop-gem-back-bottom" data-action="loose-shop-gem-back">← 石種一覧へ戻る</button>
    </section>`;
  }

  return shell('ルース屋', `
    <div class="split-layout">
      <section class="scene-space"></section>
      <section class="action-panel glass-panel">
        <div class="tab-row loose-shop-tabs">
          <button class="${tab === 'buy' ? 'active' : ''}" data-action="loose-shop-tab" data-tab="buy">ルースを買う</button>
          <button class="${tab === 'sell' ? 'active' : ''}" data-action="loose-shop-tab" data-tab="sell">ルースを売る</button>
          <button class="${tab === 'rough' ? 'active' : ''}" data-action="loose-shop-tab" data-tab="rough">原石を売る</button>
        </div>
        ${shopContent}
      </section>
    </div>`);
}

function jewelryShopRandomQuality() {
  const roll = Math.random();
  if (roll < 0.55) return 'standard';
  if (roll < 0.88) return 'good';
  return 'premium';
}

function jewelryShopPurchaseRecommendedPrice(purchasePrice) {
  const price = Math.max(1000, Math.round(Number(purchasePrice) || 0));
  return Math.max(price + 1000, roundThousand(price * 1.08));
}

function createJewelryShopStockItem() {
  const item = randomFrom(Object.keys(ITEMS), 'ring');
  const metal = randomFrom(Object.keys(METALS), 'silver');
  const gem = randomFrom(Object.values(GEMS).filter((entry) => !entry.eventOnly).map((entry) => entry.id), 'amethyst');
  const useLoose = Math.random() >= 0.12;
  const looseShape = randomFrom(looseShapeIdsForGem(gem), defaultLooseShapeForGem(gem));
  const design = randomFrom(Object.keys(DESIGNS), 'simple');
  const finish = randomFrom(Object.keys(FINISHES), 'mirror');
  const quality = jewelryShopRandomQuality();
  const draft = { item, metal, gem, useLoose, looseShape, design, finish, quality };
  const marketValue = recommendedPrice(draft);
  const purchasePrice = Math.max(1000, roundThousand(marketValue * (0.90 + Math.random() * 0.06)));
  return {
    id: `jewelry-shop-${uid()}`,
    ...draft,
    name: itemName(draft),
    marketValue,
    purchasePrice,
    recommendedPrice: jewelryShopPurchaseRecommendedPrice(purchasePrice),
  };
}

function createJewelryShopStock() {
  return Array.from({ length: JEWELRY_SHOP_STOCK_SIZE }, () => createJewelryShopStockItem());
}

function jewelryShopSellOffer(item) {
  const cost = Math.max(0, Math.round(Number(item?.cost) || 0));
  if (!cost) return 0;
  if (item?.acquisition === 'jewelryShop') return Math.max(1000, roundThousand(cost * 0.78));
  // 御徒町のジュエリーショップへの売却は卸販売。利益はごく小さくする。
  const multiplier = item?.quality === 'premium' ? 1.04 : item?.quality === 'good' ? 1.03 : 1.02;
  return Math.max(cost + 1000, roundThousand(cost * multiplier));
}

function jewelryShopProductVisual(item) {
  return `<div class="small-jewelry jewelry-shop-item-visual metal-${item.metal} item-${item.item}" style="--gem:${GEMS[item.gem]?.hue || '#ffffff'}">${jewelryItemVisual(item.item, 'jewelry-item-shape small', item.useLoose !== false)}${item.useLoose !== false ? `<i>${jewelryLooseSetVisual(item.item, item.gem, item.looseShape, 'small')}</i>` : ''}</div>`;
}

function jewelryShopHeroMarkup(mode) {
  const src = mode === 'buy'
    ? `./assets/images/jewelry-shop-buy-character.png?v=${VERSION}`
    : mode === 'sell'
      ? `./assets/images/jewelry-shop-sell-character.png?v=${VERSION}`
      : '';
  if (!src) return '';
  return `<div class="jewelry-shop-hero-layer jewelry-shop-hero-${mode}" aria-hidden="true"><img src="${src}" alt=""></div>`;
}

function renderJewelryShop() {
  const mode = screenData.mode || '';
  if (!mode) {
    return shell('ジュエリーショップ', `
      <div class="split-layout">
        <section class="scene-space"></section>
        <section class="action-panel glass-panel jewelry-shop-menu-panel">
          <div class="button-stack">
            <button type="button" class="primary-button full-button" data-action="jewelry-shop-open-sell">ジュエリーを売る</button>
            <button type="button" class="secondary-button full-button" data-action="jewelry-shop-open-buy">ジュエリーを買う</button>
          </div>
          <p class="small-note">売却時の利益と、購入品を再販売した時の利益はどちらも小さめです。売買手続きには1時間かかります。</p>
        </section>
      </div>`, { help: 'ジュエリーショップでは、保管中の完成品を売却したり、入店ごとに変わる商品を購入したりできます。' });
  }

  if (mode === 'buy') {
    if (!Array.isArray(screenData.stock)) screenData.stock = createJewelryShopStock();
    const usedCapacity = state.inventory.jewelry.filter((item) => item.status !== 'sold').length;
    const capacityFull = usedCapacity >= state.inventory.capacity;
    const rows = screenData.stock.map((item) => {
      const estimatedProfit = item.recommendedPrice - item.purchasePrice;
      const disabled = capacityFull || state.game.money < item.purchasePrice || !canSpendHours(JEWELRY_SHOP_TRANSACTION_HOURS);
      return `<article class="jewelry-shop-product-card">
        ${jewelryShopProductVisual(item)}
        <div class="jewelry-shop-product-copy">
          <h3>${esc(item.name)}</h3>
          <small>${esc(QUALITIES[item.quality]?.name || '')}・${esc(DESIGNS[item.design]?.name || '')}</small>
          <div class="jewelry-shop-price-row"><span>購入価格</span><strong>${yen(item.purchasePrice)}</strong></div>
          <div class="jewelry-shop-profit-row"><span>購入後のおすすめ価格</span><b>${yen(item.recommendedPrice)}</b><small>利益目安 ${yen(estimatedProfit)}</small></div>
        </div>
        <button type="button" class="primary-button jewelry-shop-trade-button" data-action="jewelry-shop-buy" data-id="${esc(item.id)}" ${disabled ? 'disabled' : ''}>この商品を買う</button>
      </article>`;
    }).join('');
    return shell('ジュエリーを買う', `
      <div class="split-layout jewelry-shop-layout-with-hero">
        ${jewelryShopHeroMarkup('buy')}
        <section class="scene-space"></section>
        <section class="action-panel glass-panel jewelry-shop-panel jewelry-shop-panel-with-hero">
          <div class="jewelry-shop-panel-content">
            <button type="button" class="secondary-button jewelry-shop-back" data-action="jewelry-shop-menu">← メニューへ戻る</button>
            <div class="jewelry-shop-status-row"><span>完成品保管</span><strong>${usedCapacity}／${state.inventory.capacity}</strong></div>
            ${capacityFull ? '<p class="error-text">完成品の保管場所に空きがありません。</p>' : ''}
            <p class="small-note jewelry-shop-trade-note jewelry-shop-random-note">商品は「ジュエリーを買う」を開くたびにランダムで入れ替わります。仕入れ価格が高いため、再販売しても大きな利益は出ません。</p>
            <div class="jewelry-shop-product-list">${rows || '<div class="empty-state"><strong>商品は売り切れました。</strong><p>メニューへ戻り、もう一度「ジュエリーを買う」を開くと商品が入れ替わります。</p></div>'}</div>
          </div>
        </section>
      </div>`, { help: '表示された商品から購入できます。購入品は工房の完成品へ追加され、店舗のショーケースへ陳列できます。' });
  }

  const items = state.inventory.jewelry.filter((item) => item.status === 'stored');
  const rows = items.map((item) => {
    const offer = jewelryShopSellOffer(item);
    const profit = offer - Math.max(0, Number(item.cost) || 0);
    const disabled = !canSpendHours(JEWELRY_SHOP_TRANSACTION_HOURS);
    return `<article class="jewelry-shop-product-card">
      ${jewelryShopProductVisual(item)}
      <div class="jewelry-shop-product-copy">
        <h3>${esc(item.name)}</h3>
        <small>${esc(QUALITIES[item.quality]?.name || '')}・原価 ${yen(item.cost)}</small>
        <div class="jewelry-shop-price-row"><span>卸買取価格</span><strong>${yen(offer)}</strong></div>
        <div class="jewelry-shop-profit-row ${profit < 0 ? 'loss' : ''}"><span>利益</span><b>${profit >= 0 ? '+' : '−'}${yen(Math.abs(profit))}</b></div>
      </div>
      <button type="button" class="primary-button jewelry-shop-trade-button" data-action="jewelry-shop-sell" data-id="${esc(item.id)}" ${disabled ? 'disabled' : ''}>この商品を売る</button>
    </article>`;
  }).join('');
  return shell('ジュエリーを売る', `
    <div class="split-layout jewelry-shop-layout-with-hero">
      ${jewelryShopHeroMarkup('sell')}
      <section class="scene-space"></section>
      <section class="action-panel glass-panel jewelry-shop-panel jewelry-shop-panel-with-hero">
        <div class="jewelry-shop-panel-content">
          <button type="button" class="secondary-button jewelry-shop-back" data-action="jewelry-shop-menu">← メニューへ戻る</button>
          <p class="small-note jewelry-shop-trade-note jewelry-shop-wholesale-note">工房で保管中の完成品だけを卸販売できます。ショーケースに陳列中の商品と注文品は表示されません。利益はごく少額です。</p>
          <div class="jewelry-shop-product-list">${rows || '<div class="empty-state"><strong>売却できる完成品はありません。</strong><p>工房で完成品を制作し、保管中にするとここへ表示されます。</p></div>'}</div>
        </div>
      </section>
    </div>`, { help: '保管中の完成品をジュエリーショップへ売却できます。店舗で販売するより利益は小さくなります。' });
}

function beginJewelryShopTrade(type, itemId) {
  if (type === 'buy') {
    const stockItem = Array.isArray(screenData.stock) ? screenData.stock.find((item) => item.id === itemId) : null;
    if (!stockItem) return showToast('この商品は現在購入できません。', 'error');
    jewelryShopPendingTrade = { type, itemId };
    showModal({
      title: 'ジュエリーを購入',
      body: `<p><strong>${esc(stockItem.name)}</strong>を${yen(stockItem.purchasePrice)}で購入します。</p><p class="small-note">手続きに1時間かかり、工房の完成品へ追加されます。</p>`,
      confirm: '購入する', cancel: 'やめる', action: 'jewelry-shop-confirm-trade', cancelAction: 'jewelry-shop-cancel-trade',
    });
    return;
  }
  const item = state.inventory.jewelry.find((entry) => entry.id === itemId && entry.status === 'stored');
  if (!item) return showToast('この商品は現在売却できません。', 'error');
  const offer = jewelryShopSellOffer(item);
  jewelryShopPendingTrade = { type: 'sell', itemId };
  showModal({
    title: 'ジュエリーを卸販売',
    body: `<p><strong>${esc(item.name)}</strong>を${yen(offer)}で売却します。</p><p class="small-note">自分の店舗で販売するより安い卸価格です。利益はごく少額で、手続きには1時間かかります。</p>`,
    confirm: '売却する', cancel: 'やめる', action: 'jewelry-shop-confirm-trade', cancelAction: 'jewelry-shop-cancel-trade',
  });
}

function confirmJewelryShopTrade() {
  const pending = jewelryShopPendingTrade;
  jewelryShopPendingTrade = null;
  closeModal();
  if (!pending) return;
  if (!canSpendHours(JEWELRY_SHOP_TRANSACTION_HOURS)) return showToast('今日は売買手続きをする時間がありません。', 'error');

  if (pending.type === 'buy') {
    const stockItem = Array.isArray(screenData.stock) ? screenData.stock.find((item) => item.id === pending.itemId) : null;
    if (!stockItem) return showToast('この商品は売り切れました。', 'error');
    const usedCapacity = state.inventory.jewelry.filter((item) => item.status !== 'sold').length;
    if (usedCapacity >= state.inventory.capacity) return showToast('完成品の保管場所に空きがありません。', 'error');
    if (state.game.money < stockItem.purchasePrice) return showToast('所持金が足りません。', 'error');
    const purchased = {
      id: uid(), item: stockItem.item, metal: stockItem.metal, gem: stockItem.gem, useLoose: stockItem.useLoose,
      looseShape: stockItem.looseShape, design: stockItem.design, finish: stockItem.finish, quality: stockItem.quality,
      name: stockItem.name, cost: stockItem.purchasePrice, recommendedPrice: stockItem.recommendedPrice, xp: 0,
      status: 'stored', createdDay: state.game.day, purchasedDay: state.game.day,
      acquisition: 'jewelryShop', shopPurchasePrice: stockItem.purchasePrice,
    };
    state.game.money -= stockItem.purchasePrice;
    state.inventory.jewelry.push(purchased);
    screenData.stock = screenData.stock.filter((item) => item.id !== pending.itemId);
    spendHours(JEWELRY_SHOP_TRANSACTION_HOURS);
    addFinance(`ジュエリーショップで${purchased.name}を購入`, 0, stockItem.purchasePrice);
    saveGame();
    startMoneyFeedback(-stockItem.purchasePrice);
    showToast(`${purchased.name}を購入しました。`, 'info', false);
    render();
    return;
  }

  const item = state.inventory.jewelry.find((entry) => entry.id === pending.itemId && entry.status === 'stored');
  if (!item) return showToast('この商品は現在売却できません。', 'error');
  const offer = jewelryShopSellOffer(item);
  const profit = offer - Math.max(0, Number(item.cost) || 0);
  removeJewelry(item.id);
  state.game.money += offer;
  spendHours(JEWELRY_SHOP_TRANSACTION_HOURS);
  state.daily.sold.push({ itemId: item.id, name: item.name, price: offer, profit, channel: 'jewelryShop' });
  addFinance(`${item.name}をジュエリーショップへ卸販売`, offer, 0);
  saveGame();
  startMoneyFeedback(offer);
  showToast(`${item.name}を${yen(offer)}で卸販売しました。`, 'info', false);
  render();
}

function renderDisplayProductVisual(product, extraClass = '') {
  const classes = ['display-product-visual'];
  if (product?.id) classes.push(`display-product-${product.id}`);
  if (extraClass) classes.push(extraClass);
  if (product?.image) {
    return `<span class="${classes.join(' ')}"><img src="${product.image}" alt="${esc(product.name)}" loading="lazy" decoding="async"></span>`;
  }
  return `<span class="material-chip" aria-hidden="true">${esc(product?.symbol || '')}</span>`;
}

function renderDisplayShop() {
  const inventory = state.store.displayInventory || {};
  const products = Object.values(DISPLAY_SHOP_PRODUCTS);
  const productRows = products.map((product) => {
    const owned = Math.max(0, Math.floor(Number(inventory[product.id]) || 0));
    const installed = product.id === 'showcase'
      ? installedShowcaseCount()
      : product.id === 'displaySupplies'
        ? storeDisplaySuppliesInstalled(currentStoreBranch())
        : storeCaseRemaining(currentStoreBranch());
    const totalOwned = owned + (product.id === 'case' ? installed : 0);
    const limitReached = Boolean(product.purchaseLimit) && totalOwned >= Number(product.purchaseLimit);
    const disabled = limitReached || state.game.money < product.price || !canSpendHours(1);
    const ownedText = product.id === 'case'
      ? `未設置 ${owned}個・店舗の残数 ${installed}個`
      : `未設置 ${owned}個・設置済み ${installed}${product.id === 'showcase' ? '台' : '個'}`;
    const limitText = product.purchaseLimit ? `<small>保有上限：未設置分と設置中を合わせて${product.purchaseLimit}個</small>` : '';
    if (product.id === 'case') {
      const quantity = displayCasePurchaseQuantity();
      const maximum = displayCasePurchaseMaximum();
      const caseDisabled = quantity < 1 || !canSpendHours(1);
      return `<article class="product-row display-shop-row display-case-purchase-row" data-display-case-purchase-card>
        <div class="product-main">
          ${renderDisplayProductVisual(product)}
          <div><strong>${esc(product.name)}</strong><small>${esc(product.description)}</small><small>${ownedText}</small>${limitText}</div>
        </div>
        <strong>${yen(product.price)}／個</strong>
        <div class="display-case-quantity-area">
          <span class="metal-vertical-stepper" aria-label="ケース購入数を増減">
            <button type="button" class="metal-stepper-button metal-stepper-up" data-action="display-case-qty-step" data-delta="1" aria-label="ケースを1個増やす。長押しで連続増加" ${quantity >= maximum ? 'disabled' : ''}>▲</button>
            <span class="metal-input-wrap"><output class="quantity-readout" data-display-case-quantity-value aria-live="polite" aria-label="ケースの購入数">${quantity}</output><b>個</b></span>
            <button type="button" class="metal-stepper-button metal-stepper-down" data-action="display-case-qty-step" data-delta="-1" aria-label="ケースを1個減らす。長押しで連続減少" ${quantity <= 0 ? 'disabled' : ''}>▼</button>
          </span>
          <strong class="display-case-total" data-display-case-total>合計：${yen(quantity * product.price)}</strong>
          <button class="primary-button full-button" data-action="buy-display-product" data-id="case" ${caseDisabled ? 'disabled' : ''}>購入する</button>
        </div>
      </article>`;
    }
    return `<article class="product-row display-shop-row">
      <div class="product-main">
        ${renderDisplayProductVisual(product)}
        <div><strong>${esc(product.name)}</strong><small>${esc(product.description)}</small><small>${ownedText}</small>${limitText}</div>
      </div>
      <strong>${yen(product.price)}</strong>
      <button class="primary-button" data-action="buy-display-product" data-id="${esc(product.id)}" ${disabled ? 'disabled' : ''}>購入する</button>
    </article>`;
  }).join('');

  return shell('ディスプレイ屋', `
    <div class="split-layout">
      <section class="scene-space"></section>
      <section class="action-panel glass-panel display-shop-panel">
        <div class="product-list">${productRows}</div>
        <p class="small-note">ショーケースとディスプレイ用品は1回につき1個、ケースは購入数を選択できます。手続きに1時間かかります。購入後は店舗画面の「店頭設備」から設置できます。</p>
      </section>
    </div>`, { help: 'ショーケース、ディスプレイ用品、ケースを購入できます。ケースは▲▼のタップまたは長押しで購入数を調整できます。購入した商品は店舗へ設置して使用します。' });
}

function renderRealEstate() {
  const nextBranchNumber = nextStoreBranchNumber();
  const contractAvailable = nextBranchNumber <= MAX_STORE_BRANCHES;

  if (screenData.view !== 'contract') {
    return shell('不動産屋', `
      <section class="center-card glass-panel expansion-card">
        <button class="primary-button full-button" data-action="open-store-contract" ${contractAvailable ? '' : 'disabled'}>店舗契約</button>
      </section>`, { help: contractAvailable ? '店舗契約を押すと、次に契約できる店舗の条件を確認できます。' : '現在契約できる店舗はありません。' });
  }

  if (!contractAvailable) {
    return shell('店舗契約', `
      <section class="center-card glass-panel expansion-card">
        <button class="secondary-button full-button" data-action="real-estate-menu">戻る</button>
      </section>`);
  }

  const leaseCost = storeLeaseCost(nextBranchNumber);
  const monthlyRent = storeMonthlyRent(nextBranchNumber);
  const affordable = state.game.money >= leaseCost;
  const needsStoreName = !String(state.store.name || '').trim();
  const contractTitle = `${nextBranchNumber}店舗目の契約`;

  return shell('店舗契約', `
    <section class="center-card glass-panel expansion-card">
      <h1>${contractTitle}</h1>
      <article class="summary-card">
        <div class="result-stats">
          <span>契約費：${yen(leaseCost)}</span>
          <span>月額家賃：${yen(monthlyRent)}</span>
          <span>契約月の家賃：無料</span>
          <span>ショーケース：なし</span>
          <span>設置上限：5台（1台につき完成品5個）</span>
        </div>
      </article>
      ${needsStoreName ? `<label class="name-entry-field">
        <span>店舗名</span>
        <input id="store-name-input" type="text" maxlength="30" autocomplete="organization" enterkeyhint="done" placeholder="店舗名を入力">
      </label>` : ''}
      <button class="primary-button full-button" data-action="rent-next-store" ${affordable ? '' : 'disabled'}>契約</button>
      ${affordable ? '' : `<p class="error-text store-contract-shortage">契約費が${yen(leaseCost - state.game.money)}足りません。</p>`}
      <button class="secondary-button full-button" data-action="real-estate-menu">戻る</button>
    </section>`, { help: '表示中の条件で次の店舗を契約します。契約した店舗は店舗画面の一覧から選択できます。' });
}

function ownedEquipmentCount() {
  return Object.values(state?.tools?.items || {}).filter(Boolean).length;
}

function processingKnowledgeEntries() {
  const records = Array.isArray(state?.workshop?.processingKnowledge) ? state.workshop.processingKnowledge : [];
  return records.map((record) => ({ record, document: PROCESSING_KNOWLEDGE[String(record?.id || '')] }))
    .filter((entry) => entry.document)
    .sort((a, b) => (Number(b.record?.acquiredDay) || 0) - (Number(a.record?.acquiredDay) || 0));
}

function processingKnowledgeCount() {
  return processingKnowledgeEntries().length;
}

// 今後のイベント実装では「加工知識へ追加」の共通入口としてこの関数を使う。
// 文書本体は PROCESSING_KNOWLEDGE に置き、セーブにはID・入手日・入手元だけを記録する。
function grantProcessingKnowledge(knowledgeId, source = 'イベント') {
  const id = String(knowledgeId || '').trim();
  const document = PROCESSING_KNOWLEDGE[id];
  if (!id || !document) {
    console.warn('加工知識の文書定義が見つかりません。', knowledgeId);
    return false;
  }
  state.workshop = state.workshop && typeof state.workshop === 'object' ? state.workshop : {};
  state.workshop.processingKnowledge = Array.isArray(state.workshop.processingKnowledge) ? state.workshop.processingKnowledge : [];
  if (state.workshop.processingKnowledge.some((entry) => String(entry?.id || entry) === id)) return false;
  state.workshop.processingKnowledge.push({ id, acquiredDay: Math.max(1, Number(state.game?.day) || 1), source: String(source || 'イベント').slice(0, 120) });
  addNotification('加工知識へ追加', `「${document.title || id}」が工房の加工知識へ追加されました。`, 'special');
  return true;
}

function renderWorkshop() {
  const workshopStatus = workshopUpgradeStatus();
  const roughTotal = Object.values(state.inventory.rough).reduce((a, b) => a + b, 0);
  const looseTotal = looseInventoryTotal();
  const metalTotal = roundedMetalWeight(Object.values(state.inventory.metals).reduce((a, b) => a + Number(b || 0), 0));
  const stored = state.inventory.jewelry.filter((item) => item.status !== 'sold').length;
  const equipmentTotal = ownedEquipmentCount();
  const knowledgeTotal = processingKnowledgeCount();
  const activeOrders = activeOrderCount();
  return shell('工房', `
    <div class="split-layout">
      <section class="scene-space"></section>
      <section class="action-panel glass-panel">
        <div class="stat-grid workshop-inventory-grid">
          <button type="button" class="workshop-inventory-button" data-action="open-workshop-inventory" data-tab="rough"><small>原石</small><strong>${roughTotal}個</strong></button>
          <button type="button" class="workshop-inventory-button" data-action="open-workshop-inventory" data-tab="loose"><small>ルース</small><strong>${looseTotal}個</strong></button>
          <button type="button" class="workshop-inventory-button" data-action="open-workshop-inventory" data-tab="metals"><small>地金</small><strong>${metalWeightLabel(metalTotal)}g</strong></button>
          <button type="button" class="workshop-inventory-button" data-action="open-workshop-inventory" data-tab="finished"><small>完成品</small><strong>${stored}/${state.inventory.capacity}</strong></button>
          <button type="button" class="workshop-inventory-button" data-action="open-workshop-inventory" data-tab="equipment"><small>工具・設備</small><strong>${equipmentTotal}点</strong></button>
          <button type="button" class="workshop-inventory-button" data-action="open-workshop-inventory" data-tab="knowledge"><small>加工知識</small><strong>${knowledgeTotal}件</strong></button>
        </div>
        ${workshopOperating() ? '' : `<section class="tool-break-alert"><strong>工房は作業停止中です</strong><span>未払いの工房維持費 ${yen(state.business.workshopUnpaid)}を収支画面から支払ってください。</span></section>`}
        <div class="button-stack workshop-menu">
          <div class="workshop-menu-item">
            <button class="primary-button large-button" data-action="open-craft" ${workshopOperating() && toolUsable('jewelryBench') ? '' : 'disabled'}>ジュエリー作成</button>
            ${toolUsable('jewelryBench') ? '' : '<p class="small-note workshop-requirement-note">ジュエリー作成には、御徒町のg-Lab.で購入できる彫金机が必要です。</p>'}
          </div>
          <div class="workshop-menu-item">
            <button class="primary-button large-button order-sheet-menu-button" data-action="nav" data-screen="orders" ${activeOrders > 0 ? '' : 'disabled'}>注文書${activeOrders > 0 ? `（${activeOrders}件）` : ''}</button>
            ${activeOrders > 0 ? '' : '<p class="small-note workshop-requirement-note">現在の注文がないため、注文書は選択できません。</p>'}
          </div>
          <div class="workshop-menu-item">
            <button class="primary-button large-button" data-action="nav" data-screen="polishing" ${workshopOperating() && toolUsable('polishingMachine') ? '' : 'disabled'}>原石研磨</button>
            ${toolUsable('polishingMachine') ? '' : `<p class="small-note workshop-requirement-note">${toolOwned('polishingMachine') ? `宝石研磨用平面研磨機は${workshopToolStatusText('polishingMachine')}です。修理完了まで原石研磨はできません。` : '原石研磨には、御徒町のg-Lab.で購入できる宝石研磨用平面研磨機が必要です。'}</p>`}
          </div>
          <div class="workshop-menu-item">
            <button class="primary-button large-button" data-action="nav" data-screen="workshopStaff" ${workshopStaffHoliday(gameDate()) ? 'disabled' : ''}>職人スタッフ${workshopStaffHoliday(gameDate()) ? '（おやすみ）' : ''}</button>
            ${workshopStaffHoliday(gameDate()) ? `<p class="small-note workshop-requirement-note">本日は${esc(workshopStaffHolidayReason(gameDate()))}のため、職人スタッフはお休みです。</p>` : ''}
          </div>
        </div>
        <article class="summary-card workshop-level-card workshop-level-bottom-card">
          <h2>工房レベル ${workshopLevel()} <small>（過去最高Lv.${Math.max(workshopLevel(), Number(state.workshop.peakLevel) || 1)}）</small></h2>
          <p>累計稼働 ${Math.max(0, Number(state.workshop.activeHours) || 0).toLocaleString('ja-JP')}時間・工房評価 ${workshopQualityPoints()}</p>
          ${workshopStatus.requirement ? `<ul class="condition-list compact-condition-list">${workshopStatus.conditions.map((condition) => `<li class="${condition.met ? 'condition-met' : 'condition-unmet'}"><strong>${condition.met ? '達成' : '未達成'}</strong><span>${esc(condition.label)}</span><em>${typeof condition.current === 'number' ? condition.current.toLocaleString('ja-JP') : esc(condition.current)}${condition.suffix || ''}／${typeof condition.target === 'number' ? condition.target.toLocaleString('ja-JP') : esc(condition.target)}${condition.suffix || ''}</em></li>`).join('')}</ul><p>次の拡張費：${yen(workshopStatus.cost)}</p>` : '<p>工房は最大レベルです。</p>'}
        </article>
        ${workshopLevel() >= 20 ? '' : `<button class="secondary-button full-button workshop-expansion-bottom-button" data-action="confirm-workshop-expansion" ${workshopStatus.complete ? '' : 'disabled'}>工房拡張</button>`}
      </section>
    </div>`, { help: '工房ではジュエリー作成、受注中の商品を確認する注文書、原石研磨、職人スタッフを利用できます。原石・ルース・地金・完成品・工具・設備に加え、イベントで得た加工知識の文書も確認できます。工房レベルと工房拡張は画面の一番下に表示します。注文書は現在の注文がある場合だけ開けます。' });
}

const WORKSHOP_STAFF_REQUIRED_TOOLS = Object.freeze(['jewelryBench', 'polishingMachine', 'rotaryTool', 'rollingMill', 'buffer', 'ultrasonicCleaner', 'electronicScale', 'magnifier', 'engravingBlock']);

function workshopStaffUnlockStatus() {
  const branches = contractedStoreBranches();
  const branch1 = branches.find((branch) => Number(branch.number) === 1);
  const branch2 = branches.find((branch) => Number(branch.number) === 2);
  const totalStoreSales = branches.reduce((total, branch) => total + Math.max(0, Number(branch.salesCount) || 0), 0);
  const unpaid = totalOutstandingBusinessCost();
  const missingTools = WORKSHOP_STAFF_REQUIRED_TOOLS.filter((id) => !toolUsable(id));
  const conditions = [
    { label: '職人レベル10以上', current: Math.max(1, Number(state.artisan.level) || 1), target: 10 },
    { label: 'プレイヤー自身の累計制作', current: Math.max(0, Number(state.store.playerCraftedCount) || 0), target: 100 },
    { label: '工房レベル15以上', current: workshopLevel(), target: 15 },
    { label: '主要工具・設備', current: missingTools.length ? `不足${missingTools.length}点` : '使用可能', target: 'すべて', met: missingTools.length === 0 },
    { label: '店舗1を拡大済み', current: state.store.expanded ? '完了' : '未完了', target: '完了', met: Boolean(state.store.expanded) },
    { label: '店舗2を契約済み', current: branch2 ? '完了' : '未完了', target: '完了', met: Boolean(branch2) },
    { label: '店舗1・2がともにLv.5以上', current: `${branch1 ? storeLevel(branch1) : 0}・${branch2 ? storeLevel(branch2) : 0}`, target: '5・5', met: Boolean(branch1 && branch2 && storeLevel(branch1) >= 5 && storeLevel(branch2) >= 5) },
    { label: '店舗での累計販売', current: totalStoreSales, target: 300 },
    { label: 'オーダー納品', current: Math.max(0, Number(state.store.deliveredOrderCount) || 0), target: 50 },
    { label: '家賃・工房費・給与の未払い', current: unpaid === 0 ? 'なし' : yen(unpaid), target: 'なし', met: unpaid === 0 },
  ].map((condition) => ({ ...condition, met: typeof condition.met === 'boolean' ? condition.met : Number(condition.current) >= Number(condition.target) }));
  return { conditions, missingTools, unlocked: conditions.every((condition) => condition.met) };
}

function renderWorkshopStaff() {
  const staff = workshopStaffState();
  const unlock = workshopStaffUnlockStatus();
  const holiday = workshopStaffHoliday(gameDate());
  const reason = workshopStaffHolidayReason(gameDate());
  const definition = workshopStaffDefinition(staff);
  const nextDefinition = workshopStaffNextDefinition(staff);
  const workDays = Math.max(0, Math.floor(Number(staff.workDays) || 0));
  const wageUnpaid = Math.max(0, Number(staff.wageUnpaid) || 0);
  const todayRows = Array.isArray(staff.craftedToday) ? staff.craftedToday : [];
  const growthText = nextDefinition
    ? `次の成長まであと${Math.max(0, Number(nextDefinition.minWorkDays) - workDays)}実働制作日`
    : '最高レベルまで成長しています';
  const shiftHours = `${clock(WORKSHOP_STAFF_SHIFT_START_MINUTES)}～${clock(WORKSHOP_STAFF_SHIFT_END_MINUTES)}`;
  if (!staff.hired && !unlock.unlocked) {
    return shell('職人スタッフ', `<section class="wide-panel glass-panel workshop-staff-panel"><h1>職人スタッフ（未解放）</h1><p>次の条件をすべて達成すると雇用できます。契約金・紹介料はありません。</p><ul class="condition-list">${unlock.conditions.map((condition) => `<li class="${condition.met ? 'condition-met' : 'condition-unmet'}"><strong>${condition.met ? '達成' : '未達成'}</strong><span>${esc(condition.label)}</span><em>${typeof condition.current === 'number' ? condition.current.toLocaleString('ja-JP') : esc(condition.current)}／${typeof condition.target === 'number' ? condition.target.toLocaleString('ja-JP') : esc(condition.target)}</em></li>`).join('')}</ul>${unlock.missingTools.length ? `<p class="small-note">不足設備：${unlock.missingTools.map((id) => esc(WORKSHOP_TOOLS[id]?.name || id)).join('、')}</p>` : ''}<button class="secondary-button full-button" data-action="back">戻る</button></section>`, { help: '職人スタッフは厳しい制作・工房・店舗実績を満たした後に、契約金なしで雇用できます。' });
  }
  if (holiday) {
    return shell('職人スタッフ（おやすみ）', `
      <section class="center-card glass-panel employee-card workshop-staff-card">
        <h1>本日はお休みです。</h1>
        <p>${esc(reason)}のため、職人スタッフの雇用・出勤設定は変更できません。</p>
        ${staff.hired ? `<article class="candidate-card"><strong>現在 Lv.${definition.level}（${esc(definition.label)}）</strong><p>実働制作日数 ${workDays}日</p><p>次回の日当 ${yen(definition.dailyWage)}</p></article>` : '<p>平日に工房から雇用できます。</p>'}
      </section>`, { help: '職人スタッフは土日祝日がお休みです。休日は出勤せず、日当も発生しません。' });
  }
  return shell('職人スタッフ', `
    <section class="center-card glass-panel employee-card workshop-staff-card">
      ${staff.hired ? `
        <h1>職人スタッフ</h1>
        <p class="success-text">制作力 Lv.${definition.level}（${esc(definition.label)}）</p>
        <article class="candidate-card workshop-staff-status">
          <div><strong>実働制作日数</strong><span>${workDays}日</span></div>
          <div><strong>現在の日当</strong><span>${yen(definition.dailyWage)}</span></div>
          <div><strong>制作速度</strong><span>${Math.round(definition.speedMultiplier * 100)}%</span></div>
          <div><strong>品質</strong><span>${esc(workshopStaffQualityDescription(definition).replace('品質：', ''))}</span></div>
        </article>
        <p>${esc(growthText)}</p>
        <p>出勤中は${shiftHours}の経過時間に合わせ、工房にある地金とルースだけを使ってランダムにジュエリーを制作します。注文用に確保した材料は使用しません。</p>
        <p>本日の自動制作：${todayRows.length ? `${todayRows.length}点（${todayRows.slice(0, 3).map((entry) => esc(entry.name)).join('、')}${todayRows.length > 3 ? 'ほか' : ''}）` : 'まだありません'}</p>
        <p>日当は完成品を1点以上制作した日だけ発生します。</p>
        ${wageUnpaid ? `<section class="tool-break-alert"><strong>給与未払いのため出勤停止中です</strong><span>未払い ${yen(wageUnpaid)}をスマートフォンの収支画面から支払ってください。</span></section>` : ''}
        <label class="toggle-row"><span>出勤させる</span><input type="checkbox" data-action="workshop-staff-working" ${staff.working ? 'checked' : ''} ${wageUnpaid ? 'disabled' : ''}></label>` : `
        <h1>職人スタッフを1人雇えます。</h1>
        <article class="candidate-card">
          <h2>見習い職人</h2>
          <p>はじめは制作速度が低く、完成品は標準品質だけです。実際に1点以上制作した勤務日を重ねると制作速度と品質が上がり、その分日当も上がります。</p>
          <p class="success-text">制作力 Lv.1（見習い職人）</p>
          <small>初日当 ${yen(WORKSHOP_STAFF_GROWTH_LEVELS[0].dailyWage)}・勤務時間 ${shiftHours}</small>
        </article>
        <button class="primary-button full-button" data-action="hire-workshop-staff">雇う</button>`}
      <details class="completed-order-history workshop-staff-growth-table">
        <summary>成長と日当を見る</summary>
        <div class="history-list">${WORKSHOP_STAFF_GROWTH_LEVELS.map((level) => `<p><strong>Lv.${level.level} ${esc(level.label)}</strong>　実働制作${level.minWorkDays}日～／日当${yen(level.dailyWage)}／速度${Math.round(level.speedMultiplier * 100)}%</p>`).join('')}</div>
      </details>
    </section>`, { help: '職人スタッフは平日の9:00～19:00に働き、工房の材料と完成品保管枠の範囲内でジュエリーを自動制作します。実際に1点以上制作した実働制作日数が増えると制作速度と品質が上がり、日当も段階的に上がります。土日祝日はお休みです。' });
}

function rerenderPolishingPreservingPosition() {
  const content = root.querySelector('.screen-content');
  const contentScrollTop = content?.scrollTop || 0;
  render();
  requestAnimationFrame(() => {
    const nextContent = root.querySelector('.screen-content');
    if (nextContent) nextContent.scrollTop = contentScrollTop;
  });
}

function renderPolishing() {
  if (!workshopOperating()) return shell('原石研磨', '<div class="empty-state"><strong>工房は作業停止中です。</strong><p>未払いの工房維持費を支払うと再開できます。</p></div>');
  if (!toolUsable('polishingMachine')) {
    return shell('原石研磨', `
      <section class="center-card glass-panel">
        <h1>${toolOwned('polishingMachine') ? workshopToolStatusText('polishingMachine') : '宝石研磨用平面研磨機がありません。'}</h1>
        <p>${toolOwned('polishingMachine') ? '宝石研磨用平面研磨機が使用できる状態へ戻るまで、原石研磨はできません。' : '原石をルースへ加工するには、g-Lab.で宝石研磨用平面研磨機を購入してください。'}</p>
        <button class="primary-button full-button" data-action="nav" data-screen="okachimachi">御徒町へ</button>
      </section>`, { help: '宝石研磨用平面研磨機は御徒町のg-Lab.で購入できます。' });
  }
  const ownedRoughGems = Object.values(GEMS).filter((gem) => Number(state.inventory.rough?.[gem.id] || 0) > 0 && (gem.id !== 'diamond' || toolUsable('diamondPolishingLap')));
  if (!ownedRoughGems.length) {
    return shell('原石研磨', `
      <section class="center-card glass-panel">
        <h1>研磨できる原石がありません。</h1>
        <p>石種の一覧には、現在持っている原石だけが表示されます。</p>
        <button class="primary-button full-button" data-action="nav" data-screen="mining">採掘へ行く</button>
        <button class="secondary-button full-button" data-action="nav" data-screen="okachimachi">御徒町へ</button>
      </section>`, { help: '原石を入手すると、その石種だけが研磨画面に表示されます。' });
  }
  if (!ownedRoughGems.some((gem) => gem.id === selectedPolishing)) selectedPolishing = ownedRoughGems[0].id;
  selectedPolishingShape = normalizeLooseShape(selectedPolishing, selectedPolishingShape);
  const shapeIds = looseShapeIdsForGem(selectedPolishing);
  const roughOwned = Number(state.inventory.rough[selectedPolishing] || 0);
  const shapedLooseOwned = looseOwned(selectedPolishing, selectedPolishingShape);
  const canPolish = canSpendHours(POLISHING_HOURS);
  return shell('原石研磨', `
    <section class="wide-panel glass-panel">
      <h2 class="polishing-first-heading">石種を選ぶ</h2>
      <div class="choice-grid many polishing-grid">
        ${ownedRoughGems.map((gem) => `<button class="choice-card ${selectedPolishing === gem.id ? 'selected' : ''}" data-action="select-polishing" data-id="${gem.id}">
          <span class="choice-visual">${roughVisual(gem.id, 'choice-gem')}</span>
          <strong>${esc(roughDisplayName(gem.id))}</strong><small>所持 ${state.inventory.rough[gem.id]}個</small>
        </button>`).join('')}
      </div>
      <h2>カットを選ぶ</h2>
      <div class="choice-grid many polishing-shape-grid">
        ${shapeIds.map((shapeId) => `<button class="choice-card ${selectedPolishingShape === shapeId ? 'selected' : ''}" data-action="select-polishing-shape" data-shape="${shapeId}">
          <span class="choice-visual">${looseVisual(selectedPolishing, 'choice-loose', '', shapeId)}</span>
          <strong>${esc(looseShapeLabel(shapeId))}</strong><small>所持 ${looseOwned(selectedPolishing, shapeId)}個</small>
        </button>`).join('')}
      </div>
      <article class="summary-card polishing-summary">
        <div>${roughVisual(selectedPolishing, 'polishing-rough')}</div>
        <div class="polishing-arrow">→</div>
        <div>${looseVisual(selectedPolishing, 'polishing-loose', '', selectedPolishingShape)}</div>
        <div class="polishing-copy">
          <h2>${esc(roughDisplayName(selectedPolishing))}を${esc(looseShapeLabel(selectedPolishingShape))}へ研磨</h2>
          <p>原石1個から、選択したカットのルース1個を作ります。</p>
          <div class="result-stats"><span>加工時間：${POLISHING_HOURS}時間</span><span>このルースの所持：${shapedLooseOwned}個</span></div>
        </div>
      </article>
      <button class="primary-button full-button" data-action="polish-rough" ${canPolish ? '' : 'disabled'}>このカットで原石を1個研磨する</button>
      ${canSpendHours(POLISHING_HOURS) ? '' : '<p class="error-text">今日は研磨する時間がありません。</p>'}
    </section>`, { help: '石種とカットを選び、原石1個を対応するルース1個へ研磨します。' });
}

function defaultDraft(orderId = null) {
  const order = orderId ? state.orders.find((entry) => entry.id === orderId) : null;
  const ownedSelection = firstOwnedLooseSelection('amethyst');
  const gem = order?.gem || ownedSelection.gem;
  const looseShape = order?.looseShape || (order ? defaultLooseShapeForGem(gem) : firstOwnedLooseShapeForGem(gem));
  return {
    orderId,
    item: order?.item || 'ring',
    useLoose: order ? true : null,
    gem,
    looseShape: normalizeLooseShape(gem, looseShape),
    metal: order?.metal || firstOwned(state.inventory.metals, 'silver'),
    design: order?.design || 'simple',
    finish: 'mirror',
  };
}

function firstOwned(collection, fallback) {
  return Object.keys(collection).find((key) => Number(collection[key]) > 0) || fallback;
}

function craftChoice(label, group, entries, current, locked = false) {
  return `<fieldset class="craft-field"><legend>${esc(label)}</legend><div class="choice-grid ${Object.keys(entries).length > 3 ? 'many' : 'three'}">
    ${Object.values(entries).map((entry) => `<button type="button" class="choice-card ${current === entry.id ? 'selected' : ''}" data-action="craft-choice" data-group="${group}" data-id="${entry.id}" ${locked && current !== entry.id ? 'disabled' : ''}>
      <strong>${esc(entry.name)}</strong>
      ${group === 'design' ? `<small>${entry.hours > 0 ? `制作時間 ＋${entry.hours}時間` : '追加時間なし'}</small>` : ''}
    </button>`).join('')}
  </div></fieldset>`;
}

function craftLooseModeChoice(locked = false) {
  const useLoose = craftDraft?.useLoose;
  return `<fieldset class="craft-field craft-loose-mode-field"><legend>ルース</legend><div class="choice-grid two craft-loose-mode-grid">
    <button type="button" class="choice-card ${useLoose === true ? 'selected' : ''}" data-action="craft-loose-mode" data-mode="use">
      <strong>使用する</strong>
    </button>
    <button type="button" class="choice-card ${useLoose === false ? 'selected' : ''}" data-action="craft-loose-mode" data-mode="none" ${locked ? 'disabled' : ''}>
      <strong>使用しない</strong>
    </button>
  </div></fieldset>`;
}


function craftSurfaceParts(finishId = 'mirror') {
  switch (finishId) {
    case 'matte': return { base: 'matte', decorated: false };
    case 'decorated': return { base: null, decorated: true };
    case 'mirrorDecorated': return { base: 'mirror', decorated: true };
    case 'matteDecorated': return { base: 'matte', decorated: true };
    case 'mirror':
    default: return { base: 'mirror', decorated: false };
  }
}

function craftSurfaceFinishId(base, decorated) {
  if (decorated && base === 'mirror') return 'mirrorDecorated';
  if (decorated && base === 'matte') return 'matteDecorated';
  if (decorated) return 'decorated';
  if (base === 'matte') return 'matte';
  return 'mirror';
}

function craftSurfaceChoice(current = 'mirror') {
  const surface = craftSurfaceParts(current);
  return `<fieldset class="craft-field craft-surface-field"><legend>表面</legend>
    <div class="choice-grid three craft-surface-grid">
      <button type="button" class="choice-card ${surface.base === 'mirror' ? 'selected' : ''}" data-action="craft-surface-choice" data-id="mirror" aria-pressed="${surface.base === 'mirror'}"><strong>鏡面</strong></button>
      <button type="button" class="choice-card ${surface.base === 'matte' ? 'selected' : ''}" data-action="craft-surface-choice" data-id="matte" aria-pressed="${surface.base === 'matte'}"><strong>つや消し</strong></button>
      <button type="button" class="choice-card ${surface.decorated ? 'selected' : ''}" data-action="craft-surface-choice" data-id="decorated" aria-pressed="${surface.decorated}"><strong>装飾あり</strong></button>
    </div>
  </fieldset>`;
}

function craftAvailableLooseGems(orderId = null) {
  const order = orderId ? state.orders.find((entry) => entry.id === orderId) : null;
  return Object.values(GEMS).filter((gem) => {
    if (order) {
      if (gem.id !== order.gem) return false;
      const shapeId = normalizeLooseShape(order.gem, order.looseShape);
      return looseAvailableQuantity(gem.id, shapeId, orderId) > 0;
    }
    return looseAvailableTotalForGem(gem.id) > 0;
  });
}

function craftLooseGemChoice(orderId = null) {
  const order = orderId ? state.orders.find((entry) => entry.id === orderId) : null;
  const gems = craftAvailableLooseGems(orderId);
  if (!gems.length) {
    return `<fieldset class="craft-field craft-loose-field"><legend>ルースの選択</legend><div class="empty-state craft-loose-empty"><strong>使用できるルースを持っていません。</strong><p>原石を研磨するか、ルース屋で購入してください。</p></div></fieldset>`;
  }
  return `<fieldset class="craft-field craft-loose-field"><legend>ルースの選択</legend><div class="choice-grid many craft-loose-gem-grid">
    ${gems.map((gem) => {
      const selected = craftDraft?.gem === gem.id;
      const selectedShape = selected
        ? normalizeLooseShape(gem.id, craftDraft.looseShape)
        : order
          ? normalizeLooseShape(order.gem, order.looseShape)
          : firstOwnedLooseShapeForGem(gem.id);
      const available = order
        ? looseAvailableQuantity(gem.id, selectedShape, orderId)
        : looseAvailableTotalForGem(gem.id);
      return `<button type="button" class="choice-card craft-loose-gem-card ${selected ? 'selected' : ''}" data-action="craft-loose-gem" data-id="${esc(gem.id)}">
        <span class="choice-visual">${looseVisual(gem.id, 'choice-loose', '', selectedShape)}</span>
        <strong>${esc(gem.name)}</strong>
        <small>${order ? 'この注文に使用可能' : '使用可能'} ${available}個</small>
        ${selected && gem.id !== 'pearl' ? `<small class="craft-current-loose">選択中：${esc(looseShapeLabel(selectedShape))}</small>` : ''}
      </button>`;
    }).join('')}
  </div></fieldset>`;
}

function craftMetalChoice(current, locked = false) {
  const metals = METAL_WORKSHOP_ORDER.map((metalId) => METALS[metalId]).filter(Boolean);
  return `<fieldset class="craft-field"><legend>地金</legend><div class="choice-grid three craft-metal-grid">
    ${metals.map((metal) => {
      const available = metalAvailableWeight(metal.id, craftDraft?.orderId || '');
      return `<button type="button" class="choice-card ${current === metal.id ? 'selected' : ''}" data-action="craft-choice" data-group="metal" data-id="${esc(metal.id)}" ${locked && current !== metal.id ? 'disabled' : ''}>
        <strong>${esc(metal.shortName || metal.alloy || metal.name)}</strong>
        <small>${craftDraft?.orderId ? 'この注文に使用可能' : '使用可能'} ${metalWeightLabel(available)}g</small>
      </button>`;
    }).join('')}
  </div></fieldset>`;
}

function renderCraftLooseSelection() {
  if (!craftDraft) craftDraft = defaultDraft(screenData.orderId || null);
  const orderId = craftDraft.orderId || screenData.orderId || null;
  const order = orderId ? state.orders.find((entry) => entry.id === orderId) : null;
  const gemId = GEMS[screenData.gemId] ? screenData.gemId : craftDraft.gem;
  const gem = GEMS[gemId];
  if (gemId === 'pearl') {
    craftDraft.useLoose = true;
    craftDraft.gem = 'pearl';
    craftDraft.looseShape = 'pearl';
    return shell('パールを使う', `<section class="wide-panel glass-panel craft-loose-selection-page"><header class="craft-loose-selection-heading"><small>ルースの選択</small><h1>パール</h1><p>制作に使用する一粒を確認してください。</p></header><article class="craft-loose-cut-card selected"><div class="craft-loose-cut-image">${looseVisual('pearl', 'choice-loose', '', 'pearl')}</div><div class="craft-loose-cut-copy"><strong>パール</strong><small>使用可能 ${looseAvailableQuantity('pearl', 'pearl', orderId || '')}個</small></div><button type="button" class="primary-button craft-use-loose-button" data-action="craft-use-loose" data-id="pearl" data-shape="pearl">これを使う</button></article><button type="button" class="secondary-button full-button craft-loose-bottom-back" data-action="back">戻る</button></section>`, { back: false, help: 'パールをそのままジュエリー制作へ使用します。' });
  }
  const shapeIds = (order
    ? [normalizeLooseShape(order.gem, order.looseShape)]
    : looseShapeIdsForGem(gemId)
  ).filter((shapeId) => looseAvailableQuantity(gemId, shapeId, orderId || '') > 0);

  return shell(`${gem.name}のカットを選ぶ`, `
    <section class="wide-panel glass-panel craft-loose-selection-page">
      <header class="craft-loose-selection-heading">
        <small>ルースの選択</small>
        <h1>${esc(gem.name)}</h1>
        <p>使用するカットを選び、「これを使う」を押してください。</p>
      </header>
      <div class="craft-loose-cut-list">
        ${shapeIds.length ? shapeIds.map((shapeId) => {
          const available = looseAvailableQuantity(gemId, shapeId, orderId || '');
          const selected = craftDraft.gem === gemId && normalizeLooseShape(gemId, craftDraft.looseShape) === shapeId;
          return `<article class="craft-loose-cut-card ${selected ? 'selected' : ''}">
            <div class="craft-loose-cut-image">${looseVisual(gemId, 'choice-loose', '', shapeId)}</div>
            <div class="craft-loose-cut-copy"><strong>${esc(looseShapeLabel(shapeId))}</strong><small>${order ? 'この注文に使用可能' : '使用可能'} ${available}個</small></div>
            <button type="button" class="primary-button craft-use-loose-button" data-action="craft-use-loose" data-id="${esc(gemId)}" data-shape="${esc(shapeId)}">これを使う</button>
          </article>`;
        }).join('') : '<div class="empty-state"><strong>使用できるカットがありません。</strong><p>ジュエリーを作る画面へ戻り、別の石種を選択してください。</p></div>'}
      </div>
      <button type="button" class="secondary-button full-button craft-loose-bottom-back" data-action="back">戻る</button>
    </section>`, { back: false, help: '所持しているルースのうち、使用できるカットだけを表示しています。「これを使う」で制作に使うルースを決定します。' });
}

function rerenderCraftPreservingPosition() {
  const content = root.querySelector('.screen-content');
  const options = root.querySelector('.craft-options');
  const contentScrollTop = content?.scrollTop || 0;
  const optionsScrollTop = options?.scrollTop || 0;
  render();
  requestAnimationFrame(() => {
    const nextContent = root.querySelector('.screen-content');
    const nextOptions = root.querySelector('.craft-options');
    if (nextContent) nextContent.scrollTop = contentScrollTop;
    if (nextOptions) nextOptions.scrollTop = optionsScrollTop;
  });
}

function renderCraft() {
  if (!workshopOperating()) return shell('ジュエリー作成', '<div class="empty-state"><strong>工房は作業停止中です。</strong><p>未払いの工房維持費を支払うと再開できます。</p></div>');
  if (!toolUsable('jewelryBench')) {
    return shell('ジュエリー作成', `
      <section class="center-card glass-panel">
        <h1>彫金机がありません。</h1>
        <p>ジュエリーを制作するには、g-Lab.で彫金机を購入してください。</p>
        <button class="primary-button full-button" data-action="nav" data-screen="okachimachi">御徒町へ</button>
      </section>`, { help: '彫金机は御徒町のg-Lab.で購入できます。' });
  }
  const orderId = screenData.orderId || null;
  if (!craftDraft || craftDraft.orderId !== orderId) craftDraft = defaultDraft(orderId);
  if (craftDraft.useLoose !== false) craftDraft.looseShape = normalizeLooseShape(craftDraft.gem, craftDraft.looseShape);
  const locked = Boolean(orderId);
  const order = locked ? state.orders.find((entry) => entry.id === orderId) : null;
  const hours = productionHours(craftDraft);
  const cost = productionCost(craftDraft);
  const quality = expectedQuality();
  const craftsmanship = craftProductionProfile(craftDraft);
  const basePrice = recommendedPrice({ ...craftDraft, quality });
  const price = craftsmanshipRecommendedPrice(craftDraft, quality, craftsmanship);
  const requirements = materialRequirementsFor(craftDraft);
  const looseModeSelected = typeof craftDraft.useLoose === 'boolean';
  const enoughGem = craftDraft.useLoose === false ? true : requirements.enoughLoose;
  const enoughMetal = requirements.enoughMetal;
  const capacityOk = state.inventory.jewelry.filter((item) => item.status !== 'sold').length < state.inventory.capacity;
  const canCraft = looseModeSelected && enoughGem && enoughMetal && capacityOk && canSpendHours(hours);
  const selectableLooseExists = craftDraft.useLoose === true && craftAvailableLooseGems(orderId).length > 0;
  const looseSummaryName = craftDraft.useLoose === true ? looseDisplayLabel(craftDraft.gem, craftDraft.looseShape, { suffix: true }) : 'ルースなし';

  return shell(order ? '注文の商品を作る' : 'ジュエリーを作る', `
    <div class="craft-layout craft-layout-no-preview">
      <section class="craft-options glass-panel">
        ${craftChoice('アイテムの選択', 'item', ITEMS, craftDraft.item, locked)}
        ${craftLooseModeChoice(locked)}
        ${craftDraft.useLoose === true ? craftLooseGemChoice(orderId) : ''}
        ${craftMetalChoice(craftDraft.metal, locked)}
        ${craftChoice('デザイン', 'design', DESIGNS, craftDraft.design, locked)}
        ${craftSurfaceChoice(craftDraft.finish)}

        ${looseModeSelected && (craftDraft.useLoose === false || selectableLooseExists) ? `<section class="craft-final-summary" aria-label="完成予定の詳細">
          <p class="craft-summary-loose">${craftDraft.useLoose === true ? `◇${esc(looseSummaryName)}` : esc(looseSummaryName)}</p>
          <h2>${esc(itemName(craftDraft))}</h2>
          ${order ? `<span class="order-badge">${esc(order.customerName)}さんの注文品</span>` : ''}
          <dl class="craft-summary-details">
            <div><dt>制作時間</dt><dd>${hours}時間</dd></div>
            <div><dt>原価</dt><dd>${yen(cost)}</dd></div>
            <div><dt>品質予想</dt><dd>${esc(QUALITIES[quality].name)}</dd></div>
            <div><dt>加工品質</dt><dd>${craftsmanship.craftsmanshipScore} / 100（${esc(craftsmanship.tier)}）</dd></div>
            <div><dt>有効な関連工具</dt><dd>${craftsmanship.usableToolCount} / ${craftsmanship.relevantToolCount}</dd></div>
            <div><dt>工具・知識価格補正</dt><dd>×${craftsmanship.priceMultiplier.toFixed(2)}</dd></div>
            <div><dt>基礎おすすめ価格</dt><dd>${yen(basePrice)}</dd></div>
            <div><dt>おすすめ価格</dt><dd>${yen(price)}</dd></div>
          </dl>
          ${craftsmanship.tags.length ? `<p class="small-note">加工タグ：${craftsmanship.tags.map((tag) => esc(tag)).join('・')}</p>` : ''}
          ${craftsmanship.knowledgeLabels.length ? `<p class="small-note">連携中の加工知識：${craftsmanship.knowledgeLabels.map((name) => esc(name)).join('・')}</p>` : ''}
          ${craftsmanship.missingTools.length ? `<p class="small-note">価格に影響が大きい未使用工具：${craftsmanship.missingTools.slice(0, 4).map((entry) => esc(entry.name)).join('・')}</p>` : ''}
          ${enoughMetal ? '' : `<div class="craft-metal-shortage">
            <p>${esc(METALS[craftDraft.metal].name)}が${metalWeightLabel(requirements.missingMetalWeight)}g足りません。</p>
            <button type="button" class="secondary-button full-button" data-action="nav" data-screen="supplierMetals" data-tab="buy">地金屋へ</button>
          </div>`}
        </section>` : ''}

        <div class="validation-list">
          ${capacityOk ? '' : '<p>・完成品の保管場所に空きがありません。</p>'}
          ${canSpendHours(hours) ? '' : '<p class="craft-time-warning">今日は制作する時間がありません。</p>'}
        </div>
        <button class="primary-button full-button" data-action="confirm-craft" ${canCraft ? '' : 'disabled'}>制作する</button>
        ${craftDraft.useLoose === true && !enoughGem && toolUsable('polishingMachine') && state.inventory.rough[craftDraft.gem] > 0 ? '<button class="secondary-button full-button" data-action="nav" data-screen="polishing">原石を研磨する</button>' : ''}
        ${craftDraft.useLoose === true && !enoughGem ? '<button class="secondary-button full-button" data-action="nav" data-screen="looseShop">ルース屋へ</button>' : ''}
      </section>
    </div>`, { help: 'アイテム、ルースを使用するか、地金、デザイン、表面の順に選びます。ルースを使用する場合だけ、所持している石種とカットを選びます。各項目を選んでも完成予定の詳細へ自動移動しません。ルースは石種を選んだ後、別画面で使用するカットを決定します。最後に画面下部で完成予定を確認してください。' });
}

function renderCompletion() {
  const jewelry = state.inventory.jewelry.find((item) => item.id === completionId);
  if (!jewelry) return shell('完成', '<p>完成品が見つかりません。</p>');
  const usesLoose = jewelry.useLoose !== false;
  const order = jewelry.orderId ? state.orders.find((entry) => entry.id === jewelry.orderId) : null;
  const isPendingOrderDelivery = Boolean(order && order.status === '完成' && order.jewelryId === jewelry.id && jewelry.status === 'order');
  const completionActions = isPendingOrderDelivery
    ? `<button class="primary-button" data-action="deliver-order-completion" data-id="${order.id}">お客様へ納品する</button>
       <button class="secondary-button" data-action="remake-order-completion" data-id="${order.id}" data-jewelry="${jewelry.id}">作り直す</button>`
    : `<button class="primary-button" data-action="open-craft">ジュエリー作成を続ける</button>
       <button class="secondary-button" data-action="nav" data-screen="workshop">工房へ戻る</button>`;
  return shell('完成', `
    <section class="center-card glass-panel result-card">
      <div class="jewelry-preview large completion-jewelry-preview metal-${jewelry.metal} item-${jewelry.item}" style="--gem:${GEMS[jewelry.gem]?.hue || '#ffffff'}">
        <span class="completion-jewelry-artwork item-${jewelry.item}">
          ${jewelryItemVisual(jewelry.item, 'jewelry-item-shape large', usesLoose)}
          ${usesLoose ? `<span class="jewelry-preview-loose">${jewelryLooseSetVisual(jewelry.item, jewelry.gem, jewelry.looseShape, 'completion')}</span>` : ''}
        </span>
      </div>
      <h1>${esc(jewelry.name)}が完成しました。</h1>
      <div class="result-stats">
        <span>品質：${esc(QUALITIES[jewelry.quality].name)}</span>
        ${Number(jewelry.craftsmanshipScore) > 0 ? `<span>加工品質：${Math.round(Number(jewelry.craftsmanshipScore))}/100（${esc(jewelry.craftsmanshipTier || '')}）</span>` : ''}
        ${Number(jewelry.craftsmanshipPriceMultiplier) > 0 ? `<span>工具・知識補正：×${Number(jewelry.craftsmanshipPriceMultiplier).toFixed(2)}</span>` : ''}
        <span>原価：${yen(jewelry.cost)}</span>
        <span>おすすめ価格：${yen(jewelry.recommendedPrice)}</span>
        <span>経験値：＋${jewelry.xp}</span>
      </div>
      ${Array.isArray(jewelry.craftsmanshipTags) && jewelry.craftsmanshipTags.length ? `<p class="small-note">加工タグ：${jewelry.craftsmanshipTags.map((tag) => esc(tag)).join('・')}</p>` : ''}
      ${Array.isArray(jewelry.craftsmanshipKnowledge) && jewelry.craftsmanshipKnowledge.length ? `<p class="small-note">活用した加工知識：${jewelry.craftsmanshipKnowledge.map((name) => esc(name)).join('・')}</p>` : ''}
      ${screenData.toolFailure ? `<div class="tool-break-alert"><strong>${esc(screenData.toolFailure)}が壊れました</strong><span>${WORKSHOP_TOOLS[Object.keys(WORKSHOP_TOOLS).find((id) => WORKSHOP_TOOLS[id].name === screenData.toolFailure)]?.repairable ? 'g-Lab.で修理を依頼できます。' : '工房からなくなりました。g-Lab.で再購入できます。'}</span></div>` : ''}
      <div class="button-stack">${completionActions}</div>
    </section>`, isPendingOrderDelivery ? { back: false, main: false } : { main: true });
}

function renderInventory() {
  const tabs = ['rough', 'loose', 'metals', 'finished', 'equipment', 'knowledge'];
  const tab = tabs.includes(screenData.tab) ? screenData.tab : 'finished';
  const labels = { rough: '原石', loose: 'ルース', metals: '地金', finished: '完成品', equipment: '工具・設備', knowledge: '加工知識' };
  const content = tab === 'finished'
    ? renderFinishedItems()
    : tab === 'equipment'
      ? renderToolEquipmentInventory()
      : tab === 'knowledge'
        ? renderProcessingKnowledgeInventory()
        : renderMaterialInventory(tab);
  return shell(`${labels[tab]}一覧`, `
    <section class="wide-panel glass-panel">
      <div class="tab-row inventory-category-tabs">
        <button class="${tab === 'rough' ? 'active' : ''}" data-action="inventory-tab" data-tab="rough">原石</button>
        <button class="${tab === 'loose' ? 'active' : ''}" data-action="inventory-tab" data-tab="loose">ルース</button>
        <button class="${tab === 'metals' ? 'active' : ''}" data-action="inventory-tab" data-tab="metals">地金</button>
        <button class="${tab === 'finished' ? 'active' : ''}" data-action="inventory-tab" data-tab="finished">完成品</button>
        <button class="${tab === 'equipment' ? 'active' : ''}" data-action="inventory-tab" data-tab="equipment">工具・設備</button>
        <button class="${tab === 'knowledge' ? 'active' : ''}" data-action="inventory-tab" data-tab="knowledge">加工知識</button>
      </div>
      ${content}
      ${tab === 'finished' ? '<div class="button-stack inventory-footer-actions"><button type="button" class="secondary-button full-button" data-action="nav" data-screen="workshop">工房へ戻る</button></div>' : ''}
    </section>`, { help: '工房で所持している原石・ルース・地金・完成品・工具と設備、イベントで得た加工知識の文書を種類別に確認できます。' });
}

function renderProcessingKnowledgeInventory() {
  const entries = processingKnowledgeEntries();
  if (!entries.length) return '<div class="empty-state"><strong>加工知識はまだありません。</strong><p>今後、イベントなどで加工に関する知識を得ると、詳細な文書がここへ追加されます。</p></div>';
  return `<div class="equipment-list processing-knowledge-list">${entries.map(({ record, document }) => {
    const category = String(document.category || '加工');
    const summary = String(document.summary || document.overview || '加工に関する詳細資料です。');
    const source = String(record.source || 'イベント');
    return `<button type="button" class="equipment-row equipment-detail-button processing-knowledge-row" data-action="open-processing-knowledge" data-id="${esc(record.id)}">
      <span class="equipment-icon" aria-hidden="true">文</span>
      <span class="equipment-row-copy"><strong>${esc(document.title || record.id)}</strong><small>${esc(category)}・${esc(summary)}</small></span>
      <span class="equipment-status available">${esc(source)}</span>
    </button>`;
  }).join('')}</div>`;
}

function renderProcessingKnowledgeDocument(document) {
  const sections = Array.isArray(document?.sections) ? document.sections : [];
  const references = Array.isArray(document?.references) ? document.references : [];
  const opening = [document?.overview, document?.body].filter(Boolean).map((value) => String(value));
  const wordCount = opening.join('').length + sections.reduce((total, section) => total
    + (Array.isArray(section?.paragraphs) ? section.paragraphs.join('').length : String(section?.body || '').length)
    + (Array.isArray(section?.points) ? section.points.join('').length : 0), 0);
  return `<article class="tool-learning-guide processing-knowledge-document">
    <div class="tool-guide-stats" aria-label="加工知識の収録範囲">
      <strong>加工資料 全${Math.max(1, sections.length)}章</strong>
      <span>本文約${wordCount.toLocaleString('ja-JP')}字</span>
      ${references.length ? `<span>参考資料${references.length}件</span>` : ''}
      ${document?.revision ? `<span>改訂 ${esc(document.revision)}</span>` : ''}
    </div>
    ${opening.map((paragraph, index) => `<p class="${index === 0 ? 'tool-guide-lead' : ''}">${esc(paragraph)}</p>`).join('')}
    ${sections.length > 1 ? `<details class="tool-guide-toc"><summary>目次を開く</summary><ol>${sections.map((section, index) => `<li><a href="#processing-knowledge-section-${index + 1}">${esc(section.title || '')}</a></li>`).join('')}</ol></details>` : ''}
    ${sections.map((section, index) => {
      const paragraphs = Array.isArray(section?.paragraphs) ? section.paragraphs : (section?.body ? [section.body] : []);
      const points = Array.isArray(section?.points) ? section.points : [];
      return `<section class="tool-guide-section" id="processing-knowledge-section-${index + 1}">
        <div class="tool-guide-chapter-number">${String(index + 1).padStart(2, '0')}</div>
        <h3>${esc(section.title || '')}</h3>
        ${paragraphs.map((paragraph) => `<p>${esc(paragraph)}</p>`).join('')}
        ${points.length ? `<ul>${points.map((point) => `<li>${esc(point)}</li>`).join('')}</ul>` : ''}
      </section>`;
    }).join('')}
    ${references.length ? `<section class="tool-guide-section tool-guide-references"><h3>参考資料</h3><ul>${references.map((reference) => `<li>${esc(reference)}</li>`).join('')}</ul></section>` : ''}
  </article>`;
}

function renderProcessingKnowledgeDetail() {
  const id = String(screenData.knowledgeId || '');
  const entry = processingKnowledgeEntries().find(({ record }) => String(record.id) === id);
  if (!entry) return shell('加工知識', '<div class="empty-state"><strong>加工知識が見つかりません。</strong><p>工房の加工知識一覧から文書を選択してください。</p></div>');
  const { record, document } = entry;
  return shell(document.title || '加工知識', `
    <section class="glass-panel metal-professional-guide-page processing-knowledge-detail-page">
      <div class="metal-guide-title"><span class="material-chip">${esc(document.category || '加工知識')}</span><div><h1>${esc(document.title || record.id)}</h1><p>入手元：${esc(record.source || 'イベント')}・${Math.max(1, Number(record.acquiredDay) || 1)}日目に追加</p></div></div>
      ${renderProcessingKnowledgeDocument(document)}
      <button type="button" class="primary-button full-button" data-action="back">加工知識一覧へ戻る</button>
    </section>`, { main: false, help: 'イベントなどで得た加工方法・工程・注意点・判断基準などの詳細文書を確認できます。' });
}

function renderToolEquipmentInventory() {
  const items = Object.entries(state?.tools?.items || {})
    .filter(([, record]) => Boolean(record))
    .map(([toolId, record]) => ({ toolId, record, tool: WORKSHOP_TOOLS[toolId] }))
    .filter((entry) => entry.tool);
  if (!items.length) return '<div class="empty-state"><strong>工具・設備はありません。</strong><p>g-Lab.で彫金机や宝石研磨用平面研磨盤などを購入すると、ここに表示されます。</p></div>';
  return `<section class="workshop-equipment-summary"><div><small>工房レベル</small><strong>${workshopLevel()}</strong></div><div><small>工房評価</small><strong>${workshopQualityPoints()}</strong></div></section>
    <div class="equipment-list">${items.map(({ toolId, record, tool }) => {
      const status = workshopToolStatusText(toolId, record);
      const statusClass = record.status === 'available' ? 'available' : record.status === 'repairing' ? 'repairing' : 'unusable';
      const hasProvidedImage = Boolean(tool.image && !String(tool.image).includes('placeholder.svg'));
      const visual = hasProvidedImage
        ? `<span class="equipment-icon equipment-image-icon" aria-hidden="true"><img src="${workshopToolImageSrc(tool)}" alt="" loading="lazy" decoding="async"></span>`
        : `<span class="equipment-icon" aria-hidden="true">${esc(tool.symbol || '⚒')}</span>`;
      return `<button type="button" class="equipment-row equipment-detail-button ${statusClass}" data-action="tool-detail" data-id="${esc(toolId)}">
        ${visual}
        <span class="equipment-row-copy"><strong>${esc(tool.name)}</strong><small>${esc(tool.type)}・${esc(tool.description)}</small></span>
        <span class="equipment-status ${statusClass}">${esc(status)}</span>
      </button>`;
    }).join('')}</div>`;
}

function renderMaterialInventory(kind) {
  if (kind === 'rough') {
    const items = Object.values(GEMS).filter((gem) => Number(state.inventory.rough[gem.id] || 0) > 0);
    if (!items.length) return '<div class="empty-state"><strong>原石はありません。</strong><p>採掘で原石を入手すると、ここに表示されます。</p></div>';
    return `<div class="inventory-single-list">${items.map((gem) => `<div class="material-row"><span class="material-name">${roughVisual(gem.id, 'gem-inline')}<span>${esc(roughDisplayName(gem.id))}</span></span><strong>${state.inventory.rough[gem.id]}個</strong></div>`).join('')}</div>`;
  }

  if (kind === 'loose') {
    const items = looseVariantRows({ ownedOnly: true });
    const blackDiamondKnowledgeUnlocked = Boolean(state?.events?.bluesJukeEvent?.knowledgeUnlocked);
    if (blackDiamondKnowledgeUnlocked && !items.some((entry) => entry.gem.id === BLUES_JUKE_EVENT_GEM_ID)) {
      const shapeId = BLUES_JUKE_EVENT_GEM_SHAPE_ID;
      const metrics = looseInventoryMetrics(BLUES_JUKE_EVENT_GEM_ID, shapeId);
      items.push({ gem: GEMS[BLUES_JUKE_EVENT_GEM_ID], shapeId, shape: LOOSE_SHAPES[shapeId], ...metrics });
    }
    if (!items.length) return '<div class="empty-state"><strong>ルースはありません。</strong><p>原石を研磨するか、ルース屋で購入すると、石種とカットごとに表示されます。</p></div>';
    return `<div class="inventory-single-list loose-inventory-list">${items.map(({ gem, shapeId, shape, owned, reserved, available }) => `<button type="button" class="material-row loose-inventory-row" data-action="open-loose-detail" data-id="${esc(gem.id)}" data-shape="${esc(shapeId)}"><span class="material-name">${looseVisual(gem.id, 'loose-mini', '', shapeId)}<span>${esc(workshopLooseDisplayName(gem, shape))}</span></span><span class="loose-row-counts"><strong>${owned}個</strong><small>${gem.id === BLUES_JUKE_EVENT_GEM_ID && owned === 0 && blackDiamondKnowledgeUnlocked ? '宝石学解説 解放済み' : `注文予定 ${reserved}・使用可能 ${available}`}</small></span><i aria-hidden="true">›</i></button>`).join('')}</div>`;
  }

  const items = METAL_WORKSHOP_ORDER.map((id) => METALS[id]).filter(Boolean);
  return `<div class="inventory-single-list metal-inventory-list">${items.map((metal) => `<button type="button" class="material-row metal-inventory-row" data-action="metal-inventory-detail" data-id="${esc(metal.id)}"><span class="material-name">${metalVisual(metal.id, 'metal-inline-visual')}<span>${esc(metal.shortName || metal.alloy || metal.name)}</span></span><strong>${metalWeightLabel(state.inventory.metals[metal.id])}g</strong><i aria-hidden="true">›</i></button>`).join('')}</div>`;
}

function renderLooseInventoryDetail() {
  const gem = GEMS[screenData.gemId];
  if (!gem) return shell('ルース詳細', '<div class="empty-state"><strong>ルース情報が見つかりません。</strong></div>');
  const shapeId = normalizeLooseShape(gem.id, screenData.looseShape);
  const shape = LOOSE_SHAPES[shapeId];
  const metrics = looseInventoryMetrics(gem.id, shapeId);
  const purchasePrice = loosePurchasePrice(gem.id, shapeId);
  const salePrice = looseSalePrice(gem.id, shapeId);
  const isPearl = gem.id === 'pearl';
  const isOriginalLoose = Boolean(gem.originalLoose);
  const gemGuideAvailable = Boolean(GEM_LOOSE_GUIDES[gem.id]);
  return shell(isOriginalLoose ? gem.name : (gem.id === 'pearl' ? gem.name : `${gem.name}・${shape.name}`), `
    <section class="wide-panel glass-panel loose-inventory-detail-page">
      <header class="loose-detail-heading">
        <div class="loose-detail-image">${looseVisual(gem.id, 'loose-detail-main-image', '', shapeId)}</div>
        <div><small>${isOriginalLoose ? 'オリジナルルース' : 'ルースの種類'}</small><h1>${esc(gem.name)}</h1>${isOriginalLoose || isPearl ? '' : `<p>${esc(shape.name)}</p>`}</div>
      </header>
      <div class="loose-detail-description-grid">
        <section class="loose-knowledge-card"><div><h2>${isOriginalLoose ? 'ルースについて' : '石種について'}</h2><p>${esc(looseGemShortDescription(gem.id))}</p></div>${!isOriginalLoose && gemGuideAvailable ? `<button type="button" class="secondary-button loose-knowledge-button" data-action="loose-gem-guide-open" data-id="${esc(gem.id)}">プロ向け宝石学詳細</button>` : ''}</section>
        ${isOriginalLoose || isPearl ? '' : `<section class="loose-knowledge-card"><div><h2>カットについて</h2><p>${esc(LOOSE_SHAPE_DESCRIPTIONS[shapeId] || `${shape.name}の形状です。`)}</p></div><button type="button" class="secondary-button loose-knowledge-button" data-action="loose-cut-guide-open" data-shape="${esc(shapeId)}">詳しい説明を見る</button></section>`}
      </div>
      ${isOriginalLoose ? renderOriginalLooseInfoCard(gem.id) : ''}
      <dl class="loose-inventory-metrics">
        <div><dt>所持数</dt><dd>${metrics.owned}個</dd></div>
        <div><dt>注文に使用予定の数</dt><dd>${metrics.reserved}個</dd></div>
        <div><dt>${isOriginalLoose ? '参考価格' : 'ルース屋の販売価格'}</dt><dd>${yen(purchasePrice)}</dd></div>
        <div><dt>ルース屋の売却価格</dt><dd>${isOriginalLoose ? '売却不可' : yen(salePrice)}</dd></div>
      </dl>
      ${metrics.shortage > 0 ? `<p class="loose-reservation-warning">受注中の注文に必要なルースが${metrics.shortage}個不足しています。</p>` : metrics.reserved > 0 ? '<p class="loose-reservation-note">注文に使用予定のルースは、通常制作と売却には使用できません。</p>' : ''}
      <div class="button-stack loose-detail-actions">
        <button type="button" class="secondary-button full-button" data-action="back">戻る</button>
      </div>
    </section>`);
}


function renderLooseGemGuide() {
  const gem = GEMS[screenData.gemId];
  const guide = gem ? GEM_LOOSE_GUIDES[gem.id] : null;
  if (gem && guide && (!dailyGemsModule || !looseProfessionalModule)) {
    void Promise.all([ensureDailyGemsLoaded(), ensureLooseProfessionalLoaded()])
      .then(() => { if (screen === 'looseGemGuide' || screen === 'looseCutGuide') render(); })
      .catch((error) => {
        console.error('プロ向け宝石学データ読み込みエラー', error);
        if (screen === 'looseGemGuide' || screen === 'looseCutGuide') showToast('専門データを読み込めませんでした。', 'error');
      });
    return shell(`${gem.name} ルースの詳細`, '<div class="empty-state"><strong>宝石学データを読み込んでいます。</strong><p>初回だけ専門データを準備します。</p></div>', { main: false });
  }
  const profile = gem ? looseGemProfile(gem.id) : null;
  if (!gem || !guide) return shell('ルースの詳細', '<div class="empty-state"><strong>石種情報が見つかりません。</strong></div>');
  const specs = looseGemProfessionalSpecs(gem.id, guide);
  const sectionGroups = looseGemProfessionalSections(gem.id, guide);
  const overview = profile?.overview || guide.overview || '';
  const classification = profile?.classification || guide.mineral || '';
  const sourceBasis = gem.id === 'ivory'
    ? '標準的な有機質宝石材料検査／環境省・経済産業省の象牙取引制度案内／CITESの国際取引規則／GIAのジュエリーケア指針'
    : 'GIA Gem Encyclopedia・Care & Cleaning Guides・Gems & Gemology／CIBJO Diamond・Gemstone・Pearl Blue Books／標準宝石学検査と専門ラボ分析';
  return shell(`${gem.name} ルースの詳細`, `
    <article class="today-gem-page loose-gem-professional-page">
      <header class="today-gem-hero glass-panel loose-guide-hero">
        <div class="today-gem-date"><small>GEMSTONE PROFESSIONAL DATA</small><strong>ルースの詳細</strong></div>
        <div class="today-gem-name-block">
          <h1>${esc(gem.name)}</h1>
          <p>${esc(classification)}</p>
        </div>
        <p class="today-gem-overview">${esc(overview)}</p>
      </header>

      <section class="today-gem-section glass-panel">
        <div class="today-gem-section-heading">
          <span>GEMOLOGICAL SPECIFICATIONS</span>
          <h2>宝石学的主要スペック</h2>
        </div>
        <dl class="today-gem-properties">
          ${specs.map(([label, value]) => `<div><dt>${esc(label)}</dt><dd>${esc(value || '不明')}</dd></div>`).join('')}
        </dl>
        <p class="today-gem-data-note">数値は天然宝石に一般的に用いられる代表値・代表範囲です。固溶組成、産地、成長構造、集合組織、処理、測定波長、温度、測定方法によって変動します。モース硬度は引っかき傷への相対的抵抗であり、靭性、劈開、熱衝撃、薬品への安定性とは別の性質です。</p>
      </section>

      <section class="today-gem-section glass-panel loose-professional-section-intro">
        <div class="today-gem-section-heading">
          <span>FOUNDATION AND MATERIAL SCIENCE</span>
          <h2>宝石学・素材学の基礎</h2>
        </div>
        <p class="today-gem-data-note">鉱物種・変種・有機質材料の性質、色、内包物、処理、耐久性を整理しています。一般論を現物へそのまま当てはめず、個体の検査結果を優先してください。</p>
      </section>
      <section class="today-gem-knowledge">
        ${sectionGroups.foundation.map((section, index) => `<article class="today-gem-note glass-panel"><div class="today-gem-note-number">B${String(index + 1).padStart(2, '0')}</div><div><h2>${esc(section.title || '')}</h2><p>${esc(section.body || '')}</p></div></article>`).join('')}
      </section>

      <section class="today-gem-section glass-panel loose-professional-section-intro">
        <div class="today-gem-section-heading">
          <span>IDENTIFICATION, VALUATION AND BENCH PRACTICE</span>
          <h2>プロ向け鑑別・評価・加工実務</h2>
        </div>
        <p class="today-gem-data-note">標準検査の組み立て、天然・合成・処理の判断、価値評価、カット方向、修理受付、石留めリスクを工房実務の視点で解説します。</p>
      </section>
      <section class="today-gem-knowledge loose-professional-advanced-list">
        ${sectionGroups.advanced.map((section, index) => `<article class="today-gem-note glass-panel"><div class="today-gem-note-number">P${String(index + 1).padStart(2, '0')}</div><div><h2>${esc(section.title || '')}</h2><p>${esc(section.body || '')}</p></div></article>`).join('')}
      </section>

      <section class="today-gem-section glass-panel loose-professional-section-intro">
        <div class="today-gem-section-heading">
          <span>WORKSHOP EXAMINATION PROTOCOL</span>
          <h2>工房共通の検査・記録原則</h2>
        </div>
        <p class="today-gem-data-note">石種にかかわらず、加工前検品と説明責任で外せない共通原則です。</p>
      </section>
      <section class="today-gem-knowledge loose-professional-common-list">
        ${sectionGroups.common.map((section, index) => `<article class="today-gem-note glass-panel"><div class="today-gem-note-number">W${String(index + 1).padStart(2, '0')}</div><div><h2>${esc(section.title || '')}</h2><p>${esc(section.body || '')}</p></div></article>`).join('')}
      </section>

      <section class="today-gem-reference glass-panel">
        <h2>宝石情報の見方と注意点</h2>
        <p>宝石名は鉱物種、変種名、岩石名、有機質宝石材料、光学現象名、流通名を区別して扱います。天然・合成、処理、産地は外観や単一の内包物だけで断定せず、標準宝石学検査と、必要に応じた分光分析、蛍光像、化学分析、信頼できる鑑別報告書を前提に判断してください。</p>
        <p>石言葉は鉱物学的・宝石学的性質ではなく、地域、時代、文献、販売者により異なる文化的・商業的表現です。医学的・科学的効能を示すものではありません。</p>
        <p>洗浄・修理・石留めでは、石種名だけでなく、表面到達亀裂、劈開、処理、充填、含浸、コーティング、組石、接着の有無を確認してください。処理不明石は安全側の方法を選びます。</p>
        <div class="today-gem-sources"><strong>主な参考体系</strong><span>${esc(sourceBasis)}</span></div>
      </section>

      <button type="button" class="primary-button full-button" data-action="back">戻る</button>
    </article>
  `, { main: false, help: '今日の宝石と同等以上の専門構成で、物性、鑑別、天然・合成・処理、内包物、分光・蛍光、価値評価、産地判定の限界、加工、石留め、洗浄、受付記録まで確認できます。' });
}

function renderLooseCutGuide() {
  if (screenData.gemId === 'pearl' || screenData.looseShape === 'pearl') { screenData.gemId = 'pearl'; return renderLooseGemGuide(); }
  const shapeId = screenData.looseShape;
  const shape = LOOSE_SHAPES[shapeId];
  const guide = shape ? (LOOSE_CUT_GUIDES[shapeId] || LOOSE_SPECIAL_CUT_GUIDES[shapeId]) : null;
  if (!shape || !guide) return shell('カットの詳細', '<div class="empty-state"><strong>カット情報が見つかりません。</strong></div>');
  const specs = LOOSE_CUT_SPECIFICATIONS[shapeId] || [
    ['分類', guide.category || '宝石カット'],
    ['外形', shape.name],
    ['規格', '名称が同じでも寸法、比率、面数、角度は一定ではない'],
  ];
  const sections = [...(Array.isArray(guide.sections) ? guide.sections : []), ...COMMON_LOOSE_CUT_SECTIONS];
  return shell(`${shape.name} カットの詳細`, `
    <article class="today-gem-page loose-cut-professional-page">
      <header class="today-gem-hero glass-panel loose-guide-hero">
        <div class="today-gem-date"><small>GEM CUT PROFESSIONAL DATA</small><strong>カットの詳細</strong></div>
        <div class="today-gem-name-block">
          <h1>${esc(shape.name)}</h1>
          <p>${esc(guide.category || '')}</p>
        </div>
        <p class="today-gem-overview">${esc(guide.overview || '')}</p>
      </header>

      <section class="today-gem-section glass-panel">
        <div class="today-gem-section-heading">
          <span>CUT SPECIFICATIONS</span>
          <h2>形状・光学・石留めの主要スペック</h2>
        </div>
        <dl class="today-gem-properties">
          ${specs.map(([label, value]) => `<div><dt>${esc(label)}</dt><dd>${esc(value || '不明')}</dd></div>`).join('')}
        </dl>
        <p class="today-gem-data-note">色石のカット名は、外形または代表的なファセット様式を示す名称です。同じ名称でも面数、テーブル径、クラウン角、パビリオン角、全深さ、縦横比は一定ではありません。適切な設計は石種の屈折率、複屈折、多色性、色、透明度、内包物、原石形状、用途によって変わります。</p>
      </section>

      <section class="today-gem-knowledge">
        ${sections.map((section, index) => `<article class="today-gem-note glass-panel"><div class="today-gem-note-number">${String(index + 1).padStart(2, '0')}</div><div><h2>${esc(section.title || '')}</h2><p>${esc(section.body || '')}</p></div></article>`).join('')}
      </section>

      <section class="today-gem-reference glass-panel">
        <h2>カット情報の見方と注意点</h2>
        <p>カット品質は外形、プロポーション、シンメトリー、ポリッシュ、ガードル、ファセット配列、正面色、窓抜け、消光、明暗の動きを総合して判断します。重量を多く残したことと、正面から美しく見えることは同義ではありません。</p>
        <p>色石には、すべての石種へ共通する単一の理想角度や理想縦横比はありません。ダイヤモンドのラウンドブリリアントに用いる評価基準を、そのまま他の石種やファンシーシェイプへ適用しないでください。</p>
        <div class="today-gem-sources"><strong>主な参考体系</strong><span>GIAのColored Stone Cut QualityおよびGem Cutting Styles資料／標準的な宝石研磨・石留め実務</span></div>
      </section>

      <button type="button" class="primary-button full-button" data-action="back">戻る</button>
    </article>
  `, { main: false, help: '今日の宝石と同じ構成で、外形、ファセット様式、光学性能、窓抜け、消光、ボウタイ、ガードル、対称性、研磨、測定、石留め、再研磨まで確認できます。' });
}


function renderPureMetalProfessionalGuide() {
  const metal = PURE_METAL_GUIDES[screenData.metalId];
  if (!metal) return shell('純金属の専門詳細', '<div class="empty-state"><strong>純金属情報が見つかりません。</strong></div>');
  const specs = Array.isArray(metal.specs) ? metal.specs : [];
  const sections = Array.isArray(metal.sections) ? metal.sections : [];
  return shell(`${metal.name} 専門詳細`, `
    <section class="glass-panel metal-professional-guide-page pure-metal-professional-guide-page">
      <div class="metal-guide-title"><span class="material-chip">${esc(metal.symbol || '')}</span><div><h1>${esc(metal.name)}</h1><p>${esc(metal.composition || '')}</p></div></div>
      <p class="tool-guide-lead">${esc(metal.overview || '')}</p>
      ${specs.length ? `<section class="metal-specification-panel"><h2>主要スペック</h2><dl class="metal-specification-grid">${specs.map(([label, value]) => `<div><dt>${esc(label || '')}</dt><dd>${esc(value || '')}</dd></div>`).join('')}</dl><p>物性値は純度、温度、結晶粒、加工率、熱処理、測定方法で変化します。温度条件を記していない値は室温付近の代表値です。</p></section>` : ''}
      <div class="metal-guide-sections">
        ${sections.map((section) => `<section class="tool-guide-section"><h3>${esc(section.title || '')}</h3><p>${esc(section.body || '')}</p></section>`).join('')}
      </div>
      <p class="metal-guide-caution">相場上の純金属名と、実際に購入する地金の純度・形状・保証規格は同一とは限りません。実作業では仕入れ先の成分表、ミルシート、商品データシート、SDSを優先してください。</p>
      <button type="button" class="primary-button full-button" data-action="back">戻る</button>
    </section>`, { main: false, help: '純金属の基礎物性、加工、鋳造、接合、変色、分析、回収、安全管理まで詳しく確認できます。' });
}

function metalInventoryMetrics(metalId) {
  const owned = metalOwnedWeight(metalId);
  const reserved = metalReservedWeight(metalId);
  const available = metalAvailableWeight(metalId);
  const capacity = metalStorageLimit(metalId);
  const remaining = metalRemainingCapacity(metalId);
  return { owned, reserved, available, capacity, remaining };
}

function renderMetalInventoryDetail() {
  const metal = METALS[screenData.metalId];
  if (!metal) return shell('地金詳細', '<div class="empty-state"><strong>地金情報が見つかりません。</strong></div>');
  const metrics = metalInventoryMetrics(metal.id);
  const shortage = roundedMetalWeight(Math.max(0, metrics.reserved - metrics.owned));
  return shell(`${metal.shortName || metal.alloy} 地金詳細`, `
    <section class="wide-panel glass-panel metal-inventory-detail-page">
      <header class="metal-detail-heading">
        <span class="material-chip">地金</span>
        <div><small>地金の種類</small><h1>${esc(metal.shortName || metal.alloy || metal.name)}</h1></div>
      </header>
      <section class="metal-composition-card">
        <h2>品位・主な組成</h2>
        <p>${esc(metal.composition || '')}</p>
      </section>
      <section class="metal-summary-card">
        <div><h2>特徴</h2><p>${esc(metal.summary || '')}</p></div>
        <button type="button" class="secondary-button metal-professional-button" data-action="metal-professional-open" data-id="${esc(metal.id)}">詳細</button>
      </section>
      <dl class="metal-inventory-metrics">
        <div><dt>所持重量</dt><dd>${metalWeightLabel(metrics.owned)}g</dd></div>
        <div><dt>注文に使用予定の重量</dt><dd>${metalWeightLabel(metrics.reserved)}g</dd></div>
        <div class="emphasis"><dt>実際に使用できる重量</dt><dd>${metalWeightLabel(metrics.available)}g</dd></div>
        <div><dt>保管上限</dt><dd>${metalWeightLabel(metrics.capacity)}g</dd></div>
        <div><dt>残り保管可能重量</dt><dd>${metalWeightLabel(metrics.remaining)}g</dd></div>
      </dl>
      ${shortage > 0 ? `<p class="metal-reservation-warning">注文に必要な地金が${metalWeightLabel(shortage)}g不足しています。</p>` : metrics.reserved > 0 ? '<p class="metal-reservation-note">注文に使用予定の重量は、通常制作と売却には使用できません。</p>' : ''}
      <button type="button" class="secondary-button full-button" data-action="back">戻る</button>
    </section>`, { help: '所持重量から受注中の商品に必要な重量を差し引き、通常制作や売却に使用できる重量を表示します。' });
}

function renderMetalProfessionalGuide() {
  const metal = METALS[screenData.metalId];
  if (!metal) return shell('地金の専門詳細', '<div class="empty-state"><strong>地金情報が見つかりません。</strong></div>');
  const guide = metal.guide || {};
  const specs = Array.isArray(guide.specs) ? guide.specs : [];
  const sections = Array.isArray(guide.sections) ? guide.sections : [];
  return shell(`${metal.shortName || metal.alloy} 専門詳細`, `
    <section class="glass-panel metal-professional-guide-page">
      <div class="metal-guide-title"><span class="material-chip">${esc(metal.shortName || metal.alloy)}</span><div><h1>${esc(metal.name)}</h1><p>${esc(metal.composition || '')}</p></div></div>
      <p class="tool-guide-lead">${esc(guide.overview || metal.summary || '')}</p>
      ${specs.length ? `<section class="metal-specification-panel"><h2>主要スペック</h2><dl class="metal-specification-grid">${specs.map(([label, value]) => `<div><dt>${esc(label || '')}</dt><dd>${esc(value || '')}</dd></div>`).join('')}</dl><p>合金の数値は配合・製造状態・熱履歴で変化します。「代表値」は特定の市販材または複数市販材の例であり、すべての同品位合金を保証する値ではありません。</p></section>` : ''}
      <div class="metal-guide-sections">
        ${sections.map((section) => `<section class="tool-guide-section"><h3>${esc(section.title || '')}</h3><p>${esc(section.body || '')}</p></section>`).join('')}
      </div>
      <p class="metal-guide-caution">地金の性質は、割金、製造方法、加工率、熱履歴、仕入れロットによって変わります。実作業では仕入れ先の材質情報と現物の状態を優先してください。</p>
      <button type="button" class="primary-button full-button" data-action="back">戻る</button>
    </section>`, { main: false, help: '品位、加工、溶接、石留め、回収、安全管理まで、職人向けの地金特性を確認できます。' });
}

function finishedItemStatus(item) {
  if (!item) return '';
  const displayBranch = item.status === 'displayed' ? jewelryDisplayBranch(item.id) : null;
  if (item.status === 'displayed') return `${storeBranchLabel(displayBranch?.number || item.displayBranchNumber || 1)}に陳列中`;
  if (item.status === 'order') return '注文品';
  return '保管中';
}

function renderFinishedItems() {
  const items = state.inventory.jewelry.filter((item) => item.status !== 'sold');
  if (!items.length) return '<div class="empty-state"><strong>完成品はありません。</strong><p>工房でジュエリーを作ると、ここに表示されます。</p></div>';
  return `<div class="jewelry-grid finished-item-grid">${items.map((item) => `<button type="button" class="jewelry-card finished-item-card" data-action="open-finished-item-detail" data-id="${esc(item.id)}" aria-label="${esc(item.name)}の商品詳細を開く">
      <div class="small-jewelry metal-${item.metal} item-${item.item}" style="--gem:${GEMS[item.gem]?.hue || '#ffffff'}">${jewelryItemVisual(item.item, 'jewelry-item-shape small', item.useLoose !== false)}${item.useLoose !== false ? `<i>${jewelryLooseSetVisual(item.item, item.gem, item.looseShape, 'small')}</i>` : ''}</div>
      <div class="finished-item-summary"><h3>${esc(item.name)}</h3><p>原価 ${yen(item.cost)}</p>${Number(item.craftsmanshipScore) > 0 ? `<small>加工品質 ${Math.round(Number(item.craftsmanshipScore))}/100・価格補正 ×${Number(item.craftsmanshipPriceMultiplier || 1).toFixed(2)}</small>` : ''}<small>状態：${esc(finishedItemStatus(item))}</small></div>
    </button>`).join('')}</div>`;
}

function renderFinishedItemDetail() {
  const item = state.inventory.jewelry.find((entry) => entry.id === screenData.itemId && entry.status !== 'sold');
  if (!item) return shell('商品詳細', '<section class="center-card glass-panel"><div class="empty-state"><strong>商品が見つかりません。</strong><p>完成品一覧へ戻って確認してください。</p></div><button class="primary-button full-button" data-action="back">完成品一覧へ戻る</button></section>');
  const location = item.status === 'displayed' ? showcaseLocationForJewelry(item.id) : null;
  const sellingPrice = location?.slot ? showcaseSellingPrice(location.slot, item) : null;
  const looseLabel = item.useLoose === false ? 'ルースなし' : looseDisplayLabel(item.gem, item.looseShape);
  const status = finishedItemStatus(item);
  const expectedProfit = sellingPrice === null ? null : sellingPrice - Math.max(0, Number(item.cost) || 0);
  return shell('商品詳細', `
    <section class="showcase-detail-panel glass-panel finished-item-detail-panel">
      <div class="showcase-detail-visual jewelry-preview large metal-${item.metal} item-${item.item}" style="--gem:${GEMS[item.gem]?.hue || '#ffffff'}">
        ${jewelryItemVisual(item.item, 'jewelry-item-shape large', item.useLoose !== false)}
        ${item.useLoose !== false ? `<span class="jewelry-preview-loose">${jewelryLooseSetVisual(item.item, item.gem, item.looseShape, 'large')}</span>` : ''}
      </div>
      <h1>${esc(item.name)}</h1>
      <dl class="showcase-detail-grid">
        <div><dt>商品種類</dt><dd>${esc(ITEMS[item.item]?.name || '')}</dd></div>
        <div><dt>地金</dt><dd>${esc(METALS[item.metal]?.name || '')}</dd></div>
        <div><dt>ルース</dt><dd>${esc(looseLabel)}</dd></div>
        <div><dt>品質</dt><dd>${esc(QUALITIES[item.quality]?.name || '')}</dd></div>
        ${Number(item.craftsmanshipScore) > 0 ? `<div><dt>加工品質</dt><dd>${Math.round(Number(item.craftsmanshipScore))}/100（${esc(item.craftsmanshipTier || '')}）</dd></div>` : ''}
        ${Number(item.craftsmanshipPriceMultiplier) > 0 ? `<div><dt>工具・知識価格補正</dt><dd>×${Number(item.craftsmanshipPriceMultiplier).toFixed(2)}</dd></div>` : ''}
        ${Number(item.craftsmanshipRelevantTools) > 0 ? `<div><dt>有効な関連工具</dt><dd>${Math.max(0, Number(item.craftsmanshipUsableTools) || 0)} / ${Math.max(0, Number(item.craftsmanshipRelevantTools) || 0)}</dd></div>` : ''}
        ${Array.isArray(item.craftsmanshipTags) && item.craftsmanshipTags.length ? `<div><dt>加工タグ</dt><dd>${item.craftsmanshipTags.map((tag) => esc(tag)).join('・')}</dd></div>` : ''}
        ${Array.isArray(item.craftsmanshipKnowledge) && item.craftsmanshipKnowledge.length ? `<div><dt>加工知識</dt><dd>${item.craftsmanshipKnowledge.map((name) => esc(name)).join('・')}</dd></div>` : ''}
        <div><dt>原価</dt><dd>${yen(item.cost)}</dd></div>
        <div><dt>おすすめ価格</dt><dd>${yen(item.recommendedPrice)}</dd></div>
        ${sellingPrice === null ? '' : `<div><dt>販売価格</dt><dd>${yen(sellingPrice)}</dd></div><div><dt>予想利益</dt><dd>${yen(expectedProfit)}</dd></div>`}
        <div><dt>状態</dt><dd>${esc(status)}</dd></div>
      </dl>
    </section>`, { help: '完成品の種類、素材、品質、原価、状態を確認できます。' });
}


function storeTheftEventState() {
  state.events = state.events && typeof state.events === 'object' && !Array.isArray(state.events) ? state.events : {};
  const saved = state.events.storeTheftEvent && typeof state.events.storeTheftEvent === 'object' && !Array.isArray(state.events.storeTheftEvent)
    ? state.events.storeTheftEvent
    : {};
  const validStages = new Set(['idle', 'intro1', 'choice', 'declined', 'intro2', 'intro3', 'farewell', 'pause', 'theftNotice', 'completed']);
  state.events.storeTheftEvent = {
    lastCheckedDate: /^\d{4}-\d{2}-\d{2}$/.test(String(saved.lastCheckedDate || '')) ? String(saved.lastCheckedDate) : '',
    totalTriggered: Math.max(0, Math.floor(Number(saved.totalTriggered) || 0)),
    active: Boolean(saved.active),
    stage: validStages.has(saved.stage) ? saved.stage : 'idle',
    branchId: String(saved.branchId || ''),
    branchNumber: Math.max(1, Math.floor(Number(saved.branchNumber) || 1)),
    targetItemId: String(saved.targetItemId || ''),
    targetItemName: String(saved.targetItemName || ''),
    theftApplied: Boolean(saved.theftApplied),
  };
  if (!state.events.storeTheftEvent.active && !['idle', 'completed'].includes(state.events.storeTheftEvent.stage)) {
    state.events.storeTheftEvent.stage = 'completed';
  }
  return state.events.storeTheftEvent;
}

function maybeStartStoreTheftEvent(branch = currentStoreBranch()) {
  if (illnessEventSuppressionActive()) return false;
  const eventState = storeTheftEventState();
  if (eventState.active) {
    const activeBranchId = eventState.branchId || branch?.id || '';
    setScreen('storeTheftEvent', activeBranchId ? { branchId: activeBranchId } : {}, false);
    return true;
  }
  if (!branch) return false;
  const candidates = robberyItemsInBranch(branch);
  if (!candidates.length) return false;
  if (!markVisitEventCheckOncePerDay(eventState)) return false;
  if (Math.random() >= STORE_THEFT_EVENT_CHANCE) {
    saveGame();
    return false;
  }
  const target = randomFrom(candidates, candidates[0]);
  if (!target?.item) return false;
  eventState.totalTriggered += 1;
  eventState.active = true;
  eventState.stage = 'intro1';
  eventState.branchId = String(branch.id || `branch-${Math.max(1, Number(branch.number) || 1)}`);
  eventState.branchNumber = Math.max(1, Number(branch.number) || 1);
  eventState.targetItemId = String(target.item.id || '');
  eventState.targetItemName = String(target.item.name || '完成品');
  eventState.theftApplied = false;
  state.game.screen = 'storeTheftEvent';
  saveGame();
  setScreen('storeTheftEvent', { branchId: eventState.branchId }, false);
  requestAnimationFrame(() => playSfx('old-lady-appear', { gain: .92 }));
  vibrate([24, 28, 64]);
  return true;
}

function applyStoreTheftEventLoss() {
  const eventState = storeTheftEventState();
  if (eventState.theftApplied) return;
  const itemId = String(eventState.targetItemId || '');
  const itemName = String(eventState.targetItemName || '完成品');
  const item = state.inventory?.jewelry?.find((entry) => entry.id === itemId && entry.status === 'displayed');
  if (item) removeJewelry(item.id);
  eventState.theftApplied = true;
  addNotification('店舗で盗難が発生しました', `${itemName}が盗まれていました。`, 'warning');
}

function chooseStoreTheftEvent(answer) {
  const eventState = storeTheftEventState();
  if (!eventState.active || eventState.stage !== 'choice') return;
  if (answer === 'yes') {
    eventState.stage = 'intro2';
  } else {
    eventState.stage = 'declined';
  }
  saveGame();
  playSfx('select', { gain: .82 });
  render();
}

function finishStoreTheftEvent() {
  const eventState = storeTheftEventState();
  const branchId = eventState.branchId;
  eventState.active = false;
  eventState.stage = 'completed';
  saveGame();
  playSfx('select', { gain: .82 });
  setScreen('store', branchId ? { branchId } : {}, false);
}

function recoverStoreTheftDisappearanceSequence() {
  const eventState = storeTheftEventState();
  if (!eventState.active || !['farewell', 'pause'].includes(eventState.stage)) return;
  applyStoreTheftEventLoss();
  eventState.stage = 'theftNotice';
  saveGame();
  playSfx('shoplift-steal', { gain: .76, rate: .88 });
  vibrate([18, 32, 54]);
  render();
}

async function continueStoreTheftDisappearanceSequence() {
  if (storeTheftSequenceRunning) return;
  let eventState = storeTheftEventState();
  if (!eventState.active || !['farewell', 'pause'].includes(eventState.stage)) return;
  storeTheftSequenceRunning = true;
  try {
    if (eventState.stage === 'farewell') {
      duckCurrentAmbient({ factor: 0.03, duration: 4600 });
      playSfx('old-lady-appear', { gain: .24, rate: .66 });
      await wait(1900);
      eventState = storeTheftEventState();
      if (!eventState.active || eventState.stage !== 'farewell') return;
      eventState.stage = 'pause';
      saveGame();
      render();
    }
    eventState = storeTheftEventState();
    if (eventState.stage === 'pause') {
      duckCurrentAmbient({ factor: 0, duration: 2500 });
      await wait(1650);
      eventState = storeTheftEventState();
      if (!eventState.active || eventState.stage !== 'pause') return;
      applyStoreTheftEventLoss();
      eventState = storeTheftEventState();
      eventState.stage = 'theftNotice';
      saveGame();
      playSfx('shoplift-steal', { gain: .76, rate: .88 });
      setTimeout(() => playSfx('impact', { gain: .20, rate: .72 }), 130);
      vibrate([18, 32, 54]);
      render();
    }
  } finally {
    storeTheftSequenceRunning = false;
  }
}

async function advanceStoreTheftEvent() {
  const eventState = storeTheftEventState();
  if (!eventState.active) return;
  if (eventState.stage === 'intro1') {
    eventState.stage = 'choice';
    saveGame();
    playSfx('select', { gain: .82 });
    render();
    return;
  }
  if (eventState.stage === 'declined') {
    finishStoreTheftEvent();
    return;
  }
  if (eventState.stage === 'intro2') {
    eventState.stage = 'intro3';
    saveGame();
    playSfx('select', { gain: .82 });
    render();
    return;
  }
  if (eventState.stage === 'intro3') {
    eventState.stage = 'farewell';
    saveGame();
    playSfx('select', { gain: .72 });
    duckCurrentAmbient({ factor: 0.03, duration: 4600 });
    render();
    queueMicrotask(continueStoreTheftDisappearanceSequence);
    return;
  }
  if (eventState.stage === 'theftNotice') {
    finishStoreTheftEvent();
  }
}

function renderStoreTheftEvent() {
  const eventState = storeTheftEventState();
  if (!eventState.active) {
    const branchId = eventState.branchId;
    queueMicrotask(() => setScreen('store', branchId ? { branchId } : {}, false));
    return renderStore();
  }
  const stage = eventState.stage;
  if (stage === 'farewell' || stage === 'pause') queueMicrotask(continueStoreTheftDisappearanceSequence);
  const stolenLabel = esc(String(eventState.targetItemName || '完成品'));
  const characterHidden = stage === 'pause' || stage === 'theftNotice';
  const vanishing = stage === 'farewell';
  const choiceMarkup = `<div class="event-dialogue-card visit-event-dialogue glass-panel store-theft-dialogue"><small>老婆</small><strong>これを見せて、試着していい？</strong><div class="store-theft-choice-buttons"><button type="button" class="primary-button" data-action="store-theft-event-choice" data-answer="yes">はい</button><button type="button" class="secondary-button" data-action="store-theft-event-choice" data-answer="no">いいえ</button></div></div>`;
  let bodyMarkup = '';
  if (stage === 'choice') {
    bodyMarkup = choiceMarkup;
  } else if (stage === 'farewell') {
    bodyMarkup = `<button type="button" class="event-dialogue-card visit-event-dialogue glass-panel store-theft-dialogue store-theft-dialogue-auto" data-action="store-theft-event-recover"><small>老婆</small><strong>素敵ねぇ、今度買いに来るわね、ありがとう</strong><span>そう言って老婆は去っていった……<br>自動で進まない場合はタップ</span></button>`;
  } else if (stage === 'pause') {
    bodyMarkup = `<button type="button" class="store-theft-silent-pause" data-action="store-theft-event-recover" aria-label="盗難結果へ進む"><span>……</span><small>自動で進まない場合はタップ</small></button>`;
  } else {
    const dialogue = stage === 'intro1'
      ? 'あら、素敵なお店、素敵なジュエリーねぇ'
      : stage === 'declined'
        ? 'あら残念、でもまた来るわね'
        : stage === 'intro2'
          ? 'いいわねぇこれ、あ、それとそれも見せて、、、'
          : stage === 'intro3'
            ? 'これも見せて、、'
            : `${stolenLabel}が盗まれていました`;
    const speaker = stage === 'theftNotice' ? '店舗' : '老婆';
    const subline = stage === 'theftNotice' ? 'タップすると通常の店舗画面へ戻ります' : 'タップして進む';
    bodyMarkup = `<button type="button" class="event-dialogue-card visit-event-dialogue glass-panel store-theft-dialogue ${stage === 'theftNotice' ? 'store-theft-dialogue-alert' : ''}" data-action="store-theft-event-next"><small>${speaker}</small><strong>${dialogue}</strong><span>${subline}</span></button>`;
  }
  return `
    <main class="main-screen store-theft-event-screen">
      <section class="visit-character-event store-theft-event ${characterHidden ? 'is-after' : ''} ${vanishing ? 'is-vanishing' : ''}" aria-live="polite">
        <div class="store-theft-overlay" aria-hidden="true"></div>
        ${stage === 'pause' ? `<img class="store-theft-afterimage" src="./assets/images/events/store-thief-old-woman.png?v=${VERSION}" alt="" aria-hidden="true" draggable="false">` : ''}
        ${characterHidden ? '' : `<div class="visit-character-area store-theft-character-area" aria-hidden="true"><img class="visit-character store-theft-character" src="./assets/images/events/store-thief-old-woman.png?v=${VERSION}" alt="" draggable="false"></div>`}
        ${bodyMarkup}
      </section>
    </main>`;
}

function renderStore() {
  const branches = Array.isArray(state.store.branches)
    ? state.store.branches.filter((branch) => branch && Number(branch.number) >= 1).sort((a, b) => a.number - b.number)
    : [];

  if (!branches.length) {
    return shell('店舗', '<div class="empty-state store-empty-state"><strong>現在店舗はありません</strong></div>');
  }

  const branchId = screenData.branchId;
  if (!branchId) {
    return shell('店舗', `
      <section class="center-card glass-panel store-branch-menu">
        <h1>${esc(state.store.name || '店舗')}</h1>
        <div class="button-stack">
          ${branches.map((branch) => {
            const customerWaiting = storeBranchHasWaitingCustomer(branch);
            const statusLabel = branch.suspended ? '（休業中）' : !storeBusinessOpen() ? '（営業時間外）' : '';
            const accessibleVisitLabel = customerWaiting ? '・お客様が来店中' : '';
            return `<button class="primary-button full-button store-branch-button${customerWaiting ? ' has-waiting-customer' : ''}" data-action="open-store-branch" data-id="${esc(branch.id)}" aria-label="${esc(`${storeBranchLabel(branch.number)}${statusLabel}${accessibleVisitLabel}`)}"><span class="store-branch-button-title"><strong>${esc(storeBranchLabel(branch.number))}${statusLabel}</strong>${customerWaiting ? '<span class="store-visit-dot" role="img" aria-label="お客様が来店中" title="お客様が来店中"></span>' : ''}</span><small>Lv.${storeLevel(branch)}・評価 ${storeRating(branch)}/100・陳列 ${storeShowcaseUsedSlots(branch)}点</small></button>`;
          }).join('')}
        </div>
      </section>`, { help: '店舗1、店舗2、店舗3から、開く店舗を選択してください。' });
  }

  const branch = branches.find((entry) => entry.id === branchId) || branches[0];
  state.store.branchNumber = Math.max(1, Number(branch.number) || 1);
  mirrorCurrentStoreDisplay(branch);
  const displayName = storeBranchDisplayName(branch);
  const businessOpen = storeBusinessOpen();
  const activeVisitors = canServeCustomers() ? Object.keys(CUSTOMERS).filter((id) => state.customers[id].visiting && Number(state.customers[id].visitingBranchNumber || branch.number) === Number(branch.number)) : [];
  const isFirstBranch = Number(branch.number) === 1;
  const canExpand = isFirstBranch && expansionEligible();
  const displayInventory = state.store.displayInventory || {};
  const showcasesOwned = Math.max(0, Math.floor(Number(displayInventory.showcase) || 0));
  const displaySuppliesOwned = Math.max(0, Math.floor(Number(displayInventory.displaySupplies) || 0));
  const casesOwned = Math.max(0, Math.floor(Number(displayInventory.case) || 0));
  const casesRemaining = storeCaseRemaining(branch);
  const caseInstallMaximum = displayCaseInstallMaximum(branch);
  const caseInstallQuantity = displayCaseInstallQuantity(branch);
  const canInstallShowcase = showcasesOwned > 0 && installedShowcaseCount(branch) < storeMaximumShowcases(branch);
  const displaySuppliesMaximum = storeMaximumDisplaySupplies(branch);
  const canInstallDisplaySupplies = displaySuppliesOwned > 0 && storeDisplaySuppliesInstalled(branch) < displaySuppliesMaximum;
  const canInstallCase = casesOwned > 0 && casesRemaining < storeMaximumCases();
  const expansionConditions = isFirstBranch ? storeExpansionConditions(branch) : [];
  const levelStatus = storeUpgradeStatus(branch);
  return shell('店舗', `
    <div class="store-layout">
      <section class="store-scene"></section>
      <section class="store-panel glass-panel">
        ${activeVisitors.length ? `<section class="store-service-section store-service-section-top">
          <div class="section-heading"><h2>接客</h2></div>
          <section class="visitor-box"><h2>お客様が来店しています。</h2>${activeVisitors.map((id) => `<div><strong>${esc(CUSTOMERS[id].name)}</strong><button class="primary-button" data-action="customer" data-id="${id}">接客する</button><button class="text-button" data-action="ignore-customer" data-id="${id}">今回は対応しない</button></div>`).join('')}</section>
        </section>` : ''}
        <h1 class="store-name-title">${esc(displayName)}</h1>
        ${storeBranchOperating(branch) ? '' : `<section class="tool-break-alert"><strong>この店舗は休業中です</strong><span>未払い家賃 ${yen(branch.unpaidRent)}を収支画面から支払ってください。</span></section>`}
        ${storeBranchOperating(branch) && !businessOpen ? '<section class="tool-break-alert"><strong>本日の店舗営業は終了しました</strong><span>営業時間は9:00～19:00です。</span></section>' : ''}
        <div class="store-showcase-heading"><h2>ショーケース</h2><small>${installedShowcaseCount(branch)}/${storeMaximumShowcases(branch)}台・${storeShowcaseUsedSlots(branch)}/${storeShowcaseCapacity(branch)}点</small></div>
        ${installedShowcaseCount(branch) ? `<div class="showcase-units">${branchShowcases(branch).map((showcase, showcaseIndex) => renderShowcaseUnit(showcase, showcaseIndex, branch)).join('')}</div>` : '<section class="empty-state showcase-empty-state"><strong>ショーケースがありません。</strong><p>御徒町のディスプレイ屋でショーケースを購入し、下の「店頭設備」から設置してください。</p></section>'}
        <section class="store-install-section storefront-equipment-section">
          <div class="section-heading"><h2>店頭設備</h2><button class="secondary-button" data-action="nav" data-screen="displayShop">ディスプレイ屋へ</button></div>
          <article class="store-install-row store-case-install-row" data-store-case-install-card>
            <div class="store-install-info">
              ${renderDisplayProductVisual(DISPLAY_SHOP_PRODUCTS.case, 'display-product-visual-store')}
              <div><strong>ケース</strong><small class="store-case-remaining ${casesRemaining === 0 ? 'is-empty' : ''}">残数 ${casesRemaining}/${storeMaximumCases()}個</small></div>
            </div>
            <div class="store-case-install-controls">
              <span class="store-case-install-label">設置数</span>
              <span class="metal-vertical-stepper" aria-label="ケース設置数を増減">
                <button type="button" class="metal-stepper-button metal-stepper-up" data-action="store-case-install-qty-step" data-delta="1" aria-label="ケースを1個増やす。長押しで連続増加" ${canInstallCase && caseInstallQuantity < caseInstallMaximum ? '' : 'disabled'}>▲</button>
                <span class="metal-input-wrap"><output class="quantity-readout" data-store-case-install-quantity-value aria-live="polite" aria-label="ケースの設置数">${caseInstallQuantity}</output><b>個</b></span>
                <button type="button" class="metal-stepper-button metal-stepper-down" data-action="store-case-install-qty-step" data-delta="-1" aria-label="ケースを1個減らす。長押しで連続減少" ${canInstallCase && caseInstallQuantity > 0 ? '' : 'disabled'}>▼</button>
              </span>
              <button class="primary-button" data-action="install-display-product" data-id="case" ${canInstallCase && caseInstallQuantity > 0 ? '' : 'disabled'}>店頭に設置</button>
            </div>
          </article>
          <article class="store-install-row">
            <div class="store-install-info">
              ${renderDisplayProductVisual(DISPLAY_SHOP_PRODUCTS.showcase, 'display-product-visual-store')}
              <div><strong>ショーケース</strong><small>設置済み ${installedShowcaseCount(branch)}/${storeMaximumShowcases(branch)}台</small></div>
            </div>
            <button class="primary-button" data-action="install-display-product" data-id="showcase" ${canInstallShowcase ? '' : 'disabled'}>店頭に設置</button>
          </article>
          <article class="store-install-row">
            <div class="store-install-info">
              ${renderDisplayProductVisual(DISPLAY_SHOP_PRODUCTS.displaySupplies, 'display-product-visual-store')}
              <div><strong>ディスプレイ用品</strong><small>設置済み ${storeDisplaySuppliesInstalled(branch)}/${displaySuppliesMaximum}個</small></div>
            </div>
            <button class="primary-button" data-action="install-display-product" data-id="displaySupplies" ${canInstallDisplaySupplies ? '' : 'disabled'}>店頭に設置</button>
          </article>
          <p class="small-note">店舗設備は販売環境を整えます。店舗レベルは、店舗ごとの営業日数・販売数・売上・接客成功数と改装によって上がります。</p>
        </section>
        ${storeEmployeeAvailable(branch) ? '<div class="button-grid store-employee-link"><button class="secondary-button" data-action="nav" data-screen="employee">店舗スタッフ</button></div>' : ''}
        <section class="store-evaluation-section">
          <div class="section-heading"><h2>店舗レベル</h2></div>
          <div class="store-summary">
            <div><small>現在レベル</small><strong>Lv.${storeLevel(branch)}</strong></div>
            <div><small>過去最高</small><strong>Lv.${Math.max(storeLevel(branch), Number(branch.peakLevel) || 1)}</strong></div>
            <div><small>累計営業日</small><strong>${Math.max(0, Number(branch.operatingDays) || 0)}日</strong></div>
            <div><small>店舗評価</small><strong>${storeRating(branch)} / 100</strong></div>
            <div><small>累計販売</small><strong>${Math.max(0, Number(branch.salesCount) || 0)}点</strong></div>
            <div><small>累計売上</small><strong>${yen(Math.max(0, Number(branch.totalRevenue) || 0))}</strong></div>
            <div><small>接客成功</small><strong>${Math.max(0, Number(branch.serviceSuccesses) || 0)}件</strong></div>
          </div>
          ${levelStatus.requirement ? `<h3>Lv.${levelStatus.requirement.level}への改装条件</h3><ul class="condition-list">${levelStatus.conditions.map((condition) => `<li class="${condition.met ? 'condition-met' : 'condition-unmet'}"><strong>${condition.met ? '達成' : '未達成'}</strong><span>${esc(condition.label)}</span><em>${condition.money ? yen(condition.current) : Number(condition.current).toLocaleString('ja-JP')}／${condition.money ? yen(condition.target) : Number(condition.target).toLocaleString('ja-JP')}</em></li>`).join('')}</ul><p>改装費：${yen(levelStatus.cost)}</p><button class="primary-button full-button" data-action="upgrade-store-level" ${levelStatus.complete ? '' : 'disabled'}>店舗をLv.${levelStatus.requirement.level}へ改装</button>` : '<p class="success-text">店舗は最大レベルです。</p>'}
        </section>
        <div class="store-order-sheet-link">
          <button class="secondary-button" data-action="nav" data-screen="orders" ${activeOrderCount() > 0 ? '' : 'disabled'}>工房の注文書</button>
        </div>
        ${isFirstBranch ? `<section class="store-expansion-section">
          <div class="section-heading"><h2>拡大条件</h2></div>
          ${state.store.expanded ? '<p class="success-text">店舗の拡大は完了しています。</p><p>ショーケースを最大3台まで設置でき、店舗スタッフを1人雇えます。</p>' : `
            <ul class="condition-list">
              ${expansionConditions.map((condition) => `<li class="${condition.met ? 'condition-met' : 'condition-unmet'}"><strong>${condition.met ? '達成' : '未達成'}</strong><span>${esc(condition.label)}</span><em>${esc(condition.progress)}</em></li>`).join('')}
            </ul>
            <p>拡大費：${yen(STORE_EXPANSION_REQUIREMENTS.cost)}</p>
            ${canExpand ? '<p class="success-text">すべての拡大条件を満たしています。</p>' : ''}
            <button class="primary-button full-button" data-action="expand-store" ${canExpand ? '' : 'disabled'}>店舗を拡大する</button>
            <p class="small-note">条件を満たしても、拡大するかどうかは自由です。</p>`}
        </section>` : ''}
      </section>
    </div>`, { help: '現在の店舗と設備を確認できます。店舗1だけに拡大機能があり、店舗2と店舗3には拡大機能がありません。ショーケース1台には完成品を5個まで並べられます。ケース、ショーケース、ディスプレイ用品は店頭設備から設置でき、ケースは販売ごとに1個消費されます。' });
}

function renderShowcaseUnit(showcase, showcaseIndex, branch = currentStoreBranch()) {
  const slots = Array.from({ length: 5 }, (_, slotIndex) => showcase?.slots?.[slotIndex] || null);
  const used = slots.filter(Boolean).length;
  return `<section class="showcase-unit" data-showcase-index="${showcaseIndex}"><div class="showcase-unit-header"><h3>ショーケース ${showcaseIndex + 1}</h3><small>${used}/5点</small></div><div class="showcase-grid">${slots.map((slot, slotIndex) => renderShowcaseSlot(slot, showcaseIndex, slotIndex, branch)).join('')}</div></section>`;
}

function renderShowcaseSlot(slot, showcaseIndex, slotIndex, branch = currentStoreBranch()) {
  const emptyMarkup = `<article class="showcase-slot empty"><button type="button" class="showcase-empty-button" data-action="open-showcase-empty" data-branch="${esc(branch?.id || '')}" data-showcase="${showcaseIndex}" data-slot="${slotIndex}" aria-label="空き枠に陳列する商品を選ぶ"><span>空き</span><small>タップして商品を選ぶ</small></button></article>`;
  if (!slot) return emptyMarkup;
  const item = state.inventory.jewelry.find((entry) => entry.id === slot.jewelryId);
  if (!item) return emptyMarkup;
  const price = showcaseSellingPrice(slot, item);
  return `<article class="showcase-slot showcase-slot-summary">
    <button type="button" class="showcase-item-button" data-action="open-showcase-detail" data-branch="${esc(branch?.id || '')}" data-showcase="${showcaseIndex}" data-slot="${slotIndex}" aria-label="${esc(item.name)}の詳細を開く">
      <div class="small-jewelry metal-${item.metal} item-${item.item}" style="--gem:${GEMS[item.gem]?.hue || '#ffffff'}">${jewelryItemVisual(item.item, 'jewelry-item-shape small', item.useLoose !== false)}${item.useLoose !== false ? `<i>${jewelryLooseSetVisual(item.item, item.gem, item.looseShape, 'showcaseSmall')}</i>` : ''}</div>
      <strong>${esc(item.name)}</strong>
      <span class="showcase-summary-price">${yen(price)}</span>
    </button>
  </article>`;
}

function renderShowcaseSelection() {
  const branch = state.store.branches?.find((entry) => entry.id === screenData.branchId) || currentStoreBranch();
  const showcaseIndex = Math.max(0, Number(screenData.showcaseIndex) || 0);
  const slotIndex = Math.max(0, Number(screenData.slotIndex) || 0);
  const showcase = branchShowcases(branch)?.[showcaseIndex];
  const validSlot = Boolean(branch && showcase && Array.isArray(showcase.slots) && slotIndex < showcase.slots.length);
  const targetSlot = validSlot ? showcase.slots[slotIndex] : null;
  if (!validSlot || targetSlot) {
    return shell('陳列する商品を選ぶ', `<section class="center-card glass-panel"><div class="empty-state"><strong>この空き枠は利用できません。</strong><p>店舗のショーケースへ戻って、空いている枠を選び直してください。</p></div><button class="primary-button full-button" data-action="back">店舗へ戻る</button></section>`);
  }
  const items = state.inventory.jewelry.filter((item) => item.status === 'stored');
  const targetLabel = `${storeBranchLabel(branch.number)}・ショーケース ${showcaseIndex + 1}・空き枠 ${slotIndex + 1}`;
  const content = items.length
    ? `<div class="jewelry-grid showcase-selection-grid">${items.map((item) => `<article class="jewelry-card showcase-selection-card">
        <div class="small-jewelry metal-${item.metal} item-${item.item}" style="--gem:${GEMS[item.gem]?.hue || '#ffffff'}">${jewelryItemVisual(item.item, 'jewelry-item-shape small', item.useLoose !== false)}${item.useLoose !== false ? `<i>${jewelryLooseSetVisual(item.item, item.gem, item.looseShape, 'showcaseSmall')}</i>` : ''}</div>
        <div class="showcase-selection-copy"><h3>${esc(item.name)}</h3><p>原価 ${yen(item.cost)}</p><small>状態：${esc(finishedItemStatus(item))}</small></div>
        <button type="button" class="primary-button full-button" data-action="place-item-in-slot" data-id="${esc(item.id)}" data-branch="${esc(branch.id)}" data-showcase="${showcaseIndex}" data-slot="${slotIndex}">この商品を陳列する</button>
      </article>`).join('')}</div>`
    : '<div class="empty-state"><strong>陳列できる完成品はありません。</strong><p>工房で完成品を制作して保管すると、ここに表示されます。</p></div>';
  return shell('陳列する商品を選ぶ', `
    <section class="wide-panel glass-panel showcase-selection-panel">
      <div class="showcase-selection-target"><small>陳列先</small><strong>${esc(targetLabel)}</strong></div>
      ${content}
    </section>`, { help: '店舗の空きショーケース枠に陳列する、保管中の完成品を選びます。' });
}

function renderShowcaseItemDetail() {
  const branch = state.store.branches?.find((entry) => entry.id === screenData.branchId) || currentStoreBranch();
  const showcaseIndex = Math.max(0, Number(screenData.showcaseIndex) || 0);
  const slotIndex = Math.max(0, Number(screenData.slotIndex) || 0);
  const slot = branchShowcases(branch)?.[showcaseIndex]?.slots?.[slotIndex];
  const item = slot ? state.inventory.jewelry.find((entry) => entry.id === slot.jewelryId) : null;
  if (!branch || !slot || !item) {
    return shell('商品詳細', `<section class="center-card glass-panel"><div class="empty-state"><strong>商品が見つかりません。</strong><p>ショーケースへ戻って確認してください。</p></div><button class="primary-button full-button" data-action="back">店舗へ戻る</button></section>`);
  }
  const savedPrice = showcaseSellingPrice(slot, item);
  const price = normalizeSellingPrice(
    Number.isFinite(Number(screenData.pendingSellingPrice)) ? screenData.pendingSellingPrice : savedPrice,
    item.recommendedPrice || savedPrice
  );
  const priceChanged = price !== savedPrice;
  const priceStatus = sellingPriceStatus(item, price);
  const expectedProfit = price - Math.max(0, Number(item.cost) || 0);
  const looseLabel = item.useLoose === false ? 'ルースなし' : looseDisplayLabel(item.gem, item.looseShape);
  return shell('商品詳細', `
    <section class="showcase-detail-panel glass-panel">
      <div class="showcase-detail-visual jewelry-preview large completion-jewelry-preview metal-${item.metal} item-${item.item}" style="--gem:${GEMS[item.gem]?.hue || '#ffffff'}">
        <span class="completion-jewelry-artwork item-${item.item}">
          ${jewelryItemVisual(item.item, 'jewelry-item-shape large', item.useLoose !== false)}
          ${item.useLoose !== false ? `<span class="jewelry-preview-loose">${jewelryLooseSetVisual(item.item, item.gem, item.looseShape, 'completion')}</span>` : ''}
        </span>
      </div>
      <h1>${esc(item.name)}</h1>
      <dl class="showcase-detail-grid">
        <div><dt>商品種類</dt><dd>${esc(ITEMS[item.item]?.name || '')}</dd></div>
        <div><dt>地金</dt><dd>${esc(METALS[item.metal]?.name || '')}</dd></div>
        <div><dt>ルース</dt><dd>${esc(looseLabel)}</dd></div>
        <div><dt>品質</dt><dd>${esc(QUALITIES[item.quality]?.name || '')}</dd></div>
        <div><dt>原価</dt><dd>${yen(item.cost)}</dd></div>
        <div><dt>おすすめ価格</dt><dd>${yen(item.recommendedPrice)}</dd></div>
        <div><dt>予想利益</dt><dd data-showcase-expected-profit>${yen(expectedProfit)}</dd></div>
        <div><dt>価格判定</dt><dd class="price-status ${priceStatus.id}" data-showcase-price-status>${esc(priceStatus.name)}</dd></div>
      </dl>
      <div class="showcase-detail-price-field" aria-label="販売価格を1,000円単位で変更">
        <span>販売価格</span>
        <div class="showcase-price-stepper">
          <button type="button" class="showcase-price-step-button showcase-price-step-up" data-action="selling-price-step" data-delta="1" data-branch="${esc(branch.id)}" data-showcase="${showcaseIndex}" data-slot="${slotIndex}" aria-label="販売価格を1,000円上げる。長押しで連続増加">▲</button>
          <div class="showcase-price-value-row">
            <strong class="showcase-price-value" data-showcase-price-value>${yen(price)}</strong>
            <button type="button" class="primary-button showcase-price-confirm-button" data-action="selling-price-confirm" data-showcase-price-confirm data-branch="${esc(branch.id)}" data-showcase="${showcaseIndex}" data-slot="${slotIndex}" ${priceChanged ? '' : 'disabled'}>決定</button>
          </div>
          <button type="button" class="showcase-price-step-button showcase-price-step-down" data-action="selling-price-step" data-showcase-price-down data-delta="-1" data-branch="${esc(branch.id)}" data-showcase="${showcaseIndex}" data-slot="${slotIndex}" aria-label="販売価格を1,000円下げる。長押しで連続減少" ${price <= 1000 ? 'disabled' : ''}>▼</button>
        </div>
        <small class="showcase-price-step-note">▲▼で価格を調整（長押しで連続変更）し、決定ボタンで反映</small>
      </div>
      <div class="showcase-detail-actions">
        <button class="text-button" data-action="remove-showcase" data-branch="${esc(branch.id)}" data-showcase="${showcaseIndex}" data-slot="${slotIndex}">この商品の陳列をやめる</button>
        ${contractedStoreBranches().length > 1 ? `<button class="secondary-button" data-action="move-showcase-item" data-id="${item.id}">別店舗へ移動</button>` : ''}
      </div>
    </section>`, { help: '商品の詳細を確認し、▲▼で販売価格を1,000円ずつ調整します。▲▼は長押しで連続変更でき、決定ボタンで反映します。' });
}

function updateShowcaseDetailPricePreview(price, savedPrice, item) {
  if (screen !== 'showcaseDetail' || !item) return false;
  const panel = root.querySelector('.showcase-detail-panel');
  if (!panel) return false;
  const normalizedPrice = normalizeSellingPrice(price, item.recommendedPrice || savedPrice || 1000);
  const normalizedSavedPrice = normalizeSellingPrice(savedPrice, item.recommendedPrice || normalizedPrice);
  const priceStatus = sellingPriceStatus(item, normalizedPrice);
  const expectedProfit = normalizedPrice - Math.max(0, Number(item.cost) || 0);
  const priceValue = panel.querySelector('[data-showcase-price-value]');
  const expectedProfitValue = panel.querySelector('[data-showcase-expected-profit]');
  const priceStatusValue = panel.querySelector('[data-showcase-price-status]');
  const confirmButton = panel.querySelector('[data-showcase-price-confirm]');
  const downButton = panel.querySelector('[data-showcase-price-down]');
  if (priceValue) priceValue.textContent = yen(normalizedPrice);
  if (expectedProfitValue) expectedProfitValue.textContent = yen(expectedProfit);
  if (priceStatusValue) {
    priceStatusValue.textContent = priceStatus.name;
    priceStatusValue.className = `price-status ${priceStatus.id}`;
  }
  if (confirmButton instanceof HTMLButtonElement) confirmButton.disabled = normalizedPrice === normalizedSavedPrice;
  if (downButton instanceof HTMLButtonElement) downButton.disabled = normalizedPrice <= 1000;
  return Boolean(priceValue && expectedProfitValue && priceStatusValue && confirmButton && downButton);
}

function adjustShowcaseSellingPrice(button) {
  if (!button || button.disabled || screen !== 'showcaseDetail') return false;
  const branch = button.dataset.branch
    ? state.store.branches?.find((entry) => entry.id === button.dataset.branch)
    : currentStoreBranch();
  const showcaseIndex = Number(button.dataset.showcase);
  const slotIndex = Number(button.dataset.slot);
  const slot = branchShowcases(branch)?.[showcaseIndex]?.slots?.[slotIndex];
  if (!slot) return false;
  const item = state.inventory.jewelry.find((entry) => entry.id === slot.jewelryId);
  if (!item) return false;
  const savedPrice = showcaseSellingPrice(slot, item);
  const currentPrice = normalizeSellingPrice(
    Number.isFinite(Number(screenData.pendingSellingPrice)) ? screenData.pendingSellingPrice : savedPrice,
    item.recommendedPrice || savedPrice
  );
  const delta = Number(button.dataset.delta) < 0 ? -1000 : 1000;
  const nextPrice = Math.max(1000, currentPrice + delta);
  if (nextPrice === currentPrice) return false;
  screenData.pendingSellingPrice = normalizeSellingPrice(nextPrice, item.recommendedPrice || 1000);
  if (!updateShowcaseDetailPricePreview(screenData.pendingSellingPrice, savedPrice, item)) render();
  return true;
}

function clearSellingPriceHold() {
  if (sellingPriceHoldTimeout) window.clearTimeout(sellingPriceHoldTimeout);
  if (sellingPriceHoldInterval) window.clearInterval(sellingPriceHoldInterval);
  sellingPriceHoldTimeout = null;
  sellingPriceHoldInterval = null;
  sellingPriceHoldButton?.classList.remove('is-holding');
  sellingPriceHoldButton = null;
}

function startSellingPriceHold(button) {
  clearSellingPriceHold();
  if (!button || button.disabled || screen !== 'showcaseDetail') return;
  sellingPriceHoldButton = button;
  sellingPriceHoldTriggered = false;
  button.classList.add('is-holding');
  sellingPriceHoldTimeout = window.setTimeout(() => {
    if (sellingPriceHoldButton !== button || button.disabled || screen !== 'showcaseDetail') {
      clearSellingPriceHold();
      return;
    }
    sellingPriceHoldTriggered = true;
    adjustShowcaseSellingPrice(button);
    sellingPriceHoldInterval = window.setInterval(() => {
      if (sellingPriceHoldButton !== button || button.disabled || screen !== 'showcaseDetail') {
        clearSellingPriceHold();
        return;
      }
      adjustShowcaseSellingPrice(button);
    }, 110);
  }, 420);
}

function finishSellingPriceHold(button) {
  const held = sellingPriceHoldButton === button && sellingPriceHoldTriggered;
  clearSellingPriceHold();
  sellingPriceHoldTriggered = false;
  if (held && button) button.dataset.skipNextClick = 'true';
}

function customerPreferenceLabel(request) {
  const preference = request?.preference || { type: 'gem', value: request?.gem };
  if (preference.label) return String(preference.label);
  if (preference.type === 'metal') return METALS[preference.value]?.name || '地金指定';
  if (preference.type === 'design') return DESIGNS[preference.value]?.name || 'デザイン指定';
  if (preference.type === 'color') return String(preference.value || '色指定');
  return GEMS[preference.value]?.name || '石指定';
}

function customerPreferenceMatches(item, request) {
  const preference = request?.preference || { type: 'gem', value: request?.gem };
  if (preference.type === 'metal') return item.metal === preference.value;
  if (preference.type === 'design') return item.design === preference.value;
  if (item.useLoose === false) return false;
  if (preference.type === 'color') {
    const acceptedGems = Array.isArray(preference.gems) ? preference.gems : [];
    return acceptedGems.includes(item.gem);
  }
  return item.gem === preference.value;
}

function customerMatchResult(item, request, branchNumber = state?.store?.branchNumber || 1) {
  const price = sellingPriceForJewelry(item);
  const budget = Math.max(1000, Number(request?.budget) || 1000);
  const matches = Number(item.item === request?.item)
    + Number(price <= budget)
    + Number(customerPreferenceMatches(item, request));
  const farOverBudget = price > budget * 1.25;
  const labels = ['ほとんど売れない', '売れにくい', '購入の可能性あり', 'かなり売れやすい'];
  const chances = [0.05, 0.20, 0.55, 0.90];
  const salesStaff = activeStoreStaff(branchNumber);
  // v0.10.628: 店舗スタッフの有無を接客購入率へ大きく反映する。
  // 無人時は接客力不足で-10pt、配置中は基礎+10ptにスタッフLvの購入率ボーナスを加える。
  const staffingPurchaseModifier = salesStaff
    ? 0.10 + storeStaffPurchaseBonus(branchNumber)
    : -0.10;
  const baseChance = chances[matches] + storeProductSaleBonus(item, branchNumber) + staffingPurchaseModifier;
  return {
    matches,
    price,
    farOverBudget,
    label: farOverBudget ? '予算を大きく超えている' : labels[matches],
    chance: farOverBudget ? 0 : clamp(baseChance, 0.02, 0.95),
  };
}

function renderCustomer() {
  if (!state.store.rented) return shell('お客様', '<div class="empty-state"><strong>店舗を借りてから接客できます。</strong><p>御徒町の不動産屋で契約してください。</p><button class="primary-button" data-action="nav" data-screen="okachimachi">御徒町へ</button></div>');
  if (!storeBusinessOpen()) return shell('お客様', '<div class="empty-state"><strong>店舗の営業時間外です。</strong><p>接客と注文受付は9:00～19:00です。</p><button class="primary-button" data-action="nav" data-screen="store">店舗へ戻る</button></div>');
  const customerId = screenData.customerId;
  if (!hasCraftedJewelry() && customerId !== 'brownBunny') return shell('お客様', '<div class="empty-state"><strong>まだ接客できません。</strong><p>工房でジュエリーを1点制作すると接客が解放されます。</p><button class="primary-button" data-action="nav" data-screen="workshop">工房へ</button></div>');
  const customer = CUSTOMERS[customerId];
  const customerState = state.customers[customerId];
  if (!customer || !customerState?.visiting) return shell('お客様', '<div class="empty-state"><strong>現在、接客中のお客様はいません。</strong></div>');
  if (Number(customerState.visitingBranchNumber || state.store.branchNumber) !== Number(state.store.branchNumber)) return shell('お客様', '<div class="empty-state"><strong>このお客様は別の店舗へ来店しています。</strong><p>来店中の店舗を開いて接客してください。</p><button class="primary-button" data-action="nav" data-screen="store">店舗一覧へ</button></div>');
  const request = activeCustomerRequest(customerId);
  const proposedIds = Array.isArray(customerState.proposedItemIds) ? customerState.proposedItemIds : [];
  const displayedCandidates = state.inventory.jewelry
    .filter((item) => item.status === 'displayed' && showcaseSlotForJewelry(item.id, storeBranchByNumber(customerState.visitingBranchNumber)))
    .map((item) => ({ item, result: customerMatchResult(item, request, customerState.visitingBranchNumber) }))
    .sort((a, b) => b.result.matches - a.result.matches || Math.abs(a.result.price - request.budget) - Math.abs(b.result.price - request.budget));
  const candidates = displayedCandidates
    .filter(({ result }) => result.matches >= 2 && !result.farOverBudget)
    .sort((a, b) => Number(proposedIds.includes(a.item.id)) - Number(proposedIds.includes(b.item.id)));
  const activeOrders = activeOrderCount();
  const activeOrderLimit = orderLimit();
  const proposalMinutes = customerProposalMinutes();
  const salesStaff = activeStoreStaff(customerState.visitingBranchNumber);
  const canAcceptThisOrder = customerState.wishesHeard && activeOrders < activeOrderLimit && canSpendStoreMinutes(30);
  const canProposeProduct = customerState.wishesHeard && proposedIds.length < 2 && candidates.some(({ item }) => !proposedIds.includes(item.id)) && canSpendStoreMinutes(proposalMinutes);
  const playerGreeting = state.playerName ? `${state.playerName}さん、こんにちは。` : '';
  const storeGreeting = state.store.name
    ? customerState.met
      ? `また${storeDisplayName()}に伺いました。`
      : `${storeDisplayName()}で相談できると聞いて来ました。`
    : '';
  const customerProfile = customerProfileData(customerId, request);
  const customerOpening = `${playerGreeting}${storeGreeting}${customerProfile.opening}`;
  const showingProducts = customerState.wishesHeard && screenData.view === 'products';
  const requestDetails = customerState.wishesHeard ? `
    <article class="request-card customer-wish-card">
      <small>お客様の希望</small>
      <dl class="customer-wish-list">
        <div><dt>商品種類</dt><dd>${esc(ITEMS[request.item]?.name || '指定なし')}</dd></div>
        <div><dt>予算</dt><dd>${yen(request.budget)}</dd></div>
        <div><dt>優先する希望</dt><dd>${esc(customerPreferenceLabel(request))}</dd></div>
      </dl>
    </article>` : '<p class="small-note">まず希望を聞くと、商品種類・予算・最優先の希望が分かります。</p>';
  const productList = showingProducts ? `
    <section class="customer-product-proposal">
      <div class="customer-proposal-heading"><h2>店頭商品を提案</h2><span>提案 ${proposedIds.length}／2点</span></div>
      ${candidates.length ? `<div class="candidate-list">${candidates.map(({ item, result }) => {
        const proposed = proposedIds.includes(item.id);
        return `<article class="${proposed ? 'already-proposed' : ''}"><div><strong>${esc(item.name)}</strong><small>販売価格 ${yen(result.price)}・${esc(result.label)}</small></div><button class="primary-button" data-action="customer-buy" data-customer="${customerId}" data-id="${item.id}" ${proposed || proposedIds.length >= 2 ? 'disabled' : ''}>${proposed ? '提案済み' : '提案する'}</button></article>`;
      }).join('')}</div>` : `<p class="small-note">${displayedCandidates.length ? 'お客様の希望に合う店頭商品がありません。' : '現在の店舗に陳列中の商品がありません。'}</p>`}
    </section>` : '';
  return shell(customer.name, `
    ${showingProducts ? productList : ''}
    <div class="customer-layout ${showingProducts ? 'customer-products-open' : ''}">
      <section class="customer-stage"><div class="customer-placeholder"><span>人物画像</span><small>後から透過画像を重ねられます</small></div></section>
      <section class="dialog-panel glass-panel">
        ${customerProfileCardMarkup(customerProfile)}
        <p class="dialog-text">${esc(customerOpening)}</p>
        ${requestDetails}
        <div class="customer-service-choices">
          <button class="primary-button" data-action="hear-customer-wishes" data-customer="${customerId}" ${customerState.wishesHeard ? 'disabled' : ''}>${customerState.wishesHeard ? '希望を確認済み' : '希望を聞く'}</button>
          <button class="secondary-button" data-action="open-customer-products" data-customer="${customerId}" ${canProposeProduct ? '' : 'disabled'}>店頭商品を提案</button>
          <button class="text-button" data-action="ignore-customer" data-id="${customerId}">注文を受けない</button>
          <button class="secondary-button" data-action="accept-order" data-customer="${customerId}" ${canAcceptThisOrder ? '' : 'disabled'}>オーダー制作で受け付ける</button>
        </div>
        ${salesStaff
          ? `<p class="success-text">店舗スタッフ効果：接客購入率＋${10 + Math.round(storeStaffPurchaseBonus(customerState.visitingBranchNumber) * 100)}ポイント</p>`
          : '<p class="small-note">店舗スタッフ不在：接客購入率が10ポイント下がります。</p>'}
        ${customerState.wishesHeard && proposedIds.length >= 2 ? '<p class="small-note">店頭商品の提案は2点までです。</p>' : ''}
        ${customerState.wishesHeard && activeOrders >= activeOrderLimit ? `<p class="error-text">職人レベルにより、同時に受けられる注文は${activeOrderLimit}件までです。</p>` : ''}
        ${customerState.wishesHeard && !canSpendStoreMinutes(30) ? '<p class="small-note">本日の接客・注文受付を完了できる時間が残っていません。</p>' : ''}
      </section>
    </div>`, { help: '希望を聞き、条件に合う店頭商品がある場合だけ最大2点まで提案できます。該当商品がない場合は店頭商品を提案できません。オーダー制作で受け付けるか、注文を受けないこともできます。購入判定は商品種類・予算・優先する希望の3項目で行います。' });
}

function orderCustomerProfile(customerId, order = null) {
  const request = order && typeof order === 'object' ? order : activeCustomerRequest(customerId);
  const profile = customerProfileData(customerId, request, order);
  return {
    ...profile,
    profile: profile.summary,
  };
}

function renderOrders() {
  const active = state.orders.filter((order) => !orderClosed(order));
  const completed = state.orders
    .map((order, index) => ({ order, index }))
    .filter(({ order }) => orderClosed(order))
    .sort((a, b) => orderClosedSortValue(b.order, b.index) - orderClosedSortValue(a.order, a.index))
    .map(({ order }) => order);
  const rows = active.map((order) => {
    const customer = CUSTOMERS[order.customerId];
    const customerProfile = orderCustomerProfile(order.customerId, order);
    const requirements = orderRequirements(order);
    const feasibility = orderFeasibility(order);
    const difficulty = orderDifficulty(order);
    const remaining = order.deadlineDay - state.game.day;
    const deadlineText = `${gameDateLabel(order.deadlineDay)}（${remaining === 0 ? '本日' : `あと${Math.max(0, remaining)}日`}）`;
    const isCrafted = order.status === '完成';
    const deliveryBranch = storeBranchByNumber(order.branchNumber);
    const deliveryOpen = storeDeliveryOpen();
    const deliveryBranchOperating = storeBranchOperating(deliveryBranch);
    const deadlinePassed = state.game.day > Number(order.deadlineDay);
    const canDeliverNow = isCrafted && deliveryOpen && deliveryBranchOperating && !deadlinePassed;
    const unpaidStoreRent = Math.max(0, Number(deliveryBranch?.unpaidRent) || 0);
    let deliveryBlockedReason = '';
    let deliveryButtonLabel = '納品する';
    if (isCrafted && !canDeliverNow) {
      if (!deliveryBranch) {
        deliveryBlockedReason = '注文を受けた店舗が見つからないため納品できません。';
        deliveryButtonLabel = '店舗を確認できません';
      } else if (!deliveryBranchOperating) {
        deliveryBlockedReason = unpaidStoreRent > 0
          ? `注文を受けた${storeBranchDisplayName(deliveryBranch)}は、未払い家賃${yen(unpaidStoreRent)}のため休業中です。スマートフォンの収支画面から未払いを支払うと納品できます。`
          : `注文を受けた${storeBranchDisplayName(deliveryBranch)}が休業中のため納品できません。`;
        deliveryButtonLabel = '店舗休業中';
      } else if (!deliveryOpen) {
        deliveryBlockedReason = '注文品を納品できる時間は9:00～19:00です。';
        deliveryButtonLabel = '店舗営業時間外';
      } else if (deadlinePassed) {
        deliveryBlockedReason = '納期を過ぎているため、この注文は納品できません。';
        deliveryButtonLabel = '納期超過';
      }
    }
    const materialsReady = requirements.enoughMetal && requirements.enoughLoose;
    const craftReady = order.status === '受注' && materialsReady && feasibility.artisanReady && feasibility.equipmentReady;
    const missingRows = [];
    if (!requirements.enoughMetal) missingRows.push(`${METALS[order.metal].name} ${requirements.missingMetalWeight}g`);
    if (!requirements.enoughLoose) missingRows.push(`${looseDisplayLabel(order.gem, order.looseShape, { suffix: true })} ${requirements.missingLooseQuantity}個`);
    if (!feasibility.artisanReady) missingRows.push(`職人Lv.${feasibility.requiredArtisanLevel}`);
    if (!feasibility.equipmentReady) missingRows.push(...feasibility.requiredTools.filter((toolId) => !toolUsable(toolId)).map((toolId) => WORKSHOP_TOOLS[toolId]?.name || toolId));
    const orderContent = `${looseDisplayLabel(order.gem, order.looseShape)}を使った${DESIGNS[order.design]?.name || ''}${ITEMS[order.item].name}`;
    const image = customer?.image || './assets/images/customers/customer-placeholder.svg';
    const estimatedCost = Math.max(0, Number(order.estimatedCost) || 0);
    const estimatedProfit = Number.isFinite(Number(order.estimatedProfit)) ? Number(order.estimatedProfit) : Number(order.price) - estimatedCost;
    return `<article class="order-sheet">
      <header class="order-sheet-header">
        <div class="order-customer-image"><img src="${esc(image)}?v=${VERSION}" alt="${esc(order.customerName)}さん"></div>
        <div class="order-customer-summary">
          <small>注文者</small>
          <div class="order-customer-name-profile">
            <div class="order-customer-name-line"><h2>${esc(order.customerName)}</h2><span class="order-customer-relation">${esc(customerProfile.relation)}</span></div>
            <div class="order-customer-profile-inline">
              <span class="wide"><b>概要</b>${esc(customerProfile.profile)}</span>
              <span><b>年代・職業</b>${esc(`${customerProfile.ageGroup}・${customerProfile.occupation}`)}</span>
              <span><b>使用者</b>${esc(customerProfile.wearer)}</span>
              <span class="wide"><b>来店目的</b>${esc(customerProfile.purpose)}</span>
              <span><b>着用場面</b>${esc(customerProfile.wearingScene)}</span>
              <span class="wide"><b>好み</b>${esc(customerProfile.preference)}</span>
              <span class="wide"><b>予算の考え方</b>${esc(customerProfile.budgetStyle)}</span>
              <span class="wide"><b>接客傾向</b>${esc(customerProfile.traits)}</span>
            </div>
          </div>
          <span class="order-progress-badge">${esc(orderDisplayStatus(order))}</span>
        </div>
      </header>
      <dl class="order-detail-grid">
        <div class="wide"><dt>注文内容</dt><dd>${esc(orderContent)}</dd></div>
        <div><dt>商品種類</dt><dd>${esc(ITEMS[order.item].name)}</dd></div>
        <div><dt>石</dt><dd>${esc(looseDisplayLabel(order.gem, order.looseShape))}</dd></div>
        <div><dt>地金</dt><dd>${esc(METALS[order.metal].name)}</dd></div>
        <div><dt>デザイン</dt><dd>${esc(DESIGNS[order.design]?.name || '指定なし')}</dd></div>
        <div><dt>難易度</dt><dd>${esc(difficulty.label)}・職人Lv.${feasibility.requiredArtisanLevel}</dd></div>
        <div><dt>受注金額</dt><dd>${yen(order.price)}</dd></div>
        <div><dt>予想原価</dt><dd>${yen(estimatedCost)}</dd></div>
        <div><dt>予想利益</dt><dd>${yen(estimatedProfit)}</dd></div>
        <div><dt>納期</dt><dd>${esc(deadlineText)}</dd></div>
        <div class="wide"><dt>希望条件</dt><dd>${esc(order.desiredConditions || customer?.preferenceText || '指定なし')}</dd></div>
      </dl>
      <section class="order-material-section">
        <h3>${isCrafted ? '使用した材料' : '必要材料'}</h3>
        <div class="order-material-table" role="table" aria-label="${isCrafted ? '注文品の製作に使用した材料' : '注文に必要な材料'}">
          <div class="order-material-row heading" role="row"><span>材料</span><span>必要量</span><span>${isCrafted ? '状態' : '所持している数量'}</span></div>
          <div class="order-material-row" role="row"><strong>${esc(METALS[order.metal].name)}</strong><span>${requirements.requiredMetalWeight}g</span><span>${isCrafted ? '製作時に使用済み' : `${metalWeightLabel(requirements.ownedMetalWeight)}g`}</span></div>
          <div class="order-material-row" role="row"><strong>${esc(looseDisplayLabel(order.gem, order.looseShape))}</strong><span>${requirements.requiredLooseQuantity}個</span><span>${isCrafted ? '製作時に使用済み' : `${requirements.availableLooseQuantity}個`}</span></div>
        </div>
      </section>
      <section class="order-shortage ${isCrafted || (materialsReady && feasibility.artisanReady && feasibility.equipmentReady) ? 'ready' : 'missing'}">
        <strong>${isCrafted || materialsReady ? '製作判定' : '不足している材料'}</strong>
        ${isCrafted
          ? `<p>${deadlinePassed ? '制作済みですが、納期を過ぎています。' : '制作済みです。納期内に納品できます。'}</p>`
          : craftReady ? '<p>製作可能です。</p>' : `<ul>${missingRows.map((row) => `<li>${esc(row)}</li>`).join('')}</ul>`}
      </section>
      ${!isCrafted && !materialsReady ? '<div class="order-material-navigation"><button type="button" class="secondary-button full-button" data-action="nav" data-screen="okachimachi">御徒町へ行く</button></div>' : ''}
      <div class="order-sheet-actions">
        ${order.status === '受注' ? `<button class="primary-button full-button order-craft-button" data-action="craft-order" data-id="${order.id}" ${craftReady ? '' : 'disabled'}><strong>このジュエリーを制作する</strong></button>` : ''}
        ${order.status === '完成' ? `<button class="primary-button full-button" data-action="deliver-order" data-id="${order.id}" ${canDeliverNow ? '' : 'disabled'}>${esc(deliveryButtonLabel)}</button>${deliveryBlockedReason ? `<p class="error-text order-delivery-blocked-reason">${esc(deliveryBlockedReason)}</p>` : ''}` : ''}
        ${['受注', '完成'].includes(order.status) ? `<button class="text-button full-button" data-action="confirm-cancel-order" data-id="${order.id}">注文をキャンセル</button>` : ''}
      </div>
    </article>`;
  }).join('');

  return shell('注文書', `
    <section class="wide-panel glass-panel order-sheet-panel">
      <div class="order-limit-summary"><span>同時受注</span><strong>${active.length}／${orderLimit()}件</strong><small>職人レベル帯に応じた件数まで</small></div>
      ${storeDeliveryOpen() ? '' : '<p class="small-note">注文書の確認と制作は可能ですが、注文品の納品は店舗営業時間の9:00～19:00に行ってください。</p>'}
      ${rows || '<div class="empty-state"><strong>現在の注文はありません。</strong><p>注文を受けると、工房の注文書から内容と必要材料を確認できます。</p><button class="secondary-button" data-action="nav" data-screen="workshop">工房へ戻る</button></div>'}
      ${completed.length ? `<details class="completed-order-history"><summary>納品済・期限切れ・取消の注文</summary><div class="history-list">${completed.map((order) => {
        const historyStatus = orderHistoryStatus(order);
        return `<p>${esc(order.customerName)}：${esc(looseDisplayLabel(order.gem, order.looseShape))}${esc(ITEMS[order.item].name)} <strong class="order-history-status ${historyStatus.className}">${esc(historyStatus.label)}</strong></p>`;
      }).join('')}</div></details>` : ''}
    </section>`, { help: '受注金額、予想原価・利益、納期、必要職人レベル、必要設備、材料の所持状況を確認できます。同時受注数は職人レベル帯に応じて1～6件です。' });
}

function renderEmployee() {
  if (!state.store.rented) return shell('店舗スタッフ', '<div class="empty-state"><strong>店舗を借りてから利用できます。</strong></div>');
  const branch = currentStoreBranch();
  if (!branch) return shell('店舗スタッフ', '<div class="empty-state"><strong>対象の店舗が見つかりません。</strong></div>');
  if (!storeEmployeeAvailable(branch)) return shell('店舗スタッフ', '<div class="empty-state"><strong>店舗1は店舗拡大後に店舗スタッフを雇えます。</strong></div>');
  const employee = storeBranchEmployee(branch);
  const branchName = storeBranchDisplayName(branch);
  const definition = storeStaffDefinition(employee);
  const nextDefinition = storeStaffNextDefinition(employee);
  const workDays = Math.max(0, Math.floor(Number(employee.workDays) || 0));
  const currentEffect = storeStaffSalesDescription(employee);
  const wageUnpaid = Math.max(0, Number(employee.wageUnpaid) || 0);
  const dailyWage = Math.max(0, Math.floor(Number(definition.dailyWage) || 5000));
  const growthText = nextDefinition
    ? `次の成長まであと${Math.max(0, Number(nextDefinition.minWorkDays) - workDays)}実働制作日`
    : '最高レベルまで成長しています';
  return shell('店舗スタッフ', `
    <section class="center-card glass-panel employee-card">
      <p class="employee-branch-name">${esc(branchName)}</p>
      ${employee.hired ? `
        <h1>${esc(employee.name)}</h1>
        <p class="success-text">販売力 Lv.${definition.level}（${esc(definition.label)}）</p>
        <p>${esc(STORE_EMPLOYEE_CANDIDATES[branch.number]?.profile || `${branchName}専属の店舗スタッフです。`)}</p>
        <article class="candidate-card"><strong>勤務日数 ${workDays}日</strong><p>${esc(growthText)}</p><strong>現在の効果</strong><p>${esc(currentEffect)}</p><strong>現在の日当 ${yen(dailyWage)}</strong></article>
        ${wageUnpaid ? `<section class="tool-break-alert"><strong>給与未払いのため出勤停止中です</strong><span>未払い ${yen(wageUnpaid)}をスマートフォンの収支画面から支払ってください。</span></section>` : ''}
        <p>店舗に配置して実際に営業した日は、1日の終わりに現在レベルの日当を支払います。</p>
        <label class="toggle-row"><span>店舗に配置する</span><input type="checkbox" data-action="employee-working" ${employee.working ? 'checked' : ''} ${wageUnpaid ? 'disabled' : ''}></label>` : `
        <h1>店舗スタッフを1人雇えます。</h1>
        <article class="candidate-card"><h2>${esc(employee.name)}</h2><p>${esc(STORE_EMPLOYEE_CANDIDATES[branch.number]?.profile || `${branchName}専属の店舗スタッフです。`)}</p><p class="success-text">販売力 Lv.1（見習い）</p><p>${esc(currentEffect)}</p><small>配置して働いた日数に応じて成長します。初日当：${yen(STORE_STAFF_GROWTH_LEVELS[0].dailyWage)}</small></article>
        <button class="primary-button full-button" data-action="hire-employee">雇う</button>`}
    </section>`, { help: '店舗スタッフは店舗ごとに1人雇えます。スタッフ不在でも営業できますが、ショーケース販売・来店人数・通常客の来店・接客購入率が大きく下がります。配置中は販売力が大幅に上がり、働いた日数による成長でさらに強化されます。' });
}

function renderMeal() {
  const current = hungerLevel();
  const eating = Boolean(screenData?.eating && MEALS[screenData?.mealId]);
  if (eating) {
    const meal = MEALS[screenData.mealId];
    const foodImage = mealFoodImage(meal.id);
    return shell('食事', `
      <button type="button" class="meal-eating-panel meal-eating-panel-${esc(meal.id)} meal-eating-finish-button glass-panel" data-action="meal-eating-finish" aria-label="食事を終えてメイン画面へ戻る" aria-live="polite">
        ${foodImage ? `<figure class="meal-food-display meal-food-display-${esc(meal.id)}"><img src="${foodImage}" alt="${esc(meal.name)}の料理" loading="eager" decoding="sync" fetchpriority="high"></figure>` : `<div class="meal-steam" aria-hidden="true"><i></i><i></i><i></i></div>`}
        <strong>もぐもぐもぐ...</strong>
      </button>`, {
        help: `${meal.name}で食事をしています。画面をタップすると食事を終え、操作しなくても自動でメイン画面へ戻ります。`,
        shellClass: 'meal-eating-shell',
        contentClass: 'meal-eating-screen-content',
      });
  }
  return shell('食事', `
    <section class="meal-choice-panel glass-panel">
      <div class="meal-hunger-summary">
        <div class="meal-current-hunger"><small>現在の空腹度</small><strong>${current}／7</strong></div>
      </div>
      <div class="meal-choice-grid">
        ${Object.values(MEALS).sort((a, b) => a.price - b.price || a.name.localeCompare(b.name, 'ja')).map((meal) => {
          const fullRecovery = meal.recovery >= 7;
          const disabled = state.game.money < meal.price || current >= 7;
          return `<button class="meal-choice-card meal-choice-card-${esc(meal.id)}" data-action="eat-meal" data-id="${meal.id}" ${disabled ? 'disabled' : ''}>
            <strong>${esc(meal.name)}</strong>
            <span>${yen(meal.price)}</span>
            <small>${fullRecovery ? '空腹度を全回復' : `空腹度を${meal.recovery}回復`}</small>
          </button>`;
        }).join('')}
        <button class="meal-choice-card meal-choice-card-kaitenzushi" type="button" data-action="play-kaitenzushi" ${current >= 7 || state.game.money < 190 ? 'disabled' : ''}>
          <strong>回転寿司</strong>
          <small>皿1枚につき空腹度を1回復</small>
        </button>
      </div>
      ${current >= 7 ? '<p class="meal-note">空腹度は満タンです。</p>' : '<p class="meal-note">店を選ぶと店内へ移動し、食事をします。食事には1時間かかります。</p>'}
    </section>`, { help: '食事で空腹度を回復できます。空腹度は最大7で、行動に使った時間に応じて減少します。' });
}

function kaitenzushiAudioParameters() {
  const settings = state?.settings || {};
  return new URLSearchParams({
    embedded: '1',
    budget: String(Math.max(0, Math.floor(Number(kaitenzushiSession?.budget ?? state?.game?.money) || 0))),
    free: kaitenzushiSession?.free ? '1' : '0',
    // BGMと環境音は親ゲーム側で管理し、iframe側は効果音だけを担当する。
    bgmVolume: '0',
    sfxVolume: String(Math.max(0, Math.min(1, Number(settings.sfxVolume) || 0))),
    ambientVolume: '0',
    bgmMuted: '1',
    sfxMuted: settings.sfxMuted ? '1' : '0',
    ambientMuted: '1',
    externalAudioPriority: '0',
  });
}

function clearKaitenzushiLoadWatch() {
  if (kaitenzushiReadyTimer) clearTimeout(kaitenzushiReadyTimer);
  kaitenzushiReadyTimer = null;
}

function kaitenzushiFrameSource() {
  const hash = kaitenzushiAudioParameters().toString();
  const query = new URLSearchParams({ v: VERSION, attempt: String(kaitenzushiLoadNonce) }).toString();
  return `./assets/minigames/kaitenzushi/game/index.html?${query}#${hash}`;
}

function kaitenzushiEmbeddedDocument() {
  const config = kaitenzushiAudioParameters().toString()
    .replaceAll('&', '&amp;')
    .replaceAll('"', '&quot;')
    .replaceAll('<', '&lt;')
    .replaceAll('>', '&gt;');
  return kaitenzushiEmbeddedHtml
    .replace('__JXJ_CONFIG__', config)
    .replace('__JXJ_ATTEMPT__', String(kaitenzushiLoadNonce));
}

function renderKaitenzushi() {
  if (!kaitenzushiEmbeddedHtml) {
    void ensureKaitenzushiModuleLoaded()
      .then(() => { if (screen === 'kaitenzushi') render(); })
      .catch((error) => {
        console.error('回転寿司データ読み込みエラー', error);
        if (screen === 'kaitenzushi') showKaitenzushiLoadError('回転寿司データを読み込めませんでした。');
      });
    return `<main class="kaitenzushi-game-screen" aria-label="回転寿司ミニゲーム"><button type="button" class="kaitenzushi-parent-finish-button" data-action="cancel-kaitenzushi">食事選択へ戻る</button><section class="kaitenzushi-load-error" role="status"><strong>回転寿司を準備しています</strong><p>初回だけミニゲームデータを読み込みます。</p></section></main>`;
  }
  if (!kaitenzushiSession) {
    const sushiEvent = sushiChefEventState();
    const free = Boolean(sushiEvent.active && sushiEvent.stage === 'playing');
    kaitenzushiSession = {
      budget: free ? Number.MAX_SAFE_INTEGER : Math.max(0, Math.floor(Number(state?.game?.money) || 0)),
      total: 0,
      plates: 0,
      settled: false,
      free,
      ready: false,
      loadError: false,
    };
  }
  return `<main class="kaitenzushi-game-screen" aria-label="回転寿司ミニゲーム">
    <button type="button" class="kaitenzushi-parent-finish-button" data-action="kaitenzushi-finish">回転寿司を終了する</button>
    <iframe
      class="kaitenzushi-game-frame"
      data-kaitenzushi-frame
      title="回転寿司ミニゲーム"
      allow="autoplay; fullscreen"
      loading="eager"
    ></iframe>
  </main>`;
}

function showKaitenzushiLoadError(reason = '') {
  if (screen !== 'kaitenzushi') return;
  clearKaitenzushiLoadWatch();
  if (kaitenzushiSession) kaitenzushiSession.loadError = true;
  const stage = root.querySelector('.kaitenzushi-game-screen');
  const frame = root.querySelector('[data-kaitenzushi-frame]');
  if (!(stage instanceof HTMLElement)) return;
  if (frame instanceof HTMLIFrameElement) frame.hidden = true;
  stage.querySelector('.kaitenzushi-load-error')?.remove();
  stage.insertAdjacentHTML('beforeend', `<section class="kaitenzushi-load-error" role="alert">
    <strong>回転寿司を読み込めませんでした</strong>
    <p>ゲーム本体の画面へ誤って戻らないよう停止しました。通信またはキャッシュを更新して、もう一度読み込んでください。</p>
    ${reason ? `<small>${esc(reason)}</small>` : ''}
    <div class="kaitenzushi-load-error-actions">
      <button type="button" class="primary-button" data-action="retry-kaitenzushi">もう一度読み込む</button>
      <button type="button" class="secondary-button" data-action="cancel-kaitenzushi">食事選択へ戻る</button>
    </div>
  </section>`);
}

function retryKaitenzushi() {
  if (screen !== 'kaitenzushi') return;
  clearKaitenzushiLoadWatch();
  kaitenzushiLoadNonce += 1;
  if (kaitenzushiSession) {
    kaitenzushiSession.ready = false;
    kaitenzushiSession.loadError = false;
  }
  render();
}

function cancelKaitenzushi() {
  clearKaitenzushiLoadWatch();
  kaitenzushiSession = null;
  setScreen('meal', {}, false);
}

function postKaitenzushiSettings(frame) {
  if (!(frame instanceof HTMLIFrameElement)) return;
  const settings = state?.settings || {};
  frame.contentWindow?.postMessage({
    source: 'jxj-kaitenzushi-parent',
    type: 'settings',
    // 回転寿司のBGM・環境音は親ゲーム側で再生する。iframeでは食事効果音だけを有効にする。
    bgmVolume: 0,
    sfxVolume: Math.max(0, Math.min(1, Number(settings.sfxVolume) || 0)),
    ambientVolume: 0,
    bgmMuted: true,
    sfxMuted: Boolean(settings.sfxMuted),
    ambientMuted: true,
    externalAudioPriority: false,
  }, '*');
}

function bindKaitenzushiFrame() {
  const frame = root.querySelector('[data-kaitenzushi-frame]');
  if (!(frame instanceof HTMLIFrameElement)) return;
  clearKaitenzushiLoadWatch();

  let launchAssigned = false;
  let correctDocumentSeen = false;
  const handleLoad = () => {
    if (screen !== 'kaitenzushi' || !launchAssigned) return;
    let marker = '';
    let href = '';
    try {
      marker = frame.contentDocument?.documentElement?.dataset?.jxjKaitenzushi || '';
      href = frame.contentWindow?.location?.href || '';
    } catch (_) {}
    // iframe creation can emit an initial about:blank load before srcdoc is committed.
    if (!marker && (href === 'about:blank' || href === '')) return;
    if (marker !== '1') {
      showKaitenzushiLoadError('回転寿司ではない画面が読み込まれました。');
      return;
    }
    correctDocumentSeen = true;
    postKaitenzushiSettings(frame);
    if (kaitenzushiSession?.ready) return;
    clearKaitenzushiLoadWatch();
    kaitenzushiReadyTimer = setTimeout(() => {
      if (screen === 'kaitenzushi' && !kaitenzushiSession?.ready) {
        showKaitenzushiLoadError('回転寿司から起動完了の応答がありません。');
      }
    }, 12000);
  };

  frame.addEventListener('load', handleLoad);
  frame.addEventListener('error', () => showKaitenzushiLoadError('回転寿司の画面を準備できませんでした。'), { once: true });
  launchAssigned = true;

  try {
    if ('srcdoc' in frame) {
      // content://・PWA・GitHub Pagesのどの起動方法でも、別ページ遷移を行わず同じ文書を直接起動する。
      frame.srcdoc = kaitenzushiEmbeddedDocument();
    } else {
      // 古いブラウザだけ従来の同一オリジンURLへフォールバックする。
      frame.src = kaitenzushiFrameSource();
    }
  } catch (_) {
    frame.src = kaitenzushiFrameSource();
  }

  clearKaitenzushiLoadWatch();
  kaitenzushiReadyTimer = setTimeout(() => {
    if (screen !== 'kaitenzushi' || kaitenzushiSession?.ready) return;
    showKaitenzushiLoadError(correctDocumentSeen
      ? '回転寿司から起動完了の応答がありません。'
      : '回転寿司の画面を準備できませんでした。');
  }, 15000);
}

function startKaitenzushi({ skipEventCheck = false, free = false } = {}) {
  // v0.10.654: 大将イベントの途中復帰は、満腹・同一食事・所持金・時間制限より先に扱う。
  // PWA再読込後でも、既に発生済みの無料イベントを新規食事条件で失わない。
  const savedSushiEvent = sushiChefEventState();
  if (!skipEventCheck && savedSushiEvent.active && !['idle', 'completed'].includes(savedSushiEvent.stage)) {
    if (savedSushiEvent.stage === 'playing') {
      kaitenzushiSession = {
        budget: Number.MAX_SAFE_INTEGER,
        total: 0,
        plates: 0,
        settled: false,
        free: true,
        ready: false,
        loadError: false,
      };
      setScreen('kaitenzushi', {}, true);
    } else {
      setScreen('sushiChefEvent', {}, false);
    }
    return;
  }

  const current = hungerLevel();
  if (current >= (state.wellbeing.maxHunger || 7)) return showToast('空腹度は満タンです。', 'error');
  if (state.wellbeing.mealsEaten > 0 && state.wellbeing.lastMeal === 'kaitenzushi') return showToast('栄養が片寄るので違うものを食べましょう', 'error');
  if (!free && state.game.money < 190) return showToast('回転寿司を食べるための所持金が足りません。', 'error');
  if (!canSpendMealTime()) return showToast(mealTimeUnavailableMessage(), 'error');
  if (!skipEventCheck && maybeStartSushiChefEvent()) return;
  const sushiEvent = sushiChefEventState();
  const eventFree = free || Boolean(sushiEvent.active && sushiEvent.stage === 'playing');
  kaitenzushiSession = {
    budget: eventFree ? Number.MAX_SAFE_INTEGER : Math.max(0, Math.floor(Number(state.game.money) || 0)),
    total: 0,
    plates: 0,
    settled: false,
    free: eventFree,
    ready: false,
    loadError: false,
  };
  setScreen('kaitenzushi', {}, true);
}

function finishKaitenzushiFromParent() {
  const session = kaitenzushiSession;
  if (!session) {
    setScreen('meal', {}, false);
    return;
  }
  completeKaitenzushi(session.total, session.plates);
}

function completeKaitenzushi(totalValue, plateValue) {
  clearKaitenzushiLoadWatch();
  const session = kaitenzushiSession;
  if (!session || session.settled || screen !== 'kaitenzushi') return;
  session.settled = true;

  const total = Math.max(0, Math.floor(Number(totalValue) || 0));
  const plates = Math.max(0, Math.floor(Number(plateValue) || 0));
  const totalsMatchProgress = total === session.total && plates === session.plates;
  const plateTotalsArePlausible = session.free
    ? total === 0
    : (plates === 0 ? total === 0 : total >= plates * 190 && total <= plates * 850);
  if (!totalsMatchProgress || !plateTotalsArePlausible || (!session.free && (total > session.budget || total > state.game.money))) {
    session.settled = false;
    showToast('お会計金額を確認できませんでした。もう一度お試しください。', 'error');
    return;
  }

  const before = hungerLevel();
  if (total > 0) {
    state.game.money -= total;
    addFinance('回転寿司で食事', 0, total);
    startMoneyFeedback(-total, 1200);
  }

  const maxHunger = Math.max(1, Number(state.wellbeing.maxHunger) || 7);
  if (plates > 0) spendMealTime();
  state.wellbeing.hunger = Math.min(maxHunger, hungerLevel() + plates);
  const recovery = state.wellbeing.hunger - before;
  if (plates > 0) {
    state.wellbeing.lastMeal = 'kaitenzushi';
    state.wellbeing.mealsEaten = Math.max(0, Number(state.wellbeing.mealsEaten) || 0) + 1;
    state.daily.meals.push({
      id: 'kaitenzushi',
      name: '回転寿司',
      price: total,
      recovery,
      plates,
    });
  }
  if (session.free) {
    const eventState = sushiChefEventState();
    eventState.active = true;
    eventState.stage = 'farewell';
    eventState.lastPlates = plates;
    eventState.lastHungerBefore = before;
    eventState.lastHungerAfter = state.wellbeing.hunger;
    state.game.screen = 'sushiChefEvent';
    saveGame();
    kaitenzushiSession = null;
    // 会計ボタン側で無料会計の成功音を鳴らすため、ここでは振動だけにして二重再生を防ぐ。
    vibrate([32, 28, 55]);
    setScreen('sushiChefEvent', {}, false);
    return;
  }

  state.game.screen = 'main';
  saveGame();

  kaitenzushiSession = null;
  if (plates > 0) {
    hungerFeedback = { before, after: state.wellbeing.hunger, mealName: `回転寿司（${plates}皿）` };
    clearTimeout(hungerFeedbackTimer);
    goMain();
    showToast(`ごちそうさまでした　${plates}皿・${yen(total)}`, 'meal-complete', false);
    playSfx('levelup');
    hungerFeedbackTimer = setTimeout(() => {
      hungerFeedback = null;
      if (screen === 'main') render();
    }, 1550);
  } else {
    goMain();
    showToast('何も食べずにお店を出ました。', 'info', false);
  }
}

function handleKaitenzushiMessage(event) {
  if (screen !== 'kaitenzushi' || !kaitenzushiSession) return;
  const frame = root.querySelector('[data-kaitenzushi-frame]');
  if (!(frame instanceof HTMLIFrameElement) || event.source !== frame.contentWindow) return;
  const message = event.data;
  if (!message || message.source !== 'jxj-kaitenzushi') return;
  if (message.type === 'ready') {
    kaitenzushiSession.ready = true;
    kaitenzushiSession.loadError = false;
    clearKaitenzushiLoadWatch();
    postKaitenzushiSettings(frame);
    return;
  }
  if (message.type === 'chew') {
    duckCurrentAmbient({ factor: .2, duration: 1000 });
    return;
  }
  const total = Math.max(0, Math.floor(Number(message.total) || 0));
  const plates = Math.max(0, Math.floor(Number(message.plates) || 0));
  if (total <= kaitenzushiSession.budget) {
    kaitenzushiSession.total = total;
    kaitenzushiSession.plates = plates;
  }
  if (message.type === 'checkout') {
    playSfx(kaitenzushiSession.free ? 'success' : 'coin', { gain: kaitenzushiSession.free ? .82 : .72 });
    completeKaitenzushi(total, plates);
  }
}

function handleAquariumFrameMessage(event) {
  const expectedOrigin = window.location.origin;
  if (expectedOrigin && expectedOrigin !== 'null' && event.origin !== expectedOrigin) return;
  const frame = document.querySelector('.aquarium-game-frame');
  if (!frame?.contentWindow || event.source !== frame.contentWindow) return;
  const data = event.data || {};
  if (data.source !== 'jxj-aquarium') return;
  if (data.type === 'ready' || data.type === 'request-state') {
    postAquariumSnapshot(frame);
    [0, 80, 260, 600, 1200].forEach((delay) => window.setTimeout(() => syncAquariumRuntime(frame, { force: delay >= 260 }), delay));
    return;
  }
  if (data.type === 'display-install') {
    const result = setAquariumDisplayInstalled(String(data.id || ''), data.target);
    if (!result.ok && result.message) showToast(result.message);
    saveGame(); postAquariumSnapshot(frame); syncAquariumRuntime(frame);
    if (screen === 'phone' && phoneTab === 'aquarium') render();
  }
}
window.addEventListener('message', handleAquariumFrameMessage);

window.addEventListener('message', handleKaitenzushiMessage);

// v0.10.469: 通常の食事演出は、タップで即終了できる一方、
// 操作しない場合も従来どおり自動で終了する。
function waitForMealEatingCompletion({ autoDelay = 2500, eatSoundDelay = 420 } = {}) {
  return new Promise((resolve) => {
    let settled = false;
    let autoTimer = null;
    let soundTimer = null;
    const finish = (reason = 'auto') => {
      if (settled) return false;
      settled = true;
      if (autoTimer) clearTimeout(autoTimer);
      if (soundTimer) clearTimeout(soundTimer);
      if (mealEatingCompletionController?.finish === finish) mealEatingCompletionController = null;
      resolve(reason);
      return true;
    };
    mealEatingCompletionController = { finish };
    soundTimer = setTimeout(() => {
      if (!settled) playSfx('eat');
    }, Math.max(0, Number(eatSoundDelay) || 420));
    autoTimer = setTimeout(() => finish('auto'), Math.max(300, Number(autoDelay) || 2500));
  });
}

function finishMealEatingEarly() {
  if (screen !== 'meal' || !screenData?.eating) return false;
  return Boolean(mealEatingCompletionController?.finish?.('manual'));
}

// v0.10.654: 食事イベント途中の再読込では、新規発生条件より既存イベント復帰を優先する。
function resumeActiveMealEvent(mealId) {
  const routes = {
    convenience: [['cyclopsEvent', 'cyclopsEvent']],
    ice: [['whiteBunnyIceEvent', 'whiteBunnyIceEvent']],
    kebab: [['emeraldCaptainKebabEvent', 'emeraldCaptainKebabEvent']],
    hamburger: [['touristWoodSwordEvent', 'touristWoodSwordEvent'], ['terryCaliforniaEvent', 'terryCaliforniaEvent']],
    indian: [['diamondPolishingLapEvent', 'diamondPolishingLapEvent'], ['ganeshaTuskEvent', 'ganeshaTuskEvent']],
    ramen: [['childhoodFriendEvent', 'childhoodFriendEvent']],
    soba: [['ridleyOkazakiSobaEvent', 'ridleyOkazakiSobaEvent']],
    chinese: [['mysteryChineseMealEvent', 'mysteryChineseMealEvent']],
    korean: [['grayHoodAquariumEvent', 'grayHoodAquariumEvent']],
  };
  for (const [eventKey, targetScreen] of routes[String(mealId || '')] || []) {
    const eventState = state?.events?.[eventKey];
    const stage = String(eventState?.stage || 'idle');
    if (eventState?.active && !['idle', 'completed'].includes(stage)) {
      setScreen(targetScreen, { mealId }, false);
      return true;
    }
  }
  return false;
}

async function eatMeal(mealId, { skipEventCheck = false, priceOverride = null } = {}) {
  const meal = MEALS[mealId];
  if (!meal || mealTransitioning) return;

  // v0.10.654: 途中イベントの復帰は、満腹・同一食事・所持金・時間制限より先に判定する。
  if (!skipEventCheck && resumeActiveMealEvent(mealId)) return;

  const before = hungerLevel();
  if (before >= 7) return showToast('空腹度は満タンです。', 'error');
  if (mealId !== 'ice' && state.wellbeing.mealsEaten > 0 && state.wellbeing.lastMeal === mealId) return showToast('栄養が片寄るので違うものを食べましょう', 'error');
  const actualPrice = Math.max(0, Math.floor(Number(priceOverride ?? meal.price) || 0));
  if (state.game.money < actualPrice) return showToast('所持金が足りません。', 'error');
  if (!canSpendMealTime()) return showToast(mealTimeUnavailableMessage(), 'error');
  if (mealId === 'convenience' && !skipEventCheck && maybeStartCyclopsEvent()) return;
  if (mealId === 'ice' && !skipEventCheck && maybeStartWhiteBunnyIceEvent()) return;
  if (mealId === 'kebab' && !skipEventCheck && maybeStartEmeraldCaptainKebabEvent()) return;
  if (mealId === 'hamburger' && !skipEventCheck && maybeStartTouristWoodSwordEvent()) return;
  if (mealId === 'hamburger' && !skipEventCheck && maybeStartTerryCaliforniaEvent()) return;
  if (mealId === 'indian' && !skipEventCheck && maybeStartDiamondPolishingLapEvent()) return;
  if (mealId === 'indian' && !skipEventCheck && maybeStartGaneshaTuskEvent()) return;
  if (mealId === 'ramen' && !skipEventCheck && maybeStartChildhoodFriendEvent()) return;
  if (mealId === 'soba' && !skipEventCheck && maybeStartRidleyOkazakiSobaEvent()) return;
  if (mealId === 'chinese' && !skipEventCheck && maybeStartMysteryChineseMealEvent()) return;
  if (mealId === 'korean' && !skipEventCheck && maybeStartGrayHoodAquariumEvent()) return;

  mealTransitioning = true;
  const stateBeforeMeal = structuredClone(state);
  let mealCommitted = false;
  try {
    selectedMeal = mealId;
    if (mealId === 'ice') startIceMealAudio();
    else stopIceMealAudio();
    await preloadMealAssets(mealId);

    // v0.10.654: 支払い・時間・空腹回復・履歴を一括確定してから食事演出へ入る。
    // 演出中にPWAを閉じても「代金だけ支払い済み」の中間セーブを作らない。
    state.game.money -= actualPrice;
    addFinance(`${meal.name}で食事`, 0, actualPrice);
    spendMealTime();
    state.wellbeing.hunger = Math.min(7, hungerLevel() + meal.recovery);
    state.wellbeing.lastMeal = mealId;
    state.wellbeing.mealsEaten += 1;
    state.daily.meals.push({ id: mealId, name: meal.name, price: actualPrice, recovery: state.wellbeing.hunger - before });
    saveGame();
    mealCommitted = true;
    startMoneyFeedback(-actualPrice, 1200);

    setScreen('meal', { mealId, eating: true }, false);
    const eatingCompletion = waitForMealEatingCompletion();
    await waitForNextPaintWithTimeout();
    await eatingCompletion;

    hungerFeedback = { before, after: state.wellbeing.hunger, mealName: meal.name };
    clearTimeout(hungerFeedbackTimer);
    if (mealId === 'ice' && startOyatsuIceReturnAfterMeal()) {
      showToast('ごちそうさまでした', 'meal-complete', false);
      playSfx('levelup');
      hungerFeedbackTimer = setTimeout(() => { hungerFeedback = null; }, 1550);
      return;
    }
    setScreen('main', {}, false);
    showToast('ごちそうさまでした', 'meal-complete', false);
    playSfx('levelup');
    hungerFeedbackTimer = setTimeout(() => {
      hungerFeedback = null;
      if (screen === 'main') render();
    }, 1550);
  } catch (error) {
    console.error('食事処理エラー', error);
    stopIceMealAudio();
    if (!mealCommitted) {
      state = stateBeforeMeal;
      screen = 'main';
      screenData = {};
      navigation = [];
      pendingDayMoneyDelta = 0;
      saveGame();
      render();
      try { showToast('食事処理を中断し、直前の状態へ戻しました。', 'error'); } catch (_) {}
    } else {
      // ゲーム上の食事は確定済み。演出だけ失敗した時は二重返金せず画面のみ復旧する。
      screen = 'main';
      screenData = {};
      navigation = [];
      pendingDayMoneyDelta = 0;
      if (state?.game) state.game.screen = 'main';
      saveGame();
      render();
      try { showToast('食事は完了しています。画面を復旧しました。', 'warning'); } catch (_) {}
    }
  } finally {
    mealEatingCompletionController = null;
    mealTransitioning = false;
  }
}



function ensureGiftState(gameState = state) {
  if (!gameState || typeof gameState !== 'object') return { outbox: [], inbox: [] };
  gameState.gifts = gameState.gifts && typeof gameState.gifts === 'object' && !Array.isArray(gameState.gifts) ? gameState.gifts : {};
  gameState.gifts.outbox = (Array.isArray(gameState.gifts.outbox) ? gameState.gifts.outbox : []).filter((entry) => entry?.status !== 'claimed');
  gameState.gifts.inbox = Array.isArray(gameState.gifts.inbox) ? gameState.gifts.inbox : [];
  return gameState.gifts;
}

function giftCategoryLabel(category) {
  return ({ rough: '原石', loose: 'ルース', item: 'アイテム', metal: '地金', jewelry: '完成品' })[category] || 'プレゼント';
}

function giftRoundedWeight(value) {
  return Math.round(Math.max(0, Number(value) || 0) * 10) / 10;
}

function giftPayloadSummary(payload) {
  const quantity = payload?.type === 'metal'
    ? `${metalWeightLabel(payload.quantity)}g`
    : payload?.type === 'jewelry'
      ? '1点'
      : `${Math.max(1, Math.floor(Number(payload?.quantity) || 1))}個`;
  return {
    category: giftCategoryLabel(payload?.type),
    name: String(payload?.name || 'プレゼント'),
    quantity,
  };
}

function giftSendableRows(category) {
  if (!state?.inventory) return [];
  if (category === 'rough') {
    return Object.values(GEMS).map((gem) => {
      const max = Math.max(0, Math.floor(Number(state.inventory.rough?.[gem.id]) || 0));
      return { key: gem.id, name: roughDisplayName(gem.id), max, payload: { type: 'rough', id: gem.id, name: roughDisplayName(gem.id) } };
    }).filter((row) => row.max > 0);
  }
  if (category === 'loose') {
    const rows = [];
    for (const gem of Object.values(GEMS)) {
      for (const shapeId of looseShapeIdsForGem(gem.id)) {
        const max = looseAvailableQuantity(gem.id, shapeId);
        if (max <= 0) continue;
        rows.push({
          key: `${gem.id}|${shapeId}`,
          name: looseDisplayLabel(gem.id, shapeId),
          max,
          payload: { type: 'loose', id: gem.id, shapeId, name: looseDisplayLabel(gem.id, shapeId, { suffix: true }) },
        });
      }
    }
    return rows;
  }
  if (category === 'item') {
    return Object.values(GENERAL_ITEMS).map((item) => {
      const max = Math.max(0, Math.floor(Number(state.inventory.items?.[item.id]) || 0));
      return { key: item.id, name: item.name, max, payload: { type: 'item', id: item.id, name: item.name } };
    }).filter((row) => row.max > 0);
  }
  if (category === 'metal') {
    return Object.values(METALS).map((metal) => {
      const max = Math.max(0, Math.floor(metalAvailableWeight(metal.id)));
      return { key: metal.id, name: metal.shortName || metal.name, max, payload: { type: 'metal', id: metal.id, name: `${metal.shortName || metal.name}地金` } };
    }).filter((row) => row.max >= 1);
  }
  if (category === 'jewelry') {
    return (state.inventory.jewelry || []).filter((item) => item.status === 'stored').map((item) => ({
      key: item.id,
      name: item.name || '完成品',
      max: 1,
      payload: { type: 'jewelry', id: item.id, name: item.name || '完成品', itemData: structuredClone(item) },
    }));
  }
  return [];
}

function normalizeGiftDraft() {
  const categories = ['rough', 'loose', 'item', 'metal', 'jewelry'];
  if (!categories.includes(giftDraft.category)) giftDraft.category = 'rough';
  const rows = giftSendableRows(giftDraft.category);
  if (!rows.some((row) => row.key === giftDraft.itemKey)) giftDraft.itemKey = rows[0]?.key || '';
  const row = rows.find((entry) => entry.key === giftDraft.itemKey) || rows[0] || null;
  if (!row) giftDraft.quantity = 1;
  else giftDraft.quantity = Math.max(1, Math.min(Math.floor(row.max), Math.floor(Number(giftDraft.quantity) || 1)));
  return { rows, row };
}

function syncGiftSendQuantityControls() {
  if (screen !== 'phone' || phoneTab !== 'gift' || giftView !== 'send') return false;
  const scrollSnapshot = giftControlScrollSnapshot;
  const { row } = normalizeGiftDraft();
  if (!row || giftDraft.category === 'jewelry') return false;
  const quantity = Math.max(1, Math.floor(Number(giftDraft.quantity) || 1));
  const maximum = Math.max(1, Math.floor(row.max));
  const valueDisplay = root.querySelector('[data-gift-quantity-value]');
  if (!valueDisplay) return false;
  valueDisplay.textContent = String(quantity);
  const upButton = root.querySelector('.gift-stepper-up');
  const downButton = root.querySelector('.gift-stepper-down');
  if (upButton) upButton.disabled = quantity >= maximum;
  if (downButton) downButton.disabled = quantity <= 1;
  const previewQuantity = root.querySelector('.gift-preview-card > div > span');
  if (previewQuantity) {
    previewQuantity.textContent = giftPayloadSummary({ ...row.payload, quantity }).quantity;
  }
  giftControlScrollSnapshot = null;
  if (scrollSnapshot) restoreGiftSendScrollState(scrollSnapshot);
  return true;
}

function adjustGiftQuantity(delta) {
  const { row } = normalizeGiftDraft();
  if (!row || giftDraft.category === 'jewelry') return;
  const maximum = Math.max(1, Math.floor(row.max));
  const current = Math.max(1, Math.floor(Number(giftDraft.quantity) || 1));
  giftDraft.quantity = Math.max(1, Math.min(maximum, current + (Number(delta) < 0 ? -1 : 1)));
  playSfx('select', { gain: 0.66 });
  if (!syncGiftSendQuantityControls()) render();
}

function giftVisualMarkup(payload, className = 'gift-item-visual') {
  if (!payload) return `<span class="${className}" aria-hidden="true">◆</span>`;
  if (payload.type === 'rough') return roughVisual(payload.id, className, payload.name || '原石');
  if (payload.type === 'loose') return looseVisual(payload.id, className, payload.name || 'ルース', payload.shapeId);
  if (payload.type === 'metal') return metalVisual(payload.id, className, payload.name || '地金');
  if (payload.type === 'item') {
    const item = GENERAL_ITEMS[payload.id];
    return item?.image
      ? `<img class="${className}" src="${esc(item.image)}?v=${VERSION}" alt="${esc(payload.name || item.name)}" draggable="false">`
      : `<span class="${className}" role="img" aria-label="${esc(payload.name || item?.name || 'アイテム')}">${esc(item?.symbol || '◆')}</span>`;
  }
  if (payload.type === 'jewelry') {
    const item = payload.itemData || {};
    return `<span class="gift-jewelry-visual ${className}">${jewelryItemVisual(item.item, 'jewelry-item-shape', item.useLoose !== false)}${item.useLoose === false ? '' : jewelryLooseSetVisual(item.item, item.gem, item.looseShape, 'small')}</span>`;
  }
  return `<span class="${className}" aria-hidden="true">◆</span>`;
}

function giftOutboxEntry(code, payload, status = 'pending') {
  const summary = giftPayloadSummary(payload);
  return {
    code,
    status,
    category: summary.category,
    name: summary.name,
    quantity: summary.quantity,
    createdAt: new Date().toISOString(),
  };
}

function removeGiftFromGameState(gameState, payload, code) {
  const inventory = gameState?.inventory;
  if (!inventory) throw new Error('在庫データを確認できません。');
  const quantity = payload.type === 'metal' ? giftRoundedWeight(payload.quantity) : Math.max(1, Math.floor(Number(payload.quantity) || 1));
  if (payload.type === 'rough') {
    if (!GEMS[payload.id]) throw new Error('原石データを確認できません。');
    const current = Math.max(0, Math.floor(Number(inventory.rough?.[payload.id]) || 0));
    if (current < quantity) throw new Error('原石の所持数が足りません。');
    inventory.rough[payload.id] = current - quantity;
  } else if (payload.type === 'loose') {
    if (!GEMS[payload.id] || !looseShapeIdsForGem(payload.id).includes(payload.shapeId)) throw new Error('ルースデータを確認できません。');
    const current = Math.max(0, Math.floor(Number(inventory.loose?.[payload.id]?.[payload.shapeId]) || 0));
    if (current < quantity) throw new Error('ルースの所持数が足りません。');
    inventory.loose[payload.id][payload.shapeId] = current - quantity;
  } else if (payload.type === 'item') {
    if (!GENERAL_ITEMS[payload.id]) throw new Error('アイテムデータを確認できません。');
    const current = Math.max(0, Math.floor(Number(inventory.items?.[payload.id]) || 0));
    if (current < quantity) throw new Error('アイテムの所持数が足りません。');
    inventory.items[payload.id] = current - quantity;
  } else if (payload.type === 'metal') {
    if (!METALS[payload.id]) throw new Error('地金データを確認できません。');
    const current = giftRoundedWeight(inventory.metals?.[payload.id]);
    if (quantity < 0.1 || current + 0.0001 < quantity) throw new Error('地金の所持重量が足りません。');
    inventory.metals[payload.id] = giftRoundedWeight(current - quantity);
  } else if (payload.type === 'jewelry') {
    const index = (inventory.jewelry || []).findIndex((item) => item.id === payload.id && item.status === 'stored');
    if (index < 0) throw new Error('この完成品は現在プレゼントにできません。');
    inventory.jewelry.splice(index, 1);
  } else throw new Error('プレゼントの種類を確認できません。');
  const gifts = ensureGiftState(gameState);
  gifts.outbox.unshift(giftOutboxEntry(code, payload, 'pending'));
  gifts.outbox = gifts.outbox.slice(0, 50);
  return gameState;
}

function addGiftToGameState(gameState, payload, code) {
  const inventory = gameState?.inventory;
  if (!inventory) throw new Error('在庫データを確認できません。');
  const quantity = payload.type === 'metal' ? giftRoundedWeight(payload.quantity) : Math.max(1, Math.floor(Number(payload.quantity) || 1));
  if (payload.type === 'rough') {
    if (!GEMS[payload.id]) throw new Error('原石データを確認できません。');
    inventory.rough[payload.id] = Math.max(0, Math.floor(Number(inventory.rough?.[payload.id]) || 0)) + quantity;
  } else if (payload.type === 'loose') {
    if (!GEMS[payload.id] || !looseShapeIdsForGem(payload.id).includes(payload.shapeId)) throw new Error('ルースデータを確認できません。');
    inventory.loose[payload.id] = inventory.loose[payload.id] || {};
    inventory.loose[payload.id][payload.shapeId] = Math.max(0, Math.floor(Number(inventory.loose[payload.id][payload.shapeId]) || 0)) + quantity;
  } else if (payload.type === 'item') {
    if (!GENERAL_ITEMS[payload.id]) throw new Error('アイテムデータを確認できません。');
    inventory.items[payload.id] = Math.max(0, Math.floor(Number(inventory.items?.[payload.id]) || 0)) + quantity;
  } else if (payload.type === 'metal') {
    if (!METALS[payload.id]) throw new Error('地金データを確認できません。');
    const current = giftRoundedWeight(inventory.metals?.[payload.id]);
    const capacity = Math.max(0.1, Number(inventory.metalCapacity?.[payload.id]) || Number(METALS[payload.id].storageLimit) || 1);
    if (current + quantity > capacity + 0.0001) throw new Error(`${METALS[payload.id].shortName || METALS[payload.id].name}の保管上限を超えるため受け取れません。`);
    inventory.metals[payload.id] = giftRoundedWeight(current + quantity);
  } else if (payload.type === 'jewelry') {
    const used = (inventory.jewelry || []).filter((item) => item.status !== 'sold').length;
    const capacity = finishedJewelryCapacity(gameState);
    if (used >= capacity) throw new Error('完成品の保管場所に空きがありません。');
    const item = structuredClone(payload.itemData || {});
    if (!item.item || !ITEMS[item.item]) throw new Error('完成品データを確認できません。');
    item.id = `gift-${String(code).replace(/[^A-Z0-9]/gi, '').toLowerCase()}`;
    item.status = 'stored';
    item.receivedGiftCode = code;
    item.receivedDay = Math.max(1, Math.floor(Number(gameState.game?.day) || 1));
    delete item.displayBranchNumber;
    delete item.orderId;
    if ((inventory.jewelry || []).some((entry) => entry.id === item.id)) throw new Error('このプレゼントはすでに在庫へ追加されています。');
    inventory.jewelry.push(item);
  } else throw new Error('プレゼントの種類を確認できません。');
  const gifts = ensureGiftState(gameState);
  const summary = giftPayloadSummary(payload);
  gifts.inbox.unshift({ code, ...summary, receivedAt: new Date().toISOString() });
  gifts.inbox = gifts.inbox.slice(0, 50);
  gameState.notifications = Array.isArray(gameState.notifications) ? gameState.notifications : [];
  gameState.notifications.unshift({
    id: `gift-${String(code).replace(/[^A-Z0-9]/gi, '').toLowerCase()}-received`,
    title: 'プレゼントを受け取りました',
    body: `${summary.name} ${summary.quantity}を受け取りました。`,
    type: 'special',
    day: Math.max(1, Math.floor(Number(gameState.game?.day) || 1)),
    unread: true,
  });
  return gameState;
}

function restoreGiftToGameState(gameState, payload, code) {
  const inventory = gameState?.inventory;
  if (!inventory) throw new Error('在庫データを確認できません。');
  const quantity = payload.type === 'metal' ? giftRoundedWeight(payload.quantity) : Math.max(1, Math.floor(Number(payload.quantity) || 1));
  if (payload.type === 'rough') inventory.rough[payload.id] = Math.max(0, Math.floor(Number(inventory.rough?.[payload.id]) || 0)) + quantity;
  else if (payload.type === 'loose') {
    inventory.loose[payload.id] = inventory.loose[payload.id] || {};
    inventory.loose[payload.id][payload.shapeId] = Math.max(0, Math.floor(Number(inventory.loose[payload.id][payload.shapeId]) || 0)) + quantity;
  } else if (payload.type === 'item') inventory.items[payload.id] = Math.max(0, Math.floor(Number(inventory.items?.[payload.id]) || 0)) + quantity;
  else if (payload.type === 'metal') inventory.metals[payload.id] = giftRoundedWeight(Number(inventory.metals?.[payload.id]) + quantity);
  else if (payload.type === 'jewelry') {
    const item = structuredClone(payload.itemData || {});
    item.status = 'stored';
    delete item.displayBranchNumber;
    delete item.orderId;
    if (!(inventory.jewelry || []).some((entry) => entry.id === item.id)) inventory.jewelry.push(item);
  }
  const gifts = ensureGiftState(gameState);
  const entry = gifts.outbox.find((item) => item.code === code);
  if (entry) entry.status = 'cancelled';
  gameState.notifications = Array.isArray(gameState.notifications) ? gameState.notifications : [];
  const summary = giftPayloadSummary(payload);
  gameState.notifications.unshift({
    id: `gift-${String(code).replace(/[^A-Z0-9]/gi, '').toLowerCase()}-cancelled`,
    title: 'プレゼントを取り消しました',
    body: `${summary.name} ${summary.quantity}を在庫へ戻しました。`,
    type: 'info',
    day: Math.max(1, Math.floor(Number(gameState.game?.day) || 1)),
    unread: true,
  });
  return gameState;
}

function persistTransactionalGiftState(nextState) {
  state = migrateState(nextState);
  ensureGiftState(state);
  syncFinishedJewelryCapacity();
  cloudSave = structuredClone(state);
  localStorage.setItem(localSaveKey(), JSON.stringify(state));
  localStorage.setItem(`${SAVE_KEY}-settings`, JSON.stringify(state.settings));
}

function giftStatusLabel(status) {
  return ({ pending: '未受取', claimed: '受取済み', cancelled: '取消済み' })[status] || status || '不明';
}

function pendingGiftOutboxEntries() {
  return ensureGiftState().outbox.filter((entry) => {
    const code = normalizeGiftCode(entry?.code);
    return entry?.status === 'pending' && /^JXJ-[A-Z0-9]{4}-[A-Z0-9]{4}$/.test(code);
  }).slice(0, 10);
}

function stopGiftStatusSyncTimer() {
  if (!giftStatusSyncTimer) return;
  clearTimeout(giftStatusSyncTimer);
  giftStatusSyncTimer = null;
}

function scheduleGiftOutboxStatusSync(delay = 0, force = false) {
  if (screen !== 'phone' || phoneTab !== 'gift' || !state || !currentUser || sessionTakenOver) {
    stopGiftStatusSyncTimer();
    return;
  }
  if (!pendingGiftOutboxEntries().length || giftStatusSyncTimer) return;
  giftStatusSyncTimer = setTimeout(async () => {
    giftStatusSyncTimer = null;
    try {
      await refreshGiftOutboxStatuses({ force });
    } catch (error) {
      console.warn('プレゼント受取状況の同期に失敗しました。', error);
    }
    if (screen === 'phone' && phoneTab === 'gift' && pendingGiftOutboxEntries().length) {
      scheduleGiftOutboxStatusSync(GIFT_STATUS_SYNC_INTERVAL_MS, true);
    }
  }, Math.max(0, Number(delay) || 0));
}

async function refreshGiftOutboxStatuses({ force = false } = {}) {
  if (giftStatusSyncBusy || !state || !currentUser || sessionTakenOver) return false;
  const pendingEntries = pendingGiftOutboxEntries();
  if (!pendingEntries.length) return false;
  const now = Date.now();
  if (!force && now - giftStatusLastCheckedAt < 2500) return false;
  giftStatusSyncBusy = true;
  giftStatusLastCheckedAt = now;
  let changed = false;
  try {
    const userId = currentUser.uid;
    const results = await Promise.allSettled(pendingEntries.map(async (entry) => {
      const gift = await inspectGiftCode(entry.code);
      if (!gift || gift.senderUid !== userId || normalizeGiftCode(gift.code) !== normalizeGiftCode(entry.code)) return null;
      const status = ['pending', 'claimed', 'cancelled'].includes(gift.status) ? gift.status : 'pending';
      return {
        code: normalizeGiftCode(entry.code),
        status,
        recipientName: String(gift.recipientName || '').slice(0, 40),
        claimedAtIso: String(gift.claimedAtIso || ''),
        cancelledAtIso: String(gift.cancelledAtIso || ''),
      };
    }));
    const gifts = ensureGiftState();
    const outbox = gifts.outbox;
    results.forEach((result) => {
      if (result.status !== 'fulfilled' || !result.value) return;
      const remote = result.value;
      const entryIndex = outbox.findIndex((item) => normalizeGiftCode(item?.code) === remote.code);
      if (entryIndex < 0) return;
      const entry = outbox[entryIndex];
      if (entry.status !== 'pending' || remote.status === 'pending') return;
      if (remote.status === 'claimed') {
        outbox.splice(entryIndex, 1);
        changed = true;
        return;
      }
      entry.status = remote.status;
      if (remote.cancelledAtIso) entry.cancelledAtIso = remote.cancelledAtIso;
      changed = true;
    });
    const withoutPreviouslyClaimed = outbox.filter((entry) => entry?.status !== 'claimed');
    if (withoutPreviouslyClaimed.length !== outbox.length) {
      gifts.outbox = withoutPreviouslyClaimed;
      changed = true;
    }
    if (changed) {
      await saveGame();
      if (screen === 'phone' && phoneTab === 'gift') render();
    }
    return changed;
  } finally {
    giftStatusSyncBusy = false;
  }
}

function renderGiftOutbox() {
  const outbox = ensureGiftState().outbox.filter((entry) => entry?.status !== 'claimed').slice(0, 10);
  if (!outbox.length) return '';
  return `<section class="gift-history-section"><h3>発行したプレゼント</h3><div class="gift-history-list">${outbox.map((entry) => `
    <article class="gift-history-row">
      <div><strong>${esc(entry.name || 'プレゼント')}</strong><span>${esc(entry.quantity || '')}・${esc(entry.code || '')}</span></div>
      <div class="gift-history-actions"><small class="gift-status gift-status-${esc(entry.status || 'pending')}">${esc(giftStatusLabel(entry.status))}</small>${entry.status === 'pending' ? `<button type="button" class="text-button" data-action="gift-cancel" data-code="${esc(entry.code)}" ${giftBusy ? 'disabled' : ''}>取り消す</button>` : ''}</div>
    </article>`).join('')}</div></section>`;
}

function renderGiftMenu() {
  return `<section class="phone-gift-menu">
    <div class="gift-menu-hero"><span aria-hidden="true">🎁</span><h2>プレゼント</h2><p>プレゼントコードを使って、ほかのプレイヤーと品物を受け渡せます。</p></div>
    <div class="gift-menu-buttons">
      <button type="button" class="primary-button full-button" data-action="gift-view" data-view="send"><strong>プレゼントを渡す</strong><small>品物を選んでコードを発行します</small></button>
      <button type="button" class="secondary-button full-button" data-action="gift-view" data-view="receive"><strong>プレゼントを受け取る</strong><small>相手から届いたコードを入力します</small></button>
    </div>
    ${renderGiftOutbox()}
  </section>`;
}

function renderGiftSend() {
  const { rows, row } = normalizeGiftDraft();
  const categoryOptions = [
    ['rough', '原石'], ['loose', 'ルース'], ['item', 'アイテム'], ['metal', '地金'], ['jewelry', '完成品'],
  ].map(([value, label]) => `<option value="${value}" ${giftDraft.category === value ? 'selected' : ''}>${label}</option>`).join('');
  if (!row) return `<section class="phone-gift-panel"><button type="button" class="text-button gift-back-button" data-action="gift-view" data-view="menu">‹ プレゼントへ戻る</button><h2>プレゼントを渡す</h2><label class="gift-field"><span>種類</span><select data-gift-category>${categoryOptions}</select></label><div class="empty-state"><strong>この種類で渡せるものがありません。</strong><p>別の種類を選んでください。</p></div></section>`;
  const isMetal = giftDraft.category === 'metal';
  const isJewelry = giftDraft.category === 'jewelry';
  const quantity = isJewelry ? 1 : giftDraft.quantity;
  const itemOptions = rows.map((entry) => `<option value="${esc(entry.key)}" ${entry.key === row.key ? 'selected' : ''}>${esc(entry.name)}（${isMetal ? `${metalWeightLabel(entry.max)}g` : `${entry.max}${isJewelry ? '点' : '個'}`}）</option>`).join('');
  const payload = { ...row.payload, quantity, ...(isJewelry ? { itemData: row.payload.itemData } : {}) };
  const summary = giftPayloadSummary(payload);
  return `<section class="phone-gift-panel">
    <button type="button" class="text-button gift-back-button" data-action="gift-view" data-view="menu">‹ プレゼントへ戻る</button>
    <h2>プレゼントを渡す</h2>
    <div class="gift-form-grid">
      <label class="gift-field"><span>種類</span><select data-gift-category>${categoryOptions}</select></label>
      <label class="gift-field"><span>渡すもの</span><select data-gift-item>${itemOptions}</select></label>
      ${isJewelry ? '' : `<label class="gift-field"><span>${isMetal ? '重量' : '数量'}</span><span class="gift-quantity-stepper" aria-label="${isMetal ? '地金の重量' : 'プレゼントの数量'}を増減"><button type="button" class="gift-stepper-button gift-stepper-up" data-action="gift-qty-step" data-delta="1" aria-label="${isMetal ? '地金を1g増やす' : '数量を1個増やす'}" ${quantity >= Math.floor(row.max) ? 'disabled' : ''}>▲</button><span class="gift-quantity-row"><output class="gift-quantity-value" data-gift-quantity-value aria-live="polite">${quantity}</output><em>${isMetal ? 'g' : '個'}</em></span><button type="button" class="gift-stepper-button gift-stepper-down" data-action="gift-qty-step" data-delta="-1" aria-label="${isMetal ? '地金を1g減らす' : '数量を1個減らす'}" ${quantity <= 1 ? 'disabled' : ''}>▼</button></span><small>渡せる上限：${isMetal ? `${Math.floor(row.max)}g（1g単位）` : `${row.max}個`}</small></label>`}
    </div>
    <article class="gift-preview-card">${giftVisualMarkup(payload)}<div><small>${esc(summary.category)}</small><strong>${esc(summary.name)}</strong><span>${esc(summary.quantity)}</span></div></article>
    <p class="gift-warning">コードを発行した時点で、選んだプレゼントは在庫から減ります。受け取られる前なら取り消せます。</p>
    <button type="button" class="primary-button full-button gift-create-button" data-action="gift-create" ${giftBusy ? 'disabled' : ''}>${giftBusy ? '発行しています…' : 'プレゼントコードを発行する'}</button>
  </section>`;
}

function renderGiftCreated() {
  const gift = giftLastCreated;
  if (!gift) return renderGiftMenu();
  const summary = giftPayloadSummary(gift.payload);
  return `<section class="phone-gift-panel gift-created-panel">
    <div class="gift-success-mark" aria-hidden="true">🎁</div>
    <h2>プレゼントコードを発行しました</h2>
    <article class="gift-preview-card">${giftVisualMarkup(gift.payload)}<div><small>${esc(summary.category)}</small><strong>${esc(summary.name)}</strong><span>${esc(summary.quantity)}</span></div></article>
    <button type="button" class="gift-code-card" data-action="gift-copy-code" data-code="${esc(gift.code)}"><small>相手へこのコードを伝えてください</small><strong>${esc(gift.code)}</strong><span>タップしてコピー</span></button>
    <div class="gift-complete-actions"><button type="button" class="primary-button full-button" data-action="gift-view" data-view="menu">プレゼントへ戻る</button><button type="button" class="secondary-button full-button" data-action="gift-view" data-view="send">続けて渡す</button></div>
  </section>`;
}

function renderGiftReceive() {
  if (giftView === 'received' && giftLastReceived) {
    const summary = giftPayloadSummary(giftLastReceived.payload);
    return `<section class="phone-gift-panel gift-created-panel"><div class="gift-success-mark" aria-hidden="true">✨</div><h2>プレゼントを受け取りました</h2><article class="gift-preview-card">${giftVisualMarkup(giftLastReceived.payload)}<div><small>${esc(summary.category)}</small><strong>${esc(summary.name)}</strong><span>${esc(summary.quantity)}</span></div></article><button type="button" class="primary-button full-button" data-action="gift-view" data-view="menu">プレゼントへ戻る</button></section>`;
  }
  const preview = giftPreview;
  return `<section class="phone-gift-panel">
    <button type="button" class="text-button gift-back-button" data-action="gift-view" data-view="menu">‹ プレゼントへ戻る</button>
    <h2>プレゼントを受け取る</h2>
    ${preview ? (() => {
      const summary = giftPayloadSummary(preview.payload);
      return `<article class="gift-receive-confirm"><small>${esc(preview.senderName || 'プレイヤー')}さんからのプレゼント</small><div class="gift-preview-card">${giftVisualMarkup(preview.payload)}<div><small>${esc(summary.category)}</small><strong>${esc(summary.name)}</strong><span>${esc(summary.quantity)}</span></div></div><code>${esc(preview.code)}</code><button type="button" class="primary-button full-button" data-action="gift-claim" ${giftBusy ? 'disabled' : ''}>${giftBusy ? '受け取っています…' : 'プレゼントを受け取る'}</button><button type="button" class="text-button full-button" data-action="gift-receive-reset">別のコードを入力する</button></article>`;
    })() : `<label class="gift-field gift-code-input"><span>プレゼントコード</span><input type="text" inputmode="text" autocomplete="off" autocapitalize="characters" maxlength="13" data-gift-code-input value="${esc(giftCodeInput)}" placeholder="JXJ-XXXX-XXXX"><small>相手から届いたコードを入力してください。</small></label><button type="button" class="primary-button full-button" data-action="gift-inspect" ${giftBusy ? 'disabled' : ''}>${giftBusy ? '確認しています…' : 'コードを確認する'}</button>`}
  </section>`;
}

function renderPhoneGift() {
  ensureGiftState();
  if (giftView === 'send') return renderGiftSend();
  if (giftView === 'created') return renderGiftCreated();
  if (giftView === 'receive' || giftView === 'received') return renderGiftReceive();
  giftView = 'menu';
  return renderGiftMenu();
}

async function createGiftFromDraft() {
  if (giftBusy || !currentUser) return;
  const { row } = normalizeGiftDraft();
  if (!row) return showToast('渡せるプレゼントがありません。', 'error');
  const quantity = giftDraft.category === 'jewelry' ? 1 : (giftDraft.category === 'metal' ? giftRoundedWeight(giftDraft.quantity) : Math.max(1, Math.floor(Number(giftDraft.quantity) || 1)));
  if (quantity <= 0 || quantity > row.max + 0.0001) return showToast('数量を確認してください。', 'error');
  const payload = { ...structuredClone(row.payload), quantity };
  giftBusy = true;
  render();
  try {
    await saveGame();
    const result = await createGiftCode(currentUser.uid, state.playerName, payload, removeGiftFromGameState);
    persistTransactionalGiftState(result.gameState);
    giftLastCreated = { code: result.code, payload };
    giftView = 'created';
    playSfx('western-union-handover', { gain: 0.94 });
    setTimeout(() => playSfx('loose-sparkle', { gain: 1.02 }), 140);
    vibrate([28, 28, 58]);
    render();
  } catch (error) {
    console.error('プレゼントコード発行エラー', error);
    showToast(giftErrorMessage(error), 'error');
  } finally {
    giftBusy = false;
    if (screen === 'phone' && phoneTab === 'gift') render();
  }
}

async function inspectGiftInput() {
  if (giftBusy) return;
  const code = normalizeGiftCode(giftCodeInput);
  if (!code) return showToast('プレゼントコードを入力してください。', 'error');
  giftBusy = true;
  render();
  try {
    const gift = await inspectGiftCode(code);
    if (gift.status === 'claimed') throw Object.assign(new Error('受取済み'), { code: 'gift/already-claimed' });
    if (gift.status === 'cancelled') throw Object.assign(new Error('取消済み'), { code: 'gift/cancelled' });
    if (gift.senderUid === currentUser?.uid) throw Object.assign(new Error('自分のコード'), { code: 'gift/self-claim' });
    giftPreview = gift;
    giftCodeInput = gift.code;
    playSfx('select', { gain: 0.84 });
  } catch (error) {
    console.error('プレゼントコード確認エラー', error);
    giftPreview = null;
    showToast(giftErrorMessage(error), 'error');
  } finally {
    giftBusy = false;
    render();
  }
}

async function claimGiftPreview() {
  if (giftBusy || !giftPreview || !currentUser) return;
  giftBusy = true;
  render();
  try {
    await saveGame();
    const result = await claimGiftCode(currentUser.uid, state.playerName, giftPreview.code, addGiftToGameState);
    persistTransactionalGiftState(result.gameState);
    giftLastReceived = { code: giftPreview.code, senderName: giftPreview.senderName, payload: structuredClone(giftPreview.payload) };
    giftPreview = null;
    giftCodeInput = '';
    giftView = 'received';
    playSfx('loose-sparkle', { gain: 1.12 });
    setTimeout(() => playSfx('success', { gain: 1.0 }), 130);
    vibrate([35, 25, 70, 25, 90]);
    render();
  } catch (error) {
    console.error('プレゼント受取エラー', error);
    showToast(giftErrorMessage(error), 'error');
  } finally {
    giftBusy = false;
    if (screen === 'phone' && phoneTab === 'gift') render();
  }
}

async function cancelGift(code) {
  if (giftBusy || !currentUser || !code) return;
  giftBusy = true;
  render();
  try {
    await saveGame();
    const result = await cancelGiftCode(currentUser.uid, code, restoreGiftToGameState);
    persistTransactionalGiftState(result.gameState);
    playSfx('success', { gain: 0.9 });
    vibrate([30, 25, 55]);
    showToast('プレゼントを取り消し、在庫へ戻しました。', 'info', false);
  } catch (error) {
    console.error('プレゼント取消エラー', error);
    if (error?.code === 'gift/already-claimed') {
      const entry = ensureGiftState().outbox.find((item) => item.code === code);
      if (entry) entry.status = 'claimed';
      saveGame();
    }
    showToast(giftErrorMessage(error), 'error');
  } finally {
    giftBusy = false;
    render();
  }
}

async function copyGiftCode(code) {
  let copied = false;
  try {
    await navigator.clipboard.writeText(code);
    copied = true;
  } catch (_) {
    copied = fallbackCopyText(code);
  }
  if (!copied) return showToast('コードをコピーできませんでした。', 'error');
  playSfx('success', { gain: 0.82 });
  vibrate(30);
  showToast('プレゼントコードをコピーしました。', 'info', false);
}

function renderPhone() {
  phoneTab = validPhoneTab(phoneTab);
  state.notifications = visibleNotifications();
  if (state?.game) state.game.phoneTab = phoneTab;
  if (phoneTab === 'notifications') state.notifications.forEach((note) => { note.unread = false; });
  const phoneHomeImage = String(state.settings?.phoneHomeImage || '');
  const phoneHomeClass = phoneHomeImage ? ' custom-home-background' : '';
  return shell('スマートフォン', `
    <div class="phone-stage">
      <section class="phone-ui${phoneHomeClass}">
        <nav class="phone-tabs">
          <button class="${phoneTab === 'notifications' ? 'active' : ''}" data-action="phone-tab" data-tab="notifications">通知</button>
          <button class="${phoneTab === 'profile' ? 'active' : ''}" data-action="phone-tab" data-tab="profile">プロフィール</button>
          <button class="${phoneTab === 'calendar' ? 'active' : ''}" data-action="phone-tab" data-tab="calendar">カレンダー</button>
          <button class="${phoneTab === 'finance' ? 'active' : ''}" data-action="phone-tab" data-tab="finance">収支</button>
          <button class="${phoneTab === 'items' ? 'active' : ''}" data-action="phone-tab" data-tab="items">アイテム</button>
          <button class="${phoneTab === 'gift' ? 'active' : ''}" data-action="phone-tab" data-tab="gift">プレゼント</button>
          ${aquariumUnlocked() ? `<button class="phone-aquarium-tab" data-action="open-aquarium">水槽</button>` : ''}
          <button class="phone-game-tab" data-action="open-phone-game" aria-label="スマホゲームを開く">スマホゲーム</button>
          <button class="${phoneTab === 'ai' ? 'active' : ''}" data-action="phone-tab" data-tab="ai">AI</button>
          <button class="${phoneTab === 'settings' ? 'active' : ''}" data-action="phone-tab" data-tab="settings">設定</button>
        </nav>
        <div class="phone-content">${renderPhoneContent()}</div>
      </section>
    </div>`, { help: `通知、プロフィール、カレンダー、収支、アイテム、プレゼント、${aquariumUnlocked() ? '水槽、' : ''}スマホゲーム、AI、設定を利用できます。プレゼントでは1回限りのコードを使って、ほかのプレイヤーと品物を受け渡せます。` });
}


function phoneItemEffectText(item, beforeHunger, afterHunger) {
  if (Number(item?.effect?.hunger) > 0) return `空腹度 ${beforeHunger} → ${afterHunger}`;
  return '効果が発動しました。';
}

function setPhoneItemFeedback(title, detail, symbol = '◆') {
  itemUseFeedback = { title, detail, symbol };
  clearTimeout(itemUseFeedbackTimer);
  itemUseFeedbackTimer = setTimeout(() => {
    itemUseFeedback = null;
    if (screen === 'phone' && phoneTab === 'items') render();
  }, 1500);
}

function renderPhoneItems() {
  const usableItems = Object.values(GENERAL_ITEMS).filter((item) => Number(state.inventory.items?.[item.id] || 0) > 0);
  const equipmentItems = Object.values(EQUIPMENT_ITEMS).filter((item) => Number(state.inventory.equipment?.[item.id] || 0) > 0);
  const feedback = itemUseFeedback ? `<div class="item-effect-overlay" role="status" aria-live="polite"><span>${esc(itemUseFeedback.symbol)}</span><strong>${esc(itemUseFeedback.title)}</strong><small>${esc(itemUseFeedback.detail)}</small></div>` : '';
  return `<section class="phone-item-inventory">
    ${feedback}
    <section class="phone-item-section">
      <header><div><h2>アイテム</h2></div><strong>${usableItems.reduce((sum, item) => sum + Number(state.inventory.items[item.id] || 0), 0)}個</strong></header>
      ${usableItems.length ? `<div class="phone-item-list">${usableItems.map((item) => {
        const quantity = Number(state.inventory.items[item.id] || 0);
        const hungerEffect = Number(item.effect?.hunger || 0);
        const effectAvailable = !hungerEffect || hungerLevel() < 7;
        const itemVisual = item.image
          ? `<button type="button" class="phone-item-icon phone-item-image-button has-image" data-action="open-phone-item-image" data-kind="item" data-id="${esc(item.id)}" aria-label="${esc(item.name)}の画像を拡大表示"><img src="${esc(item.image)}?v=${VERSION}" alt="" draggable="false"></button>`
          : `<span class="phone-item-icon" aria-hidden="true">${esc(item.symbol || '◆')}</span>`;
        return `<article class="phone-item-row">
          ${itemVisual}
          <div><strong>${esc(item.name)}</strong><small>${esc(item.category)}・${esc(item.description)}</small><span>所持 ${quantity}個</span></div>
          ${item.usable ? `<button class="secondary-button" data-action="use-phone-item" data-id="${esc(item.id)}" ${effectAvailable ? '' : 'disabled'}>${effectAvailable ? esc(item.useLabel || '使う') : '満腹'}</button>` : '<span class="item-status-label">使用不可</span>'}
        </article>`;
      }).join('')}</div>` : ''}
    </section>
    <section class="phone-item-section equipment-section">
      <header><div><h2>装備品</h2></div></header>
      ${equipmentItems.length ? `<div class="phone-item-list">${equipmentItems.map((item) => {
        const quantity = Number(state.inventory.equipment[item.id] || 0);
        const isBasicPickaxe = item.id === 'basicPickaxe';
        const equipped = isBasicPickaxe || state.inventory.equipped?.[item.slot] === item.id;
        const equipmentIcon = item.image
          ? `<button type="button" class="phone-item-icon phone-item-image-button equipment-image-icon" data-action="open-phone-item-image" data-kind="equipment" data-id="${esc(item.id)}" aria-label="${esc(item.name)}の画像を拡大表示">${equipmentVisual(item, 'phone-equipment-image', '')}</button>`
          : `<span class="phone-item-icon equipment-image-icon" aria-hidden="true">${equipmentVisual(item, 'phone-equipment-image', '')}</span>`;
        return `<article class="phone-item-row equipment-item ${equipped ? 'equipped' : ''}">
          ${equipmentIcon}
          <div><strong>${esc(item.name)}${equipped ? '<em>装備中</em>' : ''}</strong><small>${esc(item.category)}・${esc(item.description)}</small><span>所持 ${quantity}点</span></div>
          ${isBasicPickaxe ? '' : `<button class="secondary-button" data-action="toggle-equipment" data-id="${esc(item.id)}">${equipped ? '外す' : '装備'}</button>`}
        </article>`;
      }).join('')}</div>` : '<div class="phone-empty compact">装備品はありません。</div>'}
    </section>
  </section>`;
}

function showPhoneItemImage(kind, itemId) {
  const catalog = kind === 'equipment' ? EQUIPMENT_ITEMS : GENERAL_ITEMS;
  const item = catalog?.[itemId];
  if (!item?.image) {
    showToast('拡大表示できる画像がありません。', 'error');
    return;
  }
  showModal({
    title: item.name,
    body: `<div class="phone-item-image-preview"><img src="${esc(item.image)}?v=${VERSION}" alt="${esc(item.name)}" draggable="false"><small>${esc(item.name)}</small></div>`,
    confirm: '閉じる',
    action: 'modal-close',
    hideCancel: true,
    className: 'phone-item-image-modal',
  });
}

function usePhoneItem(itemId) {
  const item = GENERAL_ITEMS[itemId];
  const owned = Number(state.inventory.items?.[itemId] || 0);
  if (!item || !item.usable || owned <= 0) {
    showToast('使用できるアイテムがありません。', 'error');
    return;
  }
  const beforeHunger = hungerLevel();
  let changed = false;
  if (Number(item.effect?.hunger) > 0) {
    const after = Math.min(7, beforeHunger + Number(item.effect.hunger));
    if (after > beforeHunger) {
      state.wellbeing.hunger = after;
      changed = true;
    }
  }
  if (!changed) {
    showToast('今はこのアイテムを使う必要がありません。', 'error');
    return;
  }
  state.inventory.items[itemId] = owned - 1;
  saveGame();
  playSfx(item.sfx || 'success');
  if (item.id === 'energyDrink') {
    window.setTimeout(() => playSfx('success', { gain: .72 }), 260);
    vibrate([25, 22, 48]);
  }
  setPhoneItemFeedback(`${item.name}を使いました`, phoneItemEffectText(item, beforeHunger, hungerLevel()), item.symbol || '◆');
  render();
}

function togglePhoneEquipment(equipmentId) {
  const item = EQUIPMENT_ITEMS[equipmentId];
  const owned = Number(state.inventory.equipment?.[equipmentId] || 0);
  if (!item || owned <= 0) {
    showToast('その装備品を持っていません。', 'error');
    return;
  }
  const currentlyEquipped = state.inventory.equipped?.[item.slot] === equipmentId;
  state.inventory.equipped[item.slot] = currentlyEquipped ? '' : equipmentId;
  saveGame();
  playSfx('success');
  setPhoneItemFeedback(item.name, currentlyEquipped ? '装備を外しました。' : '装備しました。', item.symbol || '◇');
  render();
}

function renderPhoneProfile() {
  const progress = gameClearProgress();
  const cleared = Boolean(state.progressFlags?.gameClearAchieved);
  const clearDay = Math.max(1, Number(state.progressFlags?.gameClearDay) || state.game.day);
  return `<section class="phone-profile-screen">
    <header class="phone-profile-heading">
      <div><small>プレイヤー</small><h2>${esc(state.playerName || '名前未設定')}</h2><span>${esc(artisanTitle())}</span></div>
    </header>
    <section class="profile-level-summary">
      <div><small>職人</small><strong>Lv.${progress.artisanLevel}</strong><span>${esc(artisanTitle(progress.artisanLevel))}・最高Lv.${Math.max(progress.artisanLevel, Number(state.artisan.peakLevel) || 1)}</span></div>
      <div><small>工房</small><strong>Lv.${progress.workshopLevel}</strong><span>最大 Lv.20</span></div>
      <div><small>最高店舗</small><strong>Lv.${progress.highestStoreLevel}</strong><span>最大 Lv.20</span></div>
      <div><small>営業店舗</small><strong>${progress.operatingStoreCount}店</strong><span>契約 ${progress.contractedStoreCount}店</span></div>
    </section>
    <section class="game-clear-progress-card">
      <header><div><small>ゲームクリア条件</small><h3>${cleared ? `${clearDay}日目に達成` : '4条件を達成するとクリア'}</h3></div><strong>${progress.conditions.filter((condition) => condition.achieved).length}／4</strong></header>
      <div class="game-clear-condition-list">${gameClearConditionRows(progress)}</div>
      <p>${cleared ? 'クリア後もゲームデータを維持したまま、自由にプレイできます。' : '報酬やリセットはなく、達成後もそのままゲームを続けられます。'}</p>
    </section>
  </section>`;
}

function renderPhoneAI() {
  return `<section class="phone-ai-screen">
    <article class="phone-ai-panel">
      <button class="primary-button phone-ai-copy-button" data-action="copy-ai-game-data">AI相談データをコピー</button>
      <p>基本ゲームルールと現在の状況だけを、AIが読みやすい短い形式でコピーします。実際のAIへペーストして使用してください。</p>
    </article>
  </section>`;
}

function aiInventoryRows(source, definitions, suffix = '') {
  return Object.entries(source || {})
    .filter(([, quantity]) => Number(quantity) > 0)
    .map(([id, quantity]) => ({
      id,
      name: `${definitions[id]?.name || id}${suffix}`,
      quantity: Number(quantity),
    }));
}


function aiLooseInventoryRows() {
  return looseVariantRows({ ownedOnly: true }).map(({ gem, shapeId, shape, owned, reserved, available }) => ({
    id: `${gem.id}:${shapeId}`,
    gemId: gem.id,
    gem: gem.name,
    shapeId,
    cut: shape.name,
    name: `${gem.name}・${shape.name}ルース`,
    quantity: owned,
    reservedForOrders: reserved,
    availableQuantity: available,
    purchasePrice: loosePurchasePrice(gem.id, shapeId),
    sellPrice: looseSalePrice(gem.id, shapeId),
    baseGemPrice: gem.price,
    cutPriceMultiplier: looseCutPriceMultiplier(gem.id, shapeId),
  }));
}

function aiJewelryRows() {
  return (state.inventory.jewelry || []).map((jewelry) => ({
    id: jewelry.id,
    name: jewelry.name || itemName(jewelry),
    item: ITEMS[jewelry.item]?.name || jewelry.item,
    gem: jewelry.useLoose === false ? 'ルースなし' : (GEMS[jewelry.gem]?.name || jewelry.gem),
    looseShape: jewelry.useLoose === false ? 'なし' : (jewelry.gem === 'pearl' ? '表示なし' : looseShapeLabel(jewelry.looseShape)),
    metal: METALS[jewelry.metal]?.name || jewelry.metal,
    design: DESIGNS[jewelry.design]?.name || jewelry.design,
    finish: FINISHES[jewelry.finish]?.name || jewelry.finish,
    quality: QUALITIES[jewelry.quality]?.name || jewelry.quality,
    craftsmanshipScore: Number(jewelry.craftsmanshipScore) || null,
    craftsmanshipTier: jewelry.craftsmanshipTier || null,
    craftsmanshipPriceMultiplier: Number(jewelry.craftsmanshipPriceMultiplier) || null,
    craftsmanshipTags: Array.isArray(jewelry.craftsmanshipTags) ? jewelry.craftsmanshipTags : [],
    craftsmanshipKnowledge: Array.isArray(jewelry.craftsmanshipKnowledge) ? jewelry.craftsmanshipKnowledge : [],
    status: jewelry.status,
    cost: Number(jewelry.cost) || 0,
    recommendedPrice: Number(jewelry.recommendedPrice) || 0,
    createdDay: Number(jewelry.createdDay) || null,
    orderId: jewelry.orderId || null,
  }));
}

function aiOrderRows() {
  return (state.orders || []).map((order) => ({
    id: order.id,
    customerName: order.customerName,
    item: ITEMS[order.item]?.name || order.item,
    gem: GEMS[order.gem]?.name || order.gem,
    looseShape: order.gem === 'pearl' ? '表示なし' : looseShapeLabel(order.looseShape),
    metal: METALS[order.metal]?.name || order.metal,
    design: DESIGNS[order.design]?.name || order.design,
    difficulty: orderDifficulty(order).label,
    requiredArtisanLevel: Number(order.requiredArtisanLevel) || orderDifficulty(order).artisanLevel,
    requiredEquipment: orderRequiredTools(order).map((toolId) => WORKSHOP_TOOLS[toolId]?.name || toolId),
    displayStatus: orderDisplayStatus(order),
    budget: Number(order.budget) || 0,
    price: Number(order.price) || 0,
    estimatedCost: Number(order.estimatedCost) || 0,
    estimatedProfit: Number(order.estimatedProfit) || 0,
    acceptedDay: Number(order.acceptedDay) || null,
    acceptedDate: order.acceptedDay ? gameDateLabel(order.acceptedDay) : null,
    deadlineDay: Number(order.deadlineDay) || null,
    deadlineDate: order.deadlineDay ? gameDateLabel(order.deadlineDay) : null,
    status: order.status,
    desiredConditions: order.desiredConditions || CUSTOMERS[order.customerId]?.preferenceText || '',
    requiredMetalWeight: Number(order.requiredMetalWeight) || Number(ITEMS[order.item]?.metalWeight) || 0,
    requiredLooseQuantity: Number(order.requiredLooseQuantity) || Number(ITEMS[order.item]?.looseQuantity) || 1,
    jewelryId: order.jewelryId || null,
  }));
}

function aiWorkshopToolRows() {
  return Object.entries(state.tools?.items || {})
    .filter(([, record]) => Boolean(record))
    .map(([toolId, record]) => {
      const tool = WORKSHOP_TOOLS[toolId];
      return {
        id: toolId,
        name: tool?.name || toolId,
        type: tool?.type || '工具・設備',
        description: tool?.description || '',
        status: workshopToolStatusText(toolId, record),
        workshopPoints: Number(tool?.qualityPoints) || 0,
        acquiredDay: Number(record.acquiredDay) || null,
        acquiredDate: record.acquiredDay ? gameDateLabel(record.acquiredDay) : null,
        repairCompleteDay: record.status === 'repairing' ? Number(record.repairCompleteDay) || null : null,
        repairCompleteDate: record.status === 'repairing' && record.repairCompleteDay ? gameDateLabel(record.repairCompleteDay) : null,
      };
    });
}

function aiCurrentCapabilities() {
  const remainingHours = Math.max(0, Math.floor((DAY_END_MINUTES - state.game.minutes) / 60));
  const roughCount = Object.values(state.inventory.rough || {}).reduce((sum, qty) => sum + Math.max(0, Number(qty) || 0), 0);
  const looseCount = looseInventoryTotal();
  const metalCount = Object.values(state.inventory.metals || {}).reduce((sum, qty) => sum + Math.max(0, Number(qty) || 0), 0);
  const storedCount = state.inventory.jewelry.filter((item) => item.status !== 'sold').length;
  const activeOrders = activeOrderCount();
  return {
    remainingActionHoursToday: remainingHours,
    canMine: hungerLevel() > 0 && availableMiningLocations().some((place) => place.hours <= remainingHours),
    canPolishRoughStone: hungerLevel() > 0 && toolUsable('polishingMachine') && roughCount > 0 && remainingHours >= POLISHING_HOURS,
    canCraftJewelry: hungerLevel() > 0 && toolUsable('jewelryBench') && looseCount > 0 && metalCount > 0 && storedCount < state.inventory.capacity,
    canUseStore: Boolean(state.store.rented),
    storeBusinessOpenNow: storeBusinessOpen(),
    storeDeliveryOpenNow: storeDeliveryOpen(),
    canServeCustomers: canServeCustomers(),
    canAcceptOrders: canAcceptOrders(),
    canAcceptAnotherOrder: canServeCustomers() && canAcceptOrders() && activeOrders < orderLimit(),
      simultaneousOrderLimit: orderLimit(),
    canBuyOrSellMetals: hungerLevel() > 0 && okachimachiFacilityAvailability('materialShop').open && remainingHours >= 1,
    canSellRoughStones: hungerLevel() > 0 && okachimachiFacilityAvailability('looseShop').open && roughCount > 0 && remainingHours >= 1,
    canBuyOrSellLooseStones: hungerLevel() > 0 && okachimachiFacilityAvailability('looseShop').open && remainingHours >= 1,
    canUseJewelryShop: hungerLevel() > 0 && okachimachiFacilityAvailability('jewelryShop').open && remainingHours >= 1,
    canUseDisplayShop: hungerLevel() > 0 && okachimachiFacilityAvailability('displayShop').open && remainingHours >= 1,
    hungerRestricted: hungerLocked(),
  };
}

