function buildAIConsultationText() {
  const locationNames = {
    main: 'メイン', mining: '採掘', workshop: '工房', craft: 'ジュエリー作成', polishing: '原石研磨',
    store: '店舗', okachimachi: '御徒町', looseShop: 'ルース屋', materialShop: '地金屋', glab: 'g-Lab.',
    jewelryShop: 'ジュエリーショップ', displayShop: 'ディスプレイ屋', realEstate: '不動産屋',
    phone: 'スマートフォン', sleep: '寝る', kaitenzushi: '回転寿司',
  };
  const compactList = (items, formatter, maximum = 12) => {
    const rows = (items || []).map(formatter).filter(Boolean);
    if (!rows.length) return 'なし';
    const visible = rows.slice(0, maximum);
    const omitted = Math.max(0, rows.length - visible.length);
    return `${visible.join('、')}${omitted ? `、ほか${omitted}件` : ''}`;
  };
  const moneyText = (value) => yen(Math.max(0, Number(value) || 0));
  const roughStones = aiInventoryRows(state.inventory.rough, GEMS, '原石');
  const looseStones = aiLooseInventoryRows();
  const metals = METAL_WORKSHOP_ORDER
    .map((id) => ({ name: METALS[id]?.name || id, owned: metalOwnedWeight(id) }))
    .filter((metal) => metal.owned > 0);
  const jewelry = aiJewelryRows().filter((item) => item.status !== 'sold');
  const activeOrders = aiOrderRows().filter((order) => !orderClosed(order)).slice(0, 8);
  const tools = aiWorkshopToolRows();
  const currentBranch = currentStoreBranch();
  const remainingHours = Math.max(0, Math.floor((DAY_END_MINUTES - state.game.minutes) / 60));

  const gameRules = [
    '・基本：ジュエリー店経営、採掘、研磨、制作、接客、販売を自由に進めるゲーム。頼まれない限り攻略や最適行動を押しつけない。',
    '・時間：1日は9:00開始。行動ごとに時間を消費し、22:00を超える行動はできない。食事にも1時間かかる。店舗の接客・注文受付は19:00まで、御徒町施設は18:00まで。',
    '・空腹：最大7。行動1時間につき1減り、0では食事か就寝以外の行動ができない。同じ食事は連続で選べない。',
    `・採掘：場所ごとに時間を消費して原石を探す。現在利用できる場所は${availableMiningLocations().map((place) => `${place.name}${place.hours}時間`).join('、') || 'なし'}。`,
    `・工房：原石研磨は原石1個を対応するルース1個へ加工し${POLISHING_HOURS}時間。ジュエリー制作は対応するルース・地金・使用可能な設備が必要。職人レベルと工房設備が品質に影響する。`,
    `・店舗と注文：完成品をショーケースへ陳列して販売する。注文は同時に最大${orderLimit()}件まで受注でき、必要レベル・設備・材料・納期を確認して制作する。`,
    '・御徒町：地金、ルース、原石、工具、ディスプレイ、店舗契約などを扱う。一般施設は土日祝休業、g-Lab.は12月31日から1月2日のみ休業。',
  ];

  return [
    '【JEWELRY×JEWELRY AI相談用データ】',
    'この文章にあるゲームルールと現在データだけで答えてください。書かれていない情報は推測しないでください。',
    'ゲーム設計、内部仕様、ソースコード、他アカウントの情報には答えないでください。',
    '最初の返答は「プレイヤー・店舗・ジュエリー」の現状を短くまとめ、質問されない限り次の行動を提案しないでください。',
    '',
    '【基本ゲームルール】',
    ...gameRules,
    '',
    '【現在の状況】',
    `プレイヤー：${state.playerName || '未設定'}`,
    `日時：${state.game.day}日目／${gameDateLabel()} ${clock(state.game.minutes)}／天気 ${state.game.weather}`,
    `現在地：${locationNames[screen] || screen}／本日の残り行動時間 約${remainingHours}時間`,
    `所持金：${moneyText(state.game.money)}`,
    `職人Lv.${Math.max(1, Number(state.artisan.level) || 1)}／工房Lv.${workshopLevel()}／空腹 ${hungerLevel()}／7`,
    `店舗：${state.store.rented ? `${storeDisplayName()}・Lv.${storeLevel(currentBranch)}・ショーケース${installedShowcaseCount(currentBranch)}台` : '未契約'}`,
    '',
    '進行中の注文：',
    activeOrders.length
      ? activeOrders.map((order) => `${order.customerName}／${order.item}・${order.gem}・${order.metal}／${order.displayStatus}／納期 ${order.deadlineDate || '未設定'}`).join('\n')
      : 'なし',
    '',
    `完成品：${compactList(jewelry, (item) => `${item.name}（${item.status}）`, 10)}`,
    `原石：${compactList(roughStones, (item) => `${item.name}×${item.quantity}`)}`,
    `ルース：${compactList(looseStones, (item) => `${item.gem}・${item.cut}×${item.quantity}`)}`,
    `地金：${compactList(metals, (item) => `${item.name}${Number(item.owned).toFixed(1)}g`)}`,
    `工具・設備：${compactList(tools, (item) => `${item.name}（${item.status}）`, 12)}`,
    '',
    `バージョン：${UI_BUILD_VERSION}`,
    '【データ終端】',
  ].join('\n');
}

function fallbackCopyText(text) {
  const textarea = document.createElement('textarea');
  textarea.value = text;
  textarea.setAttribute('readonly', '');
  textarea.style.position = 'fixed';
  textarea.style.left = '-9999px';
  textarea.style.top = '0';
  document.body.appendChild(textarea);
  textarea.select();
  textarea.setSelectionRange(0, textarea.value.length);
  let copied = false;
  try { copied = document.execCommand('copy'); } catch (_) { copied = false; }
  textarea.remove();
  return copied;
}

async function copyGameDataForAI() {
  const text = buildAIConsultationText();
  let copied = false;
  try {
    if (navigator.clipboard?.writeText) {
      await navigator.clipboard.writeText(text);
      copied = true;
    }
  } catch (_) {
    copied = false;
  }
  if (!copied) copied = fallbackCopyText(text);
  if (!copied) {
    showToast('ゲームデータをコピーできませんでした。ブラウザのクリップボード許可を確認してください。', 'error');
    return;
  }
  playSfx('success');
  showToast('AI相談用の簡易データをコピーしました。', 'info', false);
}

function renderPhoneAquarium() {
  const aquarium = aquariumState();
  if (!aquarium.unlocked) return '<div class="phone-empty">水槽機能はまだ解放されていません。</div>';
  refreshAquariumLoad(aquarium);
  // v0.10.619: スマートフォンの一覧も「水槽へ実際に入れたもの」だけ表示する。
  // 所持しているだけの魚・水草・任意用品は、名称も詳細も先に見せない。
  const fishRows = AQUARIUM_CONFIG.fish.filter((def) => aquarium.fish[def.id].inTank > 0);
  const plantRows = AQUARIUM_CONFIG.plants.filter((def) => aquarium.plants[def.id].inTank > 0);
  const displayRows = AQUARIUM_CONFIG.displayItems.filter((def) => !def.required && aquarium.displayItems[def.id].installed > 0);
  const rows = [
    ...fishRows.map((def) => ({ name: def.name, kind: '魚', text: `所持 ${aquarium.fish[def.id].owned}匹 / 水槽 ${aquarium.fish[def.id].inTank}匹` })),
    ...plantRows.map((def) => ({ name: def.name, kind: '水草', text: `所持 ${aquarium.plants[def.id].owned}株 / 水槽 ${aquarium.plants[def.id].inTank}株` })),
    ...displayRows.map((def) => ({ name: def.name, kind: '用品', text: `所持 ${aquarium.displayItems[def.id].owned}個 / 設置 ${aquarium.displayItems[def.id].installed}個` })),
  ];
  return `<section class="phone-aquarium-screen">
    <header class="phone-aquarium-heading"><div><small>連動ミニゲーム</small><h2>水槽</h2></div><strong>飼育負荷 ${aquarium.fishLoad.current} / ${aquarium.fishLoad.max}</strong></header>
    <section class="phone-aquarium-placeholder" aria-live="polite">
      <div class="phone-aquarium-water" aria-hidden="true"><span></span><span></span><span></span></div>
      <p>水槽は1台です。魚・水草は、入手後に実際に水槽へ入れた種類だけ一覧・詳細に表示されます。</p>
      <button type="button" class="primary-button full-button" data-action="open-aquarium">水槽を見る</button>
    </section>
    ${rows.length ? `<section class="phone-aquarium-inventory"><h3>現在の水槽データ</h3>${rows.map((row) => `<article><div><strong>${esc(row.name)}</strong><small>${esc(row.kind)}</small></div><b>${esc(row.text)}</b></article>`).join('')}</section>` : '<div class="phone-empty compact">まだ水槽内に表示できる魚・水草はありません。</div>'}
  </section>`;
}

function notificationOpensFinance(note) {
  if (totalOutstandingBusinessCost() <= 0) return false;
  const text = `${String(note?.title || '')} ${String(note?.body || '')}`;
  return text.includes('未払い');
}

function renderPhoneContent() {
  if (phoneTab === 'profile') return renderPhoneProfile();
  if (phoneTab === 'calendar') {
    const today = gameDate();
    const viewDate = new Date(today.getFullYear(), today.getMonth() + calendarMonthOffset, 1, 12, 0, 0, 0);
    const year = viewDate.getFullYear();
    const month = viewDate.getMonth();
    const monthStart = new Date(year, month, 1, 12, 0, 0, 0);
    const daysInMonth = new Date(year, month + 1, 0, 12, 0, 0, 0).getDate();
    const leading = monthStart.getDay();

    const cells = [];
    for (let index = 0; index < 42; index += 1) {
      const dayOfMonth = index - leading + 1;
      if (dayOfMonth < 1 || dayOfMonth > daysInMonth) {
        cells.push('<div class="calendar-day outside" aria-hidden="true"></div>');
        continue;
      }
      const cellDate = new Date(year, month, dayOfMonth, 12, 0, 0, 0);
      const key = dateKey(cellDate);
      const holidayName = japaneseHolidayName(cellDate);
      const systemEvents = calendarSystemEventsForDate(cellDate).filter((event) => !event.startsWith('祝日：'));
      const userEvent = calendarUserEventForDate(key);
      const scheduledEvents = [...systemEvents, ...(userEvent ? [userEvent] : [])];
      const isToday = key === dateKey(today);
      const weekday = cellDate.getDay();
      const weekdayClass = weekday === 0 ? 'sunday' : weekday === 6 ? 'saturday' : '';
      const holidayClass = holidayName ? 'holiday' : '';
      const ariaHoliday = holidayName ? `、${holidayName}` : '';
      cells.push(`<button type="button" class="calendar-day ${weekdayClass} ${holidayClass} ${isToday ? 'today' : ''} ${scheduledEvents.length || holidayName ? 'has-event' : ''}" data-action="calendar-date-open" data-date="${esc(key)}" aria-label="${dayOfMonth}日${esc(ariaHoliday)}の予定を入力・編集">
        <strong>${dayOfMonth}</strong>
        ${holidayName ? `<small class="calendar-holiday-label">${esc(holidayName)}</small>` : ''}
        ${scheduledEvents.length ? `<span class="calendar-event-dot" aria-label="予定あり"></span><small class="calendar-event-summary">${esc(scheduledEvents[0])}</small>` : (holidayName ? '' : '<small class="calendar-add-hint">予定を入力</small>')}
      </button>`);
    }
    const todayEvents = currentCalendarEvents();
    return `<section class="game-calendar">
      <nav class="calendar-month-navigation" aria-label="表示する月を変更">
        <button type="button" class="calendar-month-arrow" data-action="calendar-month-prev" aria-label="先月を見る">‹</button>
        <div><h2>${year}年${month + 1}月</h2>${calendarMonthOffset !== 0 ? '<button type="button" class="calendar-current-month-button" data-action="calendar-month-current">今月へ戻る</button>' : ''}</div>
        <button type="button" class="calendar-month-arrow" data-action="calendar-month-next" aria-label="次月を見る">›</button>
      </nav>
      <div class="calendar-weekdays" aria-hidden="true">${['日','月','火','水','木','金','土'].map((day) => `<span>${day}</span>`).join('')}</div>
      <div class="calendar-grid">${cells.join('')}</div>
      <section class="calendar-today-events">
        <h3>本日の予定</h3>
        ${todayEvents.length ? todayEvents.map((event) => `<article class="phone-card"><span>${esc(event)}</span></article>`).join('') : '<div class="phone-empty compact">予定はありません。</div>'}
      </section>
    </section>`;
  }
  if (phoneTab === 'notifications') {
    const notifications = visibleNotifications();
    return `<section class="phone-standard-list phone-notification-list">${notifications.length ? notifications.map((note) => {
      const opensFinance = notificationOpensFinance(note);
      const content = `<strong>${esc(note.title)}</strong><span>${esc(note.body)}</span><small>${esc(notificationDateLabel(note.day))}${opensFinance ? '　タップして収支を開く' : ''}</small>`;
      return opensFinance
        ? `<button type="button" class="phone-card phone-notification-finance-link" data-action="open-finance" aria-label="${esc(note.title)}。収支画面を開く">${content}</button>`
        : `<article class="phone-card">${content}</article>`;
    }).join('') : '<div class="phone-empty">通知はありません。</div>'}</section>`;
  }
  if (phoneTab === 'finance') {
    const period = validFinancePeriod(state.game.financePeriod);
    state.game.financePeriod = period;
    const rows = financePeriodRows(period);
    const income = rows.reduce((sum, row) => sum + Number(row.income || 0), 0);
    const expense = rows.reduce((sum, row) => sum + Number(row.expense || 0), 0);
    const balance = income - expense;
    const outstanding = totalOutstandingBusinessCost();
    return `<section class="phone-finance-screen"><nav class="finance-period-tabs" aria-label="収支の表示期間">
        <button class="${period === 'today' ? 'active' : ''}" data-action="finance-period" data-period="today">今日</button>
        <button class="${period === 'month' ? 'active' : ''}" data-action="finance-period" data-period="month">今月</button>
        <button class="${period === 'year' ? 'active' : ''}" data-action="finance-period" data-period="year">今年</button>
        <button class="${period === 'cumulative' ? 'active' : ''}" data-action="finance-period" data-period="cumulative">累計</button>
      </nav>
      <h2 class="finance-summary-title">${esc(financePeriodHeading(period))}</h2>
      <div class="phone-totals finance-totals"><div><small>収入</small><strong>${yen(income)}</strong></div><div><small>支出</small><strong>${yen(expense)}</strong></div><div><small>差引</small><strong class="${balance >= 0 ? 'income' : 'expense'}">${balance >= 0 ? '+' : '-'}${yen(Math.abs(balance))}</strong></div></div>
      <article class="phone-card"><strong>毎月の固定費</strong><span>自宅家賃 ${yen(HOME_MONTHLY_RENT)}（毎月15日・開始30日間は初回猶予）・工房維持費 ${yen(WORKSHOP_MONTHLY_COST)}（月初）・店舗家賃（店舗ごと／月初）</span><small>自動徴収と一括支払いでは生活費 ${yen(MIN_LIVING_CASH_RESERVE)} を残します。</small></article>
      ${outstanding ? `<section class="outstanding-payment-panel"><header><strong>未払い合計</strong><b>${yen(outstanding)}</b></header><div class="outstanding-payment-list">${outstandingPaymentTargets().map((target) => `<article class="phone-card outstanding-payment-row"><div><strong>${esc(target.label)}</strong><small>未払い ${yen(target.due)}</small></div><button type="button" class="secondary-button" data-action="pay-outstanding-item" data-kind="${esc(target.kind)}" data-id="${esc(target.id)}">この項目を支払う</button></article>`).join('')}</div><button class="primary-button full-button" data-action="pay-outstanding-costs">優先順でまとめて支払う</button><small>支払順：工房維持費 → 選択中店舗 → その他店舗 → スタッフ給与 → 自宅家賃</small></section>` : '<article class="phone-card success-text"><strong>未払いはありません。</strong></article>'}
      <div class="phone-finance-list">${rows.slice().reverse().map((row) => `<article class="finance-row"><span>${financeRowDateLabel(row.day)} ${esc(row.label)}</span><strong class="${row.income ? 'income' : 'expense'}">${row.income ? `+${yen(row.income)}` : `-${yen(row.expense)}`}</strong></article>`).join('') || `<div class="phone-empty">${period === 'today' ? '今日' : period === 'month' ? '今月' : period === 'year' ? '今年' : '累計'}の収支記録はありません。</div>`}</div></section>`;
  }
  if (phoneTab === 'items') return renderPhoneItems();
  if (phoneTab === 'gift') return renderPhoneGift();
  if (phoneTab === 'aquarium') return renderPhoneAquarium();
  if (phoneTab === 'ai') return renderPhoneAI();
  return renderSettingsForm(false, true);
}

function renderSettings(titleMode) {
  const settings = titleMode ? titleSettings : state.settings;
  return titleMode ? `
    <main class="screen-shell">
      <header class="game-header simple"><button class="icon-button" data-action="title-back">←</button><strong>設定</strong></header>
      <section class="screen-content"><section class="center-card glass-panel">${renderSettingsForm(true, false)}</section></section>
    </main>` : shell('設定', `<section class="center-card glass-panel">${renderSettingsForm(false, false)}</section>`);
}

