root.addEventListener('change', (event) => {
  const target = event.target;
  if (target.matches('[data-setup-birthday-month]')) {
    syncSetupBirthdayDaySelect();
    return;
  }
  if (target.matches('[data-birthday-month]')) {
    syncBirthdayDaySelect();
    return;
  }
  if (target.matches('[data-gift-category]')) {
    giftDraft.category = target.value;
    giftDraft.itemKey = '';
    giftDraft.quantity = 1;
    playSfx('select', { gain: 0.72 });
    render();
    return;
  }
  if (target.matches('[data-gift-item]')) {
    giftDraft.itemKey = target.value;
    giftDraft.quantity = 1;
    playSfx('select', { gain: 0.72 });
    render();
    return;
  }
  if (target.matches('[data-phone-home-image-input]')) {
    preparePhoneHomeImage(target.files?.[0]);
    target.value = '';
    return;
  }
  if (target.matches('[data-action="employee-working"]')) {
    const branch = currentStoreBranch();
    if (branch) storeBranchEmployee(branch).working = target.checked;
    saveGame();
    render();
    return;
  }
  if (target.matches('[data-action="workshop-staff-working"]')) {
    if (workshopStaffHoliday(gameDate())) {
      target.checked = workshopStaffState().working;
      showToast('土日祝日は職人スタッフを設定できません。', 'error');
      return;
    }
    workshopStaffState().working = target.checked;
    saveGame();
    render();
    return;
  }
  if (target.matches('[data-setting]')) {
    const titleMode = target.dataset.titleMode === 'true';
    if (!titleMode && screen === 'phone' && phoneTab === 'settings') {
      playSfx('select');
      vibrate(28);
    }
    const settings = titleMode ? titleSettings : state.settings;
    const key = target.dataset.setting;
    settings[key] = target.type === 'checkbox' ? target.checked : target.type === 'range' ? Number(target.value) : target.value;
    if (titleMode) {
      titleSettings = settings;
      localStorage.setItem(`${SAVE_KEY}-settings`, JSON.stringify(settings));
    } else if (key === 'autopilotEnabled') {
      const autopilot = ensureAutopilotState();
      autopilot.lastRealDate = tokyoRealDateKey();
      autopilot.lastRunAt = new Date().toISOString();
      addNotification(
        settings.autopilotEnabled ? '自動操縦モードを開始しました' : '自動操縦モードを停止しました',
        settings.autopilotEnabled
          ? '本日はゲーム内日付を進めず、翌日から現実の1日につきゲーム内の1日を自動で進めます。自動操縦中はメイン画面からスマートフォンと今日の宝石だけ操作できます。'
          : '停止中の現実日数はゲーム内へ反映されません。',
      );
      saveGame();
      render();
    } else saveGame();
    applyAudioSettings();
  }
});

root.addEventListener('keydown', (event) => {
  if (event.key !== 'Enter') return;
  const target = event.target;
  if (target?.id === 'player-name-setup') {
    event.preventDefault();
    root.querySelector('[data-action="confirm-player-name"]')?.click();
  } else if (target?.matches?.('[data-player-name-input]')) {
    event.preventDefault();
    root.querySelector('[data-action="update-player-name"]')?.click();
  } else if (target?.matches?.('[data-gift-code-input]')) {
    event.preventDefault();
    root.querySelector('[data-action="gift-inspect"]')?.click();
  }
});

root.addEventListener('input', (event) => {
  const target = event.target;
  if (target.matches('[data-gift-code-input]')) {
    giftCodeInput = target.value.toUpperCase();
    return;
  }
  if (!target.matches('[data-setting]') || target.type !== 'range') return;
  const titleMode = target.dataset.titleMode === 'true';
  const settings = titleMode ? titleSettings : state.settings;
  settings[target.dataset.setting] = Number(target.value);
  applyAudioSettings();
});

